-- Trang "Chép câu": nhập 10 file Excel trong DATA/chep-cau thành 10 thư mục, mỗi thư mục 100 câu
-- (mục 2.1–2.10 của DATA/huong-dan-song-ngu.html, nội dung theo 12 hướng phát triển ý).
-- Chạy trong Supabase → SQL Editor. An toàn khi chạy lại: thư mục nào đã có cùng tên thì bỏ qua.

do $$
declare
  -- Email đăng nhập app. Để trống = tự lấy tài khoản có thư mục "01. ..." (bộ 01–15 hiện có).
  v_email  text := '';
  v_names  text[] := array[
    'Pattern 2.1 · Cho phép, giúp đỡ, khuyến khích',
    'Pattern 2.2 · Ngăn cản, bắt buộc',
    'Pattern 2.3 · Nguyên nhân – kết quả',
    'Pattern 2.4 · Nêu quan điểm',
    'Pattern 2.5 · Nhượng bộ và đối lập',
    'Pattern 2.6 · So sánh',
    'Pattern 2.7 · Giải pháp và đề xuất',
    'Pattern 2.8 · Điều kiện và giả định',
    'Pattern 2.9 · Nhấn mạnh và cấu trúc nâng cao',
    'Pattern 2.10 · Xu hướng và dự đoán'
  ];
  v_user   uuid;
  v_count  int;
  v_folder uuid[] := array[]::uuid[];  -- thư mục mới tạo theo thứ tự; null = đã có, bỏ qua
  v_base   timestamptz[] := array[]::timestamptz[];
  v_id     uuid;
  v_start  timestamptz := clock_timestamp();
  v_at     timestamptz;
  i        int;
begin
  if v_email <> '' then
    select id into v_user from auth.users where lower(email) = lower(v_email);
    if v_user is null then
      raise exception 'Không có tài khoản nào với email %', v_email;
    end if;
  else
    select count(distinct user_id), min(user_id::text)::uuid into v_count, v_user
    from public.sentence_folders
    where name like '01.%' and deleted_at is null;
    if v_count <> 1 then
      raise exception 'Tìm thấy % tài khoản có thư mục "01. ...". Hãy điền v_email ở đầu script.', v_count;
    end if;
  end if;

  -- Tạo thư mục, cách nhau 1 giây để giữ đúng thứ tự 2.1 → 2.10 (app xếp thư mục mới theo created_at)
  for i in 1 .. array_length(v_names, 1) loop
    if exists (
      select 1 from public.sentence_folders
      where user_id = v_user and name = v_names[i] and deleted_at is null
    ) then
      raise notice 'Thư mục "%" đã có, bỏ qua.', v_names[i];
      v_folder := v_folder || null::uuid;
      v_base := v_base || null::timestamptz;
    else
      v_at := v_start + i * interval '1 second';
      insert into public.sentence_folders (user_id, name, created_at, updated_at)
      values (v_user, v_names[i], v_at, v_at)
      returning id into v_id;
      v_folder := v_folder || v_id;
      v_base := v_base || v_at;
    end if;
  end loop;

  -- App xếp câu theo created_at: cách nhau 1 ms để giữ đúng thứ tự 1 → 100 trong mỗi thư mục
  insert into public.sentences
    (user_id, folder_id, vi, en, alt_answers, hints, level, topic, created_at, updated_at)
  select v_user, v_folder[s.k], s.vi, s.en, s.alt, s.hints, s.level, s.topic,
         v_base[s.k] + s.n * interval '1 millisecond', v_base[s.k] + s.n * interval '1 millisecond'
  from (values
    (1, 1, 'Giao ngân sách riêng cho chính quyền địa phương sẽ cho phép họ đáp ứng nhu cầu của từng khu vực nhanh hơn.', 'Giving local authorities their own budgets would allow them to respond faster to the needs of each area.', '["Giving local authorities their own budgets would allow them to respond more quickly to the needs of each area.","Giving local authorities their own budget would allow them to respond faster to the needs of each area.","Giving local authorities their own budgets will allow them to respond faster to the needs of each area."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì (mục 2.1)","local authorities = chính quyền địa phương; budget = ngân sách; respond to = đáp ứng"]'::jsonb, 'B1', '1. Chính phủ'),
    (1, 2, 'Nguồn thu từ thuế giúp nhà nước có khả năng chi trả cho những dự án mà không cá nhân nào tự gánh nổi.', 'Tax revenue enables the state to fund projects that no individual could afford alone.', '["Tax revenue enables the state to finance projects that no individual could afford alone.","Tax revenue enables the government to fund projects that no individual could afford alone.","Tax revenue enables the state to fund projects which no individual could afford alone."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì (mục 2.1)","tax revenue = nguồn thu từ thuế; fund / finance = chi tiền cho, tài trợ; afford = đủ khả năng chi trả"]'::jsonb, 'B2', '1. Chính phủ'),
    (1, 3, 'Tiền thu từ thuế thuốc lá có thể giúp chính phủ chi trả cho các đợt khám sức khỏe miễn phí.', 'Revenue from tobacco taxes can help the government pay for free health checks.', '["Revenue from tobacco taxes can help the government to pay for free health checks.","Revenue from taxes on tobacco can help the government pay for free health checks.","Revenue from tobacco taxes can help the government pay for free medical check-ups."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","revenue = nguồn thu; tobacco tax = thuế thuốc lá; pay for = chi trả cho; health check = khám sức khỏe"]'::jsonb, 'B1', '1. Chính phủ'),
    (1, 4, 'Trợ cấp mua xe máy điện sẽ khuyến khích người đi làm từ bỏ xe máy chạy xăng.', 'Subsidies for electric motorbikes would encourage commuters to give up their petrol motorbikes.', '["Subsidies for electric motorbikes would encourage commuters to give up petrol motorbikes.","Subsidies on electric motorbikes would encourage commuters to give up their petrol motorbikes.","Subsidies for electric motorbikes would encourage commuters to abandon their petrol motorbikes."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì (mục 2.1)","subsidy = trợ cấp; commuter = người đi làm hằng ngày; give up = từ bỏ; petrol = xăng"]'::jsonb, 'B1', '1. Chính phủ'),
    (1, 5, 'Ngân sách công dành cho đường nông thôn giúp nông dân có thể bán nông sản ở thành phố.', 'Public funding for rural roads makes it possible for farmers to sell their produce in cities.', '["Public funding for rural roads makes it possible for farmers to sell their products in cities.","Public investment in rural roads makes it possible for farmers to sell their produce in cities.","Public funding for rural roads makes it possible for farmers to sell their produce in the cities."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì (mục 2.1)","public funding = ngân sách công; rural road = đường nông thôn; produce (danh từ) = nông sản"]'::jsonb, 'B2', '1. Chính phủ'),
    (1, 6, 'Các chiến dịch an toàn giao thông trên truyền hình có thể thuyết phục tài xế trẻ giảm tốc độ.', 'Road safety campaigns on television can persuade young drivers to slow down.', '["Road safety campaigns on TV can persuade young drivers to slow down.","Television road safety campaigns can persuade young drivers to slow down.","Road safety campaigns on television could persuade young drivers to slow down."]'::jsonb, '["persuade sb to do sth = thuyết phục ai làm gì (mục 2.1)","road safety campaign = chiến dịch an toàn giao thông; slow down = giảm tốc độ"]'::jsonb, 'B2', '1. Chính phủ'),
    (1, 7, 'Nhà nước nên cung cấp cho người thất nghiệp khoản hỗ trợ tài chính tạm thời.', 'The state should provide unemployed people with temporary financial support.', '["The state should provide jobless people with temporary financial support.","The government should provide unemployed people with temporary financial support.","The state should provide the unemployed with temporary financial support."]'::jsonb, '["provide sb with sth = cung cấp cho ai cái gì (mục 2.1)","unemployed = thất nghiệp; temporary = tạm thời; financial support = hỗ trợ tài chính"]'::jsonb, 'B2', '1. Chính phủ'),
    (1, 8, 'Các cuộc lấy ý kiến công khai trao quyền cho người dân tham gia xây dựng những chính sách ảnh hưởng đến cuộc sống của họ.', 'Public consultations empower citizens to take part in shaping the policies that affect their lives.', '["Public consultations empower citizens to participate in shaping the policies that affect their lives.","Public consultations empower people to take part in shaping the policies that affect their lives.","Public consultations empower citizens to take part in shaping policies that affect their lives."]'::jsonb, '["empower sb to do sth = tạo sức mạnh, trao quyền cho ai làm gì (mục 2.1)","public consultation = lấy ý kiến công khai; take part in = tham gia; shape = định hình, xây dựng"]'::jsonb, 'C1', '1. Chính phủ'),
    (1, 9, 'Lệnh cấm hút thuốc nơi công cộng đã mở đường cho một thế hệ không khói thuốc.', 'The ban on smoking in public places has paved the way for a smoke-free generation.', '["A ban on smoking in public places has paved the way for a smoke-free generation.","The smoking ban in public places has paved the way for a smoke-free generation.","The ban on smoking in public places paved the way for a smoke-free generation."]'::jsonb, '["pave the way for sth = mở đường cho điều gì (mục 2.1)","ban on = lệnh cấm; public place = nơi công cộng; smoke-free = không khói thuốc"]'::jsonb, 'C1', '1. Chính phủ'),
    (1, 10, 'Những người để người khác quyết định thay mình hiếm khi học được cách tự chịu trách nhiệm.', 'People who let others make decisions for them rarely learn to take responsibility.', '["Those who let others make decisions for them rarely learn to take responsibility.","People who let others make decisions on their behalf rarely learn to take responsibility.","People who let other people make decisions for them rarely learn to take responsibility."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật, hay dùng khi nói) (mục 2.1)","make decisions for sb = quyết định thay ai; rarely = hiếm khi; take responsibility = chịu trách nhiệm"]'::jsonb, 'B1', '2. Cá nhân'),
    (1, 11, 'Lập ngân sách hằng tháng cho phép mỗi người phát hiện những khoản chi tiêu không cần thiết.', 'Keeping a monthly budget allows individuals to spot unnecessary spending.', '["Keeping a monthly budget allows people to spot unnecessary spending.","Making a monthly budget allows individuals to spot unnecessary spending.","Keeping a monthly budget allows individuals to identify unnecessary spending."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì (mục 2.1)","keep a budget = lập ngân sách; spot = phát hiện; unnecessary spending = chi tiêu không cần thiết"]'::jsonb, 'B1', '2. Cá nhân'),
    (1, 12, 'Một người hàng xóm phân loại rác tại nhà có thể khuyến khích cả con phố làm theo.', 'A neighbour who sorts their rubbish at home can encourage the whole street to do the same.', '["A neighbor who sorts their rubbish at home can encourage the whole street to do the same.","A neighbour who sorts their waste at home can encourage the whole street to do the same.","A neighbour who separates their rubbish at home can encourage the whole street to do the same."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì (mục 2.1)","sort rubbish = phân loại rác; the whole street = cả con phố; do the same = làm theo"]'::jsonb, 'B1', '2. Cá nhân'),
    (1, 13, 'Kiến nghị trực tuyến giúp người dân bình thường có thể bày tỏ mối quan ngại với lãnh đạo địa phương.', 'Online petitions make it possible for ordinary citizens to raise their concerns with local leaders.', '["Online petitions make it possible for ordinary people to raise their concerns with local leaders.","Online petitions make it possible for ordinary citizens to voice their concerns to local leaders.","Online petitions make it possible for ordinary citizens to raise concerns with local leaders."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì (mục 2.1)","petition = đơn kiến nghị; ordinary citizen = người dân bình thường; raise concerns = bày tỏ mối quan ngại"]'::jsonb, 'B2', '2. Cá nhân'),
    (1, 14, 'Đặt mục tiêu nhỏ mỗi ngày giúp mỗi người duy trì thói quen mới.', 'Setting small daily goals helps individuals stick to new habits.', '["Setting small daily goals helps individuals to stick to new habits.","Setting small daily goals helps people stick to new habits.","Setting small goals every day helps individuals stick to new habits."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","set a goal = đặt mục tiêu; stick to = duy trì, kiên trì với; habit = thói quen"]'::jsonb, 'B1', '2. Cá nhân'),
    (1, 15, 'Đọc nhãn thực phẩm giúp người mua có khả năng tránh những sản phẩm chứa nhiều đường.', 'Reading food labels enables shoppers to avoid products that are high in sugar.', '["Reading food labels enables shoppers to avoid products high in sugar.","Reading food labels enables consumers to avoid products that are high in sugar.","Reading nutrition labels enables shoppers to avoid products that are high in sugar."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì (mục 2.1)","food label = nhãn thực phẩm; shopper = người mua hàng; high in sugar = chứa nhiều đường"]'::jsonb, 'B2', '2. Cá nhân'),
    (1, 16, 'Người tiêu dùng từ chối bao bì nhựa có thể thuyết phục siêu thị đưa ra những lựa chọn xanh hơn.', 'Consumers who refuse plastic packaging can persuade supermarkets to offer greener alternatives.', '["Shoppers who refuse plastic packaging can persuade supermarkets to offer greener alternatives.","Consumers who reject plastic packaging can persuade supermarkets to offer greener alternatives.","Consumers who refuse plastic packaging can persuade supermarkets to offer greener options."]'::jsonb, '["persuade sb to do sth = thuyết phục ai làm gì (mục 2.1)","packaging = bao bì; refuse = từ chối; greener alternatives = lựa chọn xanh hơn"]'::jsonb, 'B2', '2. Cá nhân'),
    (1, 17, 'Học kỹ năng mới qua mạng tiếp sức cho người trưởng thành chuyển nghề mà không cần quay lại giảng đường đại học.', 'Learning new skills online empowers adults to change careers without going back to university.', '["Learning new skills online empowers adults to switch careers without going back to university.","Learning new skills online empowers adults to change careers without returning to university.","Learning new skills on the Internet empowers adults to change careers without going back to university."]'::jsonb, '["empower sb to do sth = tạo sức mạnh, trao quyền cho ai làm gì (mục 2.1)","change careers = chuyển nghề; go back to university = quay lại giảng đường đại học"]'::jsonb, 'C1', '2. Cá nhân'),
    (1, 18, 'Những thay đổi nhỏ của mỗi người hôm nay có thể mở đường cho lối sống xanh hơn ở thế hệ sau.', 'Each person''s small changes today can pave the way for a greener lifestyle among the next generation.', '["Every person''s small changes today can pave the way for a greener lifestyle among the next generation.","Each person''s small changes today could pave the way for a greener lifestyle among the next generation.","Each person''s small changes today can pave the way for a greener lifestyle in the next generation."]'::jsonb, '["pave the way for sth = mở đường cho điều gì (mục 2.1)","lifestyle = lối sống; next generation = thế hệ sau; among = ở, trong số"]'::jsonb, 'C1', '2. Cá nhân'),
    (1, 19, 'Chuyên viên tư vấn học đường có thể giúp học sinh đối phó với áp lực thi cử.', 'School counsellors can help students cope with the pressure of exams.', '["School counselors can help students cope with the pressure of exams.","School counsellors can help students to cope with the pressure of exams.","School counsellors can help students cope with exam pressure."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","school counsellor = chuyên viên tư vấn học đường; cope with = đối phó với; exam pressure = áp lực thi cử"]'::jsonb, 'B1', '3. Trường học'),
    (1, 20, 'Giáo viên nên để học sinh học từ sai lầm thay vì phạt mọi lỗi.', 'Teachers should let students learn from their mistakes instead of punishing every error.', '["Teachers should let students learn from their mistakes rather than punishing every error.","Teachers should let pupils learn from their mistakes instead of punishing every error.","Teachers should let students learn from mistakes instead of punishing every error."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật, hay dùng khi nói) (mục 2.1)","learn from mistakes = học từ sai lầm; punish = phạt; error = lỗi"]'::jsonb, 'B1', '3. Trường học'),
    (1, 21, 'Các tiết học về tài chính cá nhân giúp thanh thiếu niên có khả năng lập ngân sách trước khi bắt đầu kiếm tiền.', 'Personal finance lessons enable teenagers to plan a budget before they start earning money.', '["Personal finance lessons enable teenagers to make a budget before they start earning money.","Lessons in personal finance enable teenagers to plan a budget before they start earning money.","Personal finance lessons enable teenagers to plan a budget before they begin earning money."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì (mục 2.1)","personal finance = tài chính cá nhân; plan a budget = lập ngân sách; earn money = kiếm tiền"]'::jsonb, 'B2', '3. Trường học'),
    (1, 22, 'Phòng thí nghiệm khoa học trang bị cho học sinh những kỹ năng thực hành mà chỉ sách giáo khoa thì không thể dạy được.', 'Science laboratories equip pupils with practical skills that textbooks alone cannot teach.', '["Science labs equip pupils with practical skills that textbooks alone cannot teach.","Science laboratories equip students with practical skills that textbooks alone cannot teach.","Science laboratories equip pupils with hands-on skills that textbooks alone cannot teach."]'::jsonb, '["equip sb with sth = trang bị cho ai cái gì (mục 2.1)","laboratory (lab) = phòng thí nghiệm; practical / hands-on skills = kỹ năng thực hành; textbook = sách giáo khoa"]'::jsonb, 'B2', '3. Trường học'),
    (1, 23, 'Các buổi tranh biện trên lớp khuyến khích học sinh đặt câu hỏi về thông tin thay vì chỉ học thuộc lòng.', 'Class debates encourage students to question information rather than simply memorise it.', '["Class debates encourage students to question information rather than simply memorize it.","Classroom debates encourage students to question information rather than simply memorise it.","Class debates encourage students to question information instead of simply memorising it."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì (mục 2.1)","class debate = tranh biện trên lớp; question (động từ) = đặt câu hỏi, chất vấn; memorise = học thuộc lòng"]'::jsonb, 'B1', '3. Trường học'),
    (1, 24, 'Bữa ăn miễn phí ở trường giúp trẻ em nhà nghèo có thể tập trung trong giờ học.', 'Free school meals make it possible for children from poor families to concentrate in class.', '["Free school lunches make it possible for children from poor families to concentrate in class.","Free school meals make it possible for children from low-income families to concentrate in class.","Free school meals make it possible for children from poor families to focus in class."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì (mục 2.1)","free school meals = bữa ăn miễn phí ở trường; concentrate / focus = tập trung"]'::jsonb, 'B2', '3. Trường học'),
    (1, 25, 'Nhà trường nên cung cấp cho giáo viên các khóa tập huấn thường xuyên về phương pháp giảng dạy hiện đại.', 'Schools should provide teachers with regular training in modern teaching methods.', '["Schools should provide teachers with regular training on modern teaching methods.","Schools should provide their teachers with regular training in modern teaching methods.","Schools should provide teachers with regular training courses in modern teaching methods."]'::jsonb, '["provide sb with sth = cung cấp cho ai cái gì (mục 2.1)","training = tập huấn, đào tạo; regular = thường xuyên; teaching method = phương pháp giảng dạy"]'::jsonb, 'B2', '3. Trường học'),
    (1, 26, 'Hội đồng học sinh trao quyền cho các em được góp tiếng nói vào nội quy nhà trường.', 'Student councils empower pupils to have a say in school rules.', '["Student councils empower students to have a say in school rules.","Student councils empower pupils to have a voice in school rules.","Student councils empower pupils to have a say in the school rules."]'::jsonb, '["empower sb to do sth = tạo sức mạnh, trao quyền cho ai làm gì (mục 2.1)","student council = hội đồng học sinh; have a say in = có tiếng nói trong; school rules = nội quy nhà trường"]'::jsonb, 'C1', '3. Trường học'),
    (1, 27, 'Hướng nghiệp sớm có thể mở đường cho bước chuyển suôn sẻ hơn từ ghế nhà trường sang công việc.', 'Early career guidance can pave the way for a smoother transition from school to work.', '["Early career guidance could pave the way for a smoother transition from school to work.","Early career advice can pave the way for a smoother transition from school to work.","Early career guidance can pave the way for a smoother move from school to work."]'::jsonb, '["pave the way for sth = mở đường cho điều gì (mục 2.1)","career guidance = hướng nghiệp; transition = sự chuyển tiếp; smooth = suôn sẻ"]'::jsonb, 'C1', '3. Trường học'),
    (1, 28, 'Cho phép con tự quản lý tiền tiêu vặt dạy trẻ biết giá trị của việc tiết kiệm.', 'Allowing children to manage their own pocket money teaches them the value of saving.', '["Allowing children to manage their pocket money teaches them the value of saving.","Allowing kids to manage their own pocket money teaches them the value of saving.","Allowing children to handle their own pocket money teaches them the value of saving."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì (mục 2.1)","pocket money = tiền tiêu vặt; manage = quản lý; the value of saving = giá trị của việc tiết kiệm"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (1, 29, 'Cùng đọc truyện trước giờ ngủ giúp trẻ nhỏ hình thành tình yêu với sách.', 'Reading bedtime stories together helps young children develop a love of books.', '["Reading bedtime stories together helps young children to develop a love of books.","Reading bedtime stories together helps young children develop a love for books.","Reading bedtime stories together helps small children develop a love of books."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","bedtime story = truyện kể trước giờ ngủ; develop a love of = hình thành tình yêu với"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (1, 30, 'Chia sẻ việc nhà công bằng giúp cả cha lẫn mẹ có thể theo đuổi sự nghiệp.', 'Sharing housework fairly makes it possible for both parents to pursue their careers.', '["Sharing household chores fairly makes it possible for both parents to pursue their careers.","Sharing the housework fairly makes it possible for both parents to pursue their careers.","Sharing housework equally makes it possible for both parents to pursue their careers."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì (mục 2.1)","share housework = chia sẻ việc nhà; fairly = công bằng; pursue a career = theo đuổi sự nghiệp"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (1, 31, 'Cha mẹ nên để con tuổi teen tự giải quyết mâu thuẫn với bạn bè trước khi can thiệp.', 'Parents should let teenagers resolve their own conflicts with friends before stepping in.', '["Parents should let teenagers solve their own conflicts with friends before stepping in.","Parents should let their teenagers resolve their own conflicts with friends before stepping in.","Parents should let teenagers sort out their own conflicts with friends before stepping in."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật, hay dùng khi nói) (mục 2.1)","resolve a conflict = giải quyết mâu thuẫn; step in = can thiệp"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (1, 32, 'Khen ngợi sự nỗ lực thay vì kết quả khuyến khích trẻ tiếp tục cố gắng khi gặp việc khó.', 'Praising effort rather than results encourages children to keep trying when tasks are difficult.', '["Praising effort instead of results encourages children to keep trying when tasks are difficult.","Praising effort rather than results encourages children to keep trying when tasks get difficult.","Praising effort rather than results encourages kids to keep trying when tasks are difficult."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì (mục 2.1)","praise = khen ngợi; effort = sự nỗ lực; keep trying = tiếp tục cố gắng"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (1, 33, 'Cha mẹ nên cung cấp cho con một góc học tập yên tĩnh ở nhà.', 'Parents should provide their children with a quiet place to study at home.', '["Parents should provide their children with a quiet space to study at home.","Parents should provide children with a quiet place to study at home.","Parents should provide their kids with a quiet place to study at home."]'::jsonb, '["provide sb with sth = cung cấp cho ai cái gì (mục 2.1)","a quiet place to study = góc học tập yên tĩnh; at home = ở nhà"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (1, 34, 'Dạy con phép lịch sự cơ bản là trang bị cho trẻ kỹ năng xã hội để dễ dàng kết bạn.', 'Teaching children basic manners equips them with the social skills to make friends easily.', '["Teaching children good manners equips them with the social skills to make friends easily.","Teaching children basic manners equips them with the social skills needed to make friends easily.","Teaching kids basic manners equips them with the social skills to make friends easily."]'::jsonb, '["equip sb with sth = trang bị cho ai cái gì (mục 2.1)","manners = phép lịch sự; social skills = kỹ năng xã hội; make friends = kết bạn"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (1, 35, 'Cha mẹ nào tự tắt điện thoại của mình sẽ thấy dễ thuyết phục con cất thiết bị đi hơn.', 'Parents who switch off their own phones find it easier to persuade their children to put their devices away.', '["Parents who turn off their own phones find it easier to persuade their children to put their devices away.","Parents who switch off their own phones find it easier to persuade their kids to put their devices away.","Parents who switch off their own phones find it easier to persuade their children to put away their devices."]'::jsonb, '["persuade sb to do sth = thuyết phục ai làm gì (mục 2.1)","switch off = tắt; find it easier to = thấy dễ ... hơn; put sth away = cất đi; device = thiết bị"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (1, 36, 'Giao cho trẻ những trách nhiệm nhỏ trong nhà tiếp sức cho các em lớn lên thành người tự lập.', 'Giving children small responsibilities at home empowers them to grow into independent adults.', '["Giving children small responsibilities at home empowers them to become independent adults.","Giving children small tasks at home empowers them to grow into independent adults.","Giving kids small responsibilities at home empowers them to grow into independent adults."]'::jsonb, '["empower sb to do sth = tạo sức mạnh, trao quyền cho ai làm gì (mục 2.1)","responsibility = trách nhiệm; grow into = lớn lên thành; independent = tự lập"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (1, 37, 'Phần mềm điện toán đám mây giúp các công ty nhỏ có khả năng cạnh tranh với các tập đoàn lớn.', 'Cloud-based software enables small firms to compete with big corporations.', '["Cloud-based software enables small companies to compete with big corporations.","Cloud software enables small firms to compete with big corporations.","Cloud-based software enables small firms to compete with large corporations."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì (mục 2.1)","cloud-based software = phần mềm điện toán đám mây; compete with = cạnh tranh với; corporation = tập đoàn"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (1, 38, 'Chế độ nghỉ phép có lương khi sinh con cho phép nhân viên chăm sóc em bé mà không bị mất thu nhập.', 'Paid parental leave allows employees to care for their newborn babies without losing income.', '["Paid parental leave allows employees to look after their newborn babies without losing income.","Paid parental leave allows staff to care for their newborn babies without losing income.","Paid parental leave allows employees to care for their newborns without losing any income."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì (mục 2.1)","paid parental leave = nghỉ phép có lương khi sinh con; newborn = trẻ sơ sinh; income = thu nhập"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (1, 39, 'Các nhà máy phải cung cấp cho công nhân quần áo và thiết bị bảo hộ đạt chuẩn.', 'Factories must provide their workers with proper protective clothing and equipment.', '["Factories must provide workers with proper protective clothing and equipment.","Factories must provide their workers with suitable protective clothing and equipment.","Factories have to provide their workers with proper protective clothing and equipment."]'::jsonb, '["provide sb with sth = cung cấp cho ai cái gì (mục 2.1)","protective clothing = quần áo bảo hộ; equipment = thiết bị; proper = đạt chuẩn, phù hợp"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (1, 40, 'Chương trình kèm cặp giúp nhân viên mới hòa nhập với công ty nhanh hơn.', 'Mentoring schemes help new employees settle into the company more quickly.', '["Mentoring schemes help new employees to settle into the company more quickly.","Mentoring programmes help new employees settle into the company more quickly.","Mentoring programs help new employees settle into the company more quickly.","Mentoring schemes help new staff settle into the company more quickly."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","mentoring scheme = chương trình kèm cặp; settle into = hòa nhập, làm quen với"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (1, 41, 'Triển vọng hóa đơn tiền điện thấp hơn đã thuyết phục nhiều nhà máy lắp pin mặt trời trên mái.', 'The prospect of lower electricity bills has persuaded many factories to install solar panels on their roofs.', '["The prospect of lower energy bills has persuaded many factories to install solar panels on their roofs.","The prospect of lower electricity bills has persuaded many factories to put solar panels on their roofs.","The prospect of cheaper electricity bills has persuaded many factories to install solar panels on their roofs."]'::jsonb, '["persuade sb to do sth = thuyết phục ai làm gì (mục 2.1)","prospect = triển vọng; electricity bill = hóa đơn tiền điện; solar panel = tấm pin mặt trời"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (1, 42, 'Thưởng theo hiệu suất khuyến khích nhân viên làm việc chăm chỉ hơn và đóng góp ý tưởng mới.', 'Performance bonuses encourage staff to work harder and contribute new ideas.', '["Performance bonuses encourage employees to work harder and contribute new ideas.","Performance-related bonuses encourage staff to work harder and contribute new ideas.","Performance bonuses encourage staff to work harder and to contribute new ideas."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì (mục 2.1)","performance bonus = thưởng theo hiệu suất; work harder = làm việc chăm chỉ hơn; contribute ideas = đóng góp ý tưởng"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (1, 43, 'Các nhà bán lẻ lớn đang trang bị cho nhân viên những kỹ năng số cần thiết cho việc bán hàng trực tuyến.', 'Large retailers are equipping their staff with the digital skills needed for online sales.', '["Big retailers are equipping their staff with the digital skills needed for online sales.","Large retailers are equipping their employees with the digital skills needed for online sales.","Large retailers are equipping their staff with the digital skills required for online sales."]'::jsonb, '["equip sb with sth = trang bị cho ai cái gì (mục 2.1)","retailer = nhà bán lẻ; digital skills = kỹ năng số; online sales = bán hàng trực tuyến"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (1, 44, 'Các chương trình đào tạo lãnh đạo tiếp sức cho nữ nhân viên ứng tuyển vào các vị trí cấp cao.', 'Leadership programmes empower female employees to apply for senior positions.', '["Leadership programs empower female employees to apply for senior positions.","Leadership programmes empower female staff to apply for senior positions.","Leadership training programmes empower female employees to apply for senior positions."]'::jsonb, '["empower sb to do sth = tạo sức mạnh, trao quyền cho ai làm gì (mục 2.1)","leadership programme = chương trình đào tạo lãnh đạo; female employee = nữ nhân viên; senior position = vị trí cấp cao"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (1, 45, 'Tầm soát hằng năm cho phép bác sĩ điều trị ung thư trước khi bệnh lan rộng.', 'Annual screening allows doctors to treat cancer before it spreads.', '["Yearly screening allows doctors to treat cancer before it spreads.","Annual screenings allow doctors to treat cancer before it spreads.","Annual screening allows doctors to treat cancer before it has spread."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì (mục 2.1)","screening = tầm soát; treat = điều trị; spread = lan rộng"]'::jsonb, 'B1', '6. Sức khỏe'),
    (1, 46, 'Bác sĩ gia đình có thể thuyết phục bệnh nhân thừa cân thay đổi thói quen ăn uống.', 'Family doctors can persuade overweight patients to change their eating habits.', '["GPs can persuade overweight patients to change their eating habits.","Family doctors could persuade overweight patients to change their eating habits.","Family doctors can persuade overweight patients to change their diet."]'::jsonb, '["persuade sb to do sth = thuyết phục ai làm gì (mục 2.1)","family doctor (GP) = bác sĩ gia đình; overweight = thừa cân; eating habits = thói quen ăn uống"]'::jsonb, 'B2', '6. Sức khỏe'),
    (1, 47, 'Những lần đi bộ ngắn trong ngày làm việc giúp nhân viên văn phòng giải tỏa căng thẳng.', 'Short walks during the working day help office workers relieve stress.', '["Short walks during the working day help office workers to relieve stress.","Short walks during the workday help office workers relieve stress.","Short walks during the working day help office staff relieve stress."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","relieve stress = giải tỏa căng thẳng; working day = ngày làm việc; office worker = nhân viên văn phòng"]'::jsonb, 'B1', '6. Sức khỏe'),
    (1, 48, 'Bảo hiểm y tế giá phải chăng giúp người lao động thu nhập thấp có thể đi khám bác sĩ sớm.', 'Affordable health insurance makes it possible for low-income workers to see a doctor early.', '["Affordable health insurance makes it possible for low-income workers to visit a doctor early.","Affordable health insurance makes it possible for low-paid workers to see a doctor early.","Affordable health insurance makes it possible for low-income workers to see a doctor at an early stage."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì (mục 2.1)","health insurance = bảo hiểm y tế; affordable = giá phải chăng; low-income = thu nhập thấp"]'::jsonb, 'B2', '6. Sức khỏe'),
    (1, 49, 'Dụng cụ tập thể dục miễn phí trong công viên khuyến khích người dân tập luyện ngoài trời.', 'Free exercise equipment in parks encourages residents to work out outdoors.', '["Free exercise equipment in parks encourages residents to exercise outdoors.","Free fitness equipment in parks encourages residents to work out outdoors.","Free exercise equipment in parks encourages local people to work out outdoors."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì (mục 2.1)","exercise equipment = dụng cụ tập thể dục; work out = tập luyện; outdoors = ngoài trời"]'::jsonb, 'B1', '6. Sức khỏe'),
    (1, 50, 'Khám bệnh từ xa giúp bệnh nhân ở vùng hẻo lánh có khả năng hỏi ý kiến bác sĩ chuyên khoa mà không phải đi xa.', 'Telemedicine enables patients in remote areas to consult specialists without travelling long distances.', '["Telemedicine enables patients in remote areas to consult specialists without traveling long distances.","Telemedicine enables patients in remote areas to see specialists without travelling long distances.","Telemedicine enables patients in remote areas to consult specialists without travelling far."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì (mục 2.1)","telemedicine = khám chữa bệnh từ xa; consult a specialist = hỏi ý kiến bác sĩ chuyên khoa; remote area = vùng hẻo lánh"]'::jsonb, 'B2', '6. Sức khỏe'),
    (1, 51, 'Bệnh viện nên cung cấp cho bệnh nhân lớn tuổi hướng dẫn rõ ràng về cách uống thuốc.', 'Hospitals should provide elderly patients with clear instructions on how to take their medicine.', '["Hospitals should provide older patients with clear instructions on how to take their medicine.","Hospitals should provide elderly patients with clear instructions on how to take their medication.","Hospitals should provide elderly patients with clear guidance on how to take their medicine."]'::jsonb, '["provide sb with sth = cung cấp cho ai cái gì (mục 2.1)","elderly patient = bệnh nhân lớn tuổi; instructions = hướng dẫn; take medicine = uống thuốc"]'::jsonb, 'B2', '6. Sức khỏe'),
    (1, 52, 'Nắm được các dấu hiệu sớm của đột quỵ tiếp sức cho người thân hành động trước khi quá muộn.', 'Knowing the early signs of a stroke empowers relatives to act before it is too late.', '["Knowing the early warning signs of a stroke empowers relatives to act before it is too late.","Knowing the early signs of a stroke empowers family members to act before it is too late.","Knowing the early signs of a stroke empowers relatives to act before it''s too late."]'::jsonb, '["empower sb to do sth = tạo sức mạnh, trao quyền cho ai làm gì (mục 2.1)","stroke = đột quỵ; early signs = dấu hiệu sớm; relative = người thân; too late = quá muộn"]'::jsonb, 'C1', '6. Sức khỏe'),
    (1, 53, 'Giảm giá hóa đơn năng lượng giúp các hộ thu nhập thấp đối phó với chi phí sinh hoạt tăng cao.', 'Discounts on energy bills help low-income households cope with the rising cost of living.', '["Discounts on energy bills help low-income households to cope with the rising cost of living.","Discounts on electricity bills help low-income households cope with the rising cost of living.","Energy bill discounts help low-income households cope with the rising cost of living."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","discount = khoản giảm giá; low-income household = hộ thu nhập thấp; cost of living = chi phí sinh hoạt"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (1, 54, 'Lực lượng lao động có tay nghề giúp một quốc gia có khả năng thu hút các ngành công nghệ cao.', 'A skilled workforce enables a country to attract high-tech industries.', '["A skilled workforce enables a nation to attract high-tech industries.","A skilled labour force enables a country to attract high-tech industries.","A skilled labor force enables a country to attract high-tech industries."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì (mục 2.1)","skilled workforce = lực lượng lao động có tay nghề; attract = thu hút; high-tech industry = ngành công nghệ cao"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (1, 55, 'Chính phủ nên cho các doanh nghiệp nhỏ hoãn nộp thuế trong thời kỳ khủng hoảng kinh tế.', 'The government should let small firms delay their tax payments during an economic crisis.', '["The government should let small businesses delay their tax payments during an economic crisis.","The government should let small firms postpone their tax payments during an economic crisis.","The government should let small firms delay tax payments during an economic crisis."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật, hay dùng khi nói) (mục 2.1)","delay / postpone = hoãn; tax payment = khoản nộp thuế; economic crisis = khủng hoảng kinh tế"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (1, 56, 'Du lịch cung cấp cho các cộng đồng ven biển hàng nghìn việc làm theo mùa.', 'Tourism provides coastal communities with thousands of seasonal jobs.', '["The tourism industry provides coastal communities with thousands of seasonal jobs.","Tourism provides seaside communities with thousands of seasonal jobs.","Tourism provides coastal communities with thousands of jobs each season."]'::jsonb, '["provide sb with sth = cung cấp cho ai cái gì (mục 2.1)","coastal community = cộng đồng ven biển; seasonal job = việc làm theo mùa"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (1, 57, 'Lãi suất thấp khuyến khích các hộ gia đình vay và chi tiêu nhiều hơn.', 'Low interest rates encourage households to borrow and spend more money.', '["Low interest rates encourage households to borrow and spend more.","Low interest rates encourage families to borrow and spend more money.","Low interest rates encourage households to borrow more and spend more."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì (mục 2.1)","interest rate = lãi suất; borrow = vay; spend = chi tiêu"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (1, 58, 'Các khoản vay cho doanh nghiệp nhỏ giúp người trẻ mới tốt nghiệp có thể biến ý tưởng thành công ty.', 'Small business loans make it possible for young graduates to turn their ideas into companies.', '["Small business loans make it possible for recent graduates to turn their ideas into companies.","Small business loans make it possible for young graduates to turn their ideas into businesses.","Loans for small businesses make it possible for young graduates to turn their ideas into companies."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì (mục 2.1)","business loan = khoản vay kinh doanh; graduate = người tốt nghiệp; turn A into B = biến A thành B"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (1, 59, 'Các chương trình học nghề trang bị cho người vừa rời ghế nhà trường những kỹ năng mà nhà máy địa phương cần.', 'Apprenticeships equip school leavers with the skills that local factories need.', '["Apprenticeships equip school leavers with the skills local factories need.","Apprenticeship schemes equip school leavers with the skills that local factories need.","Apprenticeships equip school leavers with the skills that local factories require."]'::jsonb, '["equip sb with sth = trang bị cho ai cái gì (mục 2.1)","apprenticeship = học nghề (vừa học vừa làm); school leaver = người vừa rời ghế nhà trường"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (1, 60, 'Một cảng nước sâu mới có thể mở đường cho sự bùng nổ xuất khẩu.', 'A new deep-water port could pave the way for a boom in exports.', '["A new deep-water port could pave the way for an export boom.","A new deep-water port can pave the way for a boom in exports.","A new deepwater port could pave the way for a boom in exports."]'::jsonb, '["pave the way for sth = mở đường cho điều gì (mục 2.1)","deep-water port = cảng nước sâu; boom = sự bùng nổ; export = xuất khẩu"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (1, 61, 'Vườn chung cho phép cư dân nhà cao tầng làm quen với hàng xóm.', 'Shared gardens allow residents of high-rise buildings to get to know their neighbours.', '["Shared gardens allow residents of high-rise buildings to get to know their neighbors.","Community gardens allow residents of high-rise buildings to get to know their neighbours.","Shared gardens allow people living in high-rise buildings to get to know their neighbours."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì (mục 2.1)","shared garden = vườn chung; high-rise building = nhà cao tầng; get to know = làm quen"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (1, 62, 'Các ngân hàng thực phẩm cung cấp cho những gia đình khó khăn thực phẩm miễn phí hằng tuần.', 'Food banks provide struggling families with free groceries every week.', '["Food banks provide families in need with free groceries every week.","Food banks provide struggling families with free food every week.","Food banks provide poor families with free groceries every week."]'::jsonb, '["provide sb with sth = cung cấp cho ai cái gì (mục 2.1)","food bank = ngân hàng thực phẩm; struggling = gặp khó khăn; groceries = thực phẩm, nhu yếu phẩm"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (1, 63, 'Xã hội nên để người nhập cư đóng góp kỹ năng của mình thay vì gạt họ ra bên lề.', 'Society should let immigrants contribute their skills instead of marginalising them.', '["Society should let immigrants contribute their skills instead of marginalizing them.","Society should let immigrants contribute their skills rather than marginalising them.","Society should let migrants contribute their skills instead of marginalising them."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật, hay dùng khi nói) (mục 2.1)","immigrant = người nhập cư; contribute = đóng góp; marginalise = gạt ra bên lề"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (1, 64, 'Các nhóm tự quản an ninh khu phố giúp cư dân trông chừng lẫn nhau.', 'Neighbourhood watch groups help residents look out for one another.', '["Neighborhood watch groups help residents look out for one another.","Neighbourhood watch groups help residents to look out for one another.","Neighbourhood watch groups help residents look out for each other."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","neighbourhood watch = nhóm tự quản an ninh khu phố; look out for = trông chừng, để ý giúp; one another = lẫn nhau"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (1, 65, 'Các trung tâm dạy nghề trang bị cho người mãn hạn tù những kỹ năng để làm lại cuộc đời.', 'Job training centres equip former prisoners with the skills to rebuild their lives.', '["Job training centers equip former prisoners with the skills to rebuild their lives.","Job training centres equip ex-prisoners with the skills to rebuild their lives.","Job training centres equip former prisoners with the skills needed to rebuild their lives."]'::jsonb, '["equip sb with sth = trang bị cho ai cái gì (mục 2.1)","job training centre = trung tâm dạy nghề; former prisoner = người mãn hạn tù; rebuild one''s life = làm lại cuộc đời"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (1, 66, 'Lễ hội địa phương khuyến khích những người có xuất thân khác nhau cùng nhau vui hội.', 'Local festivals encourage people from different backgrounds to celebrate together.', '["Local festivals encourage people of different backgrounds to celebrate together.","Local festivals encourage people from diverse backgrounds to celebrate together.","Community festivals encourage people from different backgrounds to celebrate together."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì (mục 2.1)","background = xuất thân; celebrate together = cùng nhau vui hội"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (1, 67, 'Học bổng dành cho học sinh dân tộc thiểu số tiếp sức cho các em thoát khỏi vòng luẩn quẩn của nghèo đói.', 'Scholarships for ethnic minority students empower them to break the cycle of poverty.', '["Scholarships for ethnic minority students empower them to escape the cycle of poverty.","Scholarships for students from ethnic minorities empower them to break the cycle of poverty.","Scholarships for ethnic minority students can empower them to break the cycle of poverty."]'::jsonb, '["empower sb to do sth = tạo sức mạnh, trao quyền cho ai làm gì (mục 2.1)","ethnic minority = dân tộc thiểu số; scholarship = học bổng; break the cycle of poverty = thoát khỏi vòng luẩn quẩn của nghèo đói"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (1, 68, 'Tôn trọng sự khác biệt văn hóa mở đường cho một xã hội hài hòa hơn.', 'Respect for cultural differences paves the way for a more harmonious society.', '["Respecting cultural differences paves the way for a more harmonious society.","Respect for cultural differences can pave the way for a more harmonious society.","Respect for cultural diversity paves the way for a more harmonious society."]'::jsonb, '["pave the way for sth = mở đường cho điều gì (mục 2.1)","respect for = sự tôn trọng; cultural difference = khác biệt văn hóa; harmonious = hài hòa"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (1, 69, 'Chương trình hoàn tiền vỏ chai khuyến khích người mua hàng mang chai rỗng trả lại để tái chế.', 'Bottle deposit schemes encourage shoppers to return empty bottles for recycling.', '["Deposit return schemes encourage shoppers to return empty bottles for recycling.","Bottle deposit schemes encourage consumers to return empty bottles for recycling.","Bottle deposit schemes encourage shoppers to bring back empty bottles for recycling."]'::jsonb, '["encourage sb to do sth = khuyến khích ai làm gì (mục 2.1)","deposit scheme = chương trình đặt cọc, hoàn tiền vỏ chai; return = trả lại; recycling = tái chế"]'::jsonb, 'B1', '9. Môi trường'),
    (1, 70, 'Những ngày Chủ nhật không ô tô cho người dân thành phố được hít thở không khí sạch hơn và đi bộ an toàn.', 'Car-free Sundays let city residents breathe cleaner air and walk safely.', '["Car-free Sundays let city dwellers breathe cleaner air and walk safely.","Car-free Sundays let residents breathe cleaner air and walk safely.","Car-free Sundays let city residents breathe cleaner air and walk around safely."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật, hay dùng khi nói) (mục 2.1)","car-free = không có ô tô; city dweller = người dân thành phố; breathe = hít thở"]'::jsonb, 'B1', '9. Môi trường'),
    (1, 71, 'Các cơ quan môi trường nên trang bị cho thanh tra viên cảm biến hiện đại để đo khí thải nhà máy.', 'Environmental agencies should equip inspectors with modern sensors to measure factory emissions.', '["Environmental agencies should equip their inspectors with modern sensors to measure factory emissions.","Environmental agencies should equip inspectors with modern sensors for measuring factory emissions.","Environmental agencies should equip inspectors with advanced sensors to measure factory emissions."]'::jsonb, '["equip sb with sth = trang bị cho ai cái gì (mục 2.1)","environmental agency = cơ quan môi trường; inspector = thanh tra viên; sensor = cảm biến; emissions = khí thải"]'::jsonb, 'B2', '9. Môi trường'),
    (1, 72, 'Giống cây chịu hạn giúp nông dân có khả năng trồng lương thực trong điều kiện ngày càng khô hạn.', 'Drought-resistant crops enable farmers to grow food in increasingly dry conditions.', '["Drought-tolerant crops enable farmers to grow food in increasingly dry conditions.","Drought-resistant crop varieties enable farmers to grow food in increasingly dry conditions.","Drought-resistant crops enable farmers to grow food in ever drier conditions."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì (mục 2.1)","drought-resistant = chịu hạn; crop = cây trồng; increasingly = ngày càng"]'::jsonb, 'B2', '9. Môi trường'),
    (1, 73, 'Các phim tài liệu về rác nhựa trong đại dương đã thuyết phục nhiều khán giả từ bỏ chai nhựa dùng một lần.', 'Documentaries about plastic waste in the oceans have persuaded many viewers to give up single-use plastic bottles.', '["Documentaries about plastic waste in the ocean have persuaded many viewers to give up single-use plastic bottles.","Documentaries on plastic waste in the oceans have persuaded many viewers to give up single-use plastic bottles.","Documentaries about plastic waste in the oceans have persuaded many viewers to give up disposable plastic bottles."]'::jsonb, '["persuade sb to do sth = thuyết phục ai làm gì (mục 2.1)","documentary = phim tài liệu; viewer = khán giả; single-use = dùng một lần; give up = từ bỏ"]'::jsonb, 'B2', '9. Môi trường'),
    (1, 74, 'Nhà máy đốt rác phát điện giúp các thành phố có thể biến rác sinh hoạt thành điện năng.', 'Waste-to-energy plants make it possible for cities to turn household rubbish into electricity.', '["Waste-to-energy plants make it possible for cities to turn household waste into electricity.","Waste-to-energy plants make it possible for cities to convert household rubbish into electricity.","Waste-to-energy facilities make it possible for cities to turn household rubbish into electricity."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì (mục 2.1)","waste-to-energy plant = nhà máy đốt rác phát điện; household rubbish = rác sinh hoạt; turn A into B = biến A thành B"]'::jsonb, 'B2', '9. Môi trường'),
    (1, 75, 'Giao quyền quản lý rừng cho cộng đồng tiếp sức cho dân làng bảo vệ rừng khỏi nạn khai thác gỗ trái phép.', 'Giving communities control of local forests empowers villagers to protect them from illegal logging.', '["Giving communities control over local forests empowers villagers to protect them from illegal logging.","Giving local communities control of forests empowers villagers to protect them from illegal logging.","Giving communities control of local forests empowers villagers to defend them against illegal logging."]'::jsonb, '["empower sb to do sth = tạo sức mạnh, trao quyền cho ai làm gì (mục 2.1)","control of / over = quyền quản lý, kiểm soát; villager = dân làng; illegal logging = khai thác gỗ trái phép"]'::jsonb, 'C1', '9. Môi trường'),
    (1, 76, 'Giá pin giảm đang mở đường cho việc sử dụng rộng rãi ô tô điện.', 'Falling battery prices are paving the way for the widespread use of electric cars.', '["Falling battery prices are paving the way for widespread use of electric cars.","Falling battery costs are paving the way for the widespread use of electric cars.","Falling battery prices are paving the way for the widespread use of electric vehicles."]'::jsonb, '["pave the way for sth = mở đường cho điều gì (mục 2.1)","battery = pin; falling = đang giảm; widespread = rộng rãi; electric car = ô tô điện"]'::jsonb, 'C1', '9. Môi trường'),
    (1, 77, 'Chi phí nhân công tăng đã thuyết phục nhiều nhà sản xuất thay công nhân bằng robot.', 'Rising labour costs have persuaded many manufacturers to replace workers with robots.', '["Rising labor costs have persuaded many manufacturers to replace workers with robots.","Rising labour costs have persuaded many manufacturers to replace their workers with robots.","Higher labour costs have persuaded many manufacturers to replace workers with robots."]'::jsonb, '["persuade sb to do sth = thuyết phục ai làm gì (mục 2.1)","labour costs = chi phí nhân công; manufacturer = nhà sản xuất; replace A with B = thay A bằng B"]'::jsonb, 'B2', '10. Công nghệ'),
    (1, 78, 'Cài đặt quyền riêng tư cho phép người dùng quyết định ai được xem thông tin cá nhân của mình.', 'Privacy settings allow users to decide who can see their personal information.', '["Privacy settings allow users to choose who can see their personal information.","Privacy settings allow users to decide who can view their personal information.","Privacy settings allow users to decide who is able to see their personal information."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì (mục 2.1)","privacy settings = cài đặt quyền riêng tư; personal information = thông tin cá nhân"]'::jsonb, 'B1', '10. Công nghệ'),
    (1, 79, 'Trí tuệ nhân tạo giúp bệnh viện có khả năng phân tích hàng nghìn ảnh chụp chiếu chỉ trong vài phút.', 'Artificial intelligence enables hospitals to analyse thousands of scans in just a few minutes.', '["Artificial intelligence enables hospitals to analyze thousands of scans in just a few minutes.","AI enables hospitals to analyse thousands of scans in just a few minutes.","Artificial intelligence enables hospitals to analyse thousands of scans within a few minutes."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì (mục 2.1)","artificial intelligence (AI) = trí tuệ nhân tạo; analyse = phân tích; scan = ảnh chụp chiếu (X-quang, CT)"]'::jsonb, 'B2', '10. Công nghệ'),
    (1, 80, 'Một số cha mẹ để con nhỏ dùng máy tính bảng mà không hề có sự giám sát.', 'Some parents let young children use tablets without any supervision.', '["Some parents let young children use tablets without supervision.","Some parents let their young children use tablets without any supervision.","Some parents let small children use tablets without any supervision."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật, hay dùng khi nói) (mục 2.1)","tablet = máy tính bảng; supervision = sự giám sát"]'::jsonb, 'B1', '10. Công nghệ'),
    (1, 81, 'Các buổi học lập trình miễn phí giúp người lao động lớn tuổi thích nghi với nền kinh tế số.', 'Free coding workshops help older workers adapt to the digital economy.', '["Free coding workshops help older workers to adapt to the digital economy.","Free programming workshops help older workers adapt to the digital economy.","Free coding workshops help older employees adapt to the digital economy."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","coding workshop = buổi học lập trình; adapt to = thích nghi với; digital economy = kinh tế số"]'::jsonb, 'B1', '10. Công nghệ'),
    (1, 82, 'Trợ lý giọng nói giúp người có thị lực kém có thể sử dụng Internet.', 'Voice assistants make it possible for people with poor eyesight to use the Internet.', '["Voice assistants make it possible for people with poor eyesight to go online.","Voice assistants make it possible for people with weak eyesight to use the Internet.","Voice assistants make it possible for people with poor vision to use the Internet."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì (mục 2.1)","voice assistant = trợ lý giọng nói; eyesight = thị lực; go online = lên mạng"]'::jsonb, 'B2', '10. Công nghệ'),
    (1, 83, 'Các bài học về hiểu biết truyền thông trang bị cho thanh thiếu niên khả năng nhận diện tin giả.', 'Media literacy lessons equip teenagers with the ability to spot fake news.', '["Media literacy lessons equip teenagers with the ability to identify fake news.","Media literacy classes equip teenagers with the ability to spot fake news.","Media literacy lessons equip teenagers with the ability to recognise fake news.","Media literacy lessons equip teenagers with the ability to recognize fake news."]'::jsonb, '["equip sb with sth = trang bị cho ai cái gì (mục 2.1)","media literacy = hiểu biết truyền thông; spot = nhận ra; fake news = tin giả"]'::jsonb, 'B2', '10. Công nghệ'),
    (1, 84, 'Mạng di động tốc độ cao đã mở đường cho nhà thông minh và thành phố kết nối.', 'High-speed mobile networks have paved the way for smart homes and connected cities.', '["Fast mobile networks have paved the way for smart homes and connected cities.","High-speed mobile networks paved the way for smart homes and connected cities.","High-speed mobile networks have paved the way for smart houses and connected cities."]'::jsonb, '["pave the way for sth = mở đường cho điều gì (mục 2.1)","mobile network = mạng di động; smart home = nhà thông minh; connected = kết nối"]'::jsonb, 'C1', '10. Công nghệ'),
    (1, 85, 'Nhiều công ty giờ đây cho nhân viên bắt đầu làm việc muộn hơn để tránh giờ cao điểm buổi sáng.', 'Many firms now let staff start work later to avoid the morning rush hour.', '["Many companies now let staff start work later to avoid the morning rush hour.","Many firms now let employees start work later to avoid the morning rush hour.","Many firms now let staff begin work later to avoid the morning rush hour."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật, hay dùng khi nói) (mục 2.1)","start work = bắt đầu làm việc; avoid = tránh; rush hour = giờ cao điểm"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (1, 86, 'Hệ thống đặt lịch trực tuyến cho phép bệnh nhân đặt lịch hẹn mà không cần gọi điện đến phòng khám.', 'Online booking systems allow patients to make an appointment without phoning the clinic.', '["Online booking systems allow patients to book an appointment without phoning the clinic.","Online booking systems allow patients to make an appointment without calling the clinic.","Online booking systems allow patients to make appointments without phoning the clinic."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì (mục 2.1)","booking system = hệ thống đặt lịch; make an appointment = đặt lịch hẹn; phone (động từ) = gọi điện"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (1, 87, 'Ứng dụng xe buýt theo thời gian thực cung cấp cho người đi làm giờ xe đến chính xác.', 'Real-time bus apps provide commuters with accurate arrival times.', '["Real-time bus apps provide commuters with exact arrival times.","Real-time bus apps provide passengers with accurate arrival times.","Live bus tracking apps provide commuters with accurate arrival times."]'::jsonb, '["provide sb with sth = cung cấp cho ai cái gì (mục 2.1)","real-time = theo thời gian thực; commuter = người đi làm hằng ngày; arrival time = giờ đến"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (1, 88, 'Dịch vụ giao nguyên liệu sơ chế sẵn giúp các bậc cha mẹ bận rộn có thể nấu bữa tối lành mạnh trong hai mươi phút.', 'Meal-kit deliveries make it possible for busy parents to cook a healthy dinner in twenty minutes.', '["Meal-kit services make it possible for busy parents to cook a healthy dinner in twenty minutes.","Meal-kit deliveries make it possible for busy parents to cook a healthy dinner in 20 minutes.","Meal-kit deliveries make it possible for busy parents to prepare a healthy dinner in twenty minutes."]'::jsonb, '["make it possible for sb to do sth = giúp ai có thể làm gì (mục 2.1)","meal kit = bộ nguyên liệu sơ chế sẵn; delivery = dịch vụ giao hàng; busy = bận rộn"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (1, 89, 'Khai thuế trực tuyến giúp người dân có khả năng hoàn tất toàn bộ thủ tục trong chưa đầy một giờ.', 'Online tax filing enables citizens to complete the whole process in under an hour.', '["Online tax filing enables citizens to complete the whole process in less than an hour.","Filing taxes online enables citizens to complete the whole process in under an hour.","Online tax filing enables people to complete the whole process in under an hour."]'::jsonb, '["enable sb to do sth = giúp ai có khả năng làm gì (mục 2.1)","tax filing = khai thuế; complete = hoàn tất; in under an hour = trong chưa đầy một giờ"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (1, 90, 'Những hàng dài chờ đợi ở chi nhánh ngân hàng đã thuyết phục nhiều khách hàng chuyển sang ngân hàng di động.', 'Long queues at bank branches have persuaded many customers to switch to mobile banking.', '["Long lines at bank branches have persuaded many customers to switch to mobile banking.","Long queues at bank branches have persuaded many customers to move to mobile banking.","Long queues in bank branches have persuaded many customers to switch to mobile banking."]'::jsonb, '["persuade sb to do sth = thuyết phục ai làm gì (mục 2.1)","queue = hàng người xếp chờ; bank branch = chi nhánh ngân hàng; switch to = chuyển sang"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (1, 91, 'Các khóa học quản lý thời gian trang bị cho người đi làm bận rộn những cách đơn giản để sắp xếp thứ tự ưu tiên công việc.', 'Time management courses equip busy professionals with simple ways to prioritise their tasks.', '["Time management courses equip busy professionals with simple ways to prioritize their tasks.","Time management courses equip busy professionals with simple methods to prioritise their tasks.","Time management training equips busy professionals with simple ways to prioritise their tasks."]'::jsonb, '["equip sb with sth = trang bị cho ai cái gì (mục 2.1)","time management = quản lý thời gian; busy professional = người đi làm bận rộn; prioritise = sắp xếp thứ tự ưu tiên"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (1, 92, 'Thanh toán không tiếp xúc đã mở đường cho việc mua sắm nhanh gọn và đơn giản hơn.', 'Contactless payment has paved the way for faster and simpler shopping.', '["Contactless payments have paved the way for faster and simpler shopping.","Contactless payment has paved the way for quicker and simpler shopping.","Contactless payment paved the way for faster and simpler shopping."]'::jsonb, '["pave the way for sth = mở đường cho điều gì (mục 2.1)","contactless payment = thanh toán không tiếp xúc; simple = đơn giản"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (1, 93, 'Chi phí vận hành thấp hơn trong mười năm có thể thuyết phục các gia đình mua thiết bị tiết kiệm năng lượng.', 'Lower running costs over ten years can persuade families to buy energy-efficient appliances.', '["Lower running costs over a decade can persuade families to buy energy-efficient appliances.","Lower running costs over ten years can persuade households to buy energy-efficient appliances.","Lower running costs over ten years could persuade families to buy energy-efficient appliances."]'::jsonb, '["persuade sb to do sth = thuyết phục ai làm gì (mục 2.1)","running costs = chi phí vận hành; energy-efficient = tiết kiệm năng lượng; appliance = thiết bị gia dụng"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (1, 94, 'Cử tri không nên để những lời hứa ngắn hạn làm mình xao nhãng khỏi các vấn đề lâu dài.', 'Voters should not let short-term promises distract them from long-term problems.', '["Voters shouldn''t let short-term promises distract them from long-term problems.","Voters should not let short-term promises distract them from long-term issues.","Voters shouldn''t let short-term promises distract them from long-term issues."]'::jsonb, '["let sb do sth = để ai làm gì (thân mật, hay dùng khi nói) (mục 2.1)","voter = cử tri; distract sb from sth = làm ai xao nhãng khỏi; short-term / long-term = ngắn hạn / lâu dài"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (1, 95, 'Tiết kiệm một khoản nhỏ mỗi tháng cho phép người lao động trẻ có cuộc sống hưu trí thoải mái nhiều thập kỷ sau.', 'Saving a small amount every month allows young workers to enjoy a comfortable retirement decades later.', '["Saving a small amount each month allows young workers to enjoy a comfortable retirement decades later.","Saving a little every month allows young workers to enjoy a comfortable retirement decades later.","Saving a small sum every month allows young workers to enjoy a comfortable retirement decades later."]'::jsonb, '["allow sb to do sth = cho phép ai làm gì (mục 2.1)","retirement = cuộc sống hưu trí; comfortable = thoải mái, sung túc; decades later = nhiều thập kỷ sau"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (1, 96, 'Chính phủ nên cung cấp cho thợ mỏ than các khoản trợ cấp đào tạo lại khi mỏ đóng cửa.', 'The government should provide coal miners with retraining grants when the mines close.', '["The government should provide coal miners with retraining grants when mines close.","The government should provide coal miners with grants for retraining when the mines close.","The state should provide coal miners with retraining grants when the mines close."]'::jsonb, '["provide sb with sth = cung cấp cho ai cái gì (mục 2.1)","coal miner = thợ mỏ than; retraining grant = trợ cấp đào tạo lại; close = đóng cửa"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (1, 97, 'Trồng cây dọc các tuyến phố hôm nay sẽ giúp cư dân tương lai được mát mẻ trong những mùa hè nóng hơn.', 'Planting trees along streets today will help future residents stay cool during hotter summers.', '["Planting trees along streets today will help future residents to stay cool during hotter summers.","Planting trees along the streets today will help future residents stay cool during hotter summers.","Planting trees along streets now will help future residents stay cool during hotter summers."]'::jsonb, '["help sb (to) do sth = giúp ai làm gì (mục 2.1)","plant trees = trồng cây; stay cool = được mát mẻ; future residents = cư dân tương lai"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (1, 98, 'Đầu tư vào giáo dục hôm nay trang bị cho thế hệ sau những kỹ năng để đối mặt với thách thức trong tương lai.', 'Investing in education today equips the next generation with the skills to face future challenges.', '["Investment in education today equips the next generation with the skills to face future challenges.","Investing in education today equips the next generation with the skills to deal with future challenges.","Investing in education now equips the next generation with the skills to face future challenges."]'::jsonb, '["equip sb with sth = trang bị cho ai cái gì (mục 2.1)","invest in = đầu tư vào; next generation = thế hệ sau; face challenges = đối mặt với thách thức"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (1, 99, 'Nguồn tài trợ ổn định dài hạn tiếp sức cho các nhà nghiên cứu theo đuổi những dự án có thể mất hàng chục năm mới thành công.', 'Stable long-term funding empowers researchers to pursue projects that may take decades to succeed.', '["Stable long-term funding empowers researchers to pursue projects that might take decades to succeed.","Steady long-term funding empowers researchers to pursue projects that may take decades to succeed.","Stable long-term funding empowers scientists to pursue projects that may take decades to succeed."]'::jsonb, '["empower sb to do sth = tạo sức mạnh, trao quyền cho ai làm gì (mục 2.1)","long-term funding = nguồn tài trợ dài hạn; pursue = theo đuổi; decade = thập kỷ; succeed = thành công"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (1, 100, 'Giai đoạn thích nghi khó khăn sau một cuộc cải cách thường mở đường cho nhiều năm năng suất cao hơn.', 'The difficult adjustment period after a reform often paves the way for years of higher productivity.', '["The difficult period of adjustment after a reform often paves the way for years of higher productivity.","A difficult adjustment period after a reform often paves the way for years of higher productivity.","The tough adjustment period after a reform often paves the way for years of higher productivity."]'::jsonb, '["pave the way for sth = mở đường cho điều gì (mục 2.1)","adjustment period = giai đoạn thích nghi; reform = cải cách; productivity = năng suất"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (2, 1, 'Chính quyền địa phương nên ngăn không cho các chủ đầu tư xây nhà ở những khu vực hay bị ngập lụt.', 'Local authorities should prevent developers from building homes in areas that often flood.', '["Local authorities should prevent developers from building houses in areas that often flood.","Local authorities should prevent developers from building homes in areas that frequently flood.","Local councils should prevent developers from building homes in areas that often flood."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","local authorities = chính quyền địa phương; developer = chủ đầu tư; flood = ngập lụt; prevent sb from + V-ing"]'::jsonb, 'B2', '1. Chính phủ'),
    (2, 2, 'Chỉ luật pháp quốc gia mới có thể buộc mọi doanh nghiệp trong nước phải tuân theo cùng một bộ quy tắc an toàn.', 'Only national laws can force every business in the country to follow the same safety rules.', '["Only national laws can compel every business in the country to follow the same safety rules.","Only national laws can force all businesses in the country to follow the same safety rules.","Only national legislation can force every business in the country to follow the same safety rules."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","national laws = luật pháp quốc gia; safety rules = quy tắc an toàn; force / compel sb to do = buộc ai phải làm"]'::jsonb, 'B2', '1. Chính phủ'),
    (2, 3, 'Nếu không có sự quản lý của nhà nước, sẽ chẳng có gì ngăn được các công ty bóc lột người lao động của mình.', 'Without state regulation, nothing would stop companies from exploiting their workers.', '["Without state regulation, nothing would stop companies exploiting their workers.","Without government regulation, nothing would stop companies from exploiting their workers.","Without state regulation, nothing would stop firms from exploiting their workers."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","state regulation = sự quản lý của nhà nước; exploit = bóc lột; stop sb (from) + V-ing"]'::jsonb, 'B1', '1. Chính phủ'),
    (2, 4, 'Cắt giảm chi tiêu công có thể khiến các vùng nông thôn thiếu bệnh viện và trường học đạt chuẩn.', 'Cuts to public spending can deprive rural areas of decent hospitals and schools.', '["Cuts in public spending can deprive rural areas of decent hospitals and schools.","Public spending cuts can deprive rural areas of decent hospitals and schools.","Cuts to public spending may deprive rural areas of decent hospitals and schools."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","public spending = chi tiêu công; rural areas = vùng nông thôn; decent = tử tế, đạt chuẩn; deprive sb of sth = khiến ai thiếu cái gì"]'::jsonb, 'C1', '1. Chính phủ'),
    (2, 5, 'Kiểm toán thường xuyên có thể răn đe các quan chức không lạm dụng ngân sách công.', 'Regular audits can deter officials from misusing public funds.', '["Regular audits may deter officials from misusing public funds.","Regular audits can deter officials from misusing public money.","Frequent audits can deter officials from misusing public funds."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","audit = kiểm toán; official = quan chức; misuse = lạm dụng, dùng sai mục đích; public funds = ngân sách công"]'::jsonb, 'C1', '1. Chính phủ'),
    (2, 6, 'Chính phủ có thể yêu cầu các nhà hàng phải ghi rõ lượng calo của từng món trên thực đơn.', 'The government could require restaurants to show the calorie content of each dish on their menus.', '["The government could require restaurants to display the calorie content of each dish on their menus.","The government can require restaurants to show the calorie content of each dish on their menus.","Governments could require restaurants to show the calorie content of each dish on their menus."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","calorie content = lượng calo; menu = thực đơn; require sb to do = yêu cầu ai phải làm"]'::jsonb, 'B2', '1. Chính phủ'),
    (2, 7, 'Chính phủ nên cấm các công ty thuốc lá tài trợ cho các sự kiện thể thao.', 'The government should ban tobacco companies from sponsoring sports events.', '["The government should prohibit tobacco companies from sponsoring sports events.","The government should ban tobacco companies from sponsoring sporting events.","Governments should ban tobacco companies from sponsoring sports events."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","tobacco company = công ty thuốc lá; sponsor = tài trợ; ban sb from + V-ing = cấm ai làm gì"]'::jsonb, 'C1', '1. Chính phủ'),
    (2, 8, 'Thủ tục giấy tờ rườm rà có thể khiến người dân nản lòng, không muốn tự mở doanh nghiệp.', 'Complicated paperwork can discourage citizens from starting their own businesses.', '["Complicated paperwork may discourage citizens from starting their own businesses.","Complicated paperwork can discourage people from starting their own businesses.","Complex paperwork can discourage citizens from starting their own businesses."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","paperwork = thủ tục giấy tờ; start a business = mở doanh nghiệp; discourage sb from + V-ing = khiến ai nản, không muốn làm gì"]'::jsonb, 'B2', '1. Chính phủ'),
    (2, 9, 'Trước mắt, sự phản đối của người dân có thể cản trở việc triển khai các chính sách mới.', 'In the short term, public opposition can hinder the implementation of new policies.', '["In the short term, public opposition can impede the implementation of new policies.","In the short term, public opposition may hinder the implementation of new policies.","In the short run, public opposition can hinder the implementation of new policies."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","public opposition = sự phản đối của người dân; implementation = việc triển khai; hinder = cản trở"]'::jsonb, 'C1', '1. Chính phủ'),
    (2, 10, 'Đơn kiến nghị của những người dân bình thường có thể buộc chính quyền địa phương phải xem xét lại các quyết định không được lòng dân.', 'Petitions from ordinary citizens can force local authorities to reconsider unpopular decisions.', '["Petitions from ordinary citizens can compel local authorities to reconsider unpopular decisions.","Petitions from ordinary citizens may force local authorities to reconsider unpopular decisions.","Petitions from ordinary people can force local authorities to reconsider unpopular decisions."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","petition = đơn kiến nghị; reconsider = xem xét lại; unpopular = không được lòng dân; force sb to do = buộc ai phải làm"]'::jsonb, 'B2', '2. Cá nhân'),
    (2, 11, 'Mua sắm bốc đồng có thể khiến nhiều người thiếu khoản tiết kiệm cần có cho những lúc khó khăn.', 'Impulse buying can deprive many people of the savings they need for hard times.', '["Impulse shopping can deprive many people of the savings they need for hard times.","Impulse buying may deprive many people of the savings they need for hard times.","Impulse buying can deprive many people of the savings they need in hard times."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","impulse buying = mua sắm bốc đồng; savings = khoản tiết kiệm; hard times = lúc khó khăn; deprive sb of sth"]'::jsonb, 'C1', '2. Cá nhân'),
    (2, 12, 'Việc đổ lỗi cho người khác về mọi vấn đề cản trở sự trưởng thành của bản thân.', 'Blaming others for every problem hinders personal growth.', '["Blaming others for every problem impedes personal growth.","Blaming other people for every problem hinders personal growth.","Blaming others for all problems hinders personal growth."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","blame sb for sth = đổ lỗi cho ai về việc gì; personal growth = sự trưởng thành của bản thân; hinder = cản trở"]'::jsonb, 'C1', '2. Cá nhân'),
    (2, 13, 'Lựa chọn của một người có thể khiến bạn bè họ suy nghĩ lại về thói quen của chính mình.', 'One person''s choices can make their friends rethink their own habits.', '["One person''s choices could make their friends rethink their own habits.","One person''s decisions can make their friends rethink their own habits.","A single person''s choices can make their friends rethink their own habits."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","rethink = suy nghĩ lại; habit = thói quen; make sb do sth = khiến ai làm gì (V nguyên mẫu không to)"]'::jsonb, 'B1', '2. Cá nhân'),
    (2, 14, 'Nỗi sợ bị người khác đánh giá có thể răn đe người trẻ không xả rác nơi công cộng.', 'The fear of being judged by others can deter young people from dropping litter in public.', '["Fear of being judged by others can deter young people from dropping litter in public.","The fear of being judged by others may deter young people from dropping litter in public.","The fear of being judged by others can deter young people from littering in public."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","be judged = bị đánh giá; drop litter = xả rác; in public = nơi công cộng; deter sb from + V-ing"]'::jsonb, 'C1', '2. Cá nhân'),
    (2, 15, 'Đọc kỹ nhãn sản phẩm có thể ngăn người tiêu dùng mua phải những món hàng có hại cho sức khỏe.', 'Reading labels carefully can prevent consumers from buying products that harm their health.', '["Reading labels carefully may prevent consumers from buying products that harm their health.","Reading labels carefully can prevent shoppers from buying products that harm their health.","Reading the labels carefully can prevent consumers from buying products that harm their health."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","label = nhãn sản phẩm; consumer = người tiêu dùng; harm = gây hại; prevent sb from + V-ing"]'::jsonb, 'B2', '2. Cá nhân'),
    (2, 16, 'Sự thiếu ý chí thường ngăn mọi người giữ được thói quen mới lâu dài.', 'A lack of willpower often stops people from sticking to new habits for long.', '["A lack of willpower often stops people sticking to new habits for long.","Lack of willpower often stops people from sticking to new habits for long.","A lack of willpower frequently stops people from sticking to new habits for long."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","willpower = ý chí; stick to sth = duy trì, bám theo; stop sb (from) + V-ing"]'::jsonb, 'B1', '2. Cá nhân'),
    (2, 17, 'Bỏ một thói quen xấu đòi hỏi mỗi người phải kiên trì trong nhiều tháng chứ không chỉ vài ngày.', 'Breaking a bad habit requires people to stay committed for months, not just a few days.', '["Breaking a bad habit requires people to stay committed for months rather than just a few days.","Giving up a bad habit requires people to stay committed for months, not just a few days.","Breaking a bad habit requires individuals to stay committed for months, not just a few days."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","break a habit = bỏ thói quen; stay committed = kiên trì; require sb to do = đòi hỏi ai phải làm"]'::jsonb, 'B2', '2. Cá nhân'),
    (2, 18, 'Niềm tin rằng một người không thể tạo ra khác biệt khiến nhiều người ngại hành động.', 'The belief that one person cannot make a difference discourages many people from taking action.', '["The belief that one person can''t make a difference discourages many people from taking action.","The feeling that one person cannot make a difference discourages many people from taking action.","The belief that one person cannot make a difference discourages many people from acting."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","make a difference = tạo ra khác biệt; take action = hành động; discourage sb from + V-ing"]'::jsonb, 'B2', '2. Cá nhân'),
    (2, 19, 'Sĩ số lớp quá đông cản trở sự tiến bộ của học sinh vì giáo viên không thể hỗ trợ tất cả các em.', 'Overcrowded classes hinder students'' progress because teachers cannot help everyone.', '["Overcrowded classes impede students'' progress because teachers cannot help everyone.","Overcrowded classes hinder students'' progress because teachers can''t help everyone.","Overcrowded classes hinder students'' progress as teachers cannot help everyone."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","overcrowded class = lớp quá đông; progress = sự tiến bộ; hinder sth = cản trở điều gì"]'::jsonb, 'C1', '3. Trường học'),
    (2, 20, 'Học phí cao ngăn nhiều học sinh từ các gia đình thu nhập thấp vào học đại học.', 'High tuition fees stop many low-income students from going to university.', '["High tuition fees stop many low-income students going to university.","High tuition fees stop many low-income students from attending university.","High tuition fees stop a lot of low-income students from going to university."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","tuition fees = học phí; low-income = thu nhập thấp; stop sb (from) + V-ing"]'::jsonb, 'B1', '3. Trường học'),
    (2, 21, 'Áp lực thi cử khiến nhiều học sinh cảm thấy lo âu và mất ngủ.', 'Exam pressure makes many students feel anxious and lose sleep.', '["Exam pressure makes lots of students feel anxious and lose sleep.","The pressure of exams makes many students feel anxious and lose sleep.","Exam pressure makes many pupils feel anxious and lose sleep."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","exam pressure = áp lực thi cử; anxious = lo âu; lose sleep = mất ngủ; make sb + V nguyên mẫu"]'::jsonb, 'B1', '3. Trường học'),
    (2, 22, 'Thiếu hướng nghiệp buộc nhiều sinh viên phải đổi ngành giữa chừng khi đang học đại học.', 'A lack of career guidance forces many students to switch majors halfway through university.', '["A lack of career guidance compels many students to switch majors halfway through university.","Lack of career guidance forces many students to switch majors halfway through university.","A lack of career guidance forces many students to change majors halfway through university."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","career guidance = hướng nghiệp; switch majors = đổi ngành; halfway through = giữa chừng"]'::jsonb, 'B2', '3. Trường học'),
    (2, 23, 'Dạy kỹ năng tư duy phản biện có thể ngăn học sinh tin vào mọi thứ các em đọc được trên mạng.', 'Teaching critical thinking skills can prevent students from believing everything they read online.', '["Teaching critical thinking skills may prevent students from believing everything they read online.","Teaching critical thinking skills can prevent pupils from believing everything they read online.","Teaching critical thinking can prevent students from believing everything they read online."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","critical thinking = tư duy phản biện; online = trên mạng; prevent sb from + V-ing"]'::jsonb, 'B2', '3. Trường học'),
    (2, 24, 'Một số trường đại học cấm sinh viên dùng công cụ AI để viết bài luận.', 'Some universities ban students from using AI tools to write their essays.', '["Some universities prohibit students from using AI tools to write their essays.","Some universities ban students from using AI tools to write essays.","A number of universities ban students from using AI tools to write their essays."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","AI tool = công cụ AI; essay = bài luận; ban / prohibit sb from + V-ing = cấm ai làm gì"]'::jsonb, 'C1', '3. Trường học'),
    (2, 25, 'Cắt giảm giờ thể thao và nghệ thuật khiến học sinh thiếu đi một nền giáo dục toàn diện.', 'Cutting sports and art lessons deprives students of a well-rounded education.', '["Cutting sports and art classes deprives students of a well-rounded education.","Cutting sports and art lessons deprives pupils of a well-rounded education.","Reducing sports and art lessons deprives students of a well-rounded education."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","cut = cắt giảm; well-rounded education = nền giáo dục toàn diện; deprive sb of sth = khiến ai thiếu cái gì"]'::jsonb, 'C1', '3. Trường học'),
    (2, 26, 'Một chương trình học mới sẽ yêu cầu giáo viên phải tham gia thêm các khóa đào tạo.', 'A new curriculum would require teachers to attend additional training courses.', '["A new curriculum would require teachers to attend extra training courses.","A new curriculum will require teachers to attend additional training courses.","A new curriculum would require teachers to take additional training courses."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","curriculum = chương trình học; attend = tham gia; require sb to do = yêu cầu ai phải làm"]'::jsonb, 'B2', '3. Trường học'),
    (2, 27, 'Lối học thuộc lòng có thể khiến học sinh ngại đặt câu hỏi trong lớp.', 'Rote learning can discourage students from asking questions in class.', '["Rote learning may discourage students from asking questions in class.","Rote learning can discourage pupils from asking questions in class.","Learning by rote can discourage students from asking questions in class."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","rote learning = học thuộc lòng; ask questions = đặt câu hỏi; discourage sb from + V-ing"]'::jsonb, 'B2', '3. Trường học'),
    (2, 28, 'Giờ làm việc dài buộc nhiều cha mẹ phải nhờ ông bà trông con.', 'Long working hours force many parents to rely on grandparents for childcare.', '["Long working hours compel many parents to rely on grandparents for childcare.","Long working hours force many parents to depend on grandparents for childcare.","Long working hours force lots of parents to rely on grandparents for childcare."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","rely on sb = nhờ cậy ai; childcare = việc trông trẻ; force sb to do = buộc ai phải làm"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (2, 29, 'Cha mẹ lúc nào cũng bận rộn có thể khiến con thiếu đi sự quan tâm mà chúng cần.', 'Parents who are always busy may deprive their children of the attention they need.', '["Parents who are always busy can deprive their children of the attention they need.","Constantly busy parents may deprive their children of the attention they need.","Parents who are always busy may deprive their kids of the attention they need."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","attention = sự quan tâm; deprive sb of sth = khiến ai thiếu cái gì"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (2, 30, 'Việc liên tục so sánh con với người khác có thể khiến trẻ mất tự tin.', 'Constantly comparing children with others can make them lose confidence.', '["Constantly comparing children to others can make them lose confidence.","Constantly comparing children with others may make them lose confidence.","Constantly comparing children with other kids can make them lose confidence."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","compare A with B = so sánh A với B; lose confidence = mất tự tin; make sb do sth = khiến ai làm gì"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (2, 31, 'Cha mẹ nên cài mật khẩu để ngăn trẻ nhỏ tự ý mua đồ trong ứng dụng.', 'Parents should set passwords to prevent young children from buying things in apps without permission.', '["Parents should use passwords to prevent young children from buying things in apps without permission.","Parents should set passwords to prevent small children from buying things in apps without permission.","Parents should set up passwords to prevent young children from buying things in apps without permission."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","set a password = cài mật khẩu; without permission = tự ý, không xin phép; prevent sb from + V-ing"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (2, 32, 'Một số cha mẹ cấm con chơi trò chơi điện tử vào những ngày đi học.', 'Some parents ban their children from playing video games on school days.', '["Some parents prohibit their children from playing video games on school days.","Some parents ban their kids from playing video games on school days.","Some parents ban their children from playing computer games on school days."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","video games = trò chơi điện tử; school days = ngày đi học; ban sb from + V-ing = cấm ai làm gì"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (2, 33, 'Nhiều gia đình yêu cầu con cái phải tự dọn phòng của mình để rèn tính tự lập.', 'Many families require their children to tidy their own rooms to build independence.', '["Many families require children to tidy their own rooms to build independence.","Many families require their children to clean their own rooms to build independence.","Many families require their children to tidy their own rooms to develop independence."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","tidy = dọn dẹp; independence = tính tự lập; require sb to do = yêu cầu ai phải làm"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (2, 34, 'Cha mẹ bao bọc quá mức có thể ngăn con tự mình giải quyết vấn đề.', 'Overprotective parents can stop children from solving problems on their own.', '["Overprotective parents can stop children solving problems on their own.","Overprotective parents can stop their children from solving problems on their own.","Overprotective parents may stop children from solving problems by themselves."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","overprotective = bao bọc quá mức; on their own = tự mình; stop sb (from) + V-ing"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (2, 35, 'Việc đặt ra hậu quả rõ ràng có thể răn đe trẻ không nói dối cha mẹ.', 'Setting clear consequences can deter children from lying to their parents.', '["Setting clear consequences may deter children from lying to their parents.","Setting clear consequences can deter kids from lying to their parents.","Setting clear consequences can deter children from telling lies to their parents."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","consequence = hậu quả, hình thức xử lý; lie to sb = nói dối ai; deter sb from + V-ing"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (2, 36, 'Những lời chỉ trích nặng nề có thể khiến trẻ ngại chia sẻ khó khăn với cha mẹ.', 'Harsh criticism can discourage children from sharing their problems with their parents.', '["Harsh criticism may discourage children from sharing their problems with their parents.","Harsh criticism can discourage kids from sharing their problems with their parents.","Harsh criticism can discourage children from sharing their difficulties with their parents."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","harsh criticism = lời chỉ trích nặng nề; share = chia sẻ; discourage sb from + V-ing"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (2, 37, 'Quy trình an toàn nghiêm ngặt ngăn không để công nhân nhà máy bị thương khi làm việc.', 'Strict safety procedures prevent factory workers from getting injured at work.', '["Strict safety procedures prevent factory workers from being injured at work.","Strict safety procedures prevent factory workers from getting hurt at work.","Strict safety rules prevent factory workers from getting injured at work."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","safety procedures = quy trình an toàn; get injured = bị thương; prevent sb from + V-ing"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (2, 38, 'Bộ máy quan liêu quá mức thường cản trở sự đổi mới trong các tập đoàn lớn.', 'Excessive bureaucracy often hinders innovation in large corporations.', '["Excessive bureaucracy often impedes innovation in large corporations.","Too much bureaucracy often hinders innovation in large corporations.","Excessive bureaucracy often hinders innovation in big corporations."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","bureaucracy = bộ máy quan liêu; innovation = sự đổi mới; hinder / impede sth = cản trở điều gì"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (2, 39, 'Nguy cơ bị người tiêu dùng tẩy chay có thể răn đe các tập đoàn không chạy theo lợi nhuận bằng mọi giá.', 'The risk of a consumer boycott can deter corporations from chasing profit at any cost.', '["The risk of a consumer boycott may deter corporations from chasing profit at any cost.","The threat of a consumer boycott can deter corporations from chasing profit at any cost.","The risk of a consumer boycott can deter corporations from pursuing profit at any cost."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","consumer boycott = sự tẩy chay của người tiêu dùng; chase profit = chạy theo lợi nhuận; at any cost = bằng mọi giá"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (2, 40, 'Những khách hàng có ý thức bảo vệ môi trường đang buộc các hãng thời trang phải dùng chất liệu bền vững hơn.', 'Environmentally conscious customers are forcing fashion brands to use more sustainable materials.', '["Environmentally conscious customers are compelling fashion brands to use more sustainable materials.","Eco-conscious customers are forcing fashion brands to use more sustainable materials.","Environmentally conscious consumers are forcing fashion brands to use more sustainable materials."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","environmentally conscious = có ý thức bảo vệ môi trường; sustainable materials = chất liệu bền vững; force sb to do"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (2, 41, 'Giờ làm việc linh hoạt khiến nhân viên muốn gắn bó với công ty lâu hơn.', 'Flexible working hours make employees want to stay with the company for longer.', '["Flexible working hours make staff want to stay with the company for longer.","Flexible working hours make employees want to stay with the company longer.","Flexible hours make employees want to stay with the company for longer."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","flexible working hours = giờ làm việc linh hoạt; stay with = gắn bó với; make sb want to do = khiến ai muốn làm gì"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (2, 42, 'Môi trường làm việc căng thẳng khiến người tài ngại ứng tuyển vào công ty.', 'A stressful working environment discourages talented people from applying to the company.', '["A stressful work environment discourages talented people from applying to the company.","A stressful working environment discourages skilled people from applying to the company.","A stressful working environment discourages talented people from applying for jobs at the company."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","stressful = căng thẳng; talented = có tài; apply to = ứng tuyển vào; discourage sb from + V-ing"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (2, 43, 'Luật lao động ở một số nước cấm người sử dụng lao động liên lạc với nhân viên ngoài giờ làm việc.', 'Labour laws in some countries prohibit employers from contacting staff outside working hours.', '["Labour laws in some countries ban employers from contacting staff outside working hours.","Labor laws in some countries prohibit employers from contacting staff outside working hours.","Labour laws in some countries prohibit employers from contacting employees outside working hours."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","labour law = luật lao động (Mỹ: labor); employer = người sử dụng lao động; prohibit sb from + V-ing = cấm ai làm gì"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (2, 44, 'Nhiều chính phủ hiện yêu cầu các công ty lớn phải báo cáo mức chênh lệch lương theo giới tính hằng năm.', 'Many governments now require large companies to report their gender pay gap every year.', '["Many governments now require large companies to report their gender pay gap each year.","Many governments now require big companies to report their gender pay gap every year.","Many governments now require large firms to report their gender pay gap every year."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","gender pay gap = chênh lệch lương theo giới tính; report = báo cáo; require sb to do = yêu cầu ai phải làm"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (2, 45, 'Ô nhiễm không khí ở các thành phố lớn tước đi của trẻ em quyền được hít thở không khí trong lành.', 'Air pollution in big cities deprives children of the right to breathe clean air.', '["Air pollution in large cities deprives children of the right to breathe clean air.","Air pollution in big cities deprives children of their right to breathe clean air.","Air pollution in major cities deprives children of the right to breathe clean air."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","air pollution = ô nhiễm không khí; the right to do sth = quyền được làm gì; deprive sb of sth = tước đi của ai cái gì"]'::jsonb, 'C1', '6. Sức khỏe'),
    (2, 46, 'Ngồi trước máy tính hàng giờ liền khiến nhiều nhân viên văn phòng bị đau lưng.', 'Sitting at a computer for hours makes many office workers suffer from back pain.', '["Sitting at a computer for hours on end makes many office workers suffer from back pain.","Sitting in front of a computer for hours makes many office workers suffer from back pain.","Sitting at a computer for hours makes lots of office workers suffer from back pain."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","for hours on end = hàng giờ liền; suffer from = bị (bệnh, đau); back pain = đau lưng; make sb do sth"]'::jsonb, 'B1', '6. Sức khỏe'),
    (2, 47, 'Thiếu ngủ cản trở khả năng hồi phục sau bệnh tật của cơ thể.', 'A lack of sleep hinders the body''s ability to recover from illness.', '["A lack of sleep impedes the body''s ability to recover from illness.","Lack of sleep hinders the body''s ability to recover from illness.","A lack of sleep hinders the body''s ability to recover from sickness."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","a lack of sleep = thiếu ngủ; recover from = hồi phục sau; hinder sth = cản trở điều gì"]'::jsonb, 'C1', '6. Sức khỏe'),
    (2, 48, 'Các chương trình tiêm chủng ngăn không cho hàng triệu trẻ em mắc những căn bệnh nguy hiểm.', 'Vaccination programmes prevent millions of children from catching dangerous diseases.', '["Vaccination programs prevent millions of children from catching dangerous diseases.","Vaccination programmes prevent millions of children from getting dangerous diseases.","Vaccination schemes prevent millions of children from catching dangerous diseases."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","vaccination programme = chương trình tiêm chủng (Mỹ: program); catch a disease = mắc bệnh; prevent sb from + V-ing"]'::jsonb, 'B2', '6. Sức khỏe'),
    (2, 49, 'Nỗi sợ nhận tin xấu ngăn nhiều người đi khám sức khỏe định kỳ.', 'Fear of bad news stops many people from going for regular check-ups.', '["Fear of bad news stops many people going for regular check-ups.","The fear of bad news stops many people from going for regular check-ups.","Fear of bad news stops many people from having regular check-ups."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","check-up = buổi khám sức khỏe; regular = định kỳ; stop sb (from) + V-ing"]'::jsonb, 'B1', '6. Sức khỏe'),
    (2, 50, 'Một số thành phố cấm nhà hàng dùng chất béo chuyển hóa trong các món ăn.', 'Several cities ban restaurants from using trans fats in their dishes.', '["Several cities prohibit restaurants from using trans fats in their dishes.","Several cities ban restaurants from using trans fats in their food.","A number of cities ban restaurants from using trans fats in their dishes."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","trans fats = chất béo chuyển hóa; dish = món ăn; ban sb from + V-ing = cấm ai làm gì"]'::jsonb, 'C1', '6. Sức khỏe'),
    (2, 51, 'Hình ảnh cảnh báo sức khỏe trên bao thuốc lá có thể răn đe thanh thiếu niên không bắt đầu hút thuốc.', 'Graphic health warnings on cigarette packets can deter teenagers from starting to smoke.', '["Graphic health warnings on cigarette packs can deter teenagers from starting to smoke.","Graphic health warnings on cigarette packets may deter teenagers from starting to smoke.","Graphic health warnings on cigarette packets can deter teenagers from taking up smoking."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","graphic warning = hình ảnh cảnh báo; cigarette packet = bao thuốc lá; take up smoking = bắt đầu hút thuốc; deter sb from + V-ing"]'::jsonb, 'C1', '6. Sức khỏe'),
    (2, 52, 'Sự kỳ thị của xã hội có thể khiến mọi người ngại tìm kiếm sự giúp đỡ cho các vấn đề sức khỏe tinh thần.', 'Social stigma can discourage people from seeking help for mental health problems.', '["Social stigma may discourage people from seeking help for mental health problems.","Social stigma can discourage people from seeking help for mental health issues.","Social stigma can discourage people from getting help for mental health problems."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","stigma = sự kỳ thị; seek help = tìm kiếm sự giúp đỡ; mental health = sức khỏe tinh thần; discourage sb from + V-ing"]'::jsonb, 'B2', '6. Sức khỏe'),
    (2, 53, 'Chi phí sinh hoạt tăng cao khiến nhiều gia đình phải cắt giảm chi tiêu.', 'The rising cost of living makes many families cut back on spending.', '["The rising cost of living makes many households cut back on spending.","The rising cost of living is making many families cut back on spending.","The rising cost of living makes many families cut down on spending."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","cost of living = chi phí sinh hoạt; cut back on = cắt giảm; make sb do sth = khiến ai phải làm gì"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (2, 54, 'Tự động hóa buộc nhiều công nhân nhà máy phải học kỹ năng mới để giữ được việc làm.', 'Automation forces many factory workers to learn new skills to keep their jobs.', '["Automation compels many factory workers to learn new skills to keep their jobs.","Automation forces many factory workers to learn new skills in order to keep their jobs.","Automation is forcing many factory workers to learn new skills to keep their jobs."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","automation = tự động hóa; keep one''s job = giữ việc làm; force sb to do = buộc ai phải làm"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (2, 55, 'Tham nhũng cản trở sự phát triển kinh tế ở nhiều nước đang phát triển.', 'Corruption hinders economic development in many developing countries.', '["Corruption impedes economic development in many developing countries.","Corruption hinders economic progress in many developing countries.","Corruption hinders the economic development of many developing countries."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","corruption = tham nhũng; economic development = phát triển kinh tế; hinder / impede sth = cản trở điều gì"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (2, 56, 'Lạm phát cao tước đi của những người về hưu giá trị thực của khoản tiết kiệm.', 'High inflation deprives retired people of the real value of their savings.', '["High inflation deprives pensioners of the real value of their savings.","High inflation deprives retirees of the real value of their savings.","High inflation can deprive retired people of the real value of their savings."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","inflation = lạm phát; pensioner / retiree = người về hưu; real value = giá trị thực; deprive sb of sth"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (2, 57, 'Lãi suất cao ngăn nhiều doanh nghiệp nhỏ vay tiền để mở rộng.', 'High interest rates stop many small businesses from borrowing money to expand.', '["High interest rates stop many small businesses borrowing money to expand.","High interest rates stop many small firms from borrowing money to expand.","High interest rates stop many small businesses from borrowing money to grow."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","interest rate = lãi suất; borrow = vay; expand = mở rộng; stop sb (from) + V-ing"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (2, 58, 'Chính sách thay đổi liên tục khiến các nhà đầu tư nước ngoài ngại rót vốn vào đất nước.', 'Constantly changing policies discourage foreign investors from putting money into the country.', '["Constantly changing policies discourage foreign investors from investing in the country.","Frequently changing policies discourage foreign investors from putting money into the country.","Policies that change constantly discourage foreign investors from putting money into the country."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","foreign investor = nhà đầu tư nước ngoài; put money into = rót vốn vào; discourage sb from + V-ing"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (2, 59, 'Những hình phạt nặng có thể răn đe các công ty lớn không trốn thuế.', 'Heavy penalties can deter large companies from evading tax.', '["Heavy penalties may deter large companies from evading tax.","Heavy penalties can deter large companies from evading taxes.","Severe penalties can deter large companies from evading tax."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","penalty = hình phạt; evade tax = trốn thuế; deter sb from + V-ing = răn đe ai không làm gì"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (2, 60, 'Các dự án hạ tầng lớn đòi hỏi chính phủ phải vay những khoản tiền khổng lồ.', 'Large infrastructure projects require governments to borrow huge sums of money.', '["Large infrastructure projects require governments to borrow enormous sums of money.","Major infrastructure projects require governments to borrow huge sums of money.","Large infrastructure projects require the government to borrow huge sums of money."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","infrastructure project = dự án hạ tầng; huge sums of money = những khoản tiền khổng lồ; require sb to do = đòi hỏi ai phải làm"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (2, 61, 'Sống một mình ở thành phố lớn khiến nhiều người cao tuổi cảm thấy bị bỏ rơi.', 'Living alone in a big city makes many elderly people feel abandoned.', '["Living alone in a big city makes many older people feel abandoned.","Living alone in a large city makes many elderly people feel abandoned.","Living alone in big cities makes many elderly people feel abandoned."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","live alone = sống một mình; elderly people = người cao tuổi; feel abandoned = cảm thấy bị bỏ rơi; make sb feel"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (2, 62, 'Rào cản ngôn ngữ thường ngăn người nhập cư hòa nhập với cộng đồng địa phương.', 'Language barriers often stop immigrants from integrating into local communities.', '["Language barriers often stop immigrants integrating into local communities.","Language barriers frequently stop immigrants from integrating into local communities.","Language barriers often stop immigrants from integrating into the local community."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","language barrier = rào cản ngôn ngữ; immigrant = người nhập cư; integrate into = hòa nhập vào"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (2, 63, 'Việc thiếu công trình phù hợp cho người khuyết tật ngăn họ tham gia vào đời sống cộng đồng.', 'A lack of accessible facilities prevents disabled people from taking part in community life.', '["A lack of accessible facilities prevents people with disabilities from taking part in community life.","A lack of accessible facilities prevents disabled people from participating in community life.","The lack of accessible facilities prevents disabled people from taking part in community life."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","accessible facilities = công trình phù hợp cho người khuyết tật; take part in = tham gia; prevent sb from + V-ing"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (2, 64, 'Giá nhà tăng vọt buộc nhiều gia đình trẻ phải rời khỏi khu phố nơi họ lớn lên.', 'Soaring house prices force many young families to leave the neighbourhoods where they grew up.', '["Soaring house prices force many young families to leave the neighborhoods where they grew up.","Soaring house prices compel many young families to leave the neighbourhoods where they grew up.","Soaring property prices force many young families to leave the neighbourhoods where they grew up."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","soaring = tăng vọt; neighbourhood = khu phố (Mỹ: neighborhood); force sb to do = buộc ai phải làm"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (2, 65, 'Đóng cửa thư viện địa phương tước đi của người dân một nơi để gặp gỡ và học hỏi.', 'Closing local libraries deprives residents of a place to meet and learn.', '["Closing local libraries deprives residents of somewhere to meet and learn.","The closure of local libraries deprives residents of a place to meet and learn.","Closing local libraries deprives local people of a place to meet and learn."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","closure = việc đóng cửa; resident = người dân; deprive sb of sth = tước đi của ai cái gì"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (2, 66, 'Một số thành phố yêu cầu các dự án nhà ở lớn phải có căn hộ giá rẻ dành cho gia đình thu nhập thấp.', 'Some cities require large housing developments to include affordable flats for low-income families.', '["Some cities require large housing developments to include affordable apartments for low-income families.","Some cities require big housing developments to include affordable flats for low-income families.","Some cities require large housing projects to include affordable flats for low-income families."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","housing development = dự án nhà ở; affordable flat = căn hộ giá rẻ (Mỹ: apartment); require sb/sth to do"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (2, 67, 'Các nhóm tự quản an ninh khu phố có thể răn đe thanh thiếu niên không phá hoại tài sản công cộng.', 'Neighbourhood watch groups can deter teenagers from vandalising public property.', '["Neighborhood watch groups can deter teenagers from vandalizing public property.","Neighbourhood watch groups may deter teenagers from vandalising public property.","Neighbourhood watch schemes can deter teenagers from vandalising public property."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","neighbourhood watch = nhóm tự quản an ninh khu phố; vandalise = phá hoại (Mỹ: vandalize); public property = tài sản công cộng"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (2, 68, 'Luật pháp nên cấm chủ nhà từ chối người thuê chỉ vì họ có con nhỏ.', 'The law should ban landlords from refusing tenants just because they have young children.', '["The law should prohibit landlords from refusing tenants just because they have young children.","The law should ban landlords from rejecting tenants just because they have young children.","The law should ban landlords from refusing tenants simply because they have young children."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","landlord = chủ nhà; tenant = người thuê; ban / prohibit sb from + V-ing = cấm ai làm gì"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (2, 69, 'Các quy định mới yêu cầu siêu thị phải thu gom và tái chế bao bì của chính họ.', 'New rules require supermarkets to collect and recycle their own packaging.', '["New regulations require supermarkets to collect and recycle their own packaging.","The new rules require supermarkets to collect and recycle their own packaging.","New rules require supermarkets to take back and recycle their own packaging."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","regulation = quy định; packaging = bao bì; require sb to do = yêu cầu ai phải làm"]'::jsonb, 'B2', '9. Môi trường'),
    (2, 70, 'Một mức thuế carbon cao có thể răn đe các công ty năng lượng không tiếp tục dựa vào than đá.', 'A high carbon tax could deter energy companies from continuing to rely on coal.', '["A high carbon tax might deter energy companies from continuing to rely on coal.","A heavy carbon tax could deter energy companies from continuing to rely on coal.","A high carbon tax could deter power companies from continuing to rely on coal."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","carbon tax = thuế carbon; rely on = dựa vào; coal = than đá; deter sb from + V-ing"]'::jsonb, 'C1', '9. Môi trường'),
    (2, 71, 'Thiếu làn đường an toàn cho xe đạp khiến nhiều người ngại đạp xe đi làm.', 'A lack of safe cycle lanes discourages many people from cycling to work.', '["A lack of safe bike lanes discourages many people from cycling to work.","The lack of safe cycle lanes discourages many people from cycling to work.","A lack of safe cycle lanes discourages lots of people from cycling to work."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","cycle lane = làn đường cho xe đạp (Mỹ: bike lane); cycle to work = đạp xe đi làm; discourage sb from + V-ing"]'::jsonb, 'B2', '9. Môi trường'),
    (2, 72, 'Những đợt hạn hán kéo dài đang buộc nông dân phải chuyển sang các loại cây trồng khác.', 'Prolonged droughts are forcing farmers to switch to different crops.', '["Prolonged droughts are compelling farmers to switch to different crops.","Long droughts are forcing farmers to switch to different crops.","Prolonged droughts are forcing farmers to switch to other crops."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","prolonged drought = hạn hán kéo dài; switch to = chuyển sang; crop = cây trồng; force sb to do"]'::jsonb, 'B2', '9. Môi trường'),
    (2, 73, 'Ô nhiễm nguồn nước đã tước đi nguồn thu nhập chính của nhiều làng chài.', 'Water pollution has deprived many fishing villages of their main source of income.', '["Water pollution has deprived many fishing villages of their main source of livelihood.","Water pollution has deprived numerous fishing villages of their main source of income.","Polluted water has deprived many fishing villages of their main source of income."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","water pollution = ô nhiễm nguồn nước; fishing village = làng chài; source of income = nguồn thu nhập"]'::jsonb, 'C1', '9. Môi trường'),
    (2, 74, 'Nhiều quốc gia đã cấm các cửa hàng phát túi ni lông miễn phí.', 'Many countries have banned shops from giving out free plastic bags.', '["Many countries have prohibited shops from giving out free plastic bags.","Many countries have banned stores from giving out free plastic bags.","Many countries have banned shops from handing out free plastic bags."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","plastic bag = túi ni lông; give out = phát; ban sb from + V-ing = cấm ai làm gì"]'::jsonb, 'C1', '9. Môi trường'),
    (2, 75, 'Các phao chắn rác trên sông có thể ngăn rác thải nhựa trôi ra biển.', 'Floating barriers on rivers can prevent plastic waste from reaching the sea.', '["Floating barriers on rivers can prevent plastic waste from reaching the ocean.","Floating barriers on rivers may prevent plastic waste from reaching the sea.","Floating barriers in rivers can prevent plastic waste from reaching the sea."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","floating barrier = phao chắn rác; plastic waste = rác thải nhựa; prevent sth from + V-ing"]'::jsonb, 'B2', '9. Môi trường'),
    (2, 76, 'Tình trạng thiếu trạm sạc cản trở việc sử dụng rộng rãi xe điện.', 'A shortage of charging stations hinders the widespread use of electric cars.', '["A shortage of charging stations impedes the widespread use of electric cars.","A lack of charging stations hinders the widespread use of electric cars.","A shortage of charging points hinders the widespread use of electric cars."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","charging station = trạm sạc; widespread = rộng rãi; hinder / impede sth = cản trở điều gì"]'::jsonb, 'C1', '9. Môi trường'),
    (2, 77, 'Những lo ngại về bảo mật khiến nhiều người cao tuổi ngại dùng ngân hàng trực tuyến.', 'Security worries discourage many older people from using internet banking.', '["Security concerns discourage many older people from using internet banking.","Security worries discourage many elderly people from using internet banking.","Security worries discourage many older people from using online banking."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","security = bảo mật; internet banking = ngân hàng trực tuyến; discourage sb from + V-ing"]'::jsonb, 'B2', '10. Công nghệ'),
    (2, 78, 'Thông báo từ mạng xã hội khiến người dùng kiểm tra điện thoại hàng trăm lần mỗi ngày.', 'Social media notifications make users check their phones hundreds of times a day.', '["Social media notifications make users check their phones hundreds of times each day.","Notifications from social media make users check their phones hundreds of times a day.","Social media notifications make people check their phones hundreds of times a day."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","notification = thông báo; check = kiểm tra; make sb do sth = khiến ai làm gì"]'::jsonb, 'B1', '10. Công nghệ'),
    (2, 79, 'Công nghệ thay đổi nhanh chóng buộc nhà trường phải cập nhật chương trình học vài năm một lần.', 'Rapid technological change forces schools to update their curricula every few years.', '["Rapid technological change compels schools to update their curricula every few years.","Rapid technological change forces schools to update their curriculum every few years.","Fast technological change forces schools to update their curricula every few years."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","technological change = sự thay đổi công nghệ; curriculum (số nhiều: curricula) = chương trình học; force sb to do"]'::jsonb, 'B2', '10. Công nghệ'),
    (2, 80, 'Việc phụ thuộc vào máy tính cầm tay có thể khiến học sinh thiếu kỹ năng tính nhẩm cơ bản.', 'Relying on calculators can deprive students of basic mental arithmetic skills.', '["Relying on calculators may deprive students of basic mental arithmetic skills.","Relying on calculators can deprive pupils of basic mental arithmetic skills.","Dependence on calculators can deprive students of basic mental arithmetic skills."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","rely on = phụ thuộc vào; mental arithmetic = tính nhẩm; deprive sb of sth = khiến ai thiếu cái gì"]'::jsonb, 'C1', '10. Công nghệ'),
    (2, 81, 'Luật bảo vệ dữ liệu có thể ngăn các công ty công nghệ bán thông tin cá nhân của người dùng.', 'Data protection laws can prevent tech companies from selling users'' personal information.', '["Data protection laws can prevent technology companies from selling users'' personal information.","Data protection laws may prevent tech companies from selling users'' personal information.","Data protection laws can prevent tech firms from selling users'' personal information."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","data protection law = luật bảo vệ dữ liệu; personal information = thông tin cá nhân; prevent sb from + V-ing"]'::jsonb, 'B2', '10. Công nghệ'),
    (2, 82, 'Một số nước cấm trẻ em dưới 16 tuổi sử dụng mạng xã hội.', 'Some countries ban children under 16 from using social media.', '["Some countries prohibit children under 16 from using social media.","Some countries ban children under the age of 16 from using social media.","Some countries ban under-16s from using social media."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","under 16 = dưới 16 tuổi; social media = mạng xã hội; ban sb from + V-ing = cấm ai làm gì"]'::jsonb, 'C1', '10. Công nghệ'),
    (2, 83, 'Kết nối Internet chậm cản trở việc học trực tuyến ở vùng nông thôn.', 'Slow Internet connections hinder online learning in rural areas.', '["Slow Internet connections impede online learning in rural areas.","Slow Internet connections hinder online learning in the countryside.","Slow Internet connections hinder online education in rural areas."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","Internet connection = kết nối Internet; online learning = học trực tuyến; rural areas = vùng nông thôn; hinder sth = cản trở"]'::jsonb, 'C1', '10. Công nghệ'),
    (2, 84, 'Nỗi sợ mất việc không nên ngăn xã hội áp dụng công nghệ mới.', 'Fear of job losses should not stop society from adopting new technology.', '["Fear of job losses should not stop society adopting new technology.","The fear of job losses should not stop society from adopting new technology.","Fear of job losses shouldn''t stop society from adopting new technology."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","job losses = tình trạng mất việc; adopt = áp dụng; stop sb (from) + V-ing"]'::jsonb, 'B1', '10. Công nghệ'),
    (2, 85, 'Thời gian đi lại quá dài khiến nhiều người lao động ngại nhận việc ở trung tâm thành phố.', 'Long commutes discourage many workers from taking jobs in the city centre.', '["Long commutes discourage many workers from taking jobs in the city center.","Long commuting times discourage many workers from taking jobs in the city centre.","Long commutes discourage many people from taking jobs in the city centre."]'::jsonb, '["discourage sb from doing sth = làm ai nản, không muốn làm gì (mục 2.2)","commute = quãng đường, thời gian đi làm; city centre = trung tâm thành phố (Mỹ: center); discourage sb from + V-ing"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (2, 86, 'Khối lượng công việc lớn buộc nhiều nhân viên văn phòng phải ăn trưa ngay tại bàn làm việc.', 'Heavy workloads force many office workers to eat lunch at their desks.', '["Heavy workloads compel many office workers to eat lunch at their desks.","Heavy workloads force many office workers to have lunch at their desks.","Heavy workloads force lots of office workers to eat lunch at their desks."]'::jsonb, '["force / compel sb to do sth = buộc ai phải làm gì (mục 2.2)","workload = khối lượng công việc; at one''s desk = tại bàn làm việc; force sb to do = buộc ai phải làm"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (2, 87, 'Lịch làm việc dày đặc ngăn nhiều người tập thể dục thường xuyên.', 'Packed work schedules stop many people from exercising regularly.', '["Packed work schedules stop many people exercising regularly.","Busy work schedules stop many people from exercising regularly.","Packed work schedules stop lots of people from exercising regularly."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","packed schedule = lịch dày đặc; exercise regularly = tập thể dục thường xuyên; stop sb (from) + V-ing"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (2, 88, 'Nguy cơ bị phạt có thể răn đe tài xế không chặn làn xe buýt vào giờ cao điểm.', 'The threat of fines can deter drivers from blocking bus lanes at rush hour.', '["The threat of fines may deter drivers from blocking bus lanes at rush hour.","The threat of fines can deter drivers from blocking bus lanes during rush hour.","The threat of a fine can deter drivers from blocking bus lanes at rush hour."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","threat of fines = nguy cơ bị phạt; bus lane = làn xe buýt; rush hour = giờ cao điểm; deter sb from + V-ing"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (2, 89, 'Thang cuốn và thang máy ở khắp nơi khiến người thành phố đi bộ ít hơn hẳn so với trước.', 'Escalators and lifts everywhere make city dwellers walk far less than before.', '["Escalators and elevators everywhere make city dwellers walk far less than before.","Escalators and lifts everywhere make city dwellers walk much less than before.","Escalators and lifts everywhere make city residents walk far less than before."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","escalator = thang cuốn; lift = thang máy (Mỹ: elevator); city dweller = người thành phố; make sb do sth"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (2, 90, 'Một số công ty cấm nhân viên tổ chức những cuộc họp kéo dài quá ba mươi phút.', 'Some companies ban staff from holding meetings that last longer than thirty minutes.', '["Some companies prohibit staff from holding meetings that last longer than thirty minutes.","Some companies ban employees from holding meetings that last longer than thirty minutes.","Some companies ban staff from holding meetings that last more than thirty minutes."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","hold a meeting = tổ chức cuộc họp; last = kéo dài; ban sb from + V-ing = cấm ai làm gì"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (2, 91, 'Làm việc kết hợp thường yêu cầu nhân viên phải lên văn phòng hai hoặc ba ngày mỗi tuần.', 'Hybrid working usually requires employees to come into the office two or three days a week.', '["Hybrid working usually requires employees to go into the office two or three days a week.","Hybrid working usually requires staff to come into the office two or three days a week.","Hybrid work usually requires employees to come into the office two or three days a week."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","hybrid working = làm việc kết hợp (ở nhà và văn phòng); come into the office = lên văn phòng; require sb to do"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (2, 92, 'Lạm dụng các dịch vụ tiện lợi có thể cản trở việc hình thành những kỹ năng sống cơ bản như nấu ăn.', 'Overusing convenient services can hinder the development of basic life skills such as cooking.', '["Overusing convenient services can impede the development of basic life skills such as cooking.","Overusing convenient services may hinder the development of basic life skills such as cooking.","Overusing convenient services can hinder the development of basic life skills like cooking."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","overuse = lạm dụng; life skills = kỹ năng sống; hinder / impede sth = cản trở điều gì"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (2, 93, 'Khai thác tài nguyên quá mức hôm nay sẽ tước đi của thế hệ sau những khu rừng và nguồn nước sạch.', 'Overexploiting resources today will deprive future generations of forests and clean water.', '["Overexploiting natural resources today will deprive future generations of forests and clean water.","Overusing resources today will deprive future generations of forests and clean water.","Overexploiting resources now will deprive future generations of forests and clean water."]'::jsonb, '["deprive sb of sth = tước đi của ai cái gì (mục 2.2)","overexploit = khai thác quá mức; future generations = thế hệ sau; deprive sb of sth = tước đi của ai cái gì"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (2, 94, 'Lợi nhuận nhanh có thể khiến các doanh nghiệp phớt lờ những rủi ro lâu dài.', 'Quick profits can make companies ignore long-term risks.', '["Quick profits can make companies overlook long-term risks.","Quick profits may make companies ignore long-term risks.","Quick profits can make firms ignore long-term risks."]'::jsonb, '["make sb do sth = bắt / khiến ai làm gì (mục 2.2)","quick profit = lợi nhuận nhanh; ignore / overlook = phớt lờ; long-term risk = rủi ro lâu dài; make sb do sth"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (2, 95, 'Nỗi lo về chi phí ban đầu thường ngăn các gia đình lắp đặt pin mặt trời.', 'Worries about upfront costs often stop families from installing solar panels.', '["Worries about upfront costs often stop families installing solar panels.","Concerns about upfront costs often stop families from installing solar panels.","Worries about initial costs often stop families from installing solar panels."]'::jsonb, '["stop sb (from) doing sth = ngăn ai làm gì (mục 2.2)","upfront cost = chi phí ban đầu; install = lắp đặt; solar panel = pin mặt trời; stop sb (from) + V-ing"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (2, 96, 'Một hệ thống máy tính mới thường đòi hỏi nhân viên phải mất nhiều tuần để học cách sử dụng.', 'A new computer system often requires staff to spend weeks learning how to use it.', '["A new computer system often requires employees to spend weeks learning how to use it.","A new computer system usually requires staff to spend weeks learning how to use it.","A new IT system often requires staff to spend weeks learning how to use it."]'::jsonb, '["require sb to do sth = yêu cầu ai làm gì (mục 2.2)","computer system = hệ thống máy tính; spend time doing sth = dành thời gian làm gì; require sb to do = đòi hỏi ai phải làm"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (2, 97, 'Hỗ trợ tài chính trong giai đoạn chuyển đổi có thể ngăn người lao động rơi vào cảnh nghèo đói.', 'Financial support during the transition can prevent workers from falling into poverty.', '["Financial support during the transition may prevent workers from falling into poverty.","Financial help during the transition can prevent workers from falling into poverty.","Financial support during the transition period can prevent workers from falling into poverty."]'::jsonb, '["prevent sb from doing sth = ngăn cản ai làm gì (mục 2.2)","financial support = hỗ trợ tài chính; transition = giai đoạn chuyển đổi; fall into poverty = rơi vào cảnh nghèo; prevent sb from + V-ing"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (2, 98, 'Các điều khoản phạt có thể răn đe nhà thầu không bỏ dở những dự án dài hạn giữa chừng.', 'Penalty clauses can deter contractors from abandoning long-term projects halfway through.', '["Penalty clauses may deter contractors from abandoning long-term projects halfway through.","Penalty clauses can deter contractors from abandoning long-term projects halfway.","Penalty clauses in contracts can deter contractors from abandoning long-term projects halfway through."]'::jsonb, '["deter sb from doing sth = răn đe để ai không làm gì (mục 2.2)","penalty clause = điều khoản phạt; contractor = nhà thầu; abandon = bỏ dở; deter sb from + V-ing"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (2, 99, 'Một số nước dự định cấm các hãng ô tô bán xe chạy xăng mới sau năm 2035.', 'Some countries plan to ban carmakers from selling new petrol cars after 2035.', '["Some countries plan to prohibit carmakers from selling new petrol cars after 2035.","Some countries plan to ban car manufacturers from selling new petrol cars after 2035.","Some countries plan to ban carmakers from selling new gasoline cars after 2035."]'::jsonb, '["prohibit / ban sb from doing sth = cấm ai làm gì (mục 2.2)","carmaker = hãng ô tô; petrol car = xe chạy xăng (Mỹ: gasoline car); ban sb from + V-ing = cấm ai làm gì"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (2, 100, 'Những giải pháp tạm thời thường cản trở nỗ lực giải quyết tận gốc vấn đề.', 'Quick fixes often hinder efforts to tackle the root cause of a problem.', '["Quick fixes often impede efforts to tackle the root cause of a problem.","Quick fixes frequently hinder efforts to tackle the root cause of a problem.","Short-term fixes often hinder efforts to tackle the root cause of a problem."]'::jsonb, '["hinder / impede sth = cản trở điều gì (mục 2.2)","quick fix = giải pháp tạm thời; tackle the root cause = giải quyết tận gốc; hinder sth = cản trở điều gì"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (3, 1, 'Chỉ nhà nước mới giải quyết được những vấn đề ở quy mô này vì cá nhân thiếu cả tiền bạc lẫn quyền lực pháp lý.', 'Only the state can tackle problems on this scale because individuals lack both the money and the legal power.', '["Only the state can tackle problems on this scale because individuals lack both the funds and the legal power.","Only the government can solve problems on this scale because individuals lack both the money and the legal power.","Only the state can deal with problems on this scale because individuals lack both money and legal authority."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","on this scale = ở quy mô này; lack = thiếu; legal power = quyền lực pháp lý"]'::jsonb, 'B1', '1. Chính phủ'),
    (3, 2, 'Thực thi nghiêm luật an toàn thực phẩm dẫn đến ít ca ngộ độc thực phẩm hơn.', 'Strict enforcement of food safety laws results in fewer cases of food poisoning.', '["Strictly enforcing food safety laws results in fewer cases of food poisoning.","Strict enforcement of food safety regulations results in fewer cases of food poisoning.","Fewer cases of food poisoning result from strict enforcement of food safety laws."]'::jsonb, '["result in sth / result from sth = gây ra / bắt nguồn từ (mục 2.3)","enforcement = sự thực thi; food poisoning = ngộ độc thực phẩm; result in = dẫn đến"]'::jsonb, 'B2', '1. Chính phủ'),
    (3, 3, 'Điều kiện làm việc thiếu an toàn thường bắt nguồn từ quy định lỏng lẻo và việc thanh tra không thường xuyên.', 'Unsafe working conditions often stem from weak regulations and infrequent inspections.', '["Unsafe working conditions are often caused by weak regulations and infrequent inspections.","Unsafe working conditions often stem from lax regulations and infrequent inspections.","Unsafe working conditions often stem from weak rules and infrequent inspections."]'::jsonb, '["be caused by / stem from sth = do … gây ra / bắt nguồn từ (mục 2.3)","stem from = bắt nguồn từ; lax / weak regulations = quy định lỏng lẻo; infrequent inspections = thanh tra không thường xuyên"]'::jsonb, 'B2', '1. Chính phủ'),
    (3, 4, 'Tăng chi tiêu công cho bệnh viện có tác động tích cực đến sức khỏe của các gia đình thu nhập thấp.', 'Higher public spending on hospitals has a positive impact on the health of low-income families.', '["Increased public spending on hospitals has a positive impact on the health of low-income families.","Higher public spending on hospitals has a beneficial impact on the health of low-income families.","Increasing public spending on hospitals has a positive impact on the health of low-income households."]'::jsonb, '["have a positive / negative impact on sth = có tác động tích cực / tiêu cực đến (mục 2.3)","public spending = chi tiêu công; low-income = thu nhập thấp; have a positive impact on = tác động tích cực đến"]'::jsonb, 'B2', '1. Chính phủ'),
    (3, 5, 'Các loại thuế mới thường vấp phải phản đối mạnh lúc đầu do ảnh hưởng tức thời của chúng lên ngân sách hộ gia đình.', 'New taxes often face strong opposition at first due to their immediate effect on household budgets.', '["New taxes often face strong opposition at first owing to their immediate effect on household budgets.","New taxes often meet strong resistance at first due to their immediate effect on household budgets.","New taxes often face strong opposition initially due to their immediate effect on household budgets."]'::jsonb, '["due to / owing to + noun = do, bởi (mục 2.3)","face opposition = vấp phải phản đối; immediate effect = ảnh hưởng tức thời; household budget = ngân sách hộ gia đình"]'::jsonb, 'B2', '1. Chính phủ'),
    (3, 6, 'Cắt giảm ngân sách cho bệnh viện công có thể làm nảy sinh tình trạng bệnh nhân phải chờ lâu hơn.', 'Cutting funding for public hospitals could give rise to longer waiting times for patients.', '["Cutting funding for public hospitals may give rise to longer waiting times for patients.","Reducing funding for public hospitals could give rise to longer waiting times for patients.","Cutting the budget for public hospitals could give rise to longer waiting times for patients."]'::jsonb, '["give rise to sth = làm nảy sinh (mục 2.3)","funding = ngân sách, kinh phí; waiting time = thời gian chờ; give rise to = làm nảy sinh"]'::jsonb, 'C1', '1. Chính phủ'),
    (3, 7, 'Số ca tử vong trên đường giảm, phần lớn là do luật về lái xe khi say rượu nghiêm ngặt hơn.', 'The decline in road deaths is largely attributable to stricter laws on drink-driving.', '["The fall in road deaths is largely attributable to stricter laws on drink-driving.","The decline in road deaths is largely attributable to stricter drink-driving laws.","The decline in road deaths is largely attributable to tougher laws on drink-driving.","The decline in road deaths is largely attributable to stricter laws on drunk driving."]'::jsonb, '["be largely attributable to sth = phần lớn là do (mục 2.3)","road deaths = tử vong do tai nạn giao thông; drink-driving (Mỹ: drunk driving) = lái xe khi say rượu; be largely attributable to = phần lớn là do"]'::jsonb, 'C1', '1. Chính phủ'),
    (3, 8, 'Các chiến dịch nâng cao nhận thức cộng đồng thay đổi thái độ của người dân, điều này lại giúp luật mới dễ thực thi hơn.', 'Public awareness campaigns change people''s attitudes, which in turn makes new laws easier to enforce.', '["Public awareness campaigns change people''s attitudes, which in turn makes new laws easier to implement.","Awareness campaigns change public attitudes, which in turn makes new laws easier to enforce.","Public awareness campaigns change people''s attitudes, which in turn makes it easier to enforce new laws."]'::jsonb, '["…, which in turn + V = điều này đến lượt nó lại … (mục 2.3)","awareness campaign = chiến dịch nâng cao nhận thức; attitude = thái độ; enforce = thực thi"]'::jsonb, 'C1', '1. Chính phủ'),
    (3, 9, 'Luật rõ ràng cộng với việc thực thi nhất quán khiến các quy định mới dần trở thành chuẩn mực xã hội.', 'Clear laws, coupled with consistent enforcement, mean that new rules gradually become social norms.', '["Clear laws, coupled with consistent enforcement, mean new rules gradually become social norms.","Clear legislation, coupled with consistent enforcement, means that new rules gradually become social norms.","Clear laws, coupled with consistent enforcement, mean that new regulations gradually become social norms."]'::jsonb, '["A, coupled with B, means that … = A cộng với B khiến cho … (mục 2.3)","consistent enforcement = thực thi nhất quán; social norm = chuẩn mực xã hội; chủ ngữ số nhiều (laws) dùng mean"]'::jsonb, 'C1', '1. Chính phủ'),
    (3, 10, 'Người tiêu dùng có sức mạnh thực sự vì các công ty chỉ sản xuất những gì mọi người sẵn sàng mua.', 'Consumers have real power because companies only produce what people are willing to buy.', '["Consumers have real power because companies produce only what people are willing to buy.","Consumers have real power because firms only produce what people are willing to buy.","Consumers hold real power because companies only make what people are willing to buy."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","consumer = người tiêu dùng; be willing to = sẵn sàng"]'::jsonb, 'B1', '2. Cá nhân'),
    (3, 11, 'Mỗi người tái chế đều là tấm gương cho hàng xóm, nên thói quen tốt lan tỏa nhanh chóng.', 'Each person who recycles sets an example for their neighbours, so good habits spread quickly.', '["Each person who recycles sets an example for their neighbors, so good habits spread quickly.","Every person who recycles sets an example for their neighbours, so good habits spread quickly.","Each person who recycles sets an example for their neighbours; as a result, good habits spread quickly."]'::jsonb, '["so + clause / As a result, … = vì vậy, do đó (mục 2.3)","set an example for = làm gương cho; neighbour (Mỹ: neighbor) = hàng xóm; spread = lan tỏa"]'::jsonb, 'B1', '2. Cá nhân'),
    (3, 12, 'Mua ít sản phẩm dùng một lần hơn có thể dẫn đến lượng rác thải sinh hoạt giảm đáng kể.', 'Buying fewer single-use products can lead to a significant fall in household waste.', '["Buying fewer single-use products can lead to a significant reduction in household waste.","Buying fewer disposable products can lead to a significant fall in household waste.","Purchasing fewer single-use products can lead to a considerable fall in household waste."]'::jsonb, '["lead to sth = dẫn đến (mục 2.3)","single-use / disposable = dùng một lần; household waste = rác thải sinh hoạt; significant = đáng kể"]'::jsonb, 'B1', '2. Cá nhân'),
    (3, 13, 'Người tiêu dùng chọn sản phẩm thân thiện với môi trường có tác động tích cực đến cách các công ty vận hành.', 'Consumers who choose eco-friendly products have a positive impact on the way companies operate.', '["Consumers who choose eco-friendly products have a positive impact on how companies operate.","Consumers who choose environmentally friendly products have a positive impact on the way companies operate.","Shoppers who choose eco-friendly products have a positive impact on the way companies operate."]'::jsonb, '["have a positive / negative impact on sth = có tác động tích cực / tiêu cực đến (mục 2.3)","eco-friendly = thân thiện với môi trường; operate = vận hành, hoạt động"]'::jsonb, 'B2', '2. Cá nhân'),
    (3, 14, 'Nhiều người không tập thể dục đều đặn do thiếu động lực chứ không phải do thiếu thời gian.', 'Many people fail to exercise regularly due to a lack of motivation rather than a lack of time.', '["Many people fail to exercise regularly owing to a lack of motivation rather than a lack of time.","Many people do not exercise regularly due to a lack of motivation rather than a lack of time.","Many people don''t exercise regularly due to a lack of motivation rather than a lack of time."]'::jsonb, '["due to / owing to + noun = do, bởi (mục 2.3)","lack of motivation = thiếu động lực; rather than = chứ không phải; due to + danh từ = do"]'::jsonb, 'B2', '2. Cá nhân'),
    (3, 15, 'Chi tiêu cá nhân thiếu cân nhắc có thể làm nảy sinh những vấn đề nợ nần nghiêm trọng về sau.', 'Careless personal spending can give rise to serious debt problems later in life.', '["Careless personal spending may give rise to serious debt problems later in life.","Reckless personal spending can give rise to serious debt problems later in life.","Careless personal spending can give rise to serious problems with debt later in life."]'::jsonb, '["give rise to sth = làm nảy sinh (mục 2.3)","careless / reckless = thiếu cân nhắc; debt = nợ nần; later in life = về sau"]'::jsonb, 'C1', '2. Cá nhân'),
    (3, 16, 'Hóa đơn tiền điện cao của các hộ gia đình phần lớn là do những thói quen lãng phí như để đèn sáng trong phòng không có người.', 'High household electricity bills are largely attributable to wasteful habits such as leaving lights on in empty rooms.', '["High household electricity bills are largely attributable to wasteful habits like leaving lights on in empty rooms.","High household electricity bills are largely attributable to wasteful habits such as leaving the lights on in empty rooms.","High household electricity bills are mostly attributable to wasteful habits such as leaving lights on in empty rooms."]'::jsonb, '["be largely attributable to sth = phần lớn là do (mục 2.3)","electricity bill = hóa đơn tiền điện; wasteful = lãng phí; leave the lights on = để đèn sáng"]'::jsonb, 'C1', '2. Cá nhân'),
    (3, 17, 'Người tiêu dùng từ chối bao bì nhựa tạo áp lực lên các siêu thị, điều này lại buộc nhà sản xuất phải thay đổi.', 'Consumers who refuse plastic packaging put pressure on supermarkets, which in turn forces manufacturers to change.', '["Consumers who refuse plastic packaging put pressure on supermarkets, which in turn forces producers to change.","Shoppers who refuse plastic packaging put pressure on supermarkets, which in turn forces manufacturers to change.","Consumers who reject plastic packaging put pressure on supermarkets, which in turn forces manufacturers to change."]'::jsonb, '["…, which in turn + V = điều này đến lượt nó lại … (mục 2.3)","packaging = bao bì; put pressure on = tạo áp lực lên; manufacturer = nhà sản xuất"]'::jsonb, 'C1', '2. Cá nhân'),
    (3, 18, 'Nỗ lực cá nhân cộng với sự hỗ trợ từ bạn bè khiến thói quen mới dễ duy trì hơn.', 'Personal effort, coupled with support from friends, means that new habits are easier to maintain.', '["Personal effort, coupled with support from friends, means new habits are easier to maintain.","Personal effort, coupled with support from friends, means that new habits are easier to keep.","Individual effort, coupled with support from friends, means that new habits are easier to maintain."]'::jsonb, '["A, coupled with B, means that … = A cộng với B khiến cho … (mục 2.3)","personal effort = nỗ lực cá nhân; maintain = duy trì; chủ ngữ số ít (effort) dùng means"]'::jsonb, 'C1', '2. Cá nhân'),
    (3, 19, 'Nhà trường có ảnh hưởng rất lớn đến người trẻ vì trẻ em dành phần lớn thời gian trong ngày ở đó.', 'Schools have a huge influence on young people because children spend most of their day there.', '["Schools have a great influence on young people because children spend most of their day there.","Schools have a huge influence on young people because children spend most of the day there.","Schools have an enormous influence on young people because children spend most of their day at school."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","have an influence on = có ảnh hưởng đến; most of the day = phần lớn thời gian trong ngày"]'::jsonb, 'B1', '3. Trường học'),
    (3, 20, 'Nhiều sinh viên tốt nghiệp thiếu kỹ năng thực tế, vì vậy nhà tuyển dụng phải tốn tiền đào tạo lại họ.', 'Many graduates lack practical skills, so employers have to spend money retraining them.', '["Many graduates lack practical skills, so employers have to spend money on retraining them.","Many graduates lack practical skills; as a result, employers have to spend money retraining them.","Many graduates lack practical skills, so employers must spend money retraining them."]'::jsonb, '["so + clause / As a result, … = vì vậy, do đó (mục 2.3)","graduate = sinh viên tốt nghiệp; practical skills = kỹ năng thực tế; retrain = đào tạo lại"]'::jsonb, 'B1', '3. Trường học'),
    (3, 21, 'Dạy tài chính cá nhân ở trường có thể dẫn đến việc quản lý tiền bạc tốt hơn khi trưởng thành.', 'Teaching personal finance at school can lead to better money management in adulthood.', '["Teaching personal finance in schools can lead to better money management in adulthood.","Teaching personal finance at school may lead to better money management in adulthood.","Teaching personal finance at school can lead to better money management in adult life."]'::jsonb, '["lead to sth = dẫn đến (mục 2.3)","personal finance = tài chính cá nhân; money management = quản lý tiền bạc; adulthood = tuổi trưởng thành"]'::jsonb, 'B1', '3. Trường học'),
    (3, 22, 'Chương trình học quá tải thường dẫn đến việc học sinh học thuộc kiến thức mà không hiểu.', 'An overloaded curriculum often results in students memorising facts without understanding them.', '["An overloaded curriculum often results in students memorizing facts without understanding them.","An overloaded curriculum often results in students learning facts by heart without understanding them.","An overcrowded curriculum often results in students memorising facts without understanding them."]'::jsonb, '["result in sth / result from sth = gây ra / bắt nguồn từ (mục 2.3)","overloaded curriculum = chương trình học quá tải; memorise (Mỹ: memorize) / learn by heart = học thuộc"]'::jsonb, 'B2', '3. Trường học'),
    (3, 23, 'Kỹ năng đọc kém thường bắt nguồn từ việc thiếu hỗ trợ trong những năm đầu đi học.', 'Poor reading skills often stem from a lack of support in the early years of school.', '["Poor reading skills are often caused by a lack of support in the early years of school.","Weak reading skills often stem from a lack of support in the early years of school.","Poor reading skills often stem from a lack of support in the first years of school."]'::jsonb, '["be caused by / stem from sth = do … gây ra / bắt nguồn từ (mục 2.3)","reading skills = kỹ năng đọc; stem from = bắt nguồn từ; the early years of school = những năm đầu đi học"]'::jsonb, 'B2', '3. Trường học'),
    (3, 24, 'Xếp hạng trường chỉ dựa trên điểm thi có thể làm nảy sinh sự cạnh tranh không lành mạnh giữa học sinh.', 'Ranking schools only by exam scores can give rise to unhealthy competition among students.', '["Ranking schools solely by exam scores can give rise to unhealthy competition among students.","Ranking schools only by exam results can give rise to unhealthy competition among students.","Ranking schools only by exam scores may give rise to unhealthy competition between students."]'::jsonb, '["give rise to sth = làm nảy sinh (mục 2.3)","rank = xếp hạng; exam scores = điểm thi; unhealthy competition = cạnh tranh không lành mạnh"]'::jsonb, 'C1', '3. Trường học'),
    (3, 25, 'Tình trạng thất nghiệp ở sinh viên mới tốt nghiệp phần lớn là do chương trình đại học không khớp với nhu cầu của thị trường lao động.', 'Graduate unemployment is largely attributable to a mismatch between university courses and the needs of the job market.', '["Unemployment among graduates is largely attributable to a mismatch between university courses and the needs of the job market.","Graduate unemployment is largely attributable to the mismatch between university courses and the needs of the job market.","Graduate unemployment is largely attributable to a gap between university courses and the needs of the job market."]'::jsonb, '["be largely attributable to sth = phần lớn là do (mục 2.3)","graduate unemployment = thất nghiệp ở sinh viên tốt nghiệp; mismatch = sự không khớp; job market = thị trường lao động"]'::jsonb, 'C1', '3. Trường học'),
    (3, 26, 'Các câu lạc bộ ngoại khóa xây dựng sự tự tin cho học sinh, điều này lại cải thiện kết quả học tập trên lớp của các em.', 'Extracurricular clubs build students'' confidence, which in turn improves their performance in class.', '["Extracurricular clubs boost students'' confidence, which in turn improves their performance in class.","Extracurricular clubs build students'' confidence, which in turn improves their academic performance.","After-school clubs build students'' confidence, which in turn improves their performance in class."]'::jsonb, '["…, which in turn + V = điều này đến lượt nó lại … (mục 2.3)","extracurricular = ngoại khóa; confidence = sự tự tin; performance in class = kết quả học tập trên lớp"]'::jsonb, 'C1', '3. Trường học'),
    (3, 27, 'Giáo viên được đào tạo tốt cộng với chương trình học hiện đại khiến thế hệ tiếp theo được chuẩn bị tốt hơn cho công việc.', 'Well-trained teachers, coupled with a modern curriculum, mean that the next generation will be better prepared for work.', '["Well-trained teachers, coupled with a modern curriculum, mean the next generation will be better prepared for work.","Well-trained teachers, coupled with an up-to-date curriculum, mean that the next generation will be better prepared for work.","Well-trained teachers, coupled with a modern curriculum, mean that the next generation will be better prepared for employment."]'::jsonb, '["A, coupled with B, means that … = A cộng với B khiến cho … (mục 2.3)","well-trained = được đào tạo tốt; curriculum = chương trình học; be prepared for = được chuẩn bị cho"]'::jsonb, 'C1', '3. Trường học'),
    (3, 28, 'Ông bà thường trông các cháu nhỏ vì cả bố lẫn mẹ đều đi làm toàn thời gian.', 'Grandparents often look after their young grandchildren because both parents work full-time.', '["Grandparents often take care of their young grandchildren because both parents work full-time.","Grandparents often look after their young grandchildren because both parents have full-time jobs.","Grandparents often look after their little grandchildren because both parents work full-time."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","look after / take care of = trông nom, chăm sóc; grandchildren = các cháu; full-time = toàn thời gian"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (3, 29, 'Ngày nay nhiều cha mẹ làm việc nhiều giờ, nên bữa tối gia đình đã trở thành khoảng thời gian quan trọng để trò chuyện.', 'Many parents now work long hours, so family dinners have become an important time to talk.', '["Many parents now work long hours, so family meals have become an important time to talk.","Many parents now work long hours; as a result, family dinners have become an important time to talk.","Many parents work long hours nowadays, so family dinners have become an important time to talk."]'::jsonb, '["so + clause / As a result, … = vì vậy, do đó (mục 2.3)","work long hours = làm việc nhiều giờ; family dinner = bữa tối gia đình"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (3, 30, 'Việc cha mẹ liên tục chỉ trích có thể dẫn đến lòng tự trọng thấp ở trẻ.', 'Constant criticism from parents can lead to low self-esteem in children.', '["Constant criticism from parents may lead to low self-esteem in children.","Constant parental criticism can lead to low self-esteem in children.","Constant criticism from parents can lead to low self-esteem among children."]'::jsonb, '["lead to sth = dẫn đến (mục 2.3)","criticism = sự chỉ trích; self-esteem = lòng tự trọng; parental = của cha mẹ"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (3, 31, 'Để trẻ tự quản lý tiền tiêu vặt dẫn đến thói quen tài chính tốt hơn về sau.', 'Letting children manage their own pocket money results in better financial habits later on.', '["Allowing children to manage their own pocket money results in better financial habits later on.","Letting children manage their own pocket money results in better financial habits later in life.","Letting children manage their own pocket money results in better money habits later on."]'::jsonb, '["result in sth / result from sth = gây ra / bắt nguồn từ (mục 2.3)","pocket money = tiền tiêu vặt; financial habits = thói quen tài chính; later on = về sau"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (3, 32, 'Nhiều vấn đề về hành vi ở thanh thiếu niên bắt nguồn từ việc thiếu sự quan tâm ở nhà.', 'Many behavioural problems in teenagers stem from a lack of attention at home.', '["Many behavioral problems in teenagers stem from a lack of attention at home.","Many behavioural problems in teenagers are caused by a lack of attention at home.","Many behavioural problems among teenagers stem from a lack of attention at home."]'::jsonb, '["be caused by / stem from sth = do … gây ra / bắt nguồn từ (mục 2.3)","behavioural (Mỹ: behavioral) problems = vấn đề về hành vi; lack of attention = thiếu quan tâm"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (3, 33, 'Đọc sách cho trẻ nghe mỗi tối có tác động tích cực đến sự phát triển ngôn ngữ của trẻ.', 'Reading to children every night has a positive impact on their language development.', '["Reading to children every evening has a positive impact on their language development.","Reading to children every night has a beneficial impact on their language development.","Reading to children each night has a positive impact on their language development."]'::jsonb, '["have a positive / negative impact on sth = có tác động tích cực / tiêu cực đến (mục 2.3)","read to sb = đọc cho ai nghe; language development = sự phát triển ngôn ngữ"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (3, 34, 'Nhiều cha mẹ đi làm thấy khó dành thời gian cho con do quãng đường đi làm quá xa.', 'Many working parents find it hard to spend time with their children due to long commutes.', '["Many working parents find it hard to spend time with their children owing to long commutes.","Many working parents struggle to spend time with their children due to long commutes.","Many working parents find it difficult to spend time with their children due to long commutes."]'::jsonb, '["due to / owing to + noun = do, bởi (mục 2.3)","working parents = cha mẹ đi làm; find it hard to = thấy khó; commute = quãng đường đi làm"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (3, 35, 'Trẻ làm việc nhà học được tính trách nhiệm, điều này lại giúp các em sống tự lập khi trưởng thành.', 'Children who do household chores learn responsibility, which in turn helps them live independently as adults.', '["Children who do housework learn responsibility, which in turn helps them live independently as adults.","Children who do household chores learn responsibility, which in turn helps them to live independently as adults.","Children who do household chores learn responsibility, which in turn helps them live independently when they grow up."]'::jsonb, '["…, which in turn + V = điều này đến lượt nó lại … (mục 2.3)","household chores / housework = việc nhà; responsibility = tính trách nhiệm; live independently = sống tự lập"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (3, 36, 'Sự dạy dỗ của cha mẹ cộng với sự hỗ trợ từ nhà trường khiến trẻ hình thành cả giá trị tốt lẫn kỹ năng vững vàng.', 'Parental guidance, coupled with support from schools, means that children develop both good values and solid skills.', '["Parental guidance, coupled with support from schools, means children develop both good values and solid skills.","Parental guidance, coupled with school support, means that children develop both good values and solid skills.","Guidance from parents, coupled with support from schools, means that children develop both good values and solid skills."]'::jsonb, '["A, coupled with B, means that … = A cộng với B khiến cho … (mục 2.3)","parental guidance = sự dạy dỗ của cha mẹ; values = giá trị sống; solid = vững vàng"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (3, 37, 'Công nghệ xanh tốn kém khi lắp đặt, nên nhiều công ty có lợi nhuận thấp hơn trong vài năm đầu.', 'Green technology is expensive to install, so many firms make lower profits in the first few years.', '["Green technology is costly to install, so many firms make lower profits in the first few years.","Green technology is expensive to install; as a result, many firms make lower profits in the first few years.","Green technology is expensive to install, so many companies make lower profits in the first few years."]'::jsonb, '["so + clause / As a result, … = vì vậy, do đó (mục 2.3)","install = lắp đặt; make a profit = có lợi nhuận; the first few years = vài năm đầu"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (3, 38, 'Chế độ làm việc linh hoạt có thể dẫn đến sự gắn bó lớn hơn của nhân viên.', 'Flexible working arrangements can lead to greater loyalty among employees.', '["Flexible working arrangements can lead to greater employee loyalty.","Flexible working arrangements may lead to greater loyalty among employees.","Flexible work arrangements can lead to greater loyalty among staff."]'::jsonb, '["lead to sth = dẫn đến (mục 2.3)","flexible working arrangements = chế độ làm việc linh hoạt; loyalty = sự gắn bó, trung thành"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (3, 39, 'Cắt giảm các biện pháp an toàn để tiết kiệm tiền thường dẫn đến tai nạn lao động nghiêm trọng.', 'Cutting back on safety measures to save money often results in serious workplace accidents.', '["Cutting back on safety measures to save money often results in serious accidents at work.","Cutting safety measures to save money often results in serious workplace accidents.","Serious workplace accidents often result from cutting back on safety measures to save money."]'::jsonb, '["result in sth / result from sth = gây ra / bắt nguồn từ (mục 2.3)","cut back on = cắt giảm; safety measures = biện pháp an toàn; workplace accident = tai nạn lao động"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (3, 40, 'Tình trạng nhân viên nghỉ việc nhiều thường do lương thấp và thiếu cơ hội thăng tiến gây ra.', 'High staff turnover is often caused by low pay and a lack of career prospects.', '["High staff turnover often stems from low pay and a lack of career prospects.","High staff turnover is often caused by low wages and a lack of career prospects.","High staff turnover is often caused by poor pay and a lack of promotion opportunities."]'::jsonb, '["be caused by / stem from sth = do … gây ra / bắt nguồn từ (mục 2.3)","staff turnover = tỷ lệ nhân viên nghỉ việc; career prospects = cơ hội thăng tiến; be caused by = do … gây ra"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (3, 41, 'Các tập đoàn đa quốc gia có tác động rất lớn đến nền kinh tế của các nước đang phát triển.', 'Multinational corporations have a huge impact on the economies of developing countries.', '["Multinational corporations have an enormous impact on the economies of developing countries.","Multinational companies have a huge impact on the economies of developing countries.","Multinational corporations have a huge impact on the economies of developing nations."]'::jsonb, '["have a positive / negative impact on sth = có tác động tích cực / tiêu cực đến (mục 2.3)","multinational corporation = tập đoàn đa quốc gia; developing countries = các nước đang phát triển"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (3, 42, 'Nhiều doanh nghiệp chuyển sang hoạt động xanh chỉ do áp lực pháp luật chứ không xuất phát từ sự quan tâm thực sự đến môi trường.', 'Many firms go green only due to legal pressure rather than genuine concern for the environment.', '["Many firms go green only owing to legal pressure rather than genuine concern for the environment.","Many companies go green only due to legal pressure rather than genuine concern for the environment.","Many firms only go green due to legal pressure rather than genuine concern for the environment."]'::jsonb, '["due to / owing to + noun = do, bởi (mục 2.3)","go green = chuyển sang hoạt động xanh; legal pressure = áp lực pháp luật; genuine concern = sự quan tâm thực sự"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (3, 43, 'Chạy theo lợi nhuận ngắn hạn bằng mọi giá có thể làm nảy sinh tình trạng bóc lột người lao động.', 'Chasing short-term profit at all costs can give rise to the exploitation of workers.', '["Chasing short-term profits at all costs can give rise to the exploitation of workers.","Pursuing short-term profit at all costs can give rise to the exploitation of workers.","Chasing short-term profit at any cost can give rise to the exploitation of workers."]'::jsonb, '["give rise to sth = làm nảy sinh (mục 2.3)","chase / pursue profit = chạy theo lợi nhuận; at all costs = bằng mọi giá; exploitation = sự bóc lột"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (3, 44, 'Năng suất tăng ở nhiều công ty phần lớn là do đầu tư vào đào tạo nhân viên.', 'The rise in productivity at many companies is largely attributable to investment in staff training.', '["The increase in productivity at many companies is largely attributable to investment in staff training.","The rise in productivity at many firms is largely attributable to investment in staff training.","The rise in productivity at many companies is largely attributable to investment in employee training."]'::jsonb, '["be largely attributable to sth = phần lớn là do (mục 2.3)","productivity = năng suất; investment in = đầu tư vào; staff training = đào tạo nhân viên"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (3, 45, 'Nhiều người trẻ bị lo âu vì họ luôn chịu áp lực phải thành công.', 'Many young people suffer from anxiety because they are under constant pressure to succeed.', '["Many young people suffer from anxiety because they are constantly under pressure to succeed.","Many young people suffer from anxiety because of constant pressure to succeed.","A lot of young people suffer from anxiety because they are under constant pressure to succeed."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","anxiety = sự lo âu; be under pressure to = chịu áp lực phải; because of + danh từ"]'::jsonb, 'B1', '6. Sức khỏe'),
    (3, 46, 'Nhiều ca trầm cảm do sự cô đơn và căng thẳng kéo dài gây ra.', 'Many cases of depression are caused by loneliness and long-term stress.', '["Many cases of depression stem from loneliness and long-term stress.","Many cases of depression are caused by loneliness and prolonged stress.","Many cases of depression are caused by loneliness and chronic stress."]'::jsonb, '["be caused by / stem from sth = do … gây ra / bắt nguồn từ (mục 2.3)","depression = trầm cảm; loneliness = sự cô đơn; prolonged / chronic stress = căng thẳng kéo dài"]'::jsonb, 'B2', '6. Sức khỏe'),
    (3, 47, 'Ô nhiễm không khí có tác động đặc biệt nguy hại đến trẻ nhỏ và người cao tuổi.', 'Air pollution has a particularly harmful impact on young children and the elderly.', '["Air pollution has an especially harmful impact on young children and the elderly.","Air pollution has a particularly harmful impact on young children and elderly people.","Air pollution has a particularly damaging impact on young children and the elderly."]'::jsonb, '["have a positive / negative impact on sth = có tác động tích cực / tiêu cực đến (mục 2.3)","particularly = đặc biệt; harmful = nguy hại, có hại; the elderly = người cao tuổi"]'::jsonb, 'B2', '6. Sức khỏe'),
    (3, 48, 'Nhiều bệnh mãn tính không được phát hiện trong nhiều năm do thiếu khám sức khỏe định kỳ.', 'Many chronic illnesses go undetected for years due to a lack of regular check-ups.', '["Many chronic illnesses go undetected for years owing to a lack of regular check-ups.","Many chronic diseases go undetected for years due to a lack of regular check-ups.","Many chronic illnesses remain undetected for years due to a lack of regular check-ups."]'::jsonb, '["due to / owing to + noun = do, bởi (mục 2.3)","chronic illness = bệnh mãn tính; go undetected = không được phát hiện; check-up = khám sức khỏe"]'::jsonb, 'B2', '6. Sức khỏe'),
    (3, 49, 'Dân số già hóa đã làm nảy sinh nhu cầu ngày càng tăng về chăm sóc dài hạn.', 'An ageing population has given rise to a growing demand for long-term care.', '["An aging population has given rise to a growing demand for long-term care.","An ageing population has given rise to an increasing demand for long-term care.","The ageing population has given rise to a growing demand for long-term care."]'::jsonb, '["give rise to sth = làm nảy sinh (mục 2.3)","ageing (Mỹ: aging) population = dân số già hóa; demand for = nhu cầu về; long-term care = chăm sóc dài hạn"]'::jsonb, 'C1', '6. Sức khỏe'),
    (3, 50, 'Bệnh tim gia tăng ở nhân viên văn phòng phần lớn là do ngồi nhiều giờ liền.', 'The rise in heart disease among office workers is largely attributable to sitting for long hours.', '["The increase in heart disease among office workers is largely attributable to sitting for long hours.","The rise in heart disease among office workers is largely attributable to long hours of sitting.","The rise in heart disease among office staff is largely attributable to sitting for long hours."]'::jsonb, '["be largely attributable to sth = phần lớn là do (mục 2.3)","heart disease = bệnh tim; office workers = nhân viên văn phòng; sit for long hours = ngồi nhiều giờ liền"]'::jsonb, 'C1', '6. Sức khỏe'),
    (3, 51, 'Tập thể dục đều đặn cải thiện chất lượng giấc ngủ, điều này lại giúp mọi người tập trung tốt hơn khi làm việc.', 'Regular exercise improves sleep quality, which in turn helps people concentrate better at work.', '["Regular exercise improves the quality of sleep, which in turn helps people concentrate better at work.","Regular exercise improves sleep quality, which in turn helps people to concentrate better at work.","Regular physical activity improves sleep quality, which in turn helps people concentrate better at work."]'::jsonb, '["…, which in turn + V = điều này đến lượt nó lại … (mục 2.3)","sleep quality = chất lượng giấc ngủ; concentrate = tập trung; physical activity = vận động"]'::jsonb, 'C1', '6. Sức khỏe'),
    (3, 52, 'Khám sàng lọc miễn phí cộng với lời khuyên rõ ràng từ bác sĩ khiến bệnh tật có thể được điều trị sớm hơn và rẻ hơn.', 'Free health screenings, coupled with clear advice from doctors, mean that diseases can be treated earlier and more cheaply.', '["Free health screenings, coupled with clear advice from doctors, mean diseases can be treated earlier and more cheaply.","Free health screening, coupled with clear advice from doctors, means that diseases can be treated earlier and more cheaply.","Free health checks, coupled with clear advice from doctors, mean that illnesses can be treated earlier and more cheaply."]'::jsonb, '["A, coupled with B, means that … = A cộng với B khiến cho … (mục 2.3)","health screening = khám sàng lọc; be treated = được điều trị; more cheaply = rẻ hơn"]'::jsonb, 'C1', '6. Sức khỏe'),
    (3, 53, 'Các công ty nước ngoài đang đầu tư mạnh vào đất nước này vì thuế thấp và lực lượng lao động có tay nghề.', 'Foreign companies are investing heavily in the country because of its low taxes and skilled workforce.', '["Foreign firms are investing heavily in the country because of its low taxes and skilled workforce.","Foreign companies are investing heavily in the country because it has low taxes and a skilled workforce.","Foreign companies are investing heavily in this country because of its low taxes and skilled workforce."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","invest heavily = đầu tư mạnh; skilled workforce = lực lượng lao động có tay nghề; because of + danh từ"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (3, 54, 'Du lịch mang tiền về vùng nông thôn, nên người trẻ không còn phải lên thành phố tìm việc.', 'Tourism brings money into rural areas, so young people no longer have to move to cities to find work.', '["Tourism brings money into rural areas, so young people no longer need to move to cities to find work.","Tourism brings money into rural areas; as a result, young people no longer have to move to cities to find work.","Tourism brings money to rural areas, so young people no longer have to move to cities to find work."]'::jsonb, '["so + clause / As a result, … = vì vậy, do đó (mục 2.3)","rural areas = vùng nông thôn; no longer = không còn; find work = tìm việc"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (3, 55, 'Vay nợ nhiều để xây dựng hạ tầng có thể dẫn đến nợ công tăng mạnh.', 'Heavy borrowing to build infrastructure can lead to a sharp rise in public debt.', '["Heavy borrowing to build infrastructure may lead to a sharp rise in public debt.","Heavy borrowing to build infrastructure can lead to a sharp increase in public debt.","Borrowing heavily to build infrastructure can lead to a sharp rise in public debt."]'::jsonb, '["lead to sth = dẫn đến (mục 2.3)","borrowing = vay nợ; infrastructure = hạ tầng; public debt = nợ công; sharp rise = tăng mạnh"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (3, 56, 'Cạnh tranh toàn cầu đã dẫn đến việc nhiều nhà máy địa phương phải đóng cửa.', 'Global competition has resulted in the closure of many local factories.', '["Global competition has resulted in many local factories closing down.","Global competition has resulted in the closure of numerous local factories.","The closure of many local factories has resulted from global competition."]'::jsonb, '["result in sth / result from sth = gây ra / bắt nguồn từ (mục 2.3)","global competition = cạnh tranh toàn cầu; closure = sự đóng cửa; close down = đóng cửa"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (3, 57, 'Sự suy giảm của các ngành công nghiệp truyền thống đã làm nảy sinh tình trạng thất nghiệp cao ở một số vùng.', 'The decline of traditional industries has given rise to high unemployment in some regions.', '["The decline of traditional industries has given rise to high unemployment in certain regions.","The decline in traditional industries has given rise to high unemployment in some regions.","The decline of traditional industries has given rise to high levels of unemployment in some regions."]'::jsonb, '["give rise to sth = làm nảy sinh (mục 2.3)","decline = sự suy giảm; traditional industries = ngành công nghiệp truyền thống; unemployment = thất nghiệp"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (3, 58, 'Tăng trưởng gần đây của đất nước này phần lớn là do ngành xuất khẩu đang bùng nổ.', 'The country''s recent growth is largely attributable to its booming export sector.', '["The country''s recent economic growth is largely attributable to its booming export sector.","The country''s recent growth is largely attributable to its thriving export sector.","This country''s recent growth is largely attributable to its booming export sector."]'::jsonb, '["be largely attributable to sth = phần lớn là do (mục 2.3)","booming / thriving = bùng nổ, phát đạt; export sector = ngành xuất khẩu"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (3, 59, 'Các chương trình đào tạo lại giúp người thất nghiệp tìm được việc, điều này lại làm giảm chi tiêu của chính phủ cho trợ cấp.', 'Retraining programmes help unemployed people find work, which in turn reduces government spending on benefits.', '["Retraining programs help unemployed people find work, which in turn reduces government spending on benefits.","Retraining programmes help jobless people find work, which in turn reduces government spending on benefits.","Retraining programmes help unemployed people find jobs, which in turn reduces government spending on benefits."]'::jsonb, '["…, which in turn + V = điều này đến lượt nó lại … (mục 2.3)","retraining programme (Mỹ: program) = chương trình đào tạo lại; benefits = trợ cấp xã hội"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (3, 60, 'Lương tăng cộng với giá cả ổn định khiến các gia đình có nhiều tiền hơn để chi tiêu.', 'Rising wages, coupled with stable prices, mean that families have more money to spend.', '["Rising wages, coupled with stable prices, mean families have more money to spend.","Higher wages, coupled with stable prices, mean that families have more money to spend.","Rising wages, coupled with stable prices, mean that households have more money to spend."]'::jsonb, '["A, coupled with B, means that … = A cộng với B khiến cho … (mục 2.3)","wages = tiền lương; stable prices = giá cả ổn định; household = hộ gia đình"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (3, 61, 'Nhiều người già cảm thấy bị cô lập vì con cái họ đã chuyển lên các thành phố lớn.', 'Many elderly people feel isolated because their children have moved away to big cities.', '["Many old people feel isolated because their children have moved away to big cities.","Many elderly people feel isolated because their children have moved to big cities.","Many elderly people feel isolated because their children have moved away to large cities."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","isolated = bị cô lập; move away = chuyển đi nơi khác"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (3, 62, 'Thư viện mới tổ chức các hoạt động miễn phí cho mọi lứa tuổi, nên giờ người dân đã có nơi để gặp gỡ.', 'The new library offers free activities for all ages, so residents now have a place to meet.', '["The new library offers free activities for all ages, so local residents now have a place to meet.","The new library offers free activities for all ages; as a result, residents now have a place to meet.","The new library provides free activities for all ages, so residents now have a place to meet."]'::jsonb, '["so + clause / As a result, … = vì vậy, do đó (mục 2.3)","residents = người dân, cư dân; for all ages = cho mọi lứa tuổi"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (3, 63, 'Khoảng cách giàu nghèo ngày càng lớn có thể dẫn đến sự bất mãn và bất ổn xã hội.', 'A widening gap between rich and poor can lead to resentment and social unrest.', '["A widening gap between the rich and the poor can lead to resentment and social unrest.","A growing gap between rich and poor can lead to resentment and social unrest.","A widening gap between rich and poor may lead to resentment and social unrest."]'::jsonb, '["lead to sth = dẫn đến (mục 2.3)","widening gap = khoảng cách ngày càng lớn; resentment = sự bất mãn; social unrest = bất ổn xã hội"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (3, 64, 'Đầu tư lâu dài vào các dự án cộng đồng dẫn đến những khu dân cư an toàn và hòa nhập hơn.', 'Long-term investment in community projects results in safer and more inclusive neighbourhoods.', '["Long-term investment in community projects results in safer and more inclusive neighborhoods.","Long-term investment in community projects results in safer, more inclusive neighbourhoods.","Sustained investment in community projects results in safer and more inclusive neighbourhoods."]'::jsonb, '["result in sth / result from sth = gây ra / bắt nguồn từ (mục 2.3)","community project = dự án cộng đồng; inclusive = hòa nhập; neighbourhood (Mỹ: neighborhood) = khu dân cư"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (3, 65, 'Nhiều vụ phạm tội ở khu vực nghèo bắt nguồn từ thất nghiệp và việc thiếu cơ hội cho người trẻ.', 'Many crimes in poor areas stem from unemployment and a lack of opportunities for young people.', '["Many crimes in poor areas are caused by unemployment and a lack of opportunities for young people.","Many crimes in deprived areas stem from unemployment and a lack of opportunities for young people.","Many crimes in poor areas stem from joblessness and a lack of opportunities for young people."]'::jsonb, '["be caused by / stem from sth = do … gây ra / bắt nguồn từ (mục 2.3)","stem from = bắt nguồn từ; deprived areas = khu vực nghèo; opportunities = cơ hội"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (3, 66, 'Các chương trình hòa nhập dành cho người nhập cư có tác động tích cực đến sự hòa hợp xã hội.', 'Integration programmes for immigrants have a positive impact on social harmony.', '["Integration programs for immigrants have a positive impact on social harmony.","Integration programmes for immigrants have a beneficial impact on social harmony.","Integration programmes for migrants have a positive impact on social harmony."]'::jsonb, '["have a positive / negative impact on sth = có tác động tích cực / tiêu cực đến (mục 2.3)","integration programme (Mỹ: program) = chương trình hòa nhập; immigrant = người nhập cư; social harmony = sự hòa hợp xã hội"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (3, 67, 'Nhiều người khuyết tật không thể tham gia đời sống cộng đồng do không gian công cộng được thiết kế kém.', 'Many disabled people cannot take part in community life due to poorly designed public spaces.', '["Many disabled people cannot take part in community life owing to poorly designed public spaces.","Many people with disabilities cannot take part in community life due to poorly designed public spaces.","Many disabled people are unable to take part in community life due to poorly designed public spaces."]'::jsonb, '["due to / owing to + noun = do, bởi (mục 2.3)","disabled people = người khuyết tật; take part in = tham gia; poorly designed = thiết kế kém"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (3, 68, 'Mạng lưới tình nguyện viên cộng với việc nhân viên xã hội thường xuyên đến thăm khiến người già cô đơn nhận được sự giúp đỡ họ cần.', 'Volunteer networks, coupled with regular visits from social workers, mean that lonely older people get the help they need.', '["Volunteer networks, coupled with regular visits from social workers, mean lonely older people get the help they need.","Volunteer networks, coupled with regular visits by social workers, mean that lonely older people get the help they need.","Volunteer networks, coupled with regular visits from social workers, mean that lonely elderly people receive the help they need."]'::jsonb, '["A, coupled with B, means that … = A cộng với B khiến cho … (mục 2.3)","volunteer network = mạng lưới tình nguyện viên; social worker = nhân viên xã hội; lonely = cô đơn"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (3, 69, 'Trồng thêm cây xanh trong thành phố có thể dẫn đến đường phố mát mẻ hơn và không khí trong lành hơn.', 'Planting more trees in cities can lead to cooler streets and cleaner air.', '["Planting more trees in cities may lead to cooler streets and cleaner air.","Planting more trees in urban areas can lead to cooler streets and cleaner air.","Planting more trees in cities can lead to cooler streets and fresher air."]'::jsonb, '["lead to sth = dẫn đến (mục 2.3)","plant trees = trồng cây; urban areas = khu đô thị; cleaner / fresher air = không khí trong lành hơn"]'::jsonb, 'B1', '9. Môi trường'),
    (3, 70, 'Đánh bắt cá quá mức đã dẫn đến trữ lượng cá giảm mạnh ở nhiều vùng biển.', 'Overfishing has resulted in a sharp fall in fish stocks in many seas.', '["Overfishing has resulted in a sharp decline in fish stocks in many seas.","Overfishing has resulted in a dramatic fall in fish stocks in many seas.","A sharp fall in fish stocks in many seas has resulted from overfishing."]'::jsonb, '["result in sth / result from sth = gây ra / bắt nguồn từ (mục 2.3)","overfishing = đánh bắt cá quá mức; fish stocks = trữ lượng cá; sharp fall = giảm mạnh"]'::jsonb, 'B2', '9. Môi trường'),
    (3, 71, 'Lũ lụt nghiêm trọng ở nhiều thành phố thường do việc phá hủy vùng đất ngập nước và không gian xanh gây ra.', 'Severe flooding in many cities is often caused by the destruction of wetlands and green spaces.', '["Severe flooding in many cities often stems from the destruction of wetlands and green spaces.","Serious flooding in many cities is often caused by the destruction of wetlands and green spaces.","Severe floods in many cities are often caused by the destruction of wetlands and green spaces."]'::jsonb, '["be caused by / stem from sth = do … gây ra / bắt nguồn từ (mục 2.3)","flooding = lũ lụt; destruction = sự phá hủy; wetlands = vùng đất ngập nước; green spaces = không gian xanh"]'::jsonb, 'B2', '9. Môi trường'),
    (3, 72, 'Đồ nhựa dùng một lần có tác động tàn khốc đến sinh vật biển và các cộng đồng ven biển.', 'Single-use plastics have a devastating impact on marine life and coastal communities.', '["Single-use plastics have a devastating impact on sea life and coastal communities.","Disposable plastics have a devastating impact on marine life and coastal communities.","Single-use plastic has a devastating impact on marine life and coastal communities."]'::jsonb, '["have a positive / negative impact on sth = có tác động tích cực / tiêu cực đến (mục 2.3)","devastating = tàn khốc; marine life = sinh vật biển; coastal = ven biển"]'::jsonb, 'B2', '9. Môi trường'),
    (3, 73, 'Nhiều doanh nghiệp trì hoãn việc chuyển sang năng lượng sạch do chi phí thiết bị mới cao.', 'Many companies delay switching to clean energy due to the high cost of new equipment.', '["Many companies delay switching to clean energy owing to the high cost of new equipment.","Many firms delay switching to clean energy due to the high cost of new equipment.","Many companies put off switching to clean energy due to the high cost of new equipment."]'::jsonb, '["due to / owing to + noun = do, bởi (mục 2.3)","delay / put off = trì hoãn; switch to = chuyển sang; equipment = thiết bị"]'::jsonb, 'B2', '9. Môi trường'),
    (3, 74, 'Mực nước biển dâng có thể làm nảy sinh một cuộc khủng hoảng người tị nạn khí hậu trong những thập kỷ tới.', 'Rising sea levels could give rise to a climate refugee crisis in the coming decades.', '["Rising sea levels may give rise to a climate refugee crisis in the coming decades.","Rising sea levels could give rise to a climate refugee crisis in the decades to come.","Rising sea levels could give rise to a climate refugee crisis over the coming decades."]'::jsonb, '["give rise to sth = làm nảy sinh (mục 2.3)","sea levels = mực nước biển; refugee crisis = khủng hoảng người tị nạn; in the coming decades = trong những thập kỷ tới"]'::jsonb, 'C1', '9. Môi trường'),
    (3, 75, 'Môi trường sống của động vật hoang dã bị thu hẹp phần lớn là do việc mở rộng đất nông nghiệp.', 'The shrinking of wildlife habitats is largely attributable to the expansion of farmland.', '["The shrinking of wildlife habitats is largely attributable to the spread of farmland.","The shrinking of wildlife habitats is largely attributable to the expansion of agricultural land.","The shrinkage of wildlife habitats is largely attributable to the expansion of farmland."]'::jsonb, '["be largely attributable to sth = phần lớn là do (mục 2.3)","wildlife habitat = môi trường sống của động vật hoang dã; shrinking = sự thu hẹp; farmland = đất nông nghiệp"]'::jsonb, 'C1', '9. Môi trường'),
    (3, 76, 'Trồng lại rừng giúp đất giữ nước, điều này lại làm giảm nguy cơ sạt lở đất.', 'Reforestation helps the soil hold water, which in turn reduces the risk of landslides.', '["Reforestation helps the soil to hold water, which in turn reduces the risk of landslides.","Replanting forests helps the soil hold water, which in turn reduces the risk of landslides.","Reforestation helps the soil retain water, which in turn reduces the risk of landslides."]'::jsonb, '["…, which in turn + V = điều này đến lượt nó lại … (mục 2.3)","reforestation = trồng lại rừng; hold / retain water = giữ nước; landslide = sạt lở đất"]'::jsonb, 'C1', '9. Môi trường'),
    (3, 77, 'Nhiều người lớn tuổi ngại dùng ngân hàng trực tuyến vì sợ bị kẻ lừa đảo lấy mất tiền.', 'Many older people avoid online banking because they are afraid of losing money to scammers.', '["Many elderly people avoid online banking because they are afraid of losing money to scammers.","Many older people avoid online banking because they worry about losing money to scammers.","Many older people avoid online banking because of the fear of losing money to scammers."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","online banking = ngân hàng trực tuyến; scammer = kẻ lừa đảo; be afraid of = sợ"]'::jsonb, 'B1', '10. Công nghệ'),
    (3, 78, 'Máy móc giờ đảm nhận nhiều công việc văn phòng lặp lại, nên người lao động phải học kỹ năng số mới để giữ được việc làm.', 'Machines now handle many routine office tasks, so workers must learn new digital skills to keep their jobs.', '["Machines now handle many routine office tasks, so employees must learn new digital skills to keep their jobs.","Machines now handle many routine office tasks; as a result, workers must learn new digital skills to keep their jobs.","Machines now handle many routine office tasks, so workers have to learn new digital skills to keep their jobs."]'::jsonb, '["so + clause / As a result, … = vì vậy, do đó (mục 2.3)","routine tasks = công việc lặp lại; digital skills = kỹ năng số; keep one''s job = giữ việc làm"]'::jsonb, 'B1', '10. Công nghệ'),
    (3, 79, 'Các nền tảng học trực tuyến có tác động tích cực đến học sinh sống ở vùng sâu vùng xa.', 'Online learning platforms have a positive impact on students living in remote areas.', '["Online learning platforms have a positive impact on students in remote areas.","E-learning platforms have a positive impact on students living in remote areas.","Online learning platforms have a beneficial impact on students living in remote areas."]'::jsonb, '["have a positive / negative impact on sth = có tác động tích cực / tiêu cực đến (mục 2.3)","online learning platform = nền tảng học trực tuyến; remote areas = vùng sâu vùng xa"]'::jsonb, 'B2', '10. Công nghệ'),
    (3, 80, 'Nhiều người dùng vô tình chia sẻ dữ liệu cá nhân do phần cài đặt quyền riêng tư quá phức tạp.', 'Many users unknowingly share their personal data due to overly complicated privacy settings.', '["Many users unknowingly share their personal data owing to overly complicated privacy settings.","Many users unknowingly share their personal data due to overly complex privacy settings.","Many users unintentionally share their personal data due to overly complicated privacy settings."]'::jsonb, '["due to / owing to + noun = do, bởi (mục 2.3)","unknowingly = vô tình, không hay biết; privacy settings = cài đặt quyền riêng tư; overly = quá"]'::jsonb, 'B2', '10. Công nghệ'),
    (3, 81, 'Việc dễ dàng tiếp cận các công cụ AI đã làm nảy sinh mối lo ngại về gian lận trong trường học.', 'Easy access to AI tools has given rise to concerns about cheating in schools.', '["Easy access to AI tools has given rise to worries about cheating in schools.","Easy access to artificial intelligence tools has given rise to concerns about cheating in schools.","Easy access to AI tools has given rise to concerns about cheating at school."]'::jsonb, '["give rise to sth = làm nảy sinh (mục 2.3)","easy access to = dễ dàng tiếp cận; concern = mối lo ngại; cheating = gian lận"]'::jsonb, 'C1', '10. Công nghệ'),
    (3, 82, 'Sự phổ biến của điện thoại thông minh ở các nước nghèo hơn phần lớn là do giá thiết bị giảm.', 'The spread of smartphones in poorer countries is largely attributable to falling device prices.', '["The spread of smartphones in poorer countries is largely attributable to the falling price of devices.","The popularity of smartphones in poorer countries is largely attributable to falling device prices.","The spread of smartphones in poorer nations is largely attributable to falling device prices."]'::jsonb, '["be largely attributable to sth = phần lớn là do (mục 2.3)","spread = sự lan rộng, phổ biến; device = thiết bị; falling prices = giá giảm"]'::jsonb, 'C1', '10. Công nghệ'),
    (3, 83, 'Tự động hóa tạo ra nhu cầu về các vị trí kỹ thuật mới, điều này lại mở ra những nghề nghiệp trước đây chưa từng có.', 'Automation creates demand for new technical roles, which in turn opens up careers that did not exist before.', '["Automation creates demand for new technical roles, which in turn opens up careers that never existed before.","Automation creates demand for new technical jobs, which in turn opens up careers that did not exist before.","Automation creates demand for new technical roles, which in turn opens up careers that didn''t exist before."]'::jsonb, '["…, which in turn + V = điều này đến lượt nó lại … (mục 2.3)","technical roles = vị trí kỹ thuật; open up = mở ra; career = nghề nghiệp"]'::jsonb, 'C1', '10. Công nghệ'),
    (3, 84, 'Luật bảo vệ dữ liệu rõ ràng cộng với việc giáo dục kỹ năng số tốt khiến mọi người có thể dùng công nghệ an toàn hơn.', 'Clear data protection laws, coupled with good digital education, mean that people can use technology more safely.', '["Clear data protection laws, coupled with good digital education, mean people can use technology more safely.","Clear data protection laws, coupled with proper digital education, mean that people can use technology more safely.","Clear data protection laws, coupled with good digital education, mean that people can use technology more securely."]'::jsonb, '["A, coupled with B, means that … = A cộng với B khiến cho … (mục 2.3)","data protection = bảo vệ dữ liệu; digital education = giáo dục kỹ năng số; safely = an toàn"]'::jsonb, 'C1', '10. Công nghệ'),
    (3, 85, 'Các bậc cha mẹ đi làm phụ thuộc nhiều vào dịch vụ giao hàng vì họ có ít thời gian để đi mua sắm.', 'Working parents rely heavily on delivery services because they have little time to go shopping.', '["Working parents depend heavily on delivery services because they have little time to go shopping.","Working parents rely heavily on delivery services because they have little time for shopping.","Working parents rely heavily on delivery services because they have very little time to go shopping."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","rely / depend heavily on = phụ thuộc nhiều vào; delivery services = dịch vụ giao hàng"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (3, 86, 'Đồ ăn chế biến sẵn chỉ mất vài phút để chuẩn bị, nên người đi làm bận rộn hiếm khi tự nấu từ đầu.', 'Ready meals take only minutes to prepare, so busy workers rarely cook from scratch.', '["Ready meals take only a few minutes to prepare, so busy workers rarely cook from scratch.","Ready meals take only minutes to prepare; as a result, busy workers rarely cook from scratch.","Ready meals take just minutes to prepare, so busy workers rarely cook from scratch."]'::jsonb, '["so + clause / As a result, … = vì vậy, do đó (mục 2.3)","ready meals = đồ ăn chế biến sẵn; cook from scratch = tự nấu từ đầu; rarely = hiếm khi"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (3, 87, 'Một tuyến tàu điện nhanh hơn có thể dẫn đến thời gian đi làm ngắn hơn và ít căng thẳng hơn cho cư dân thành phố.', 'A faster metro line can lead to shorter commutes and less stress for city dwellers.', '["A faster metro line can lead to shorter journeys to work and less stress for city dwellers.","A faster metro line may lead to shorter commutes and less stress for city dwellers.","A faster metro line can lead to shorter commutes and less stress for city residents."]'::jsonb, '["lead to sth = dẫn đến (mục 2.3)","metro line = tuyến tàu điện; commute = quãng đường đi làm; city dwellers = cư dân thành phố"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (3, 88, 'Mua mọi thứ qua mạng dẫn đến việc ít tiếp xúc trực tiếp với người khác hơn.', 'Buying everything online results in less face-to-face contact with other people.', '["Shopping for everything online results in less face-to-face contact with other people.","Buying everything online results in less direct contact with other people.","Buying everything online results in fewer face-to-face interactions with other people."]'::jsonb, '["result in sth / result from sth = gây ra / bắt nguồn từ (mục 2.3)","face-to-face / direct contact = tiếp xúc trực tiếp; buy online = mua qua mạng"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (3, 89, 'Áp lực thời gian mà nhiều người cảm thấy mỗi ngày bắt nguồn từ những chuyến đi làm dài và khó đoán trước.', 'The time pressure many people feel every day stems from long and unpredictable commutes.', '["The time pressure that many people feel every day stems from long and unpredictable commutes.","The time pressure many people feel every day is caused by long and unpredictable commutes.","The daily time pressure many people feel stems from long and unpredictable commutes."]'::jsonb, '["be caused by / stem from sth = do … gây ra / bắt nguồn từ (mục 2.3)","time pressure = áp lực thời gian; unpredictable = khó đoán trước; stem from = bắt nguồn từ"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (3, 90, 'Sự phổ biến của đồ ăn tiện lợi phần lớn là do lối sống ngày càng bận rộn của mọi người.', 'The popularity of convenience food is largely attributable to people''s increasingly busy lifestyles.', '["The popularity of convenience food is largely attributable to people''s increasingly hectic lifestyles.","The popularity of convenience foods is largely attributable to people''s increasingly busy lifestyles.","The popularity of convenience food is largely attributable to people''s increasingly busy way of life."]'::jsonb, '["be largely attributable to sth = phần lớn là do (mục 2.3)","convenience food = đồ ăn tiện lợi; increasingly = ngày càng; busy / hectic lifestyle = lối sống bận rộn"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (3, 91, 'Giờ làm linh hoạt giúp nhân viên tránh giờ cao điểm, điều này lại cho họ thêm thời gian để tập thể dục.', 'Flexible working hours let employees avoid the rush hour, which in turn gives them more time to exercise.', '["Flexible working hours allow employees to avoid the rush hour, which in turn gives them more time to exercise.","Flexible working hours let employees avoid rush hour, which in turn gives them more time to exercise.","Flexible working hours let staff avoid the rush hour, which in turn gives them more time for exercise."]'::jsonb, '["…, which in turn + V = điều này đến lượt nó lại … (mục 2.3)","flexible working hours = giờ làm linh hoạt; rush hour = giờ cao điểm"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (3, 92, 'Thiết bị nhà thông minh cộng với mua sắm trực tuyến khiến mọi người dành ít thời gian hơn cho việc nhà.', 'Smart home devices, coupled with online shopping, mean that people spend less time on housework.', '["Smart home devices, coupled with online shopping, mean people spend less time on housework.","Smart home devices, coupled with online shopping, mean that people spend less time on household chores.","Smart home appliances, coupled with online shopping, mean that people spend less time on housework."]'::jsonb, '["A, coupled with B, means that … = A cộng với B khiến cho … (mục 2.3)","smart home devices = thiết bị nhà thông minh; housework / household chores = việc nhà"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (3, 93, 'Các chính trị gia thường thích giải pháp tạm thời vì cử tri mong thấy kết quả trước kỳ bầu cử tiếp theo.', 'Politicians often prefer quick fixes because voters expect to see results before the next election.', '["Politicians often choose quick fixes because voters expect to see results before the next election.","Politicians often prefer quick fixes because voters want to see results before the next election.","Politicians often prefer short-term solutions because voters expect to see results before the next election."]'::jsonb, '["because + clause / because of + noun = vì, bởi vì (mục 2.3)","quick fix = giải pháp tạm thời; voter = cử tri; election = bầu cử"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (3, 94, 'Đào tạo nhân viên dùng hệ thống mới mất vài tuần, nên năng suất thường giảm lúc đầu.', 'Training staff to use a new system takes several weeks, so productivity often drops at first.', '["Training staff to use a new system takes several weeks, so productivity often falls at first.","Training staff to use a new system takes several weeks; as a result, productivity often drops at first.","Training employees to use a new system takes several weeks, so productivity often drops at first."]'::jsonb, '["so + clause / As a result, … = vì vậy, do đó (mục 2.3)","train sb to do sth = đào tạo ai làm gì; productivity = năng suất; at first = lúc đầu"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (3, 95, 'Chọn vật liệu rẻ nhưng kém chất lượng có thể dẫn đến chi phí sửa chữa cao hơn về lâu dài.', 'Choosing cheap but poor-quality materials can lead to higher repair costs in the long run.', '["Choosing cheap but low-quality materials can lead to higher repair costs in the long run.","Choosing cheap but poor-quality materials may lead to higher repair costs in the long run.","Choosing cheap but poor-quality materials can lead to higher repair costs in the long term."]'::jsonb, '["lead to sth = dẫn đến (mục 2.3)","poor-quality = kém chất lượng; repair costs = chi phí sửa chữa; in the long run = về lâu dài"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (3, 96, 'Khai thác quá mức nước ngầm hôm nay có thể dẫn đến tình trạng thiếu nước nghiêm trọng cho thế hệ sau.', 'Overusing groundwater today could result in severe water shortages for the next generation.', '["Overusing groundwater today may result in severe water shortages for the next generation.","Overusing groundwater today could result in serious water shortages for the next generation.","Overexploiting groundwater today could result in severe water shortages for the next generation."]'::jsonb, '["result in sth / result from sth = gây ra / bắt nguồn từ (mục 2.3)","groundwater = nước ngầm; overuse / overexploit = khai thác quá mức; water shortage = thiếu nước"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (3, 97, 'Nhiều vấn đề lâu dài do những quyết định thiển cận nhằm lấy lòng công chúng gây ra.', 'Many long-term problems are caused by short-sighted decisions made to please the public.', '["Many long-term problems stem from short-sighted decisions made to please the public.","Many long-term problems are caused by short-sighted decisions taken to please the public.","Many long-term problems are caused by short-sighted decisions designed to please the public."]'::jsonb, '["be caused by / stem from sth = do … gây ra / bắt nguồn từ (mục 2.3)","short-sighted = thiển cận; please the public = lấy lòng công chúng; be caused by = do … gây ra"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (3, 98, 'Thực hiện cải cách từng bước có tác động ít xáo trộn hơn đến cuộc sống hằng ngày của người dân.', 'Introducing reforms gradually has a less disruptive impact on people''s daily lives.', '["Introducing reforms step by step has a less disruptive impact on people''s daily lives.","Introducing reforms gradually has a less disruptive impact on people''s everyday lives.","Implementing reforms gradually has a less disruptive impact on people''s daily lives."]'::jsonb, '["have a positive / negative impact on sth = có tác động tích cực / tiêu cực đến (mục 2.3)","reform = cải cách; gradually / step by step = từng bước; disruptive = gây xáo trộn"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (3, 99, 'Nhiều người lao động phản đối công nghệ mới lúc đầu do nỗi sợ mất việc.', 'Many workers resist new technology at first due to the fear of losing their jobs.', '["Many workers resist new technology at first owing to the fear of losing their jobs.","Many workers resist new technology at first due to fear of losing their jobs.","Many employees resist new technology at first due to the fear of losing their jobs."]'::jsonb, '["due to / owing to + noun = do, bởi (mục 2.3)","resist = phản đối, kháng cự; fear of = nỗi sợ; lose one''s job = mất việc"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (3, 100, 'Trì hoãn hành động đối với biến đổi khí hậu sẽ làm nảy sinh những chi phí cao hơn nhiều trong tương lai.', 'Delaying action on climate change will give rise to much higher costs in the future.', '["Delaying action on climate change will give rise to far higher costs in the future.","Postponing action on climate change will give rise to much higher costs in the future.","Delaying action on climate change will give rise to much greater costs in the future."]'::jsonb, '["give rise to sth = làm nảy sinh (mục 2.3)","delay / postpone = trì hoãn; action on = hành động đối với; much higher = cao hơn nhiều"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (4, 1, 'Tôi tin rằng chính quyền địa phương có vị thế tốt hơn các bộ ở trung ương để đáp ứng nhu cầu của từng khu vực.', 'I believe that local authorities are better placed than central ministries to meet the needs of each area.', '["I believe local authorities are better placed than central ministries to meet the needs of each area.","I believe that local authorities are in a better position than central ministries to meet the needs of each area.","I believe that local governments are better placed than central ministries to meet the needs of each area."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","local authorities = chính quyền địa phương; be better placed to V = có vị thế tốt hơn để; central ministries = các bộ trung ương"]'::jsonb, 'B1', '1. Chính phủ'),
    (4, 2, 'Tôi tin chắc rằng chỉ nhà nước mới có đủ thẩm quyền để buộc các công ty lớn tuân thủ quy định về môi trường.', 'I am convinced that only the state has the authority to make large companies obey environmental rules.', '["I''m convinced that only the state has the authority to make large companies obey environmental rules.","I am convinced that only the state has the power to make large companies obey environmental rules.","I am convinced that only the state has the authority to make big companies follow environmental rules."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","authority = thẩm quyền; make sb V = buộc ai làm gì; obey = tuân thủ; environmental rules = quy định về môi trường"]'::jsonb, 'B2', '1. Chính phủ'),
    (4, 3, 'Từ góc nhìn của tôi, những vấn đề như ô nhiễm không khí quá lớn để từng cá nhân tự giải quyết.', 'From my perspective, problems such as air pollution are too large for individuals to solve on their own.', '["From my perspective, problems like air pollution are too large for individuals to solve on their own.","From my perspective, problems such as air pollution are too big for individuals to solve on their own.","From my perspective, problems such as air pollution are too large for individuals to solve by themselves."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","too large for sb to V = quá lớn để ai làm gì; on their own = tự mình"]'::jsonb, 'B2', '1. Chính phủ'),
    (4, 4, 'Nhiều người tin rằng chỉ một đạo luật quốc gia cũng có thể thay đổi hành vi của hàng triệu người.', 'It is widely believed that a single national law can change the behaviour of millions of people.', '["A single national law is widely believed to be able to change the behaviour of millions of people.","It''s widely believed that a single national law can change the behaviour of millions of people.","It is widely believed that a single national law can change the behavior of millions of people."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","national law = luật quốc gia; behaviour = hành vi"]'::jsonb, 'C1', '1. Chính phủ'),
    (4, 5, 'Tôi nghĩ rằng một chính sách được hoạch định kém có thể lãng phí tiền thuế và làm tổn hại lòng tin của người dân vào chính phủ.', 'I think that a poorly planned policy can waste taxpayers'' money and damage public trust in the government.', '["I think a poorly planned policy can waste taxpayers'' money and damage public trust in the government.","I think that a badly planned policy can waste taxpayers'' money and damage public trust in the government.","I think that a poorly planned policy can waste taxpayers'' money and harm public trust in the government."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","poorly planned = hoạch định kém; taxpayers'' money = tiền thuế của dân; public trust = lòng tin của công chúng"]'::jsonb, 'B1', '1. Chính phủ'),
    (4, 6, 'Theo tôi, tiền thu được từ thuế thuốc lá nên được dùng cho các chương trình giúp người hút thuốc cai thuốc.', 'In my opinion, money raised from tobacco taxes should be spent on programmes that help smokers quit.', '["In my opinion, money raised from tobacco taxes should be spent on programs that help smokers quit.","In my opinion, revenue from tobacco taxes should be spent on programmes that help smokers quit.","In my opinion, money raised from tobacco taxes should be used for programmes that help smokers quit.","In my opinion, money collected from tobacco taxes should be spent on programmes that help smokers quit."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","tobacco tax = thuế thuốc lá; revenue = nguồn thu; quit = bỏ, cai"]'::jsonb, 'B1', '1. Chính phủ'),
    (4, 7, 'Với tôi thì có vẻ như các chính sách mới thường gặp phản đối mạnh mẽ trước khi người dân thấy được lợi ích của chúng.', 'It seems to me that new policies often meet strong resistance before people see their benefits.', '["It seems to me that new policies often face strong resistance before people see their benefits.","It seems to me that new policies often meet strong opposition before people see their benefits.","It seems to me that new policies often meet strong resistance before people see their advantages."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","meet resistance = gặp phản đối; benefit = lợi ích"]'::jsonb, 'B2', '1. Chính phủ'),
    (4, 8, 'Tôi cho rằng một đạo luật nghiêm khắc sẽ vô ích nếu chính quyền không thực thi nó một cách nhất quán.', 'I would argue that a strict law is useless if the authorities do not enforce it consistently.', '["I would argue that a strict law is pointless if the authorities do not enforce it consistently.","I would argue that a strict law is useless if the authorities don''t enforce it consistently.","I would argue that a tough law is useless if the authorities do not enforce it consistently."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","enforce = thực thi; consistently = nhất quán; useless = vô ích"]'::jsonb, 'C1', '1. Chính phủ'),
    (4, 9, 'Tôi kiên quyết cho rằng chỉ riêng các hướng dẫn tự nguyện sẽ không bao giờ đủ để ngăn các công ty gây ô nhiễm.', 'I am firmly of the view that voluntary guidelines alone will never be enough to stop companies from polluting.', '["I''m firmly of the view that voluntary guidelines alone will never be enough to stop companies from polluting.","I am firmly of the view that voluntary guidelines alone will never be enough to stop companies polluting.","I am firmly of the view that voluntary guidelines alone will never be enough to prevent companies from polluting."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","voluntary guidelines = hướng dẫn tự nguyện; stop sb from V-ing = ngăn ai làm gì; pollute = gây ô nhiễm"]'::jsonb, 'C1', '1. Chính phủ'),
    (4, 10, 'Theo tôi, người tiêu dùng có quyền lực thực sự vì các công ty sản xuất bất cứ thứ gì mà mọi người sẵn sàng mua.', 'In my opinion, consumers have real power because companies produce whatever people are willing to buy.', '["In my opinion, consumers have real power because companies make whatever people are willing to buy.","In my opinion, consumers have genuine power because companies produce whatever people are willing to buy.","In my opinion, consumers hold real power because companies produce whatever people are willing to buy."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","consumer = người tiêu dùng; be willing to V = sẵn sàng làm gì"]'::jsonb, 'B1', '2. Cá nhân'),
    (4, 11, 'Từ góc nhìn của tôi, người trẻ thấy việc tiếp nhận thói quen mới dễ hơn nhiều so với thế hệ lớn tuổi.', 'From my perspective, young people find it much easier to adopt new habits than older generations do.', '["From my perspective, young people find it much easier to adopt new habits than older generations.","From my perspective, young people find it far easier to adopt new habits than older generations do.","From my perspective, young people find it much easier to form new habits than older generations do."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","adopt new habits = tiếp nhận thói quen mới; older generations = thế hệ lớn tuổi"]'::jsonb, 'B2', '2. Cá nhân'),
    (4, 12, 'Nhiều người tin rằng những thói quen hằng ngày thiếu ý thức, như để đèn sáng, gây lãng phí rất nhiều năng lượng.', 'It is widely believed that careless daily habits, such as leaving lights on, waste a huge amount of energy.', '["Careless daily habits, such as leaving lights on, are widely believed to waste a huge amount of energy.","It''s widely believed that careless daily habits, such as leaving lights on, waste a huge amount of energy.","It is widely believed that careless daily habits, like leaving lights on, waste a huge amount of energy.","It is widely believed that careless daily habits, such as leaving lights on, waste a great deal of energy."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","careless = thiếu ý thức, cẩu thả; leave lights on = để đèn sáng; waste = lãng phí"]'::jsonb, 'C1', '2. Cá nhân'),
    (4, 13, 'Tôi tin chắc rằng giá trị cá nhân định hình hành vi của con người mạnh mẽ hơn so với tiền phạt.', 'I am convinced that personal values shape people''s behaviour more strongly than fines do.', '["I''m convinced that personal values shape people''s behaviour more strongly than fines do.","I am convinced that personal values shape people''s behavior more strongly than fines do.","I am convinced that personal values shape people''s behaviour more strongly than fines.","I am convinced that personal values shape people''s behaviour more powerfully than fines do."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","personal values = giá trị cá nhân; shape = định hình; fine = tiền phạt"]'::jsonb, 'B2', '2. Cá nhân'),
    (4, 14, 'Tôi tin rằng những nỗ lực nhỏ hằng ngày, khi được nhân lên bởi hàng triệu người, có thể tạo ra khác biệt rất lớn.', 'I believe that small daily efforts, when multiplied by millions of people, can make a huge difference.', '["I believe small daily efforts, when multiplied by millions of people, can make a huge difference.","I believe that small daily efforts, when multiplied by millions of people, can make an enormous difference.","I believe that small everyday efforts, when multiplied by millions of people, can make a huge difference."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","multiply = nhân lên; make a difference = tạo ra khác biệt"]'::jsonb, 'B1', '2. Cá nhân'),
    (4, 15, 'Tôi kiên quyết cho rằng những người thay đổi lối sống của chính mình là tấm gương cho mọi người xung quanh.', 'I am firmly of the view that people who change their own lifestyle set an example for everyone around them.', '["I''m firmly of the view that people who change their own lifestyle set an example for everyone around them.","I am firmly of the view that people who change their own lifestyles set an example for everyone around them.","I am firmly of the view that people who change their own lifestyle set an example to everyone around them."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","lifestyle = lối sống; set an example for sb = làm gương cho ai"]'::jsonb, 'C1', '2. Cá nhân'),
    (4, 16, 'Với tôi thì có vẻ như đọc kỹ nhãn sản phẩm là cách đơn giản nhất để trở thành người tiêu dùng có trách nhiệm.', 'It seems to me that reading product labels carefully is the simplest way to become a responsible consumer.', '["It seems to me that reading product labels carefully is the easiest way to become a responsible consumer.","It seems to me that carefully reading product labels is the simplest way to become a responsible consumer.","It seems to me that reading product labels carefully is the simplest way to be a responsible consumer."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","product label = nhãn sản phẩm; responsible consumer = người tiêu dùng có trách nhiệm"]'::jsonb, 'B2', '2. Cá nhân'),
    (4, 17, 'Tôi cho rằng thói quen mới nào lúc đầu cũng thấy khó nhưng sau vài tháng sẽ trở nên tự nhiên.', 'I would argue that any new habit feels difficult at first but becomes second nature after a few months.', '["I would argue that any new habit feels hard at first but becomes second nature after a few months.","I would argue that every new habit feels difficult at first but becomes second nature after a few months.","I would argue that any new habit feels difficult at first but becomes natural after a few months."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","second nature = điều tự nhiên như bản năng; at first = lúc đầu"]'::jsonb, 'C1', '2. Cá nhân'),
    (4, 18, 'Theo tôi, hành động của cá nhân hiệu quả nhất khi được hỗ trợ bởi các chính sách hợp lý của chính phủ.', 'In my opinion, individual action works best when it is supported by sensible government policies.', '["In my opinion, individual action works best when it is backed by sensible government policies.","In my opinion, individual action is most effective when it is supported by sensible government policies.","In my opinion, individual action works best when it is supported by sensible government policy."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","individual action = hành động cá nhân; sensible = hợp lý; be supported by = được hỗ trợ bởi"]'::jsonb, 'B1', '2. Cá nhân'),
    (4, 19, 'Với tôi thì có vẻ như nhiều trường đại học không dạy được những kỹ năng mà nhà tuyển dụng thực sự cần.', 'It seems to me that many universities fail to teach the skills that employers actually need.', '["It seems to me that many universities fail to teach the skills employers actually need.","It seems to me that many universities fail to teach the skills that employers really need.","It seems to me that a lot of universities fail to teach the skills that employers actually need."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","fail to V = không làm được; employer = nhà tuyển dụng"]'::jsonb, 'B2', '3. Trường học'),
    (4, 20, 'Tôi tin rằng nhà trường mang lại cho trẻ em nhà nghèo một cơ hội công bằng để thành công trong cuộc sống.', 'I believe that schools give children from poor families a fair chance to succeed in life.', '["I believe schools give children from poor families a fair chance to succeed in life.","I believe that schools give children from poor backgrounds a fair chance to succeed in life.","I believe that schools give children from low-income families a fair chance to succeed in life.","I believe that schools give poor children a fair chance to succeed in life."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","fair chance = cơ hội công bằng; succeed = thành công; low-income = thu nhập thấp"]'::jsonb, 'B1', '3. Trường học'),
    (4, 21, 'Tôi kiên quyết cho rằng nhà trường định hình thái độ của trẻ vì học sinh dành phần lớn thời gian trong ngày ở đó.', 'I am firmly of the view that schools shape children''s attitudes because pupils spend most of their day there.', '["I''m firmly of the view that schools shape children''s attitudes because pupils spend most of their day there.","I am firmly of the view that schools shape children''s attitudes because students spend most of their day there.","I am firmly of the view that schools shape children''s attitudes since pupils spend most of their day there."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","shape = định hình; attitude = thái độ; pupil = học sinh"]'::jsonb, 'C1', '3. Trường học'),
    (4, 22, 'Nhiều người tin rằng áp lực thi cử nặng nề gây ra căng thẳng nghiêm trọng ở học sinh trung học.', 'It is widely believed that heavy exam pressure causes serious stress among secondary school students.', '["Heavy exam pressure is widely believed to cause serious stress among secondary school students.","It''s widely believed that heavy exam pressure causes serious stress among secondary school students.","It is widely believed that intense exam pressure causes serious stress among secondary school students.","It is widely believed that heavy exam pressure causes serious stress among high school students."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","exam pressure = áp lực thi cử; secondary school = trường trung học"]'::jsonb, 'C1', '3. Trường học'),
    (4, 23, 'Tôi tin chắc rằng các dự án thực hành giúp học sinh chuẩn bị cho cuộc sống thực tế tốt hơn so với chỉ học sách giáo khoa.', 'I am convinced that hands-on projects prepare students for real life better than textbooks alone.', '["I''m convinced that hands-on projects prepare students for real life better than textbooks alone.","I am convinced that hands-on projects prepare students for real life better than textbooks alone do.","I am convinced that practical projects prepare students for real life better than textbooks alone."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","hands-on = thực hành; prepare sb for sth = chuẩn bị cho ai đón nhận điều gì; textbook = sách giáo khoa"]'::jsonb, 'B2', '3. Trường học'),
    (4, 24, 'Theo tôi, nấu ăn và sơ cứu nên được dạy ở trường như những kỹ năng sống thiết yếu.', 'In my opinion, cooking and first aid should be taught at school as essential life skills.', '["In my opinion, cooking and first aid should be taught in schools as essential life skills.","In my opinion, schools should teach cooking and first aid as essential life skills.","In my opinion, cooking and first aid ought to be taught at school as essential life skills."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","first aid = sơ cứu; essential = thiết yếu; life skills = kỹ năng sống"]'::jsonb, 'B1', '3. Trường học'),
    (4, 25, 'Từ góc nhìn của tôi, đào tạo giáo viên cho chương trình mới tuy tốn kém nhưng không thể tránh khỏi.', 'From my perspective, training teachers for a new curriculum is costly but unavoidable.', '["From my perspective, training teachers for a new curriculum is expensive but unavoidable.","From my perspective, training teachers for a new curriculum is costly but inevitable.","From my perspective, training teachers for a new syllabus is costly but unavoidable."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","curriculum = chương trình học; costly = tốn kém; unavoidable = không thể tránh khỏi"]'::jsonb, 'B2', '3. Trường học'),
    (4, 26, 'Tôi cho rằng giá trị thực sự của giáo dục chỉ trở nên rõ ràng sau nhiều năm.', 'I would argue that the true value of education only becomes clear after many years.', '["I would argue that the real value of education only becomes clear after many years.","I would argue that the true value of education becomes clear only after many years.","I would argue that the true value of education only becomes obvious after many years."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","true value = giá trị thực sự; become clear = trở nên rõ ràng"]'::jsonb, 'C1', '3. Trường học'),
    (4, 27, 'Tôi tin chắc rằng giáo dục làm giảm tội phạm ở thanh thiếu niên hiệu quả hơn so với hình phạt nghiêm khắc.', 'I am convinced that education reduces youth crime more effectively than harsh punishment does.', '["I''m convinced that education reduces youth crime more effectively than harsh punishment does.","I am convinced that education reduces youth crime more effectively than harsh punishment.","I am convinced that education reduces juvenile crime more effectively than harsh punishment does.","I am convinced that education cuts youth crime more effectively than harsh punishment does."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","youth crime = tội phạm ở thanh thiếu niên; harsh punishment = hình phạt nghiêm khắc"]'::jsonb, 'B2', '3. Trường học'),
    (4, 28, 'Nhiều người tin rằng ông bà đóng vai trò quý giá trong việc nuôi dạy trẻ khi cả cha lẫn mẹ đều đi làm.', 'It is widely believed that grandparents play a valuable role in raising children when both parents work.', '["Grandparents are widely believed to play a valuable role in raising children when both parents work.","It''s widely believed that grandparents play a valuable role in raising children when both parents work.","It is widely believed that grandparents play a valuable role in bringing up children when both parents work."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","raise / bring up children = nuôi dạy con; valuable = quý giá"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (4, 29, 'Với tôi thì có vẻ như trẻ em bắt chước thói quen của cha mẹ nhiều hơn hẳn so với làm theo lời khuyên của họ.', 'It seems to me that children copy their parents'' habits far more than they follow their advice.', '["It seems to me that children imitate their parents'' habits far more than they follow their advice.","It seems to me that children copy their parents'' habits much more than they follow their advice.","It seems to me that kids copy their parents'' habits far more than they follow their advice."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","copy / imitate = bắt chước; follow advice = làm theo lời khuyên"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (4, 30, 'Tôi nghĩ rằng năm năm đầu đời có ảnh hưởng lâu dài đến tính cách của một đứa trẻ.', 'I think that the first five years of life have a lasting effect on a child''s personality.', '["I think the first five years of life have a lasting effect on a child''s personality.","I think that the first five years of life have a lasting impact on a child''s personality.","I think that the first five years of life have a lasting effect on a child''s character."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","lasting effect = ảnh hưởng lâu dài; personality = tính cách"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (4, 31, 'Từ góc nhìn của tôi, những đứa trẻ lớn lên trong một gia đình yêu thương sẽ tự tin hơn khi đối mặt với thử thách.', 'From my perspective, children who grow up in a loving home are more confident when facing challenges.', '["From my perspective, children who grow up in a loving family are more confident when facing challenges.","From my perspective, children who grow up in a loving home are more confident when they face challenges.","From my perspective, children raised in a loving home are more confident when facing challenges."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","loving home = gia đình yêu thương; confident = tự tin; face challenges = đối mặt thử thách"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (4, 32, 'Tôi tin chắc rằng sự thiếu quan tâm của cha mẹ thường đẩy thanh thiếu niên đến chỗ nghiện màn hình.', 'I am convinced that a lack of parental attention often pushes teenagers towards screen addiction.', '["I''m convinced that a lack of parental attention often pushes teenagers towards screen addiction.","I am convinced that a lack of parental attention often pushes teenagers toward screen addiction.","I am convinced that a lack of parental attention often drives teenagers towards screen addiction."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","parental attention = sự quan tâm của cha mẹ; screen addiction = nghiện màn hình"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (4, 33, 'Tôi cho rằng cha mẹ nên tắt điện thoại của chính mình trong các bữa ăn gia đình.', 'I would argue that parents should switch off their own phones during family meals.', '["I would argue that parents should turn off their own phones during family meals.","I would argue that parents ought to switch off their own phones during family meals.","I would argue that parents should switch off their own phones at family meals."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","switch off / turn off = tắt; family meal = bữa ăn gia đình"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (4, 34, 'Với tôi thì có vẻ như nhiều cha mẹ đi làm gặp khó khăn trong việc tìm thời gian đọc sách cùng con.', 'It seems to me that many working parents struggle to find time to read with their children.', '["It seems to me that many working parents struggle to find the time to read with their children.","It seems to me that many working parents find it hard to find time to read with their children.","It seems to me that a lot of working parents struggle to find time to read with their children."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","working parents = cha mẹ đi làm; struggle to V = gặp khó khăn khi làm gì"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (4, 35, 'Theo tôi, những đứa trẻ được phép tự đưa ra quyết định nhỏ sẽ trở thành người trưởng thành tự lập hơn.', 'In my opinion, children who are allowed to make small decisions for themselves grow into more independent adults.', '["In my opinion, children who are allowed to make small decisions on their own grow into more independent adults.","In my opinion, children who are allowed to make small decisions for themselves become more independent adults.","In my opinion, children who are allowed to make minor decisions for themselves grow into more independent adults."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","make decisions = đưa ra quyết định; independent = tự lập; grow into = lớn lên thành"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (4, 36, 'Tôi kiên quyết cho rằng việc làm gương dạy trẻ được nhiều điều hơn so với những quy định nghiêm khắc.', 'I am firmly of the view that setting a good example teaches children more than strict rules do.', '["I''m firmly of the view that setting a good example teaches children more than strict rules do.","I am firmly of the view that setting a good example teaches children more than strict rules.","I am firmly of the view that leading by example teaches children more than strict rules do."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","set a good example / lead by example = làm gương; strict rules = quy định nghiêm khắc"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (4, 37, 'Tôi tin chắc rằng các doanh nghiệp vừa và nhỏ tạo ra nhiều việc làm ở địa phương hơn các tập đoàn lớn.', 'I am convinced that small and medium-sized firms create more local jobs than large corporations.', '["I''m convinced that small and medium-sized firms create more local jobs than large corporations.","I am convinced that small and medium-sized companies create more local jobs than large corporations.","I am convinced that small and medium-sized businesses create more local jobs than big corporations."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","small and medium-sized firms = doanh nghiệp vừa và nhỏ; corporation = tập đoàn"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (4, 38, 'Nhiều người tin rằng các tập đoàn lớn có đủ nguồn lực để đầu tư vào công nghệ sạch hơn.', 'Large corporations are widely believed to have the resources to invest in cleaner technology.', '["It is widely believed that large corporations have the resources to invest in cleaner technology.","Big corporations are widely believed to have the resources to invest in cleaner technology.","Large corporations are widely believed to have the resources to invest in cleaner technologies."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","corporation = tập đoàn; resources = nguồn lực; cleaner technology = công nghệ sạch hơn"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (4, 39, 'Tôi tin rằng những công ty chăm lo sức khỏe nhân viên cuối cùng sẽ thu được lợi nhuận cao hơn.', 'I believe that companies which look after their employees'' health end up making higher profits.', '["I believe companies which look after their employees'' health end up making higher profits.","I believe that companies that look after their employees'' health end up making higher profits.","I believe that companies which take care of their employees'' health end up making higher profits.","I believe that firms which look after their employees'' health end up making higher profits."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","look after = chăm lo; end up V-ing = cuối cùng sẽ; profit = lợi nhuận"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (4, 40, 'Tôi cho rằng việc chạy theo lợi nhuận ngắn hạn thường khiến sự an toàn của người lao động gặp nguy hiểm.', 'I would argue that chasing short-term profit often puts workers'' safety at risk.', '["I would argue that chasing short-term profits often puts workers'' safety at risk.","I would argue that pursuing short-term profit often puts workers'' safety at risk.","I would argue that chasing short-term profit often puts the safety of workers at risk."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","chase profit = chạy theo lợi nhuận; put sth at risk = khiến điều gì gặp nguy hiểm"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (4, 41, 'Tôi kiên quyết cho rằng các công ty làm ăn có lãi có nghĩa vụ đóng góp lại cho cộng đồng nơi họ hoạt động.', 'I am firmly of the view that profitable companies have a duty to give something back to the communities they operate in.', '["I''m firmly of the view that profitable companies have a duty to give something back to the communities they operate in.","I am firmly of the view that profitable companies have a duty to give something back to the communities in which they operate.","I am firmly of the view that profitable firms have a duty to give something back to the communities they operate in."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","profitable = có lãi; have a duty to V = có nghĩa vụ; give something back = đóng góp lại; operate = hoạt động"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (4, 42, 'Từ góc nhìn của tôi, giờ làm việc linh hoạt là một cách ít tốn kém để người sử dụng lao động giữ cho nhân viên luôn có động lực.', 'From my perspective, flexible working hours are a cheap way for employers to keep their staff motivated.', '["From my perspective, flexible working hours are an inexpensive way for employers to keep their staff motivated.","From my perspective, flexible working hours are a cheap way for employers to keep their employees motivated.","From my perspective, flexible hours are a cheap way for employers to keep their staff motivated."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","flexible working hours = giờ làm linh hoạt; employer = người sử dụng lao động; motivated = có động lực"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (4, 43, 'Với tôi thì có vẻ như các công ty có đạo đức kinh doanh sẽ xây dựng được uy tín vững chắc hơn theo thời gian, dù chi phí ban đầu cao hơn.', 'It seems to me that ethical companies build a stronger reputation over time, even if their costs are higher at first.', '["It seems to me that ethical companies build a stronger reputation over time, even though their costs are higher at first.","It seems to me that ethical firms build a stronger reputation over time, even if their costs are higher at first.","It seems to me that ethical companies build a stronger reputation over time, even if their initial costs are higher."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","ethical = có đạo đức; reputation = uy tín; over time = theo thời gian; initial costs = chi phí ban đầu"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (4, 44, 'Theo tôi, hầu hết các doanh nghiệp sẽ không cắt giảm khí thải trừ khi bị buộc phải làm vậy hoặc có thể tiết kiệm tiền nhờ đó.', 'In my opinion, most firms will not cut their emissions unless they are forced to or can save money by doing so.', '["In my opinion, most companies will not cut their emissions unless they are forced to or can save money by doing so.","In my opinion, most firms won''t cut their emissions unless they are forced to or can save money by doing so.","In my opinion, most firms will not reduce their emissions unless they are forced to or can save money by doing so."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","cut emissions = cắt giảm khí thải; unless = trừ khi; be forced to = bị buộc phải"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (4, 45, 'Từ góc nhìn của tôi, người cao tuổi chịu thiệt nhiều nhất khi các bệnh viện công bị quá tải.', 'From my perspective, the elderly suffer most when public hospitals are overcrowded.', '["From my perspective, elderly people suffer most when public hospitals are overcrowded.","From my perspective, the elderly suffer the most when public hospitals are overcrowded.","From my perspective, the elderly suffer most when public hospitals are overloaded."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","the elderly = người cao tuổi; suffer = chịu thiệt; overcrowded = quá tải"]'::jsonb, 'B2', '6. Sức khỏe'),
    (4, 46, 'Theo tôi, đồ ăn nhanh được ưa chuộng chủ yếu vì nó rẻ và nhanh hơn so với nấu ăn ở nhà.', 'In my opinion, fast food is popular mainly because it is cheaper and quicker than cooking at home.', '["In my opinion, fast food is popular mainly because it is cheaper and faster than cooking at home.","In my opinion, fast food is popular largely because it is cheaper and quicker than cooking at home.","In my opinion, fast food is popular mainly because it is cheaper and quicker than home cooking."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","popular = được ưa chuộng; mainly = chủ yếu; cook at home = nấu ăn ở nhà"]'::jsonb, 'B1', '6. Sức khỏe'),
    (4, 47, 'Tôi kiên quyết cho rằng lối sống ít vận động là một trong những nguyên nhân chính gây ra các bệnh thời hiện đại.', 'I am firmly of the view that a sedentary lifestyle is one of the main causes of modern diseases.', '["I''m firmly of the view that a sedentary lifestyle is one of the main causes of modern diseases.","I am firmly of the view that an inactive lifestyle is one of the main causes of modern diseases.","I am firmly of the view that a sedentary lifestyle is one of the major causes of modern diseases."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","sedentary lifestyle = lối sống ít vận động; main cause = nguyên nhân chính"]'::jsonb, 'C1', '6. Sức khỏe'),
    (4, 48, 'Tôi nghĩ rằng bệnh mãn tính làm giảm khả năng làm việc và kiếm sống của con người.', 'I think that chronic illness reduces people''s ability to work and earn a living.', '["I think chronic illness reduces people''s ability to work and earn a living.","I think that chronic illnesses reduce people''s ability to work and earn a living.","I think that chronic illness reduces people''s ability to work and make a living."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","chronic illness = bệnh mãn tính; earn / make a living = kiếm sống"]'::jsonb, 'B1', '6. Sức khỏe'),
    (4, 49, 'Tôi tin chắc rằng mọi nơi làm việc nên cung cấp dịch vụ tư vấn tâm lý miễn phí cho nhân viên bị căng thẳng.', 'I am convinced that every workplace should offer free counselling for stressed employees.', '["I''m convinced that every workplace should offer free counselling for stressed employees.","I am convinced that every workplace should offer free counseling for stressed employees.","I am convinced that every workplace should provide free counselling for stressed employees.","I am convinced that every workplace should offer free counselling to stressed employees."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","workplace = nơi làm việc; counselling = tư vấn tâm lý; stressed = bị căng thẳng"]'::jsonb, 'B2', '6. Sức khỏe'),
    (4, 50, 'Với tôi thì có vẻ như chỉ cần đi bộ một chút sau bữa trưa cũng khiến mọi người cảm thấy tràn đầy năng lượng hơn vào buổi chiều.', 'It seems to me that even a short walk after lunch makes people feel more energetic in the afternoon.', '["It seems to me that even a brief walk after lunch makes people feel more energetic in the afternoon.","It seems to me that even a short walk after lunch helps people feel more energetic in the afternoon.","It seems to me that even a short walk after lunch makes people feel more energetic in the afternoons."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","a short walk = đi bộ một chút; energetic = tràn đầy năng lượng"]'::jsonb, 'B2', '6. Sức khỏe'),
    (4, 51, 'Nhiều người tin rằng dân số khỏe mạnh hơn giúp chính phủ tiết kiệm rất nhiều tiền chi cho chăm sóc tại bệnh viện.', 'It is widely believed that a healthier population saves the government a great deal of money on hospital care.', '["A healthier population is widely believed to save the government a great deal of money on hospital care.","It''s widely believed that a healthier population saves the government a great deal of money on hospital care.","It is widely believed that a healthier population saves the government a lot of money on hospital care."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","population = dân số; a great deal of = rất nhiều; hospital care = chăm sóc tại bệnh viện"]'::jsonb, 'C1', '6. Sức khỏe'),
    (4, 52, 'Tôi cho rằng chính phủ nên chi tiêu cho việc phòng bệnh nhiều hơn là cho việc chữa bệnh.', 'I would argue that governments should spend more on preventing disease than on treating it.', '["I would argue that governments should spend more on disease prevention than on treatment.","I would argue that the government should spend more on preventing disease than on treating it.","I would argue that governments should spend more money on preventing disease than on treating it.","I would argue that governments should spend more on preventing illness than on treating it."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","prevent disease = phòng bệnh; treat = điều trị; spend on = chi tiêu cho"]'::jsonb, 'C1', '6. Sức khỏe'),
    (4, 53, 'Với tôi thì có vẻ như các hộ gia đình bình thường cảm nhận tác động của giá cả tăng sớm hơn nhiều so với chính phủ.', 'It seems to me that ordinary households feel the effects of rising prices much earlier than the government does.', '["It seems to me that ordinary households feel the effects of rising prices much earlier than the government.","It seems to me that ordinary families feel the effects of rising prices much earlier than the government does.","It seems to me that ordinary households feel the impact of rising prices much earlier than the government does."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","household = hộ gia đình; rising prices = giá cả tăng; effect = tác động"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (4, 54, 'Tôi tin rằng tự động hóa đe dọa các công việc tay nghề thấp nhiều hơn so với cạnh tranh toàn cầu.', 'I believe that automation threatens low-skilled jobs more than global competition does.', '["I believe automation threatens low-skilled jobs more than global competition does.","I believe that automation threatens low-skilled jobs more than global competition.","I believe that automation is a bigger threat to low-skilled jobs than global competition."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","automation = tự động hóa; low-skilled jobs = công việc tay nghề thấp; global competition = cạnh tranh toàn cầu"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (4, 55, 'Từ góc nhìn của tôi, tăng trưởng kinh tế chẳng có mấy ý nghĩa nếu phần lớn của cải rơi vào tay một nhóm nhỏ.', 'From my perspective, economic growth means little if most of the wealth goes to a small group of people.', '["From my perspective, economic growth means little if most of the wealth goes to a small number of people.","From my perspective, economic growth means very little if most of the wealth goes to a small group of people.","From my perspective, economic growth means little if most wealth goes to a small group of people."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","mean little = chẳng có mấy ý nghĩa; wealth = của cải"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (4, 56, 'Tôi kiên quyết cho rằng đầu tư vào đường sá và cảng biển là điều thiết yếu để thu hút đầu tư nước ngoài.', 'I am firmly of the view that investing in roads and ports is essential for attracting foreign investment.', '["I''m firmly of the view that investing in roads and ports is essential for attracting foreign investment.","I am firmly of the view that investing in roads and ports is essential to attract foreign investment.","I am firmly of the view that investment in roads and ports is essential for attracting foreign investment."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","port = cảng biển; essential = thiết yếu; attract foreign investment = thu hút đầu tư nước ngoài"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (4, 57, 'Tôi tin chắc rằng các chương trình đào tạo lại là cách tốt nhất để giúp những người lao động bị máy móc lấy mất việc làm.', 'I am convinced that retraining programmes are the best way to help workers who lose their jobs to machines.', '["I''m convinced that retraining programmes are the best way to help workers who lose their jobs to machines.","I am convinced that retraining programs are the best way to help workers who lose their jobs to machines.","I am convinced that retraining schemes are the best way to help workers who lose their jobs to machines."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","retraining programme = chương trình đào tạo lại; lose one''s job to machines = bị máy móc lấy mất việc"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (4, 58, 'Nhiều người tin rằng đầu tư công quy mô lớn làm tăng nợ quốc gia trong ngắn hạn.', 'Heavy public investment is widely believed to increase national debt in the short term.', '["It is widely believed that heavy public investment increases national debt in the short term.","Heavy public investment is widely believed to raise national debt in the short term.","Large-scale public investment is widely believed to increase national debt in the short term.","It''s widely believed that heavy public investment increases national debt in the short term."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","public investment = đầu tư công; national debt = nợ quốc gia; in the short term = trong ngắn hạn"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (4, 59, 'Theo tôi, tạo việc làm là giải pháp lâu dài tốt hơn so với phát trợ cấp thất nghiệp.', 'In my opinion, creating jobs is a better long-term solution than giving out unemployment benefits.', '["In my opinion, creating jobs is a better long-term solution than handing out unemployment benefits.","In my opinion, job creation is a better long-term solution than giving out unemployment benefits.","In my opinion, creating jobs is a better long-term solution than paying unemployment benefits."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","unemployment benefits = trợ cấp thất nghiệp; job creation = tạo việc làm; long-term solution = giải pháp lâu dài"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (4, 60, 'Tôi cho rằng các quốc gia nên coi trọng tăng trưởng ổn định hơn là những khoản lợi nhuận nhanh nhưng nhiều rủi ro.', 'I would argue that countries should value stable growth over quick but risky profits.', '["I would argue that countries should value steady growth over quick but risky profits.","I would argue that nations should value stable growth over quick but risky profits.","I would argue that countries should put stable growth before quick but risky profits."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","value A over B = coi trọng A hơn B; stable growth = tăng trưởng ổn định; risky = nhiều rủi ro"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (4, 61, 'Tôi tin rằng người nhập cư đóng góp rất nhiều cho xã hội nhưng thường bị đối xử bất công.', 'I believe that immigrants contribute a great deal to society but are often treated unfairly.', '["I believe immigrants contribute a great deal to society but are often treated unfairly.","I believe that immigrants contribute a lot to society but are often treated unfairly.","I believe that immigrants make a great contribution to society but are often treated unfairly."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","immigrant = người nhập cư; contribute to = đóng góp cho; treat unfairly = đối xử bất công"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (4, 62, 'Tôi cho rằng cư dân địa phương có thể làm được nhiều hơn cảnh sát trong việc giữ an toàn cho đường phố của họ.', 'I would argue that local residents can do more than the police to keep their streets safe.', '["I would argue that local people can do more than the police to keep their streets safe.","I would argue that residents can do more than the police to keep their streets safe.","I would argue that local residents can do more than the police to make their streets safe."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","local residents = cư dân địa phương; keep sth safe = giữ an toàn cho"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (4, 63, 'Với tôi thì có vẻ như người dân ở các thành phố lớn hiếm khi biết tên hàng xóm của mình.', 'It seems to me that people in big cities rarely know the names of their neighbours.', '["It seems to me that people in big cities rarely know the names of their neighbors.","It seems to me that people in large cities rarely know the names of their neighbours.","It seems to me that people in big cities rarely know their neighbours'' names.","It seems to me that city dwellers rarely know the names of their neighbours."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","rarely = hiếm khi; neighbour = hàng xóm; city dwellers = người dân thành phố"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (4, 64, 'Nhiều người tin rằng khoảng cách giàu nghèo ngày càng lớn là một nguyên nhân chính gây ra căng thẳng xã hội.', 'The growing gap between rich and poor is widely believed to be a major cause of social tension.', '["It is widely believed that the growing gap between rich and poor is a major cause of social tension.","The widening gap between rich and poor is widely believed to be a major cause of social tension.","The growing gap between the rich and the poor is widely believed to be a major cause of social tension."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","growing / widening gap = khoảng cách ngày càng lớn; social tension = căng thẳng xã hội"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (4, 65, 'Theo tôi, nghèo đói là rào cản lớn nhất đối với việc học của trẻ em ở nông thôn.', 'In my opinion, poverty is the biggest barrier to education for children in rural areas.', '["In my opinion, poverty is the greatest barrier to education for children in rural areas.","In my opinion, poverty is the biggest obstacle to education for children in rural areas.","In my opinion, poverty is the biggest barrier to education for rural children."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","barrier to sth = rào cản đối với; rural areas = vùng nông thôn"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (4, 66, 'Tôi tin chắc rằng hoạt động tình nguyện dạy thanh thiếu niên biết quan tâm đến những người ngoài gia đình mình.', 'I am convinced that volunteering teaches teenagers to care about people outside their own family.', '["I''m convinced that volunteering teaches teenagers to care about people outside their own family.","I am convinced that volunteer work teaches teenagers to care about people outside their own family.","I am convinced that volunteering teaches teenagers to care about people beyond their own family."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","volunteering = hoạt động tình nguyện; care about = quan tâm đến"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (4, 67, 'Tôi kiên quyết cho rằng các dự án cộng đồng làm giảm tội phạm, dù phải mất nhiều năm mới thấy kết quả.', 'I am firmly of the view that community projects reduce crime, even though their results take years to appear.', '["I''m firmly of the view that community projects reduce crime, even though their results take years to appear.","I am firmly of the view that community projects reduce crime, even though the results take years to appear.","I am firmly of the view that community projects cut crime, even though their results take years to appear.","I am firmly of the view that community projects reduce crime, although their results take years to appear."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","community project = dự án cộng đồng; take years to V = mất nhiều năm mới"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (4, 68, 'Từ góc nhìn của tôi, đào tạo nghề giúp các nhóm yếu thế nhiều hơn hẳn so với việc phát tiền mặt.', 'From my perspective, job training helps disadvantaged groups far more than cash handouts do.', '["From my perspective, job training helps disadvantaged groups far more than cash handouts.","From my perspective, job training helps disadvantaged groups much more than cash handouts do.","From my perspective, vocational training helps disadvantaged groups far more than cash handouts do."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","disadvantaged groups = nhóm yếu thế; cash handouts = phát tiền mặt; vocational training = đào tạo nghề"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (4, 69, 'Tôi tin chắc rằng những người lái xe bình thường phải chịu trách nhiệm cho một phần lớn ô nhiễm không khí ở các thành phố.', 'I am convinced that ordinary drivers are responsible for a large share of air pollution in cities.', '["I''m convinced that ordinary drivers are responsible for a large share of air pollution in cities.","I am convinced that ordinary drivers are responsible for a large part of air pollution in cities.","I am convinced that ordinary drivers are responsible for a large share of the air pollution in cities."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","be responsible for = chịu trách nhiệm cho; a large share of = một phần lớn"]'::jsonb, 'B2', '9. Môi trường'),
    (4, 70, 'Tôi nghĩ rằng xăng giá rẻ khuyến khích mọi người lái xe ngay cả cho những chuyến đi rất ngắn.', 'I think that cheap petrol encourages people to drive even for very short trips.', '["I think cheap petrol encourages people to drive even for very short trips.","I think that cheap fuel encourages people to drive even for very short trips.","I think that cheap gas encourages people to drive even for very short trips.","I think that cheap petrol encourages people to drive even for very short journeys."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","petrol = xăng; encourage sb to V = khuyến khích ai làm gì; short trip = chuyến đi ngắn"]'::jsonb, 'B1', '9. Môi trường'),
    (4, 71, 'Nhiều người tin rằng biến đổi khí hậu đe dọa nguồn cung lương thực ở nhiều nước nghèo.', 'Climate change is widely believed to threaten food supplies in many poor countries.', '["It is widely believed that climate change threatens food supplies in many poor countries.","It''s widely believed that climate change threatens food supplies in many poor countries.","Climate change is widely believed to endanger food supplies in many poor countries.","Climate change is widely believed to threaten food supplies in many developing countries."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","climate change = biến đổi khí hậu; threaten = đe dọa; food supplies = nguồn cung lương thực"]'::jsonb, 'C1', '9. Môi trường'),
    (4, 72, 'Từ góc nhìn của tôi, việc chặt phá rừng để lấy đất canh tác phá hủy nơi sống của vô số loài động vật.', 'From my perspective, cutting down forests for farmland destroys the homes of countless animals.', '["From my perspective, cutting down forests for farmland destroys the habitats of countless animals.","From my perspective, clearing forests for farmland destroys the homes of countless animals.","From my perspective, cutting down forests for farmland destroys the homes of countless species."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","cut down / clear forests = chặt phá rừng; farmland = đất canh tác; habitat = nơi sống; countless = vô số"]'::jsonb, 'B2', '9. Môi trường'),
    (4, 73, 'Với tôi thì có vẻ như thu phí túi nilon là một cách đơn giản để thay đổi thói quen của người mua sắm.', 'It seems to me that charging for plastic bags is a simple way to change shoppers'' habits.', '["It seems to me that charging for plastic bags is an easy way to change shoppers'' habits.","It seems to me that charging for plastic bags is a simple way to change the habits of shoppers.","It seems to me that charging money for plastic bags is a simple way to change shoppers'' habits."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","charge for sth = thu phí cho; plastic bag = túi nilon; shopper = người mua sắm"]'::jsonb, 'B2', '9. Môi trường'),
    (4, 74, 'Theo tôi, chi phí cao của việc chuyển sang năng lượng mặt trời không nên ngăn các quốc gia hành động ngay bây giờ.', 'In my opinion, the high cost of switching to solar power should not stop countries from acting now.', '["In my opinion, the high cost of switching to solar energy should not stop countries from acting now.","In my opinion, the high cost of switching to solar power should not prevent countries from acting now.","In my opinion, the high cost of switching to solar power shouldn''t stop countries from acting now."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","switch to = chuyển sang; solar power = năng lượng mặt trời; act = hành động"]'::jsonb, 'B1', '9. Môi trường'),
    (4, 75, 'Tôi cho rằng một số thiệt hại về môi trường sẽ trở thành vĩnh viễn nếu chúng ta chờ thêm một thập kỷ nữa.', 'I would argue that some environmental damage will become permanent if we wait another decade.', '["I would argue that some environmental damage will become irreversible if we wait another decade.","I would argue that some environmental damage will become permanent if we wait another ten years.","I would argue that some damage to the environment will become permanent if we wait another decade."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","permanent = vĩnh viễn; irreversible = không thể đảo ngược; decade = thập kỷ"]'::jsonb, 'C1', '9. Môi trường'),
    (4, 76, 'Tôi kiên quyết cho rằng các nước giàu nên chi trả nhiều hơn để chống biến đổi khí hậu vì họ đã gây ô nhiễm nhiều nhất.', 'I am firmly of the view that rich countries should pay more to fight climate change because they have polluted the most.', '["I''m firmly of the view that rich countries should pay more to fight climate change because they have polluted the most.","I am firmly of the view that wealthy countries should pay more to fight climate change because they have polluted the most.","I am firmly of the view that rich countries should pay more to tackle climate change because they have polluted the most.","I am firmly of the view that rich nations should pay more to fight climate change because they have polluted the most."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","fight / tackle climate change = chống biến đổi khí hậu; pollute = gây ô nhiễm"]'::jsonb, 'C1', '9. Môi trường'),
    (4, 77, 'Tôi kiên quyết cho rằng các công ty công nghệ phải bị xử phạt khi họ không bảo vệ được dữ liệu cá nhân của người dùng.', 'I am firmly of the view that tech companies must be punished when they fail to protect users'' personal data.', '["I''m firmly of the view that tech companies must be punished when they fail to protect users'' personal data.","I am firmly of the view that technology companies must be punished when they fail to protect users'' personal data.","I am firmly of the view that tech companies should be punished when they fail to protect users'' personal data."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","tech company = công ty công nghệ; punish = xử phạt; personal data = dữ liệu cá nhân"]'::jsonb, 'C1', '10. Công nghệ'),
    (4, 78, 'Theo tôi, người lớn tuổi thường bị bỏ lại phía sau vì các ứng dụng mới không được thiết kế cho họ.', 'In my opinion, older people are often left behind because new apps are not designed for them.', '["In my opinion, elderly people are often left behind because new apps are not designed for them.","In my opinion, older people are often left behind because new apps aren''t designed for them.","In my opinion, older people are often left behind because new applications are not designed for them."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","be left behind = bị bỏ lại phía sau; app = ứng dụng; be designed for = được thiết kế cho"]'::jsonb, 'B1', '10. Công nghệ'),
    (4, 79, 'Từ góc nhìn của tôi, điện thoại thông minh giá rẻ đã đưa Internet đến với hàng triệu người ở các vùng nghèo.', 'From my perspective, cheap smartphones have brought the Internet to millions of people in poor regions.', '["From my perspective, affordable smartphones have brought the Internet to millions of people in poor regions.","From my perspective, cheap smartphones have brought the Internet to millions of people in poorer regions.","From my perspective, cheap smartphones have brought the Internet to millions of people in poor areas."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","affordable = giá phải chăng; bring sth to sb = đưa điều gì đến với ai; region = vùng"]'::jsonb, 'B2', '10. Công nghệ'),
    (4, 80, 'Nhiều người tin rằng trí tuệ nhân tạo sẽ thay thế nhiều công việc văn phòng trong vòng hai mươi năm tới.', 'It is widely believed that artificial intelligence will replace many office jobs within the next twenty years.', '["It''s widely believed that artificial intelligence will replace many office jobs within the next twenty years.","It is widely believed that AI will replace many office jobs within the next twenty years.","It is widely believed that artificial intelligence will replace many office jobs in the next twenty years.","It is widely believed that artificial intelligence will replace many office jobs within the next 20 years."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","artificial intelligence (AI) = trí tuệ nhân tạo; replace = thay thế; office job = công việc văn phòng"]'::jsonb, 'C1', '10. Công nghệ'),
    (4, 81, 'Tôi nghĩ rằng việc dành hàng giờ trên mạng xã hội khiến thanh thiếu niên còn ít thời gian hơn cho những tình bạn thực sự.', 'I think that spending hours on social media leaves teenagers with less time for real friendships.', '["I think spending hours on social media leaves teenagers with less time for real friendships.","I think that spending hours on social media leaves teenagers less time for real friendships.","I think that spending hours on social media leaves teenagers with less time for genuine friendships."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","social media = mạng xã hội; leave sb with sth = để lại cho ai cái gì; real friendships = tình bạn thực sự"]'::jsonb, 'B1', '10. Công nghệ'),
    (4, 82, 'Tôi tin chắc rằng trẻ em nên học cách nhận biết tin giả trước khi có điện thoại thông minh riêng.', 'I am convinced that children should learn how to spot fake news before they get their own smartphones.', '["I''m convinced that children should learn how to spot fake news before they get their own smartphones.","I am convinced that children should learn to spot fake news before they get their own smartphones.","I am convinced that children should learn how to identify fake news before they get their own smartphones."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","spot / identify = nhận biết; fake news = tin giả"]'::jsonb, 'B2', '10. Công nghệ'),
    (4, 83, 'Với tôi thì có vẻ như tự động hóa xóa bỏ việc làm rất nhanh nhưng tạo ra việc làm mới thì lại chậm.', 'It seems to me that automation destroys jobs quickly but creates new ones only slowly.', '["It seems to me that automation eliminates jobs quickly but creates new ones only slowly.","It seems to me that automation destroys jobs quickly but only slowly creates new ones.","It seems to me that automation wipes out jobs quickly but creates new ones only slowly."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","automation = tự động hóa; destroy / eliminate jobs = xóa bỏ việc làm"]'::jsonb, 'B2', '10. Công nghệ'),
    (4, 84, 'Tôi cho rằng việc cấm điện thoại trong lớp học mang lại nhiều lợi hơn hại.', 'I would argue that a ban on phones in classrooms does more good than harm.', '["I would argue that banning phones in classrooms does more good than harm.","I would argue that a ban on mobile phones in classrooms does more good than harm.","I would argue that a ban on phones in the classroom does more good than harm."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","a ban on sth = lệnh cấm; do more good than harm = lợi nhiều hơn hại"]'::jsonb, 'C1', '10. Công nghệ'),
    (4, 85, 'Tôi tin rằng những người đi làm bận rộn được hưởng lợi nhiều nhất từ các dịch vụ giúp họ tiết kiệm thời gian.', 'I believe that busy professionals benefit most from services that save them time.', '["I believe busy professionals benefit most from services that save them time.","I believe that busy professionals benefit the most from services that save them time.","I believe that busy professionals benefit most from time-saving services."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","busy professionals = người đi làm bận rộn; benefit from = được hưởng lợi từ; time-saving = tiết kiệm thời gian"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (4, 86, 'Nhiều người tin rằng ùn tắc giao thông là lý do chính khiến thời gian đi làm ngày càng dài hơn.', 'Traffic congestion is widely believed to be the main reason why commutes are getting longer.', '["It is widely believed that traffic congestion is the main reason why commutes are getting longer.","Traffic congestion is widely believed to be the main reason commutes are getting longer.","Traffic jams are widely believed to be the main reason why commutes are getting longer."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","traffic congestion = ùn tắc giao thông; commute = chuyến đi làm hằng ngày"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (4, 87, 'Với tôi thì có vẻ như cuộc sống đô thị hiện đại khiến con người hầu như không còn thời gian để thư giãn.', 'It seems to me that modern city life leaves people with almost no time to relax.', '["It seems to me that modern city life leaves people almost no time to relax.","It seems to me that modern urban life leaves people with almost no time to relax.","It seems to me that modern city life leaves people with hardly any time to relax."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","city life = cuộc sống đô thị; leave sb with = để lại cho ai; relax = thư giãn"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (4, 88, 'Tôi cho rằng các dịch vụ trực tuyến giúp mọi người tiết kiệm công sức cũng như thời gian, nhất là khi làm thủ tục giấy tờ.', 'I would argue that online services save people effort as well as time, especially when it comes to paperwork.', '["I would argue that online services save people effort as well as time, particularly when it comes to paperwork.","I would argue that online services save people both time and effort, especially when it comes to paperwork.","I would argue that online services save people effort as well as time, especially when dealing with paperwork."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","save effort = tiết kiệm công sức; paperwork = thủ tục giấy tờ; when it comes to = khi nói đến"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (4, 89, 'Theo tôi, đặt mua thực phẩm trực tuyến là một cách hợp lý để cha mẹ đi làm tiết kiệm thời gian.', 'In my opinion, ordering groceries online is a sensible way for working parents to save time.', '["In my opinion, buying groceries online is a sensible way for working parents to save time.","In my opinion, ordering groceries online is a smart way for working parents to save time.","In my opinion, ordering food online is a sensible way for working parents to save time."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","groceries = thực phẩm, đồ tạp hóa; sensible = hợp lý; working parents = cha mẹ đi làm"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (4, 90, 'Từ góc nhìn của tôi, những người dựa vào ứng dụng cho mọi việc có thể gặp khó khăn khi phải xoay xở mà không có chúng.', 'From my perspective, people who rely on apps for everything may struggle to cope without them.', '["From my perspective, people who depend on apps for everything may struggle to cope without them.","From my perspective, people who rely on apps for everything might struggle to cope without them.","From my perspective, people who rely on apps for everything may find it hard to cope without them."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","rely on / depend on = dựa vào; struggle to V = gặp khó khăn khi; cope = xoay xở"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (4, 91, 'Tôi kiên quyết cho rằng kết hợp làm việc ở văn phòng và ở nhà là phù hợp nhất với hầu hết nhân viên.', 'I am firmly of the view that a mix of office and home working suits most employees best.', '["I''m firmly of the view that a mix of office and home working suits most employees best.","I am firmly of the view that a combination of office and home working suits most employees best.","I am firmly of the view that a mix of office and remote working suits most employees best."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","a mix / combination of A and B = sự kết hợp A và B; home working = làm việc tại nhà; suit sb = phù hợp với ai"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (4, 92, 'Tôi tin chắc rằng tiết kiệm thời gian là vô nghĩa trừ khi người ta dùng nó cho việc gì đó có ý nghĩa.', 'I am convinced that saving time is pointless unless people use it for something meaningful.', '["I''m convinced that saving time is pointless unless people use it for something meaningful.","I am convinced that saving time is pointless unless people spend it on something meaningful.","I am convinced that saving time is useless unless people use it for something meaningful."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","pointless = vô nghĩa; unless = trừ khi; meaningful = có ý nghĩa"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (4, 93, 'Theo tôi, thế hệ hiện tại nên chấp nhận chi phí cao hơn ngày hôm nay để bảo vệ tương lai của con cháu.', 'In my opinion, the current generation should accept higher costs today to protect the future of their children and grandchildren.', '["In my opinion, today''s generation should accept higher costs now to protect the future of their children and grandchildren.","In my opinion, the current generation should accept higher costs today to safeguard the future of their children and grandchildren.","In my opinion, the present generation should accept higher costs today to protect the future of their children and grandchildren."]'::jsonb, '["In my opinion, … = theo tôi (mục 2.4)","current generation = thế hệ hiện tại; accept = chấp nhận; safeguard = bảo vệ; children and grandchildren = con cháu"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (4, 94, 'Tôi tin chắc rằng các chính trị gia thích kết quả nhanh vì họ cần thắng cuộc bầu cử tiếp theo.', 'I am convinced that politicians prefer quick results because they need to win the next election.', '["I''m convinced that politicians prefer quick results because they need to win the next election.","I am convinced that politicians prefer fast results because they need to win the next election.","I am convinced that politicians prefer quick results because they have to win the next election."]'::jsonb, '["I am convinced that … = tôi tin chắc rằng (mục 2.4)","politician = chính trị gia; quick results = kết quả nhanh; election = cuộc bầu cử"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (4, 95, 'Tôi nghĩ rằng hàng giá rẻ thường mang lại khoản tiết kiệm trước mắt nhưng lại gây tốn kém về lâu dài.', 'I think that cheap products often bring short-term savings but long-term costs.', '["I think cheap products often bring short-term savings but long-term costs.","I think that cheap goods often bring short-term savings but long-term costs.","I think that cheap products often bring savings in the short term but costs in the long term."]'::jsonb, '["I think / I believe that … = tôi nghĩ / tôi tin rằng (mục 2.4)","short-term savings = khoản tiết kiệm trước mắt; long-term costs = chi phí về lâu dài"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (4, 96, 'Tôi kiên quyết cho rằng chúng ta không có quyền dùng cạn những tài nguyên mà các thế hệ tương lai sẽ cần đến.', 'I am firmly of the view that we have no right to use up resources that future generations will need.', '["I''m firmly of the view that we have no right to use up resources that future generations will need.","I am firmly of the view that we have no right to use up the resources that future generations will need.","I am firmly of the view that we have no right to use up resources future generations will need.","I am firmly of the view that we have no right to exhaust resources that future generations will need."]'::jsonb, '["I am firmly of the view that … = tôi kiên quyết cho rằng (mục 2.4)","have no right to V = không có quyền; use up / exhaust = dùng cạn; resources = tài nguyên"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (4, 97, 'Từ góc nhìn của tôi, các cải cách lớn nên được thực hiện từng bước để người dân có thời gian thích nghi.', 'From my perspective, major reforms should be introduced step by step so that people have time to adjust.', '["From my perspective, major reforms should be introduced gradually so that people have time to adjust.","From my perspective, major reforms should be introduced step by step so that people have time to adapt.","From my perspective, big reforms should be introduced step by step so that people have time to adjust."]'::jsonb, '["From my perspective, … = từ góc nhìn của tôi (mục 2.4)","reform = cải cách; step by step / gradually = từng bước; adjust / adapt = thích nghi"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (4, 98, 'Nhiều người tin rằng những người lao động mất việc trong giai đoạn chuyển đổi xứng đáng được nhà nước hỗ trợ tài chính.', 'It is widely believed that workers who lose their jobs during a transition deserve financial support from the state.', '["Workers who lose their jobs during a transition are widely believed to deserve financial support from the state.","It''s widely believed that workers who lose their jobs during a transition deserve financial support from the state.","It is widely believed that workers who lose their jobs during a transition deserve financial help from the state.","It is widely believed that workers who lose their jobs during a transition deserve financial support from the government."]'::jsonb, '["It is widely believed that … / X is widely believed to V = nhiều người tin rằng (mục 2.4)","transition = giai đoạn chuyển đổi; deserve = xứng đáng; financial support = hỗ trợ tài chính"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (4, 99, 'Với tôi thì có vẻ như hầu hết mọi người đánh giá một chính sách qua tác động trước mắt của nó hơn là kết quả lâu dài.', 'It seems to me that most people judge a policy by its immediate effects rather than its long-term results.', '["It seems to me that most people judge a policy by its immediate effects instead of its long-term results.","It seems to me that most people judge a policy by its short-term effects rather than its long-term results.","It seems to me that most people judge a policy on its immediate effects rather than its long-term results."]'::jsonb, '["It seems to me that … = với tôi thì có vẻ như (mục 2.4)","judge sth by = đánh giá điều gì qua; immediate effects = tác động trước mắt; long-term results = kết quả lâu dài"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (4, 100, 'Tôi cho rằng các giải pháp tạm thời rốt cuộc thường tốn kém hơn các giải pháp lâu dài.', 'I would argue that temporary solutions usually cost more in the end than permanent ones.', '["I would argue that temporary solutions usually end up costing more than permanent ones.","I would argue that short-term solutions usually cost more in the end than permanent ones.","I would argue that temporary fixes usually cost more in the end than permanent ones.","I would argue that temporary solutions usually cost more in the long run than permanent ones."]'::jsonb, '["I would argue that … = tôi cho rằng (khi lập luận) (mục 2.4)","temporary solution = giải pháp tạm thời; permanent = lâu dài, vĩnh viễn; in the end = rốt cuộc"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (5, 1, 'Chính phủ trung ương có thể ban hành luật cho cả nước, trong khi chính quyền địa phương hiểu rõ hơn nhu cầu của từng cộng đồng.', 'The central government can pass laws for the whole country, whereas local authorities better understand the needs of each community.', '["The central government can pass laws for the whole country, while local authorities better understand the needs of each community.","The central government can pass laws for the whole country, whereas local authorities understand the needs of each community better.","The central government can pass laws for the entire country, whereas local authorities better understand the needs of each community."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","central government = chính phủ trung ương; local authorities = chính quyền địa phương; whereas = trong khi (đối lập)"]'::jsonb, 'B2', '1. Chính phủ'),
    (5, 2, 'Dù người dân rất coi trọng tự do cá nhân, một số vấn đề quá lớn để giải quyết mà không có sự can thiệp của nhà nước.', 'Much as citizens value their personal freedom, some problems are too large to solve without state intervention.', '["Much as citizens value their individual freedom, some problems are too large to solve without state intervention.","Much as people value their personal freedom, some problems are too large to solve without state intervention.","Much as citizens value their personal freedom, some problems are too big to solve without government intervention."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; personal freedom = tự do cá nhân; state intervention = sự can thiệp của nhà nước"]'::jsonb, 'C1', '1. Chính phủ'),
    (5, 3, 'Phải thừa nhận là thị trường tự do tạo ra của cải một cách hiệu quả; dù vậy, nó thường không bảo vệ được người yếu thế và môi trường.', 'Admittedly, the free market creates wealth efficiently; nevertheless, it often fails to protect vulnerable people and the environment.', '["Admittedly, the free market creates wealth efficiently; nevertheless, it frequently fails to protect vulnerable people and the environment.","Admittedly, free markets create wealth efficiently; nevertheless, they often fail to protect vulnerable people and the environment.","Admittedly, the free market generates wealth efficiently; nevertheless, it often fails to protect vulnerable people and the environment."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","admittedly = phải thừa nhận là; nevertheless = dù vậy; fail to do sth = không làm được gì; vulnerable people = người yếu thế"]'::jsonb, 'C1', '1. Chính phủ'),
    (5, 4, 'Hành động của chính phủ có thể thay đổi hành vi trên cả nước, nhưng một chính sách được lên kế hoạch kém có thể lãng phí rất nhiều tiền thuế của dân.', 'Government action can change behaviour across the whole country, but a badly planned policy can waste a great deal of taxpayers'' money.', '["Government action can change behaviour across the whole country; however, a badly planned policy can waste a great deal of taxpayers'' money.","Government action can change behaviour across the entire country, but a poorly planned policy can waste a great deal of taxpayers'' money.","Government action can change behavior across the whole country, but a badly planned policy can waste a great deal of taxpayers'' money."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","behaviour (Mỹ: behavior) = hành vi; badly planned = được lên kế hoạch kém; taxpayers'' money = tiền thuế của dân"]'::jsonb, 'B1', '1. Chính phủ'),
    (5, 5, 'Bất chấp việc không được nhiều cử tri ưa chuộng, thuế đánh vào đồ uống có đường có thể giúp giảm tỷ lệ béo phì.', 'Despite being unpopular with many voters, taxes on sugary drinks can help to reduce obesity rates.', '["In spite of being unpopular with many voters, taxes on sugary drinks can help to reduce obesity rates.","Despite being unpopular with many voters, taxes on sugary drinks can help reduce obesity rates.","Despite their unpopularity with many voters, taxes on sugary drinks can help to reduce obesity rates."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + V-ing / danh từ, không + mệnh đề; unpopular with = không được ai ưa chuộng; obesity rate = tỷ lệ béo phì"]'::jsonb, 'B2', '1. Chính phủ'),
    (5, 6, 'Các chiến dịch nâng cao nhận thức khá rẻ để triển khai, nhưng chúng hiếm khi thay đổi được thói quen của người dân nếu không có luật nghiêm hơn hỗ trợ.', 'Awareness campaigns are fairly cheap to run, but they seldom change people''s habits without the support of stricter laws.', '["Awareness campaigns are fairly cheap to run; however, they seldom change people''s habits without the support of stricter laws.","Awareness campaigns are quite cheap to run, but they seldom change people''s habits without the support of stricter laws.","Awareness campaigns are fairly cheap to run, but they rarely change people''s habits without the support of stricter laws."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","awareness campaign = chiến dịch nâng cao nhận thức; run = triển khai, tổ chức; seldom = hiếm khi"]'::jsonb, 'B1', '1. Chính phủ'),
    (5, 7, 'Mặc dù các quy định mới tốn kém để thực thi lúc đầu, chúng có thể mang lại thay đổi bền vững và có hệ thống về lâu dài.', 'Although new regulations are expensive to enforce at first, they can bring lasting, systematic change in the long run.', '["Even though new regulations are expensive to enforce at first, they can bring lasting, systematic change in the long run.","Although new regulations are costly to enforce at first, they can bring lasting, systematic change in the long run.","Although new rules are expensive to enforce at first, they can bring lasting, systematic change in the long term."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","enforce = thực thi; lasting = bền vững, lâu dài; systematic change = thay đổi có hệ thống"]'::jsonb, 'B1', '1. Chính phủ'),
    (5, 8, 'Một mặt, lời kêu gọi tự nguyện tôn trọng lựa chọn cá nhân; mặt khác, các biện pháp có tính ràng buộc pháp lý hiệu quả hơn nhiều.', 'On the one hand, voluntary appeals respect personal choice; on the other hand, legally binding measures are far more effective.', '["On the one hand, voluntary appeals respect individual choice; on the other hand, legally binding measures are far more effective.","On the one hand, voluntary appeals respect personal choice; on the other hand, legally binding measures are much more effective.","On the one hand, voluntary appeals respect personal choice; on the other hand, compulsory measures are far more effective."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","voluntary appeal = lời kêu gọi tự nguyện; legally binding = có tính ràng buộc pháp lý; far more effective = hiệu quả hơn nhiều"]'::jsonb, 'B2', '1. Chính phủ'),
    (5, 9, 'Dù đúng là chính phủ nắm nhiều quyền lực nhất, chính phủ không thể thành công nếu thiếu sự tham gia của người dân bình thường.', 'While it is true that the government has the most power, it cannot succeed without the participation of ordinary citizens.', '["While it''s true that the government has the most power, it cannot succeed without the participation of ordinary citizens.","While it is true that the government has the most power, it cannot succeed without the involvement of ordinary citizens.","While it is true that the government holds the most power, it can''t succeed without the participation of ordinary citizens."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","while it is true that = dù đúng là; participation = sự tham gia; ordinary citizens = người dân bình thường"]'::jsonb, 'C1', '1. Chính phủ'),
    (5, 10, 'Người trẻ khá dễ dàng tiếp nhận thói quen mới, trong khi người lớn tuổi thường thích giữ nếp sinh hoạt quen thuộc.', 'Young people adopt new habits quite easily, whereas older people often prefer to keep their familiar routines.', '["Young people adopt new habits quite easily, while older people often prefer to keep their familiar routines.","Young people pick up new habits quite easily, whereas older people often prefer to keep their familiar routines.","Young people adopt new habits fairly easily, whereas elderly people often prefer to keep their familiar routines."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","adopt a habit = tiếp nhận thói quen; routine = nếp sinh hoạt; whereas = trong khi (đối lập)"]'::jsonb, 'B2', '2. Cá nhân'),
    (5, 11, 'Dù rất muốn mua sản phẩm thân thiện với môi trường, nhiều người tiêu dùng không đủ khả năng chi trả mức giá cao hơn.', 'Much as consumers want to buy eco-friendly products, many of them cannot afford the higher prices.', '["Much as consumers would like to buy eco-friendly products, many of them cannot afford the higher prices.","Much as consumers want to buy environmentally friendly products, many of them cannot afford the higher prices.","Much as consumers want to buy eco-friendly products, many of them can''t afford the higher prices."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; eco-friendly = thân thiện với môi trường; afford = đủ khả năng chi trả"]'::jsonb, 'C1', '2. Cá nhân'),
    (5, 12, 'Phải thừa nhận là luật pháp có thể điều chỉnh hành vi nơi công cộng; dù vậy, luật không thể kiểm soát mọi lựa chọn mà người dân đưa ra ở nhà.', 'Admittedly, laws can regulate public behaviour; nevertheless, they cannot control every choice people make at home.', '["Admittedly, laws can regulate public behaviour; nevertheless, they cannot control every choice that people make at home.","Admittedly, laws can regulate public behavior; nevertheless, they cannot control every choice people make at home.","Admittedly, the law can regulate public behaviour; nevertheless, it cannot control every choice people make at home."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","regulate = điều chỉnh, quản lý; public behaviour (Mỹ: behavior) = hành vi nơi công cộng; nevertheless = dù vậy"]'::jsonb, 'C1', '2. Cá nhân'),
    (5, 13, 'Mặc dù một lựa chọn cá nhân có vẻ không đáng kể, hàng triệu lựa chọn như vậy cộng lại gây ra nhiều vấn đề xã hội và môi trường.', 'Although a single personal choice seems insignificant, millions of such choices together cause many social and environmental problems.', '["Even though a single personal choice seems insignificant, millions of such choices together cause many social and environmental problems.","Although one personal choice seems insignificant, millions of such choices together cause many social and environmental problems.","Although a single personal choice seems unimportant, millions of such choices together cause many social and environmental problems."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","insignificant = không đáng kể; such choices = những lựa chọn như vậy; together = cộng lại"]'::jsonb, 'B1', '2. Cá nhân'),
    (5, 14, 'Thay đổi thói quen cá nhân đòi hỏi nỗ lực, nhưng việc này thường truyền cảm hứng cho bạn bè và người thân làm theo.', 'Changing personal habits takes effort, but it often inspires friends and relatives to do the same.', '["Changing personal habits takes effort; however, it often inspires friends and relatives to do the same.","Changing personal habits requires effort, but it often inspires friends and relatives to do the same.","Changing personal habits takes effort, but it frequently inspires friends and relatives to do the same."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","take effort = đòi hỏi nỗ lực; inspire sb to do sth = truyền cảm hứng cho ai làm gì; relatives = người thân"]'::jsonb, 'B1', '2. Cá nhân'),
    (5, 15, 'Dù có lịch trình bận rộn, nhiều người vẫn dành thời gian làm tình nguyện ở cộng đồng địa phương.', 'Despite having busy schedules, many people still find time to volunteer in their local community.', '["In spite of having busy schedules, many people still find time to volunteer in their local community.","Despite their busy schedules, many people still find time to volunteer in their local community.","Despite having busy schedules, many people still make time to volunteer in their local community."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + V-ing, không + mệnh đề; busy schedule = lịch trình bận rộn; find time = dành thời gian; volunteer = làm tình nguyện"]'::jsonb, 'B2', '2. Cá nhân'),
    (5, 16, 'Một mặt, tìm hiểu thông tin trước khi mua sắm tốn thời gian; mặt khác, việc này giúp người tiêu dùng tránh lãng phí tiền.', 'On the one hand, doing research before shopping takes time; on the other hand, it helps consumers avoid wasting money.', '["On the one hand, doing research before shopping takes time; on the other hand, it helps consumers to avoid wasting money.","On the one hand, doing research before shopping is time-consuming; on the other hand, it helps consumers avoid wasting money.","On the one hand, researching products before shopping takes time; on the other hand, it helps consumers avoid wasting money."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","do research = tìm hiểu thông tin; time-consuming = tốn thời gian; avoid doing sth = tránh làm gì"]'::jsonb, 'B2', '2. Cá nhân'),
    (5, 17, 'Mặc dù cha mẹ có thể không tự mình thấy được kết quả, thói quen tốt của họ có khả năng được truyền lại cho con cái.', 'Although parents may not see the results themselves, their good habits are likely to be passed on to their children.', '["Even though parents may not see the results themselves, their good habits are likely to be passed on to their children.","Although parents might not see the results themselves, their good habits are likely to be passed on to their children.","Although parents may not see the results themselves, their good habits are likely to be passed down to their children."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","be passed on / down to = được truyền lại cho; be likely to = có khả năng; themselves = tự mình"]'::jsonb, 'B1', '2. Cá nhân'),
    (5, 18, 'Dù đúng là cá nhân có thể hành động nhanh hơn chính phủ, nỗ lực của họ hiếm khi bền lâu nếu thiếu sự hỗ trợ của pháp luật.', 'While it is true that individuals can act faster than governments, their efforts rarely last without legal support.', '["While it''s true that individuals can act faster than governments, their efforts rarely last without legal support.","While it is true that individuals can act more quickly than governments, their efforts rarely last without legal support.","While it is true that individuals can act faster than governments, their efforts seldom last without legal support."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","while it is true that = dù đúng là; act = hành động; last = bền lâu, kéo dài; legal support = sự hỗ trợ của pháp luật"]'::jsonb, 'C1', '2. Cá nhân'),
    (5, 19, 'Giáo viên định hình thái độ của học sinh trong lớp học, trong khi ban giám hiệu quyết định chương trình học gồm những gì.', 'Teachers shape students'' attitudes in the classroom, whereas school leaders decide what the curriculum includes.', '["Teachers shape students'' attitudes in the classroom, while school leaders decide what the curriculum includes.","Teachers shape pupils'' attitudes in the classroom, whereas school leaders decide what the curriculum includes.","Teachers shape students'' attitudes in class, whereas school leaders decide what the curriculum includes."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","shape = định hình; attitude = thái độ; school leaders = ban giám hiệu; curriculum = chương trình học"]'::jsonb, 'B2', '3. Trường học'),
    (5, 20, 'Dù xuất thân từ gia đình nghèo, nhiều trẻ em vẫn được tiếp cận tri thức nhờ các trường công miễn phí.', 'Despite coming from poor families, many children gain access to knowledge through free public schools.', '["In spite of coming from poor families, many children gain access to knowledge through free public schools.","Despite coming from low-income families, many children gain access to knowledge through free public schools.","Despite coming from poor families, many children gain access to knowledge thanks to free public schools."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + V-ing, không + mệnh đề; come from = xuất thân từ; gain access to = được tiếp cận; public school = trường công"]'::jsonb, 'B2', '3. Trường học'),
    (5, 21, 'Phải thừa nhận là gia đình dạy trẻ những bài học đầu tiên; dù vậy, trường học mới là nơi phần lớn kiến thức và thái độ của trẻ được hình thành.', 'Admittedly, families teach children their first lessons; nevertheless, schools are where most of their knowledge and attitudes are shaped.', '["Admittedly, families give children their first lessons; nevertheless, schools are where most of their knowledge and attitudes are shaped.","Admittedly, families teach children their first lessons; nevertheless, school is where most of their knowledge and attitudes are shaped.","Admittedly, families teach children their first lessons; nevertheless, schools are where most of their knowledge and attitudes are formed."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","admittedly = phải thừa nhận là; first lessons = những bài học đầu tiên; be shaped / be formed = được hình thành"]'::jsonb, 'C1', '3. Trường học'),
    (5, 22, 'Thi cử thúc đẩy học sinh học chăm hơn, nhưng áp lực quá lớn có thể gây hại cho sức khỏe tinh thần của các em.', 'Exams motivate students to study harder, but too much pressure can damage their mental health.', '["Exams motivate students to study harder; however, too much pressure can damage their mental health.","Exams motivate students to work harder, but too much pressure can damage their mental health.","Exams motivate students to study harder, but excessive pressure can damage their mental health."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","motivate sb to do sth = thúc đẩy ai làm gì; excessive = quá mức; mental health = sức khỏe tinh thần"]'::jsonb, 'B1', '3. Trường học'),
    (5, 23, 'Dù các trường rất muốn mở thêm khóa học thực hành, nhiều trường lại thiếu kinh phí và đội ngũ được đào tạo.', 'Much as schools would like to offer more practical courses, many of them lack the funding and trained staff.', '["Much as schools want to offer more practical courses, many of them lack the funding and trained staff.","Much as schools would like to provide more practical courses, many of them lack the funding and trained staff.","Much as schools would like to offer more practical courses, many of them lack the money and trained staff."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; practical course = khóa học thực hành; lack = thiếu; funding = kinh phí"]'::jsonb, 'C1', '3. Trường học'),
    (5, 24, 'Một mặt, hướng nghiệp làm tăng khối lượng công việc của giáo viên; mặt khác, nó ngăn nhiều học sinh chọn sai ngành.', 'On the one hand, career guidance adds to teachers'' workload; on the other hand, it stops many students from choosing the wrong major.', '["On the one hand, career guidance increases teachers'' workload; on the other hand, it stops many students from choosing the wrong major.","On the one hand, career guidance adds to teachers'' workload; on the other hand, it prevents many students from choosing the wrong major.","On the one hand, career guidance adds to teachers'' workloads; on the other hand, it stops many students from choosing the wrong major."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","career guidance = hướng nghiệp; add to = làm tăng thêm; workload = khối lượng công việc; major = ngành học"]'::jsonb, 'B2', '3. Trường học'),
    (5, 25, 'Bất chấp chi phí cao của việc đào tạo lại giáo viên, chương trình học mới sẽ tạo ra một thế hệ được chuẩn bị tốt hơn về lâu dài.', 'Despite the high cost of retraining teachers, a new curriculum will produce a better-prepared generation in the long run.', '["In spite of the high cost of retraining teachers, a new curriculum will produce a better-prepared generation in the long run.","Despite the high cost of retraining teachers, a new curriculum will produce a better-prepared generation in the long term.","Despite the high costs of retraining teachers, a new curriculum will create a better-prepared generation in the long run."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + danh từ; retrain = đào tạo lại; better-prepared = được chuẩn bị tốt hơn; in the long run = về lâu dài"]'::jsonb, 'B2', '3. Trường học'),
    (5, 26, 'Mặc dù lợi ích của giáo dục phải mất hàng chục năm mới thấy rõ, chúng kéo dài lâu hơn nhiều so với lợi ích của hầu hết các chính sách khác.', 'Although the benefits of education take decades to appear, they last far longer than those of most other policies.', '["Even though the benefits of education take decades to appear, they last far longer than those of most other policies.","Although the benefits of education take decades to appear, they last much longer than those of most other policies.","Although the benefits of education take decades to become visible, they last far longer than those of most other policies."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","take decades = mất hàng chục năm; appear = thấy rõ, xuất hiện; those of = lợi ích của (thay cho danh từ đã nói)"]'::jsonb, 'B1', '3. Trường học'),
    (5, 27, 'Dù đúng là học thuộc lòng giúp học sinh vượt qua kỳ thi, kết hợp lý thuyết với thực hành mới phát triển được sự hiểu biết sâu sắc hơn.', 'While it is true that rote learning helps students pass exams, combining theory with practice develops deeper understanding.', '["While it''s true that rote learning helps students pass exams, combining theory with practice develops deeper understanding.","While it is true that rote learning helps students to pass exams, combining theory with practice develops deeper understanding.","While it is true that rote learning helps students pass exams, combining theory and practice develops deeper understanding."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","rote learning = học thuộc lòng; combine A with B = kết hợp A với B; deeper understanding = sự hiểu biết sâu sắc hơn"]'::jsonb, 'C1', '3. Trường học'),
    (5, 28, 'Trong nhiều gia đình, ông bà chăm cháu hằng ngày, trong khi cha mẹ chịu trách nhiệm kiếm thu nhập cho cả nhà.', 'In many families, grandparents provide daily childcare, whereas parents are responsible for earning the household income.', '["In many families, grandparents provide daily childcare, while parents are responsible for earning the household income.","In many families, grandparents provide everyday childcare, whereas parents are responsible for earning the household income.","In many families, grandparents provide daily childcare, whereas parents are responsible for earning the family income."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","childcare = việc chăm trẻ; be responsible for = chịu trách nhiệm; household income = thu nhập của gia đình"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (5, 29, 'Mặc dù cha mẹ cho con rất nhiều lời khuyên, trẻ học được nhiều hơn hẳn từ những gì cha mẹ thực sự làm.', 'Although parents give their children plenty of advice, children learn far more from what their parents actually do.', '["Even though parents give their children plenty of advice, children learn far more from what their parents actually do.","Although parents give their children lots of advice, children learn far more from what their parents actually do.","Although parents give their children plenty of advice, children learn much more from what their parents actually do."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","plenty of = rất nhiều; advice = lời khuyên (không đếm được); far more = nhiều hơn hẳn; actually = thực sự"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (5, 30, 'Dù đúng là trẻ gặp gỡ nhiều người khi lớn lên, gia đình vẫn là môi trường đầu tiên và gần gũi nhất mà các em biết.', 'While it is true that children meet many people as they grow up, the family remains the first and closest environment they know.', '["While it''s true that children meet many people as they grow up, the family remains the first and closest environment they know.","While it is true that children meet a lot of people as they grow up, the family remains the first and closest environment they know.","While it is true that children meet many people as they grow up, the family is still the first and closest environment they know."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","while it is true that = dù đúng là; grow up = lớn lên; remain = vẫn là; closest = gần gũi nhất"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (5, 31, 'Dù đối mặt với nhiều thử thách ở trường, trẻ lớn lên trong gia đình yêu thương thường vẫn giữ được sự tự tin.', 'Despite facing many challenges at school, children from loving homes usually remain confident.', '["In spite of facing many challenges at school, children from loving homes usually remain confident.","Despite facing many difficulties at school, children from loving homes usually remain confident.","Despite facing many challenges at school, children from loving families usually remain confident."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + V-ing, không + mệnh đề; face challenges = đối mặt thử thách; loving home = gia đình yêu thương; remain confident = vẫn tự tin"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (5, 32, 'Cha mẹ bận rộn có thể cho con mọi thứ cần thiết về vật chất, nhưng thiếu sự quan tâm vẫn có thể khiến trẻ cảm thấy cô đơn.', 'Busy parents may give their children everything they need materially, but a lack of attention can still make them feel lonely.', '["Busy parents may give their children everything they need materially; however, a lack of attention can still make them feel lonely.","Busy parents might give their children everything they need materially, but a lack of attention can still make them feel lonely.","Busy parents may provide their children with everything they need materially, but a lack of attention can still make them feel lonely."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","materially = về mặt vật chất; a lack of attention = thiếu sự quan tâm; make sb feel = khiến ai cảm thấy"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (5, 33, 'Dù cha mẹ rất muốn giới hạn thời gian dùng màn hình của con, chính họ thường thấy khó đặt điện thoại của mình xuống.', 'Much as parents want to limit their children''s screen time, they often find it hard to put down their own phones.', '["Much as parents would like to limit their children''s screen time, they often find it hard to put down their own phones.","Much as parents want to limit their children''s screen time, they often find it difficult to put down their own phones.","Much as parents want to restrict their children''s screen time, they often find it hard to put down their own phones."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; screen time = thời gian dùng màn hình; find it hard to = thấy khó; put down = đặt xuống"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (5, 34, 'Một mặt, bữa tối gia đình có thể khó sắp xếp; mặt khác, chúng cho mọi người cơ hội trò chuyện và gắn kết.', 'On the one hand, family dinners can be difficult to organise; on the other hand, they give everyone a chance to talk and bond.', '["On the one hand, family dinners can be hard to organise; on the other hand, they give everyone a chance to talk and bond.","On the one hand, family dinners can be difficult to organize; on the other hand, they give everyone a chance to talk and bond.","On the one hand, family dinners can be difficult to arrange; on the other hand, they give everyone a chance to talk and bond."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","organise (Mỹ: organize) / arrange = sắp xếp; give sb a chance to = cho ai cơ hội; bond = gắn kết"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (5, 35, 'Phải thừa nhận là dạy con tự lập đòi hỏi rất nhiều kiên nhẫn; dù vậy, việc này giúp trẻ trở thành người trưởng thành có trách nhiệm về lâu dài.', 'Admittedly, teaching children to be independent requires a lot of patience; nevertheless, it helps them become responsible adults in the long run.', '["Admittedly, teaching children to be independent requires a great deal of patience; nevertheless, it helps them become responsible adults in the long run.","Admittedly, teaching children to be independent takes a lot of patience; nevertheless, it helps them become responsible adults in the long run.","Admittedly, teaching children to be independent requires a lot of patience; nevertheless, it helps them to become responsible adults in the long term."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","independent = tự lập; patience = sự kiên nhẫn; responsible adults = người trưởng thành có trách nhiệm"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (5, 36, 'Cha mẹ ảnh hưởng đến trẻ ngay từ khi chào đời, trong khi giáo viên thường chỉ gặp các em khi các em bắt đầu đi học.', 'Parents influence children from birth, whereas teachers usually meet them only when they start school.', '["Parents influence children from birth, while teachers usually meet them only when they start school.","Parents influence their children from birth, whereas teachers usually meet them only when they start school.","Parents influence children from birth, whereas teachers usually only meet them when they start school."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","influence = ảnh hưởng đến; from birth = từ khi chào đời; start school = bắt đầu đi học"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (5, 37, 'Các tập đoàn đa quốc gia hoạt động trên quy mô toàn cầu, trong khi doanh nghiệp nhỏ tạo ra phần lớn việc làm ở các cộng đồng địa phương.', 'Multinational corporations operate on a global scale, whereas small businesses provide most of the jobs in local communities.', '["Multinational corporations operate on a global scale, while small businesses provide most of the jobs in local communities.","Multinational corporations operate on a global scale, whereas small firms provide most of the jobs in local communities.","Multinational companies operate on a global scale, whereas small businesses provide most of the jobs in local communities."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","multinational corporation = tập đoàn đa quốc gia; on a global scale = trên quy mô toàn cầu; whereas = trong khi (đối lập)"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (5, 38, 'Phải thừa nhận là doanh nghiệp tồn tại chủ yếu để kiếm lợi nhuận; dù vậy, lợi nhuận của họ phụ thuộc vào việc có đội ngũ nhân viên khỏe mạnh và có động lực.', 'Admittedly, companies exist mainly to make a profit; nevertheless, their profits depend on having healthy and motivated staff.', '["Admittedly, businesses exist mainly to make a profit; nevertheless, their profits depend on having healthy and motivated staff.","Admittedly, companies exist primarily to make a profit; nevertheless, their profits depend on having healthy and motivated staff.","Admittedly, companies exist mainly to make profits; nevertheless, their profits depend on having healthy and motivated employees."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","make a profit = kiếm lợi nhuận; depend on = phụ thuộc vào; motivated = có động lực"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (5, 39, 'Doanh nghiệp tạo ra việc làm và thúc đẩy nền kinh tế, nhưng chạy theo lợi nhuận ngắn hạn có thể khiến sức khỏe người lao động gặp nguy hiểm.', 'Businesses create jobs and boost the economy, but chasing short-term profit can put workers'' health at risk.', '["Businesses create jobs and boost the economy; however, chasing short-term profit can put workers'' health at risk.","Companies create jobs and boost the economy, but chasing short-term profit can put workers'' health at risk.","Businesses create jobs and boost the economy, but chasing short-term profits can put workers'' health at risk."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","boost the economy = thúc đẩy kinh tế; chase profit = chạy theo lợi nhuận; put sth at risk = khiến điều gì gặp nguy hiểm"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (5, 40, 'Dù các công ty rất thích thể hiện mình là doanh nghiệp xanh, nhiều sản phẩm của họ vẫn tạo ra rất nhiều rác thải.', 'Much as companies like to present themselves as green, many of their products still create a great deal of waste.', '["Much as companies like to present themselves as green, many of their products still create a lot of waste.","Much as companies like to portray themselves as green, many of their products still create a great deal of waste.","Much as firms like to present themselves as green, many of their products still create a great deal of waste."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; present oneself as = thể hiện mình là; green = xanh, thân thiện môi trường; a great deal of = rất nhiều"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (5, 41, 'Một mặt, giờ làm linh hoạt khiến các nhà quản lý khó điều phối hơn; mặt khác, nó giúp giảm căng thẳng và khiến nhân viên ít có xu hướng nghỉ việc hơn.', 'On the one hand, flexible working hours are harder for managers to coordinate; on the other hand, they reduce stress and make staff less likely to quit.', '["On the one hand, flexible working hours are more difficult for managers to coordinate; on the other hand, they reduce stress and make staff less likely to quit.","On the one hand, flexible working hours are harder for managers to coordinate; on the other hand, they reduce stress and make employees less likely to quit.","On the one hand, flexible hours are harder for managers to coordinate; on the other hand, they reduce stress and make staff less likely to leave."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","flexible working hours = giờ làm linh hoạt; coordinate = điều phối; be less likely to = ít có xu hướng; quit = nghỉ việc"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (5, 42, 'Bất chấp chi phí chuyển sang công nghệ sạch, những công ty hoạt động theo hướng xanh thường giành được khách hàng trung thành theo thời gian.', 'Despite the expense of switching to clean technology, companies that go green often win loyal customers over time.', '["In spite of the expense of switching to clean technology, companies that go green often win loyal customers over time.","Despite the cost of switching to clean technology, companies that go green often win loyal customers over time.","Despite the expense of switching to clean technology, firms that go green often gain loyal customers over time."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + danh từ; switch to = chuyển sang; go green = hoạt động theo hướng xanh; loyal customers = khách hàng trung thành"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (5, 43, 'Mặc dù đào tạo nhân viên làm tăng chi phí lúc đầu, việc này khiến nhân viên gắn bó và làm việc hiệu quả hơn về sau.', 'Although training staff raises costs at first, it makes employees more loyal and productive later on.', '["Even though training staff raises costs at first, it makes employees more loyal and productive later on.","Although staff training raises costs at first, it makes employees more loyal and productive later on.","Although training staff increases costs at first, it makes employees more loyal and productive later on."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","raise costs = làm tăng chi phí; loyal = gắn bó, trung thành; productive = làm việc hiệu quả; later on = về sau"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (5, 44, 'Dù đúng là một số công ty tự giác hành động có trách nhiệm, phần lớn doanh nghiệp chỉ thay đổi khi điều đó mang lại lợi nhuận cho họ hoặc khi luật pháp yêu cầu.', 'While it is true that some companies act responsibly on their own, most firms only change when it brings them profit or the law demands it.', '["While it''s true that some companies act responsibly on their own, most firms only change when it brings them profit or the law demands it.","While it is true that some companies act responsibly on their own, most businesses only change when it brings them profit or the law demands it.","While it is true that some companies behave responsibly on their own, most firms only change when it brings them profit or the law demands it."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","act responsibly = hành động có trách nhiệm; on their own = tự giác, tự mình; the law demands it = luật pháp yêu cầu"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (5, 45, 'Người trẻ hiếm khi nghĩ về sức khỏe của mình, trong khi người già phụ thuộc rất nhiều vào hệ thống y tế.', 'Young adults rarely think about their health, whereas the elderly depend heavily on the healthcare system.', '["Young adults rarely think about their health, while the elderly depend heavily on the healthcare system.","Young adults seldom think about their health, whereas the elderly depend heavily on the healthcare system.","Young adults rarely think about their health, whereas elderly people rely heavily on the healthcare system."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","the elderly = người già; depend heavily on = phụ thuộc rất nhiều vào; healthcare system = hệ thống y tế"]'::jsonb, 'B2', '6. Sức khỏe'),
    (5, 46, 'Mặc dù hầu hết mọi người biết đồ ăn nhanh không lành mạnh, họ vẫn ăn vì nó rẻ và tiện lợi.', 'Although most people know that fast food is unhealthy, they still eat it because it is cheap and convenient.', '["Even though most people know that fast food is unhealthy, they still eat it because it is cheap and convenient.","Although most people know fast food is unhealthy, they still eat it because it is cheap and convenient.","Although most people know that fast food is unhealthy, they still eat it because it''s cheap and convenient."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","although + mệnh đề; unhealthy = không lành mạnh; convenient = tiện lợi"]'::jsonb, 'B1', '6. Sức khỏe'),
    (5, 47, 'Một mặt, công việc văn phòng an toàn về thể chất; mặt khác, chúng khuyến khích lối sống ít vận động, gây hại cho sức khỏe lâu dài.', 'On the one hand, office jobs are physically safe; on the other hand, they encourage a sedentary lifestyle that harms long-term health.', '["On the one hand, office jobs are physically safe; on the other hand, they promote a sedentary lifestyle that harms long-term health.","On the one hand, office work is physically safe; on the other hand, it encourages a sedentary lifestyle that harms long-term health.","On the one hand, office jobs are physically safe; on the other hand, they encourage a sedentary lifestyle that damages long-term health."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","physically safe = an toàn về thể chất; sedentary lifestyle = lối sống ít vận động; long-term health = sức khỏe lâu dài"]'::jsonb, 'B2', '6. Sức khỏe'),
    (5, 48, 'Dù đúng là ngày nay con người sống lâu hơn, nhiều người phải trải qua những năm cuối đời với bệnh mãn tính.', 'While it is true that people now live longer, many of them spend their final years suffering from chronic illnesses.', '["While it''s true that people now live longer, many of them spend their final years suffering from chronic illnesses.","While it is true that people live longer nowadays, many of them spend their final years suffering from chronic illnesses.","While it is true that people now live longer, many of them spend their last years suffering from chronic diseases."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","chronic illness = bệnh mãn tính; final years = những năm cuối đời; suffer from = mắc (bệnh)"]'::jsonb, 'C1', '6. Sức khỏe'),
    (5, 49, 'Dù nhân viên văn phòng rất muốn tập thể dục đều đặn, giờ làm việc dài khiến họ còn rất ít thời gian và sức lực.', 'Much as office workers want to exercise regularly, long working hours leave them with little time or energy.', '["Much as office workers would like to exercise regularly, long working hours leave them with little time or energy.","Much as office workers want to exercise regularly, long working hours leave them with very little time or energy.","Much as office workers want to work out regularly, long working hours leave them with little time or energy."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; exercise / work out = tập thể dục; leave sb with = khiến ai chỉ còn lại; energy = sức lực"]'::jsonb, 'C1', '6. Sức khỏe'),
    (5, 50, 'Nhiều nơi làm việc tặng thẻ tập gym miễn phí, nhưng rất ít nơi hỗ trợ đúng mức cho sức khỏe tinh thần.', 'Many workplaces offer free gym memberships, but few provide proper support for mental health.', '["Many workplaces offer free gym memberships; however, few provide proper support for mental health.","Many workplaces offer free gym memberships, but few provide adequate support for mental health.","Many workplaces offer free gym membership, but few provide proper mental health support."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","gym membership = thẻ tập gym; proper / adequate support = sự hỗ trợ đúng mức; mental health = sức khỏe tinh thần"]'::jsonb, 'B1', '6. Sức khỏe'),
    (5, 51, 'Dù cảm thấy tràn đầy năng lượng hơn chỉ sau vài tuần, nhiều người bỏ tập trước khi thấy được lợi ích lâu dài.', 'Despite feeling more energetic after just a few weeks, many people give up exercising before they see long-term benefits.', '["In spite of feeling more energetic after just a few weeks, many people give up exercising before they see long-term benefits.","Despite feeling more energetic after only a few weeks, many people give up exercising before they see long-term benefits.","Despite feeling more energetic after just a few weeks, many people stop exercising before they see the long-term benefits."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + V-ing, không + mệnh đề; energetic = tràn đầy năng lượng; give up doing sth = bỏ làm gì"]'::jsonb, 'B2', '6. Sức khỏe'),
    (5, 52, 'Phải thừa nhận là y học hiện đại có thể chữa khỏi nhiều bệnh; dù vậy, phòng bệnh bằng lối sống lành mạnh tốn ít chi phí hơn nhiều.', 'Admittedly, modern medicine can cure many diseases; nevertheless, preventing illness through a healthy lifestyle costs far less.', '["Admittedly, modern medicine can cure many diseases; nevertheless, preventing illness through a healthy lifestyle costs much less.","Admittedly, modern medicine can cure many illnesses; nevertheless, preventing disease through a healthy lifestyle costs far less.","Admittedly, modern medicine is able to cure many diseases; nevertheless, preventing illness through a healthy lifestyle costs far less."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","cure = chữa khỏi; prevent illness = phòng bệnh; cost far less = tốn ít hơn nhiều"]'::jsonb, 'C1', '6. Sức khỏe'),
    (5, 53, 'Nhà đầu tư có thể dễ dàng chuyển tiền ra nước ngoài, trong khi người lao động bình thường thường phụ thuộc vào việc làm tại địa phương.', 'Investors can move their money abroad easily, whereas ordinary workers usually depend on local jobs.', '["Investors can move their money abroad easily, while ordinary workers usually depend on local jobs.","Investors can easily move their money abroad, whereas ordinary workers usually depend on local jobs.","Investors can move their money overseas easily, whereas ordinary workers usually rely on local jobs."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","move money abroad = chuyển tiền ra nước ngoài; ordinary workers = người lao động bình thường; depend on = phụ thuộc vào"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (5, 54, 'Dù có việc làm toàn thời gian, nhiều người lao động vẫn chật vật trả các hóa đơn vì chi phí sinh hoạt tăng nhanh hơn tiền lương.', 'Despite having full-time jobs, many workers struggle to pay their bills because living costs are rising faster than wages.', '["In spite of having full-time jobs, many workers struggle to pay their bills because living costs are rising faster than wages.","Despite having full-time jobs, many workers struggle to pay their bills because the cost of living is rising faster than wages.","Despite having full-time jobs, many workers struggle to pay their bills as living costs are rising faster than wages."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + V-ing, không + mệnh đề; struggle to do sth = chật vật làm gì; living costs = chi phí sinh hoạt; wages = tiền lương"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (5, 55, 'Dù các công ty rất muốn mở rộng, tình trạng thiếu lao động có kỹ năng thường kìm hãm họ.', 'Much as companies want to expand, a shortage of skilled workers often holds them back.', '["Much as companies would like to expand, a shortage of skilled workers often holds them back.","Much as firms want to expand, a shortage of skilled workers often holds them back.","Much as companies want to expand, a lack of skilled workers often holds them back."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; expand = mở rộng; a shortage of = sự thiếu hụt; hold sb back = kìm hãm ai"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (5, 56, 'Tăng trưởng kinh tế làm tăng thu nhập bình quân, nhưng không phải lúc nào cũng mang lại lợi ích cho những hộ nghèo nhất.', 'Economic growth raises average incomes, but it does not always benefit the poorest households.', '["Economic growth raises average incomes; however, it does not always benefit the poorest households.","Economic growth increases average incomes, but it does not always benefit the poorest households.","Economic growth raises average incomes, but it doesn''t always benefit the poorest households."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","average income = thu nhập bình quân; benefit sb = mang lại lợi ích cho ai; the poorest households = những hộ nghèo nhất"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (5, 57, 'Phải thừa nhận là ưu đãi thuế làm giảm nguồn thu của chính phủ lúc đầu; dù vậy, chúng thu hút các công ty nước ngoài tạo ra hàng nghìn việc làm.', 'Admittedly, tax incentives reduce government revenue at first; nevertheless, they attract foreign companies that create thousands of jobs.', '["Admittedly, tax incentives reduce government revenue initially; nevertheless, they attract foreign companies that create thousands of jobs.","Admittedly, tax incentives cut government revenue at first; nevertheless, they attract foreign companies that create thousands of jobs.","Admittedly, tax incentives reduce government revenue at first; nevertheless, they attract foreign firms which create thousands of jobs."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","tax incentive = ưu đãi thuế; government revenue = nguồn thu của chính phủ; attract = thu hút"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (5, 58, 'Một mặt, trợ cấp thất nghiệp giúp người dân trang trải cuộc sống trước mắt; mặt khác, các chương trình đào tạo lại giúp họ tìm được việc làm mới.', 'On the one hand, unemployment benefits help people get by in the short term; on the other hand, retraining programmes help them find new jobs.', '["On the one hand, unemployment benefits help people get by in the short term; on the other hand, retraining programs help them find new jobs.","On the one hand, unemployment benefits help people get by in the short term; on the other hand, retraining programmes help them to find new jobs.","On the one hand, unemployment benefits help people to get by in the short term; on the other hand, retraining schemes help them find new jobs."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","unemployment benefits = trợ cấp thất nghiệp; get by = trang trải cuộc sống; retraining programme (Mỹ: program) = chương trình đào tạo lại"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (5, 59, 'Mặc dù đầu tư lớn vào hạ tầng có thể làm tăng nợ công, nó thúc đẩy tăng trưởng kinh tế trong nhiều thập kỷ.', 'Although heavy investment in infrastructure may increase public debt, it stimulates economic growth for decades.', '["Even though heavy investment in infrastructure may increase public debt, it stimulates economic growth for decades.","Although heavy investment in infrastructure may raise public debt, it stimulates economic growth for decades.","Although large-scale investment in infrastructure may increase public debt, it stimulates economic growth for decades."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","heavy investment = đầu tư lớn; infrastructure = hạ tầng; public debt = nợ công; stimulate = thúc đẩy, kích thích"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (5, 60, 'Dù đúng là cắt giảm chi tiêu công giúp tiết kiệm tiền nhanh chóng, đầu tư vào con người mới tạo ra tăng trưởng bền vững hơn.', 'While it is true that cutting public spending saves money quickly, investing in people produces more sustainable growth.', '["While it''s true that cutting public spending saves money quickly, investing in people produces more sustainable growth.","While it is true that cutting public spending saves money quickly, investing in people leads to more sustainable growth.","While it is true that reducing public spending saves money quickly, investing in people produces more sustainable growth."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","cut public spending = cắt giảm chi tiêu công; invest in people = đầu tư vào con người; sustainable growth = tăng trưởng bền vững"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (5, 61, 'Dù đúng là người nhập cư đóng góp rất nhiều cho xã hội, họ thường bị phân biệt đối xử khi tìm việc.', 'While it is true that immigrants contribute a great deal to society, they often face discrimination when looking for work.', '["While it''s true that immigrants contribute a great deal to society, they often face discrimination when looking for work.","While it is true that immigrants contribute a lot to society, they often face discrimination when looking for work.","While it is true that immigrants contribute a great deal to society, they often face discrimination when looking for jobs."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","contribute a great deal to = đóng góp rất nhiều cho; face discrimination = bị phân biệt đối xử; look for work = tìm việc"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (5, 62, 'Mặc dù các căn hộ ở thành phố được xây sát nhau, nhiều cư dân chưa bao giờ nói chuyện với hàng xóm sát vách.', 'Although city flats are built close together, many residents have never spoken to the people next door.', '["Even though city flats are built close together, many residents have never spoken to the people next door.","Although city apartments are built close together, many residents have never spoken to the people next door.","Although city flats are built close together, many residents have never talked to the people next door."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","flat (Mỹ: apartment) = căn hộ; close together = sát nhau; the people next door = hàng xóm sát vách"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (5, 63, 'Các gia đình giàu có thể chi trả cho gia sư và phòng khám tư, trong khi các gia đình nghèo phụ thuộc hoàn toàn vào dịch vụ công vốn đã quá tải.', 'Wealthy families can afford private tutors and clinics, whereas poor families rely entirely on overstretched public services.', '["Wealthy families can afford private tutors and clinics, while poor families rely entirely on overstretched public services.","Rich families can afford private tutors and clinics, whereas poor families rely entirely on overstretched public services.","Wealthy families can afford private tutors and clinics, whereas poor families depend entirely on overstretched public services."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","afford = đủ khả năng chi trả; private tutor = gia sư; rely on = phụ thuộc vào; overstretched = quá tải"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (5, 64, 'Nghèo đói thường được xem là vấn đề cá nhân, nhưng nó tước đi cơ hội học tập và việc làm của cả cộng đồng.', 'Poverty is often seen as a personal problem, but it deprives whole communities of education and job opportunities.', '["Poverty is often seen as a personal problem; however, it deprives whole communities of education and job opportunities.","Poverty is often regarded as a personal problem, but it deprives whole communities of education and job opportunities.","Poverty is often seen as an individual problem, but it deprives entire communities of education and job opportunities."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","be seen as / be regarded as = được xem là; deprive sb of sth = tước đi của ai cái gì; job opportunities = cơ hội việc làm"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (5, 65, 'Dù cư dân rất hoan nghênh công viên và thư viện mới, chính quyền địa phương thường gặp khó khăn trong việc chi trả chi phí bảo trì.', 'Much as residents welcome new parks and libraries, local councils often struggle to pay for their maintenance.', '["Much as residents welcome new parks and libraries, local authorities often struggle to pay for their maintenance.","Much as residents welcome new parks and libraries, local councils often find it hard to pay for their maintenance.","Much as local people welcome new parks and libraries, local councils often struggle to pay for their maintenance."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; welcome = hoan nghênh; local council = chính quyền địa phương; maintenance = việc bảo trì"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (5, 66, 'Phải thừa nhận là các chương trình tình nguyện phụ thuộc vào thời gian rảnh của mọi người; dù vậy, chúng mang lại cho người trẻ cảm giác gắn bó thực sự.', 'Admittedly, volunteer programmes rely on people''s free time; nevertheless, they give young people a real sense of belonging.', '["Admittedly, volunteer programmes depend on people''s free time; nevertheless, they give young people a real sense of belonging.","Admittedly, volunteer programs rely on people''s free time; nevertheless, they give young people a real sense of belonging.","Admittedly, volunteer programmes rely on people''s spare time; nevertheless, they give young people a real sense of belonging."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","volunteer programme (Mỹ: program) = chương trình tình nguyện; free / spare time = thời gian rảnh; a sense of belonging = cảm giác gắn bó"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (5, 67, 'Dù phải mất nhiều năm mới thấy kết quả, các dự án cộng đồng có thể giúp khu dân cư an toàn và hòa nhập hơn.', 'Despite taking years to show results, community projects can make neighbourhoods safer and more inclusive.', '["In spite of taking years to show results, community projects can make neighbourhoods safer and more inclusive.","Despite taking years to show results, community projects can make neighborhoods safer and more inclusive.","Despite taking years to produce results, community projects can make neighbourhoods safer and more inclusive."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + V-ing, không + mệnh đề; show results = cho thấy kết quả; neighbourhood (Mỹ: neighborhood) = khu dân cư; inclusive = hòa nhập"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (5, 68, 'Một mặt, phát tiền mặt giúp giảm nghèo nhanh chóng; mặt khác, tạo cơ hội mới giúp người dân thoát nghèo lâu dài.', 'On the one hand, cash handouts relieve poverty quickly; on the other hand, creating opportunities helps people escape it permanently.', '["On the one hand, cash handouts relieve poverty quickly; on the other hand, creating opportunities helps people to escape it permanently.","On the one hand, cash handouts ease poverty quickly; on the other hand, creating opportunities helps people escape it permanently.","On the one hand, handing out cash relieves poverty quickly; on the other hand, creating opportunities helps people escape it permanently."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","cash handout = phát tiền mặt; relieve poverty = giảm nghèo; escape poverty = thoát nghèo; permanently = lâu dài, vĩnh viễn"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (5, 69, 'Nhà máy gây ô nhiễm sông ngòi một cách trực tiếp, trong khi người tiêu dùng góp phần gây ô nhiễm một cách gián tiếp qua những gì họ mua.', 'Factories pollute rivers directly, whereas consumers contribute to pollution indirectly through what they buy.', '["Factories pollute rivers directly, while consumers contribute to pollution indirectly through what they buy.","Factories pollute rivers directly, whereas consumers contribute to pollution indirectly through the things they buy.","Factories directly pollute rivers, whereas consumers contribute to pollution indirectly through what they buy."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","directly = trực tiếp; indirectly = gián tiếp; contribute to = góp phần vào"]'::jsonb, 'B2', '9. Môi trường'),
    (5, 70, 'Dù mọi người rất thích sự tự do khi lái xe riêng, phương tiện cá nhân là một nguồn gây ô nhiễm không khí chính.', 'Much as people enjoy the freedom of driving their own cars, private vehicles are a major source of air pollution.', '["Much as people love the freedom of driving their own cars, private vehicles are a major source of air pollution.","Much as people enjoy the freedom of driving their own cars, private vehicles are a main source of air pollution.","Much as people enjoy the freedom of driving their own cars, private cars are a major source of air pollution."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; private vehicle = phương tiện cá nhân; a major source of = nguồn chính gây ra"]'::jsonb, 'C1', '9. Môi trường'),
    (5, 71, 'Đồ nhựa dùng một lần rẻ và tiện dụng, nhưng phải mất hàng trăm năm chúng mới phân hủy.', 'Single-use plastics are cheap and practical, but they take hundreds of years to break down.', '["Single-use plastics are cheap and practical; however, they take hundreds of years to break down.","Single-use plastics are cheap and convenient, but they take hundreds of years to break down.","Single-use plastics are cheap and practical, but they take hundreds of years to decompose."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","single-use plastics = đồ nhựa dùng một lần; practical = tiện dụng; break down / decompose = phân hủy"]'::jsonb, 'B1', '9. Môi trường'),
    (5, 72, 'Bất chấp luật pháp nghiêm ngặt ở nhiều nước, nạn khai thác gỗ trái phép vẫn tiếp tục phá hủy môi trường sống của các loài nguy cấp.', 'Despite strict laws in many countries, illegal logging continues to destroy the habitats of endangered species.', '["In spite of strict laws in many countries, illegal logging continues to destroy the habitats of endangered species.","Despite strict laws in many countries, illegal logging is still destroying the habitats of endangered species.","Despite tough laws in many countries, illegal logging continues to destroy the habitats of endangered species."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + danh từ; illegal logging = khai thác gỗ trái phép; habitat = môi trường sống; endangered species = loài nguy cấp"]'::jsonb, 'B2', '9. Môi trường'),
    (5, 73, 'Một mặt, lệnh cấm túi nilon gây bất tiện cho người mua sắm; mặt khác, nó làm giảm đáng kể lượng rác thải trên biển.', 'On the one hand, a ban on plastic bags inconveniences shoppers; on the other hand, it greatly reduces the amount of waste in the sea.', '["On the one hand, a plastic bag ban inconveniences shoppers; on the other hand, it greatly reduces the amount of waste in the sea.","On the one hand, a ban on plastic bags is inconvenient for shoppers; on the other hand, it greatly reduces the amount of waste in the sea.","On the one hand, a ban on plastic bags inconveniences shoppers; on the other hand, it significantly reduces the amount of waste in the ocean."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","a ban on = lệnh cấm; inconvenience sb = gây bất tiện cho ai; greatly reduce = giảm đáng kể"]'::jsonb, 'B2', '9. Môi trường'),
    (5, 74, 'Mặc dù chuyển sang năng lượng tái tạo hiện nay tốn kém cho doanh nghiệp, việc này sẽ bảo vệ các thế hệ tương lai khỏi những tác động tồi tệ nhất của biến đổi khí hậu.', 'Although the switch to renewable energy is costly for businesses now, it will protect future generations from the worst effects of climate change.', '["Even though the switch to renewable energy is costly for businesses now, it will protect future generations from the worst effects of climate change.","Although the switch to renewable energy is expensive for businesses now, it will protect future generations from the worst effects of climate change.","Although the switch to renewable energy is costly for businesses now, it will protect future generations from the worst impacts of climate change."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","the switch to = việc chuyển sang; renewable energy = năng lượng tái tạo; protect sb from = bảo vệ ai khỏi"]'::jsonb, 'B1', '9. Môi trường'),
    (5, 75, 'Phải thừa nhận là luật môi trường có thể làm chậm tăng trưởng kinh tế; dù vậy, trì hoãn hành động có thể gây ra thiệt hại không thể đảo ngược.', 'Admittedly, environmental laws can slow down economic growth; nevertheless, delaying action could cause irreversible damage.', '["Admittedly, environmental laws may slow down economic growth; nevertheless, delaying action could cause irreversible damage.","Admittedly, environmental laws can slow economic growth; nevertheless, delaying action could cause irreversible damage.","Admittedly, environmental regulations can slow down economic growth; nevertheless, delaying action could cause irreversible damage."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","slow down = làm chậm; delay action = trì hoãn hành động; irreversible damage = thiệt hại không thể đảo ngược"]'::jsonb, 'C1', '9. Môi trường'),
    (5, 76, 'Dù đúng là nhiên liệu hóa thạch vẫn rẻ hơn ở một số quốc gia, các nguồn năng lượng tái tạo sẽ không bao giờ cạn kiệt.', 'While it is true that fossil fuels are still cheaper in some countries, renewable sources will never run out.', '["While it''s true that fossil fuels are still cheaper in some countries, renewable sources will never run out.","While it is true that fossil fuels are still cheaper in some countries, renewable energy sources will never run out.","While it is true that fossil fuels remain cheaper in some countries, renewable sources will never run out."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","fossil fuels = nhiên liệu hóa thạch; renewable sources = nguồn năng lượng tái tạo; run out = cạn kiệt"]'::jsonb, 'C1', '9. Môi trường'),
    (5, 77, 'Các công ty công nghệ thu thập lượng dữ liệu cá nhân khổng lồ, trong khi hầu hết người dùng gần như không biết dữ liệu đó được sử dụng thế nào.', 'Tech companies collect huge amounts of personal data, whereas most users have little idea how it is used.', '["Tech companies collect huge amounts of personal data, while most users have little idea how it is used.","Technology companies collect huge amounts of personal data, whereas most users have little idea how it is used.","Tech companies collect vast amounts of personal data, whereas most users have little idea how it is used."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","personal data = dữ liệu cá nhân; huge / vast amounts of = lượng khổng lồ; have little idea = gần như không biết"]'::jsonb, 'B2', '10. Công nghệ'),
    (5, 78, 'Dù giá điện thoại thông minh ngày càng giảm, nhiều gia đình ở nông thôn vẫn không đủ tiền dùng kết nối Internet ổn định.', 'Despite the falling price of smartphones, many families in rural areas still cannot afford a reliable Internet connection.', '["In spite of the falling price of smartphones, many families in rural areas still cannot afford a reliable Internet connection.","Despite the falling prices of smartphones, many families in rural areas still cannot afford a reliable Internet connection.","Despite the falling price of smartphones, many rural families still cannot afford a reliable Internet connection."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + danh từ; falling price = giá ngày càng giảm; afford = đủ tiền chi trả; reliable connection = kết nối ổn định"]'::jsonb, 'B2', '10. Công nghệ'),
    (5, 79, 'Internet cho học sinh tiếp cận thông tin ngay lập tức, nhưng không phải mọi thứ các em tìm thấy trên mạng đều chính xác.', 'The Internet gives students instant access to information, but not everything they find online is accurate.', '["The Internet gives students instant access to information; however, not everything they find online is accurate.","The Internet gives students immediate access to information, but not everything they find online is accurate.","The Internet gives students instant access to information, but not everything they find online is correct."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","instant access = sự tiếp cận ngay lập tức; online = trên mạng; accurate = chính xác"]'::jsonb, 'B1', '10. Công nghệ'),
    (5, 80, 'Dù thanh thiếu niên rất thích trò chuyện trên mạng, việc nhắn tin liên tục có thể làm yếu đi kỹ năng giao tiếp trực tiếp của các em.', 'Much as teenagers enjoy chatting online, constant messaging can weaken their face-to-face communication skills.', '["Much as teenagers love chatting online, constant messaging can weaken their face-to-face communication skills.","Much as teenagers enjoy chatting online, constant texting can weaken their face-to-face communication skills.","Much as teenagers enjoy chatting online, constant messaging may weaken their face-to-face communication skills."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; chat online = trò chuyện trên mạng; constant messaging = nhắn tin liên tục; weaken = làm yếu đi"]'::jsonb, 'C1', '10. Công nghệ'),
    (5, 81, 'Phải thừa nhận là luật bảo vệ dữ liệu tạo thêm việc cho các công ty công nghệ; dù vậy, chúng là thiết yếu để giữ an toàn thông tin của người dùng.', 'Admittedly, data protection laws create extra work for tech firms; nevertheless, they are essential for keeping users'' information safe.', '["Admittedly, data protection laws create extra work for tech companies; nevertheless, they are essential for keeping users'' information safe.","Admittedly, data protection laws create additional work for tech firms; nevertheless, they are essential for keeping users'' information safe.","Admittedly, data protection laws create extra work for tech firms; nevertheless, they are vital for keeping users'' information safe."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","data protection law = luật bảo vệ dữ liệu; extra work = thêm việc; essential / vital = thiết yếu; keep sth safe = giữ an toàn"]'::jsonb, 'C1', '10. Công nghệ'),
    (5, 82, 'Một mặt, tự động hóa có khả năng xóa bỏ nhiều công việc lặp lại; mặt khác, nó chắc chắn sẽ tạo ra những nghề nghiệp hoàn toàn mới.', 'On the one hand, automation is likely to eliminate many routine jobs; on the other hand, it is set to create entirely new careers.', '["On the one hand, automation is likely to eliminate many routine jobs; on the other hand, it is set to create completely new careers.","On the one hand, automation is likely to wipe out many routine jobs; on the other hand, it is set to create entirely new careers.","On the one hand, automation is likely to eliminate many routine jobs; on the other hand, it is set to create entirely new occupations."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","eliminate / wipe out = xóa bỏ; routine jobs = công việc lặp lại; be set to = chắc chắn sẽ"]'::jsonb, 'B2', '10. Công nghệ'),
    (5, 83, 'Mặc dù người lao động lớn tuổi thấy khó thích nghi với công nghệ mới lúc đầu, các khóa đào tạo lại có thể mang lại cho họ những kỹ năng số giá trị.', 'Although older workers find it hard to adapt to new technology at first, retraining courses can give them valuable digital skills.', '["Even though older workers find it hard to adapt to new technology at first, retraining courses can give them valuable digital skills.","Although older workers find it difficult to adapt to new technology at first, retraining courses can give them valuable digital skills.","Although older workers find it hard to adapt to new technology at first, retraining courses can equip them with valuable digital skills."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","adapt to = thích nghi với; retraining course = khóa đào tạo lại; digital skills = kỹ năng số"]'::jsonb, 'B1', '10. Công nghệ'),
    (5, 84, 'Dù đúng là AI có thể xử lý dữ liệu nhanh hơn con người, nó vẫn không thể thay thế khả năng phán đoán của con người trong những lĩnh vực như y khoa.', 'While it is true that AI can process data faster than humans, it still cannot replace human judgement in areas such as medicine.', '["While it''s true that AI can process data faster than humans, it still cannot replace human judgement in areas such as medicine.","While it is true that AI can process data faster than humans, it still cannot replace human judgment in areas such as medicine.","While it is true that AI can process data more quickly than humans, it still cannot replace human judgement in fields such as medicine."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","process data = xử lý dữ liệu; human judgement (Mỹ: judgment) = khả năng phán đoán của con người; replace = thay thế"]'::jsonb, 'C1', '10. Công nghệ'),
    (5, 85, 'Người dân thành phố thường mất hàng giờ đi lại mỗi ngày, trong khi người ở nông thôn thường sống gần nơi làm việc.', 'City dwellers often spend hours commuting each day, whereas people in rural areas usually live close to where they work.', '["City dwellers often spend hours commuting each day, while people in rural areas usually live close to where they work.","City dwellers often spend hours commuting every day, whereas people in rural areas usually live close to where they work.","City residents often spend hours commuting each day, whereas people in the countryside usually live close to where they work."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","city dwellers = người dân thành phố; commute = đi lại (đi làm); live close to = sống gần"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (5, 86, 'Mặc dù các thiết bị hiện đại làm được nhiều việc nhà, nhiều người cảm thấy họ có ít thời gian rảnh hơn bao giờ hết.', 'Although modern appliances do much of the housework, many people feel they have less free time than ever.', '["Even though modern appliances do much of the housework, many people feel they have less free time than ever.","Although modern appliances do much of the housework, many people feel that they have less free time than ever.","Although modern appliances do a lot of the housework, many people feel they have less free time than ever before."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","appliance = thiết bị gia dụng; housework = việc nhà; than ever = hơn bao giờ hết"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (5, 87, 'Ứng dụng giao đồ ăn giúp các gia đình bận rộn tiết kiệm rất nhiều thời gian, nhưng chúng cũng khiến mọi người nấu ăn ít hơn và chi tiêu nhiều hơn.', 'Food delivery apps save busy families a lot of time, but they also make people cook less and spend more.', '["Food delivery apps save busy families a lot of time; however, they also make people cook less and spend more.","Food delivery apps save busy families a great deal of time, but they also make people cook less and spend more.","Food delivery apps save busy families lots of time, but they also make people cook less and spend more money."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","food delivery app = ứng dụng giao đồ ăn; save sb time = giúp ai tiết kiệm thời gian; spend more = chi tiêu nhiều hơn"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (5, 88, 'Dù giúp cuộc sống hằng ngày dễ dàng hơn, sự tiện lợi quá mức có thể khiến con người lười vận động.', 'Despite making daily life easier, too much convenience can leave people physically inactive.', '["In spite of making daily life easier, too much convenience can leave people physically inactive.","Despite making everyday life easier, too much convenience can leave people physically inactive.","Despite making daily life easier, excessive convenience can leave people physically inactive."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + V-ing, không + mệnh đề; convenience = sự tiện lợi; physically inactive = ít vận động; leave sb + tính từ = khiến ai trở nên"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (5, 89, 'Một mặt, làm việc tại nhà loại bỏ quãng đường đi làm hằng ngày; mặt khác, nó có thể làm mờ ranh giới giữa công việc và đời sống riêng.', 'On the one hand, working from home removes the daily commute; on the other hand, it can blur the line between work and private life.', '["On the one hand, working from home eliminates the daily commute; on the other hand, it can blur the line between work and private life.","On the one hand, working from home removes the daily commute; on the other hand, it can blur the boundary between work and private life.","On the one hand, remote work removes the daily commute; on the other hand, it can blur the line between work and private life."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","commute = quãng đường đi làm; blur the line between = làm mờ ranh giới giữa; private life = đời sống riêng"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (5, 90, 'Dù mọi người rất đánh giá cao các thiết bị gia dụng thông minh, những thiết bị này thường đắt và khó sửa chữa.', 'Much as people appreciate smart appliances, these devices are often expensive and difficult to repair.', '["Much as people value smart appliances, these devices are often expensive and difficult to repair.","Much as people appreciate smart appliances, these devices are often expensive and hard to repair.","Much as people appreciate smart appliances, such devices are often expensive and difficult to repair."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; appreciate = đánh giá cao; smart appliance = thiết bị gia dụng thông minh; repair = sửa chữa"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (5, 91, 'Phải thừa nhận là các dịch vụ tiện lợi giúp cuộc sống dễ dàng hơn ngay lập tức; dù vậy, dựa vào chúng cho mọi việc có thể dẫn đến sự phụ thuộc.', 'Admittedly, convenient services make life easier immediately; nevertheless, relying on them for everything can lead to dependence.', '["Admittedly, convenient services make life easier straight away; nevertheless, relying on them for everything can lead to dependence.","Admittedly, convenient services make life easier immediately; nevertheless, relying on them for everything may lead to dependence.","Admittedly, convenient services make life easier immediately; nevertheless, relying on them for everything can make people dependent."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","convenient services = dịch vụ tiện lợi; rely on = dựa vào; dependence = sự phụ thuộc"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (5, 92, 'Dù đúng là công nghệ giúp con người tiết kiệm thời gian, điều quan trọng nhất là họ sử dụng những giờ có thêm đó như thế nào.', 'While it is true that technology saves people time, what matters most is how they use the extra hours.', '["While it''s true that technology saves people time, what matters most is how they use the extra hours.","While it is true that technology saves people time, what matters most is how they spend the extra hours.","While it is true that technology saves people time, the most important thing is how they use the extra hours."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","save sb time = giúp ai tiết kiệm thời gian; what matters most = điều quan trọng nhất; extra hours = những giờ có thêm"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (5, 93, 'Thế hệ hiện tại trả chi phí cho sự thay đổi, trong khi các thế hệ tương lai sẽ hưởng phần lớn lợi ích.', 'The current generation pays the cost of change, whereas future generations will enjoy most of the benefits.', '["The current generation pays the cost of change, while future generations will enjoy most of the benefits.","The present generation pays the cost of change, whereas future generations will enjoy most of the benefits.","The current generation pays the costs of change, whereas future generations will reap most of the benefits."]'::jsonb, '["whereas / while + clause = trong khi (đối lập) (mục 2.5)","the current generation = thế hệ hiện tại; future generations = các thế hệ tương lai; reap the benefits = hưởng lợi ích"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (5, 94, 'Dù các chính trị gia rất quan tâm đến tương lai, áp lực phải thắng cuộc bầu cử tiếp theo khiến họ ưu tiên những kết quả nhanh chóng.', 'Much as politicians care about the future, the pressure to win the next election pushes them to favour quick results.', '["Much as politicians care about the future, the pressure to win the next election pushes them to favor quick results.","Much as politicians care about the future, the pressure to win the next election pushes them to prefer quick results.","Much as politicians care about the future, the pressure of winning the next election pushes them to favour quick results."]'::jsonb, '["Much as + clause, … = dù rất … (mục 2.5)","much as = dù rất; win an election = thắng cử; favour (Mỹ: favor) = ưu tiên, thiên về"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (5, 95, 'Chặt phá rừng mang lại lợi nhuận nhanh, nhưng nó gây thiệt hại lâu dài cho đất đai và khí hậu.', 'Cutting down forests brings quick profits, but it causes long-term damage to the soil and climate.', '["Cutting down forests brings quick profits; however, it causes long-term damage to the soil and climate.","Cutting down forests brings quick profits, but it does long-term damage to the soil and climate.","Cutting down forests generates quick profits, but it causes long-term damage to the soil and the climate."]'::jsonb, '["but / however = nhưng / tuy nhiên (mục 2.5)","cut down forests = chặt phá rừng; quick profits = lợi nhuận nhanh; long-term damage = thiệt hại lâu dài"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (5, 96, 'Bất chấp giai đoạn thích nghi khó khăn, hầu hết nhân viên làm việc hiệu quả hơn khi đã quen với hệ thống mới.', 'Despite a difficult adjustment period, most employees become more productive once they get used to a new system.', '["In spite of a difficult adjustment period, most employees become more productive once they get used to a new system.","Despite a difficult period of adjustment, most employees become more productive once they get used to a new system.","Despite a difficult adjustment period, most staff become more productive once they get used to a new system."]'::jsonb, '["despite / in spite of + noun / V-ing = mặc dù (mục 2.5)","despite + danh từ; adjustment period = giai đoạn thích nghi; get used to = quen với; productive = làm việc hiệu quả"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (5, 97, 'Phải thừa nhận là khai thác tài nguyên thiên nhiên tạo ra việc làm ngay hôm nay; dù vậy, nó đe dọa cuộc sống của thế hệ sau.', 'Admittedly, exploiting natural resources creates jobs today; nevertheless, it threatens the wellbeing of the next generation.', '["Admittedly, exploiting natural resources creates jobs now; nevertheless, it threatens the wellbeing of the next generation.","Admittedly, exploiting natural resources creates jobs today; nevertheless, it threatens the well-being of the next generation.","Admittedly, overusing natural resources creates jobs today; nevertheless, it threatens the wellbeing of the next generation."]'::jsonb, '["Admittedly, … Nevertheless, … = phải thừa nhận là … dù vậy … (mục 2.5)","exploit natural resources = khai thác tài nguyên thiên nhiên; threaten = đe dọa; wellbeing = cuộc sống, sự an sinh"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (5, 98, 'Một mặt, thực hiện thay đổi từng bước cho người dân thời gian thích nghi; mặt khác, cách này làm chậm những lợi ích mà xã hội cần.', 'On the one hand, introducing changes gradually gives people time to adapt; on the other hand, it delays the benefits that society needs.', '["On the one hand, introducing changes gradually gives people time to adjust; on the other hand, it delays the benefits that society needs.","On the one hand, introducing changes step by step gives people time to adapt; on the other hand, it delays the benefits that society needs.","On the one hand, introducing changes gradually gives people time to adapt; on the other hand, it delays the benefits society needs."]'::jsonb, '["On the one hand, … On the other hand, … = một mặt … mặt khác … (mục 2.5)","introduce changes gradually = thực hiện thay đổi từng bước; adapt / adjust = thích nghi; delay = làm chậm, trì hoãn"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (5, 99, 'Mặc dù một tuyến tàu điện ngầm mới mất nhiều năm để xây dựng, nó có thể hoàn vốn nhờ lợi ích kinh tế trong vòng một thập kỷ.', 'Although a new metro line takes years to build, it can pay back its cost through economic gains within a decade.', '["Even though a new metro line takes years to build, it can pay back its cost through economic gains within a decade.","Although a new metro line takes many years to build, it can pay back its cost through economic gains within a decade.","Although a new metro line takes years to build, it can recover its cost through economic gains within a decade."]'::jsonb, '["although / even though + clause = mặc dù (mục 2.5)","metro line = tuyến tàu điện ngầm; pay back / recover its cost = hoàn vốn; within a decade = trong vòng một thập kỷ"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (5, 100, 'Dù đúng là các giải pháp tạm thời làm hài lòng cử tri, chỉ những giải pháp bền vững mới xử lý được gốc rễ của vấn đề.', 'While it is true that quick fixes satisfy voters, only sustainable solutions deal with the root causes of a problem.', '["While it''s true that quick fixes satisfy voters, only sustainable solutions deal with the root causes of a problem.","While it is true that quick fixes please voters, only sustainable solutions deal with the root causes of a problem.","While it is true that quick fixes satisfy voters, only sustainable solutions tackle the root causes of a problem."]'::jsonb, '["While it is true that …, … = dù đúng là … nhưng … (mục 2.5)","quick fix = giải pháp tạm thời; satisfy = làm hài lòng; root cause = gốc rễ, nguyên nhân sâu xa"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (6, 1, 'Chính phủ trung ương là bên có quyền lực lớn nhất trong việc làm luật, bỏ xa mọi bên khác.', 'The central government is by far the most powerful actor when it comes to making laws.', '["The national government is by far the most powerful actor when it comes to making laws.","The central government is by far the most powerful player when it comes to making laws.","The central government is by far the most powerful actor in making laws."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","central government = chính phủ trung ương; actor = bên tham gia, chủ thể; powerful → by far the most powerful"]'::jsonb, 'C1', '1. Chính phủ'),
    (6, 2, 'Chính phủ có nguồn lực lớn hơn nhiều so với từng cá nhân để giải quyết các vấn đề trên toàn quốc.', 'Governments have far greater resources than individuals to tackle nationwide problems.', '["Governments have much greater resources than individuals to tackle nationwide problems.","Governments have considerably greater resources than individuals to tackle nationwide problems.","The government has far greater resources than individuals to deal with nationwide problems."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","resources = nguồn lực; nationwide = trên toàn quốc; great → far greater"]'::jsonb, 'B2', '1. Chính phủ'),
    (6, 3, 'Đối với nhà nước, chi tiền cho các chiến dịch chống hút thuốc ít tốn kém hơn chi trả cho việc điều trị ung thư phổi.', 'For the state, funding anti-smoking campaigns is less expensive than paying for lung cancer treatment.', '["For the state, funding anti-smoking campaigns is less costly than paying for lung cancer treatment.","For the government, funding anti-smoking campaigns is less expensive than paying for lung cancer treatment.","For the state, funding anti-smoking campaigns is less expensive than paying for the treatment of lung cancer."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","fund = chi tiền, tài trợ; anti-smoking campaign = chiến dịch chống hút thuốc; lung cancer = ung thư phổi; less expensive than = ít tốn kém hơn"]'::jsonb, 'B1', '1. Chính phủ'),
    (6, 4, 'Một chiến dịch tuyên truyền được thiết kế tốt có thể có sức ảnh hưởng ngang với một đạo luật mới.', 'A well-designed public campaign can be as influential as a new law.', '["A well-designed public campaign can be just as influential as a new law.","A well-planned public campaign can be as influential as a new law.","A well-designed awareness campaign can be as influential as a new law."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","well-designed = được thiết kế tốt; public campaign = chiến dịch tuyên truyền; influential = có sức ảnh hưởng"]'::jsonb, 'B1', '1. Chính phủ'),
    (6, 5, 'So với các khoản trợ cấp ngắn hạn, đầu tư làm đường mang lại lợi ích lâu dài hơn cho vùng nông thôn.', 'Compared with short-term subsidies, investment in roads brings longer-lasting benefits to rural areas.', '["In comparison with short-term subsidies, investment in roads brings longer-lasting benefits to rural areas.","Compared to short-term subsidies, investment in roads brings longer-lasting benefits to rural areas.","Compared with short-term subsidies, investing in roads brings longer-lasting benefits to rural areas."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","subsidy = khoản trợ cấp; investment in sth = đầu tư vào; longer-lasting = lâu dài hơn; rural areas = vùng nông thôn"]'::jsonb, 'B2', '1. Chính phủ'),
    (6, 6, 'Luật được thực thi càng nhất quán, người dân càng ít vi phạm.', 'The more consistently laws are enforced, the less often people break them.', '["The more consistently the law is enforced, the less often people break it.","The more consistently laws are enforced, the less frequently people break them.","The more consistently rules are enforced, the less often people break them."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","enforce = thực thi; consistently = nhất quán; break the law = vi phạm pháp luật; often → the less often"]'::jsonb, 'C1', '1. Chính phủ'),
    (6, 7, 'Bắt buộc đội mũ bảo hiểm bằng luật hiệu quả hơn việc chỉ khuyên người dân tự giác đội.', 'Making helmets compulsory by law is more effective than simply advising people to wear them.', '["Making helmets mandatory by law is more effective than simply advising people to wear them.","Making helmets compulsory by law is more effective than just advising people to wear them.","Making helmets compulsory by law is more effective than simply telling people to wear them."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","compulsory = bắt buộc; helmet = mũ bảo hiểm; advise sb to do sth = khuyên ai làm gì; effective → more effective than"]'::jsonb, 'B1', '1. Chính phủ'),
    (6, 8, 'Lợi ích của thuế đánh vào đồ uống có đường lớn hơn bất lợi của nó.', 'The benefits of a tax on sugary drinks outweigh its drawbacks.', '["The advantages of a tax on sugary drinks outweigh its disadvantages.","The benefits of taxing sugary drinks outweigh the drawbacks.","The benefits of a tax on sugary drinks outweigh the drawbacks."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","sugary drinks = đồ uống có đường; benefit = lợi ích; drawback = bất lợi, hạn chế; outweigh = lớn hơn"]'::jsonb, 'B2', '1. Chính phủ'),
    (6, 9, 'Một chính sách được thiết kế kém có thể còn kém hơn cả việc không làm gì, vì nó lãng phí tiền thuế của dân.', 'A poorly designed policy can be inferior to doing nothing at all, as it wastes taxpayers'' money.', '["A badly designed policy can be inferior to doing nothing at all, as it wastes taxpayers'' money.","A poorly designed policy can be inferior to doing nothing at all, since it wastes taxpayers'' money.","A poorly designed policy may be inferior to doing nothing at all, as it wastes taxpayers'' money."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","poorly designed = thiết kế kém; be inferior to = kém hơn; waste = lãng phí; taxpayers'' money = tiền thuế của dân"]'::jsonb, 'C1', '1. Chính phủ'),
    (6, 10, 'Bỏ phiếu là công cụ mạnh nhất mà người dân bình thường có để tác động đến chính quyền, bỏ xa các công cụ khác.', 'Voting is by far the most powerful tool that ordinary citizens have to influence the authorities.', '["Voting is by far the most powerful tool ordinary citizens have to influence the authorities.","Voting is by far the most powerful tool that ordinary people have to influence the authorities.","Voting is by far the most powerful tool that ordinary citizens have to influence those in power."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","vote = bỏ phiếu; ordinary citizens = người dân bình thường; influence = tác động; the authorities = chính quyền"]'::jsonb, 'C1', '2. Cá nhân'),
    (6, 11, 'So với những người chỉ biết phàn nàn, những người chủ động hành động tạo ra nhiều thay đổi hơn.', 'Compared with people who only complain, those who take the initiative create more change.', '["In comparison with people who only complain, those who take the initiative create more change.","Compared to people who only complain, those who take the initiative create more change.","Compared with people who just complain, those who take the initiative bring about more change."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","complain = phàn nàn; take the initiative = chủ động; bring about change = tạo ra thay đổi"]'::jsonb, 'B2', '2. Cá nhân'),
    (6, 12, 'Thay đổi xuất phát từ nhận thức của chính mỗi người thường bền vững hơn thay đổi do bị ép buộc.', 'Change driven by personal conviction is usually more lasting than forced change.', '["Change driven by personal conviction is often more lasting than forced change.","Change that comes from personal conviction is usually more lasting than forced change.","Change driven by personal belief is usually more lasting than forced change."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","personal conviction = nhận thức, niềm tin của bản thân; lasting = bền vững, lâu dài; forced = bị ép buộc"]'::jsonb, 'B1', '2. Cá nhân'),
    (6, 13, 'Mang theo túi vải khi đi mua sắm cũng quan trọng ngang với việc phân loại rác để tái chế ở nhà.', 'Bringing a cloth bag when shopping is as important as sorting waste for recycling at home.', '["Bringing a cloth bag when shopping is just as important as sorting waste for recycling at home.","Taking a cloth bag when shopping is as important as sorting waste for recycling at home.","Bringing a cloth bag when you go shopping is as important as sorting waste for recycling at home."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","cloth bag = túi vải; sort waste = phân loại rác; recycling = tái chế; important → as important as"]'::jsonb, 'B1', '2. Cá nhân'),
    (6, 14, 'Lựa chọn của người tiêu dùng có thể có sức mạnh ngang với luật pháp trong việc thay đổi những gì doanh nghiệp sản xuất.', 'Consumer choices can be as powerful as laws in changing what businesses produce.', '["Consumers'' choices can be as powerful as laws in changing what businesses produce.","Consumer choices can be just as powerful as laws in changing what businesses produce.","Consumer choices can be as powerful as legislation in changing what businesses produce."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","consumer choices = lựa chọn của người tiêu dùng; powerful = có sức mạnh; legislation = luật pháp"]'::jsonb, 'B1', '2. Cá nhân'),
    (6, 15, 'Đối với hầu hết mọi người, thay đổi một vài thói quen nhỏ dễ hơn nhiều so với thay đổi cả lối sống.', 'For most people, changing a few small habits is far easier than changing their entire lifestyle.', '["For most people, changing a few small habits is much easier than changing their entire lifestyle.","For most people, changing a few small habits is considerably easier than changing their whole lifestyle.","For most people, changing a few small habits is far easier than changing their whole lifestyle."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","habit = thói quen; lifestyle = lối sống; entire / whole = toàn bộ; easy → far easier"]'::jsonb, 'B2', '2. Cá nhân'),
    (6, 16, 'Một thói quen mới được lặp lại càng lâu, nó càng trở nên tự nhiên.', 'The longer a new habit is repeated, the more natural it becomes.', '["The longer a new habit is practised, the more natural it becomes.","The longer a new habit is practiced, the more natural it becomes.","The longer you repeat a new habit, the more natural it becomes.","The longer a new habit is repeated, the more natural it feels."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","repeat = lặp lại; practise (Mỹ: practice) = luyện tập; natural = tự nhiên; long → the longer"]'::jsonb, 'C1', '2. Cá nhân'),
    (6, 17, 'Lợi ích của việc tự học trực tuyến theo tốc độ của riêng mình lớn hơn bất lợi.', 'The advantages of learning online at your own pace outweigh the disadvantages.', '["The benefits of learning online at your own pace outweigh the drawbacks.","The advantages of studying online at your own pace outweigh the disadvantages.","The advantages of learning online at one''s own pace outweigh the disadvantages."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","at your own pace = theo tốc độ của riêng mình; outweigh = lớn hơn; disadvantage = bất lợi"]'::jsonb, 'B2', '2. Cá nhân'),
    (6, 18, 'Về mức độ tác động, hành động của một cá nhân đơn lẻ kém hơn hành động tập thể.', 'In terms of impact, the action of a single individual is inferior to collective action.', '["In terms of impact, the actions of a single individual are inferior to collective action.","In terms of impact, a single individual''s action is inferior to collective action.","When it comes to impact, the action of a single individual is inferior to collective action."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","single individual = cá nhân đơn lẻ; collective action = hành động tập thể; be inferior to = kém hơn; in terms of = về mặt"]'::jsonb, 'C1', '2. Cá nhân'),
    (6, 19, 'Đối với nhà tuyển dụng, những kỹ năng mềm mà sinh viên rèn luyện ở đại học quan trọng ngang với tấm bằng.', 'For employers, the soft skills students develop at university are as important as their degree.', '["For employers, the soft skills that students develop at university are as important as their degree.","For employers, the soft skills students develop at university are just as important as their degree.","For employers, the soft skills students gain at university are as important as their degree."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","employer = nhà tuyển dụng; soft skills = kỹ năng mềm; degree = bằng cấp; important → as important as"]'::jsonb, 'B1', '3. Trường học'),
    (6, 20, 'Đối với trẻ em nhà nghèo, trường công là con đường quan trọng nhất để tiếp cận tri thức, bỏ xa mọi con đường khác.', 'For children from poor families, state schools are by far the most important route to knowledge.', '["For children from poor families, public schools are by far the most important route to knowledge.","For children from poor backgrounds, state schools are by far the most important route to knowledge.","For children from poor families, state schools are by far the most important path to knowledge."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","state school (Mỹ: public school) = trường công; route to sth = con đường dẫn tới; knowledge = tri thức"]'::jsonb, 'C1', '3. Trường học'),
    (6, 21, 'Trẻ em dành thời gian ở trường nhiều hơn nhiều so với bất kỳ nơi nào khác ngoài nhà.', 'Children spend far more time at school than anywhere else outside the home.', '["Children spend much more time at school than anywhere else outside the home.","Children spend considerably more time at school than anywhere else outside the home.","Children spend far more time at school than in any other place outside the home."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","spend time = dành thời gian; anywhere else = bất kỳ nơi nào khác; more time → far more time"]'::jsonb, 'B2', '3. Trường học'),
    (6, 22, 'Với nhiều học sinh, áp lực thi cử còn gây căng thẳng hơn cả khối lượng bài vở.', 'For many students, exam pressure is more stressful than the workload itself.', '["For many pupils, exam pressure is more stressful than the workload itself.","For many students, the pressure of exams is more stressful than the workload itself.","For many students, exam pressure is more stressful than the workload."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","exam pressure = áp lực thi cử; stressful = gây căng thẳng; workload = khối lượng công việc, bài vở"]'::jsonb, 'B1', '3. Trường học'),
    (6, 23, 'So với học sinh chỉ học lý thuyết, những em được dạy kỹ năng thực tế tự tin hơn khi đi làm.', 'Compared with students who only learn theory, those taught practical skills feel more confident at work.', '["In comparison with students who only learn theory, those taught practical skills feel more confident at work.","Compared to students who only learn theory, those taught practical skills feel more confident at work.","Compared with students who only study theory, those who learn practical skills feel more confident at work."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","theory = lý thuyết; practical skills = kỹ năng thực tế; confident = tự tin"]'::jsonb, 'B2', '3. Trường học'),
    (6, 24, 'Lợi ích của việc đưa môn tài chính cá nhân vào chương trình học lớn hơn bất lợi.', 'The advantages of adding personal finance to the curriculum outweigh the disadvantages.', '["The benefits of adding personal finance to the curriculum outweigh the drawbacks.","The advantages of including personal finance in the curriculum outweigh the disadvantages.","The benefits of including personal finance in the curriculum outweigh the drawbacks."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","personal finance = tài chính cá nhân; curriculum = chương trình học; add sth to sth = đưa cái gì vào"]'::jsonb, 'B2', '3. Trường học'),
    (6, 25, 'Hướng nghiệp sớm rẻ hơn nhiều so với việc học sai ngành suốt nhiều năm.', 'Early career guidance is much cheaper than studying the wrong major for several years.', '["Early career guidance is far cheaper than studying the wrong major for several years.","Early career guidance is considerably cheaper than studying the wrong subject for several years.","Early careers guidance is much cheaper than studying the wrong major for several years."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","career guidance = hướng nghiệp; major = ngành học; cheap → much cheaper"]'::jsonb, 'B2', '3. Trường học'),
    (6, 26, 'Học sinh học cách lập ngân sách càng sớm thì khi trưởng thành càng ít có nguy cơ mắc nợ.', 'The earlier students learn to budget, the less likely they are to fall into debt as adults.', '["The earlier pupils learn to budget, the less likely they are to fall into debt as adults.","The earlier students learn how to budget, the less likely they are to fall into debt as adults.","The earlier students learn to budget, the less likely they are to get into debt as adults."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","budget = lập ngân sách; fall into debt = mắc nợ; early → the earlier; likely → the less likely"]'::jsonb, 'C1', '3. Trường học'),
    (6, 27, 'Học qua dự án vượt trội hơn các bài giảng truyền thống trong việc phát triển tư duy phản biện.', 'Project-based learning is superior to traditional lectures in developing critical thinking.', '["Project-based learning is superior to traditional lectures when it comes to developing critical thinking.","Learning through projects is superior to traditional lectures in developing critical thinking.","Project-based learning is superior to conventional lectures in developing critical thinking."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","project-based learning = học qua dự án; lecture = bài giảng; critical thinking = tư duy phản biện; be superior to = vượt trội hơn"]'::jsonb, 'C1', '3. Trường học'),
    (6, 28, 'Ông bà có thể quan trọng ngang với cha mẹ trong việc chăm sóc trẻ nhỏ.', 'Grandparents can be as important as parents in caring for young children.', '["Grandparents can be just as important as parents in caring for young children.","Grandparents can be as important as parents in looking after young children.","Grandparents can be as important as parents when it comes to caring for young children."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","grandparents = ông bà; care for / look after = chăm sóc; important → as important as"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (6, 29, 'So với những năm về sau, những năm đầu đời có ảnh hưởng lớn hơn đến tính cách của trẻ.', 'Compared with later years, the first years of life have a greater influence on a child''s personality.', '["In comparison with later years, the first years of life have a greater influence on a child''s personality.","Compared to later years, the first years of life have a greater influence on a child''s personality.","Compared with later years, the early years of life have a greater influence on a child''s personality."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","the first years of life = những năm đầu đời; personality = tính cách; have an influence on = ảnh hưởng đến"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (6, 30, 'Cha mẹ càng đọc sách nhiều ở nhà, con cái càng có khả năng yêu thích việc đọc.', 'The more parents read at home, the more likely their children are to enjoy reading.', '["The more parents read at home, the more likely their children are to love reading.","The more parents read at home, the more likely children are to enjoy reading.","The more often parents read at home, the more likely their children are to enjoy reading."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","be likely to V = có khả năng; enjoy reading = thích đọc sách; much → the more"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (6, 31, 'Những đứa trẻ cảm thấy được yêu thương ở nhà tự tin hơn nhiều so với những đứa trẻ bị bỏ mặc.', 'Children who feel loved at home are far more confident than those who are neglected.', '["Children who feel loved at home are much more confident than those who are neglected.","Children who feel loved at home are considerably more confident than those who are neglected.","Children who feel loved at home are far more confident than neglected children."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","feel loved = cảm thấy được yêu thương; neglected = bị bỏ mặc; confident → far more confident"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (6, 32, 'Đặt ra quy tắc rõ ràng về thời gian dùng thiết bị hiệu quả hơn việc tịch thu điện thoại của con.', 'Setting clear rules on screen time is more effective than confiscating children''s phones.', '["Setting clear rules about screen time is more effective than confiscating children''s phones.","Setting clear screen time rules is more effective than confiscating children''s phones.","Setting clear rules on screen time is more effective than taking children''s phones away."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","screen time = thời gian dùng thiết bị; confiscate = tịch thu; effective → more effective than"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (6, 33, 'Bữa ăn gia đình là dịp tốt nhất để cha mẹ trò chuyện với con, bỏ xa mọi dịp khác.', 'Family meals are by far the best opportunity for parents to talk with their children.', '["Family meals are by far the best opportunity for parents to talk to their children.","Family meals are by far the best chance for parents to talk with their children.","Family mealtimes are by far the best opportunity for parents to talk with their children."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","family meal = bữa ăn gia đình; opportunity = dịp, cơ hội; good → by far the best"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (6, 34, 'So với những đứa trẻ được cha mẹ quyết định mọi thứ, trẻ tự đưa ra những lựa chọn nhỏ sẽ trở thành người trưởng thành tự lập hơn.', 'Compared with children whose parents decide everything for them, those who make small choices themselves become more independent adults.', '["In comparison with children whose parents decide everything for them, those who make small choices themselves become more independent adults.","Compared to children whose parents decide everything for them, those who make small choices themselves become more independent adults.","Compared with children whose parents make every decision for them, those who make small choices themselves become more independent adults."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","decide everything = quyết định mọi thứ; make a choice = đưa ra lựa chọn; independent = tự lập"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (6, 35, 'Đối với nhiều cha mẹ bận rộn, lợi ích của việc làm bán thời gian để ở bên con nhiều hơn lớn hơn bất lợi.', 'For many busy parents, the advantages of working part-time to spend more time with their children outweigh the disadvantages.', '["For many busy parents, the benefits of working part-time to spend more time with their children outweigh the drawbacks.","For many busy parents, the advantages of working part-time in order to spend more time with their children outweigh the disadvantages.","For many busy parents, the advantages of working part-time to spend more time with their kids outweigh the disadvantages."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","work part-time = làm bán thời gian; busy = bận rộn; outweigh the disadvantages = lớn hơn bất lợi"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (6, 36, 'La mắng trẻ kém hơn sự động viên khi muốn thay đổi hành vi của các em.', 'Shouting at children is inferior to encouragement when it comes to changing their behaviour.', '["Shouting at children is inferior to encouragement when it comes to changing their behavior.","Scolding children is inferior to encouragement when it comes to changing their behaviour.","Shouting at children is inferior to praise when it comes to changing their behaviour."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","shout at / scold sb = la mắng; encouragement = sự động viên; behaviour (Mỹ: behavior) = hành vi; be inferior to = kém hơn"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (6, 37, 'Các doanh nghiệp vừa và nhỏ có thể quan trọng ngang với các tập đoàn lớn trong việc tạo việc làm.', 'Small and medium-sized businesses can be as important as large corporations in creating jobs.', '["Small and medium-sized firms can be as important as large corporations in creating jobs.","Small and medium-sized businesses can be just as important as large corporations in creating jobs.","Small and medium-sized businesses can be as important as big corporations in creating jobs."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","small and medium-sized businesses = doanh nghiệp vừa và nhỏ; corporation = tập đoàn; create jobs = tạo việc làm"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (6, 38, 'Lợi nhuận là động lực mạnh nhất khiến doanh nghiệp thay đổi cách hoạt động, bỏ xa mọi động lực khác.', 'Profit is by far the strongest incentive for companies to change the way they operate.', '["Profit is by far the strongest motive for companies to change the way they operate.","Profit is by far the strongest reason for companies to change the way they operate.","Profit is by far the strongest incentive for companies to change how they operate."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","profit = lợi nhuận; incentive = động lực; operate = hoạt động; strong → by far the strongest"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (6, 39, 'So với các doanh nghiệp nhỏ, các tập đoàn đa quốc gia gây ra nhiều ô nhiễm công nghiệp hơn.', 'Compared with small businesses, multinational corporations cause more industrial pollution.', '["In comparison with small businesses, multinational corporations cause more industrial pollution.","Compared to small businesses, multinational corporations cause more industrial pollution.","Compared with small firms, multinational corporations cause more industrial pollution."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","multinational corporation = tập đoàn đa quốc gia; industrial pollution = ô nhiễm công nghiệp"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (6, 40, 'Ngày nay, sản phẩm xanh được người tiêu dùng ưa chuộng hơn nhiều so với mười năm trước.', 'Green products are far more popular with consumers today than they were a decade ago.', '["Green products are much more popular with consumers today than they were a decade ago.","Green products are considerably more popular with consumers today than they were ten years ago.","Eco-friendly products are far more popular with consumers today than they were a decade ago."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","green / eco-friendly products = sản phẩm xanh; be popular with sb = được ai ưa chuộng; a decade = mười năm"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (6, 41, 'Nhân viên càng ít căng thẳng thì càng làm việc năng suất.', 'The less stressed employees feel, the more productive they become.', '["The less stressed employees are, the more productive they become.","The less stressed staff feel, the more productive they become.","The less stressed employees feel, the more productive they are."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","stressed = căng thẳng; productive = năng suất; little → the less; productive → the more productive"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (6, 42, 'Đối với phần lớn nhà sản xuất, lợi ích của việc áp dụng công nghệ xanh lớn hơn bất lợi.', 'For most manufacturers, the advantages of adopting green technology outweigh the disadvantages.', '["For most manufacturers, the benefits of adopting green technology outweigh the drawbacks.","For most manufacturers, the advantages of using green technology outweigh the disadvantages.","For most manufacturers, the advantages of adopting clean technology outweigh the disadvantages."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","manufacturer = nhà sản xuất; adopt = áp dụng; green technology = công nghệ xanh"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (6, 43, 'Giữ chân một nhân viên giỏi ít tốn kém hơn tuyển dụng và đào tạo một người mới.', 'Keeping a skilled employee is less expensive than recruiting and training a new one.', '["Keeping a skilled employee is less costly than recruiting and training a new one.","Retaining a skilled employee is less expensive than recruiting and training a new one.","Keeping a skilled worker is less expensive than recruiting and training a new one."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","keep / retain = giữ chân; skilled = giỏi, lành nghề; recruit = tuyển dụng; expensive → less expensive than"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (6, 44, 'Những công ty sớm áp dụng công nghệ mới thường vượt trội hơn đối thủ về năng suất.', 'Companies that adopt new technology early are often superior to their rivals in terms of productivity.', '["Firms that adopt new technology early are often superior to their rivals in terms of productivity.","Companies that adopt new technology early are often superior to their competitors in terms of productivity.","Companies that adopt new technology early are often superior to their rivals in productivity."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","adopt = áp dụng; rival / competitor = đối thủ; productivity = năng suất; be superior to = vượt trội hơn"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (6, 45, 'Người cao tuổi là nhóm dễ bị tổn thương nhất khi dịch cúm bùng phát, bỏ xa các nhóm khác.', 'Elderly people are by far the most vulnerable group when a flu epidemic breaks out.', '["Older people are by far the most vulnerable group when a flu epidemic breaks out.","The elderly are by far the most vulnerable group when a flu epidemic breaks out.","Elderly people are by far the most vulnerable group when there is a flu epidemic."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","vulnerable = dễ bị tổn thương; flu epidemic = dịch cúm; break out = bùng phát"]'::jsonb, 'C1', '6. Sức khỏe'),
    (6, 46, 'Với nhiều gia đình, đồ ăn nhanh tiện lợi hơn việc nấu những bữa ăn lành mạnh ở nhà.', 'For many families, fast food is more convenient than cooking healthy meals at home.', '["For many families, fast food is more convenient than preparing healthy meals at home.","For a lot of families, fast food is more convenient than cooking healthy meals at home.","For many households, fast food is more convenient than cooking healthy meals at home."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","fast food = đồ ăn nhanh; convenient = tiện lợi; healthy meal = bữa ăn lành mạnh"]'::jsonb, 'B1', '6. Sức khỏe'),
    (6, 47, 'Mỗi ngày người ta ngồi càng lâu, nguy cơ mắc bệnh tim càng cao.', 'The longer people sit each day, the higher their risk of heart disease.', '["The longer people sit every day, the higher their risk of heart disease.","The longer people spend sitting each day, the higher their risk of heart disease.","The longer people sit each day, the greater their risk of heart disease."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","risk of sth = nguy cơ mắc; heart disease = bệnh tim; long → the longer; high → the higher"]'::jsonb, 'C1', '6. Sức khỏe'),
    (6, 48, 'So với người có lối sống ít vận động, những người tập thể dục đều đặn ít phải nghỉ ốm hơn.', 'Compared with people who lead a sedentary lifestyle, those who exercise regularly take fewer sick days.', '["In comparison with people who lead a sedentary lifestyle, those who exercise regularly take fewer sick days.","Compared to people who lead a sedentary lifestyle, those who exercise regularly take fewer sick days.","Compared with people who lead sedentary lives, those who exercise regularly take fewer sick days."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","sedentary lifestyle = lối sống ít vận động; exercise regularly = tập thể dục đều đặn; sick day = ngày nghỉ ốm"]'::jsonb, 'B2', '6. Sức khỏe'),
    (6, 49, 'Ngủ đủ giấc cũng quan trọng ngang với ăn uống lành mạnh.', 'Getting enough sleep is as important as eating a healthy diet.', '["Getting enough sleep is just as important as eating a healthy diet.","Getting enough sleep is as important as having a healthy diet.","Sleeping enough is as important as eating a healthy diet."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","get enough sleep = ngủ đủ giấc; healthy diet = chế độ ăn lành mạnh; important → as important as"]'::jsonb, 'B1', '6. Sức khỏe'),
    (6, 50, 'Lợi ích của các chương trình hỗ trợ sức khỏe tinh thần tại nơi làm việc lớn hơn bất lợi của chúng.', 'The advantages of mental health programmes in the workplace outweigh their disadvantages.', '["The advantages of mental health programs in the workplace outweigh their disadvantages.","The benefits of mental health programmes in the workplace outweigh their drawbacks.","The advantages of workplace mental health programmes outweigh their disadvantages."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","mental health = sức khỏe tinh thần; programme (Mỹ: program) = chương trình; workplace = nơi làm việc"]'::jsonb, 'B2', '6. Sức khỏe'),
    (6, 51, 'Khám sức khỏe định kỳ rẻ hơn nhiều so với điều trị bệnh ở giai đoạn muộn.', 'Regular check-ups are far cheaper than treating diseases at a late stage.', '["Regular check-ups are much cheaper than treating diseases at a late stage.","Regular check-ups are considerably cheaper than treating illnesses at a late stage.","Regular medical check-ups are far cheaper than treating diseases at a late stage."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","regular check-up = khám sức khỏe định kỳ; at a late stage = ở giai đoạn muộn; cheap → far cheaper"]'::jsonb, 'B2', '6. Sức khỏe'),
    (6, 52, 'Một chế độ ăn cân bằng vượt trội hơn thực phẩm chức năng trong việc giữ gìn sức khỏe.', 'A balanced diet is superior to dietary supplements when it comes to staying healthy.', '["A balanced diet is superior to supplements when it comes to staying healthy.","A balanced diet is superior to dietary supplements for staying healthy.","A balanced diet is superior to dietary supplements when it comes to keeping healthy."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","balanced diet = chế độ ăn cân bằng; dietary supplements = thực phẩm chức năng; be superior to = vượt trội hơn"]'::jsonb, 'C1', '6. Sức khỏe'),
    (6, 53, 'So với mười năm trước, chi phí sinh hoạt ở các thành phố lớn đã tăng mạnh.', 'Compared with ten years ago, the cost of living in big cities has risen sharply.', '["Compared to ten years ago, the cost of living in big cities has risen sharply.","In comparison with ten years ago, the cost of living in big cities has risen sharply.","Compared with a decade ago, the cost of living in large cities has risen sharply."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","cost of living = chi phí sinh hoạt; rise sharply = tăng mạnh; a decade = mười năm"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (6, 54, 'Nhờ tự động hóa, nhiều sản phẩm thiết yếu hằng ngày có giá phải chăng hơn bao giờ hết.', 'Thanks to automation, many everyday products are more affordable than ever before.', '["Thanks to automation, many everyday goods are more affordable than ever before.","Because of automation, many everyday products are more affordable than ever before.","Thanks to automation, many everyday products are more affordable than ever."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","automation = tự động hóa; everyday products = sản phẩm hằng ngày; affordable = giá phải chăng; than ever before = hơn bao giờ hết"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (6, 55, 'Một quốc gia càng có nhiều lao động lành nghề thì càng thu hút nhiều nhà đầu tư nước ngoài.', 'The more skilled workers a country has, the more foreign investors it attracts.', '["The more skilled workers a country has, the more foreign investment it attracts.","The more skilled workers a nation has, the more foreign investors it attracts.","The more skilled workers a country has, the more foreign investors it will attract."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","skilled workers = lao động lành nghề; foreign investor = nhà đầu tư nước ngoài; attract = thu hút"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (6, 56, 'Đào tạo lại những người lao động bị mất việc cũng quan trọng ngang với việc tạo ra việc làm mới.', 'Retraining workers who have lost their jobs is as important as creating new ones.', '["Retraining workers who have lost their jobs is just as important as creating new ones.","Retraining unemployed workers is as important as creating new jobs.","Retraining people who have lost their jobs is as important as creating new ones."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","retrain = đào tạo lại; lose one''s job = mất việc; create jobs = tạo việc làm"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (6, 57, 'Với một nước đang phát triển, đầu tư vào con người là con đường chắc chắn nhất dẫn đến tăng trưởng bền vững, bỏ xa mọi con đường khác.', 'For a developing country, investing in people is by far the most reliable path to sustainable growth.', '["For a developing country, investing in people is by far the most reliable route to sustainable growth.","For developing countries, investing in people is by far the most reliable path to sustainable growth.","For a developing nation, investing in people is by far the most reliable path to sustainable growth."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","developing country = nước đang phát triển; reliable = chắc chắn, đáng tin cậy; sustainable growth = tăng trưởng bền vững"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (6, 58, 'Tạo việc làm ổn định tốt cho nền kinh tế hơn nhiều so với việc phát trợ cấp lâu dài cho người dân.', 'Creating stable jobs is much better for the economy than giving people long-term handouts.', '["Creating stable jobs is far better for the economy than giving people long-term handouts.","Creating stable jobs is considerably better for the economy than giving people long-term handouts.","Creating secure jobs is much better for the economy than giving people long-term handouts."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","stable / secure job = việc làm ổn định; handout = tiền trợ cấp, của cho không; good → much better"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (6, 59, 'Với một thị trấn nhỏ, lợi ích kinh tế của du lịch lớn hơn bất lợi của nó.', 'For a small town, the economic benefits of tourism outweigh its drawbacks.', '["For a small town, the economic advantages of tourism outweigh its disadvantages.","For small towns, the economic benefits of tourism outweigh its drawbacks.","For a small town, the economic benefits of tourism outweigh the drawbacks."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","economic benefits = lợi ích kinh tế; tourism = du lịch; drawback = bất lợi; outweigh = lớn hơn"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (6, 60, 'Tăng trưởng nhanh nhưng không đồng đều kém hơn tăng trưởng chậm hơn nhưng mang lại lợi ích cho mọi người.', 'Rapid but uneven growth is inferior to slower growth that benefits everyone.', '["Fast but uneven growth is inferior to slower growth that benefits everyone.","Rapid but uneven growth is inferior to slower growth that benefits all.","Rapid but unequal growth is inferior to slower growth that benefits everyone."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","uneven / unequal = không đồng đều; growth = tăng trưởng; benefit sb = mang lại lợi ích cho ai; be inferior to = kém hơn"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (6, 61, 'So với người dân bản địa, người nhập cư thường gặp khó khăn hơn trong việc tìm việc làm.', 'Compared with local people, immigrants often find it harder to get a job.', '["In comparison with local people, immigrants often find it harder to get a job.","Compared to local people, immigrants often find it harder to find a job.","Compared with local residents, immigrants often find it harder to get a job."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","immigrant = người nhập cư; local people = người bản địa; find it hard to V = thấy khó làm gì"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (6, 62, 'Nghèo đói là rào cản nghiêm trọng nhất đối với việc học của các nhóm yếu thế, bỏ xa mọi rào cản khác.', 'Poverty is by far the most serious barrier to education for vulnerable groups.', '["Poverty is by far the most serious obstacle to education for vulnerable groups.","Poverty is by far the biggest barrier to education for vulnerable groups.","Poverty is by far the most serious barrier to education for disadvantaged groups."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","poverty = nghèo đói; barrier / obstacle to sth = rào cản; vulnerable groups = nhóm yếu thế"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (6, 63, 'Ở các thành phố lớn, người cao tuổi thường bị cô lập hơn những người sống ở làng quê.', 'In big cities, elderly people are often more isolated than those living in villages.', '["In large cities, elderly people are often more isolated than those living in villages.","In big cities, older people are often more isolated than those living in villages.","In big cities, elderly people are often more isolated than people living in villages."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","elderly people = người cao tuổi; isolated = bị cô lập; village = làng quê"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (6, 64, 'Đối với cư dân địa phương, một thư viện công cộng có thể có giá trị ngang với một trung tâm thương mại mới.', 'For local residents, a public library can be as valuable as a new shopping centre.', '["For local residents, a public library can be as valuable as a new shopping center.","For local residents, a public library can be just as valuable as a new shopping centre.","For local people, a public library can be as valuable as a new shopping centre."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","local residents = cư dân địa phương; valuable = có giá trị; shopping centre (Mỹ: center) = trung tâm thương mại"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (6, 65, 'Tuần tra thường xuyên giúp khu dân cư an toàn hơn nhiều so với việc chỉ lắp camera an ninh.', 'Regular police patrols make neighbourhoods much safer than security cameras alone.', '["Regular police patrols make neighborhoods much safer than security cameras alone.","Regular police patrols make neighbourhoods far safer than security cameras alone.","Regular police patrols make neighbourhoods considerably safer than security cameras alone."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","police patrol = tuần tra; neighbourhood (Mỹ: neighborhood) = khu dân cư; security camera = camera an ninh; safe → much safer"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (6, 66, 'Cư dân càng thường xuyên tham gia hoạt động chung, cộng đồng của họ càng gắn bó.', 'The more often residents take part in shared activities, the closer their community becomes.', '["The more often residents join in shared activities, the closer their community becomes.","The more often residents take part in shared activities, the more united their community becomes.","The more frequently residents take part in shared activities, the closer their community becomes."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","take part in = tham gia; shared activities = hoạt động chung; close / united = gắn bó; close → the closer"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (6, 67, 'Lợi ích của việc xây thêm nhà ở xã hội lớn hơn bất lợi.', 'The advantages of building more social housing outweigh the disadvantages.', '["The benefits of building more social housing outweigh the drawbacks.","The advantages of building more public housing outweigh the disadvantages.","The advantages of providing more social housing outweigh the disadvantages."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","social housing = nhà ở xã hội; build = xây dựng; outweigh = lớn hơn"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (6, 68, 'Đối với người già, các hoạt động cộng đồng vượt trội hơn các cuộc gọi video trong việc giảm cô đơn.', 'For elderly people, community activities are superior to video calls in reducing loneliness.', '["For older people, community activities are superior to video calls in reducing loneliness.","For elderly people, community activities are superior to video calls when it comes to reducing loneliness.","For the elderly, community activities are superior to video calls in reducing loneliness."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","community activities = hoạt động cộng đồng; video call = cuộc gọi video; loneliness = sự cô đơn; be superior to = vượt trội hơn"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (6, 69, 'Người tiêu dùng cũng có trách nhiệm ngang với nhà sản xuất đối với rác thải nhựa.', 'Consumers are as responsible as manufacturers for plastic waste.', '["Consumers are just as responsible as manufacturers for plastic waste.","Consumers are as responsible as producers for plastic waste.","Shoppers are as responsible as manufacturers for plastic waste."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","consumer = người tiêu dùng; manufacturer = nhà sản xuất; be responsible for = chịu trách nhiệm về; plastic waste = rác thải nhựa"]'::jsonb, 'B1', '9. Môi trường'),
    (6, 70, 'Đốt nhiên liệu hóa thạch là nguyên nhân lớn nhất gây ra biến đổi khí hậu, bỏ xa các nguyên nhân khác.', 'Burning fossil fuels is by far the biggest cause of climate change.', '["Burning fossil fuels is by far the largest cause of climate change.","The burning of fossil fuels is by far the biggest cause of climate change.","Burning fossil fuels is by far the most significant cause of climate change."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","fossil fuels = nhiên liệu hóa thạch; climate change = biến đổi khí hậu; big → by far the biggest"]'::jsonb, 'C1', '9. Môi trường'),
    (6, 71, 'Ô nhiễm không khí nguy hiểm hơn những gì phần lớn mọi người nhận ra.', 'Air pollution is more dangerous than most people realise.', '["Air pollution is more dangerous than most people realize.","Air pollution is more harmful than most people realise.","Air pollution is more dangerous than most people think."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","air pollution = ô nhiễm không khí; dangerous = nguy hiểm; realise (Mỹ: realize) = nhận ra"]'::jsonb, 'B1', '9. Môi trường'),
    (6, 72, 'Rừng bị chặt phá càng nhiều, càng có nhiều loài mất môi trường sống tự nhiên.', 'The more forests are cut down, the more species lose their natural habitats.', '["The more forests are cleared, the more species lose their natural habitats.","The more forests we cut down, the more species lose their natural habitats.","The more forests are cut down, the more animal species lose their habitats."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","cut down = chặt phá; species = loài; natural habitat = môi trường sống tự nhiên"]'::jsonb, 'C1', '9. Môi trường'),
    (6, 73, 'Tái chế một lon nhôm tốn ít năng lượng hơn nhiều so với sản xuất một lon mới.', 'Recycling an aluminium can uses far less energy than making a new one.', '["Recycling an aluminum can uses far less energy than making a new one.","Recycling an aluminium can uses much less energy than making a new one.","Recycling an aluminium can uses considerably less energy than producing a new one."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","recycle = tái chế; aluminium (Mỹ: aluminum) can = lon nhôm; little → far less"]'::jsonb, 'B2', '9. Môi trường'),
    (6, 74, 'So với xe máy, xe buýt điện thải ra ít khí thải hơn tính trên mỗi hành khách.', 'Compared with motorbikes, electric buses produce fewer emissions per passenger.', '["In comparison with motorbikes, electric buses produce fewer emissions per passenger.","Compared to motorbikes, electric buses produce fewer emissions per passenger.","Compared with motorbikes, electric buses produce lower emissions per passenger."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","electric bus = xe buýt điện; emissions = khí thải; per passenger = trên mỗi hành khách"]'::jsonb, 'B2', '9. Môi trường'),
    (6, 75, 'Lợi ích của việc cấm túi nilon lớn hơn bất lợi là sự bất tiện cho người mua sắm.', 'The benefits of banning plastic bags outweigh the inconvenience it causes shoppers.', '["The advantages of banning plastic bags outweigh the inconvenience it causes shoppers.","The benefits of a ban on plastic bags outweigh the inconvenience it causes shoppers.","The benefits of banning plastic bags outweigh the inconvenience to shoppers."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","ban = cấm; plastic bag = túi nilon; inconvenience = sự bất tiện; outweigh = lớn hơn"]'::jsonb, 'B2', '9. Môi trường'),
    (6, 76, 'Ở thành phố, đi xe đạp vượt trội hơn lái ô tô cả về khí thải lẫn tiếng ồn.', 'In cities, cycling is superior to driving in terms of both emissions and noise.', '["In cities, cycling is superior to driving in terms of emissions and noise.","In urban areas, cycling is superior to driving in terms of both emissions and noise.","In cities, cycling is superior to driving when it comes to both emissions and noise."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","cycling = đi xe đạp; emissions = khí thải; noise = tiếng ồn; be superior to = vượt trội hơn"]'::jsonb, 'C1', '9. Môi trường'),
    (6, 77, 'So với người lớn tuổi, thanh thiếu niên dễ nghiện mạng xã hội hơn.', 'Compared with older adults, teenagers become addicted to social media more easily.', '["In comparison with older adults, teenagers become addicted to social media more easily.","Compared to older adults, teenagers become addicted to social media more easily.","Compared with older adults, teenagers get addicted to social media more easily."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","older adults = người lớn tuổi; become addicted to sth = nghiện; social media = mạng xã hội"]'::jsonb, 'B2', '10. Công nghệ'),
    (6, 78, 'Điện thoại thông minh rẻ hơn nhiều so với trước đây, và giờ gần như ai cũng có thể mua được.', 'Smartphones are far cheaper than they used to be, and almost everyone can now afford one.', '["Smartphones are much cheaper than they used to be, and almost everyone can now afford one.","Smartphones are considerably cheaper than they used to be, and almost everyone can now afford one.","Smartphones are far cheaper than they used to be, and nearly everyone can now afford one."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","afford = đủ tiền mua; used to be = từng là, trước đây; cheap → far cheaper"]'::jsonb, 'B2', '10. Công nghệ'),
    (6, 79, 'Robot đáng tin cậy hơn con người khi làm những công việc lặp đi lặp lại.', 'Robots are more reliable than humans when it comes to repetitive tasks.', '["Robots are more reliable than people when it comes to repetitive tasks.","Robots are more reliable than humans at repetitive tasks.","Robots are more reliable than human workers when it comes to repetitive tasks."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","reliable = đáng tin cậy; repetitive tasks = công việc lặp đi lặp lại; when it comes to = khi nói đến"]'::jsonb, 'B1', '10. Công nghệ'),
    (6, 80, 'Internet là cách nhanh nhất để học sinh tìm kiếm thông tin, bỏ xa các cách khác.', 'The Internet is by far the fastest way for students to find information.', '["The Internet is by far the quickest way for students to find information.","The Internet is by far the fastest way for students to look up information.","The Internet is by far the fastest way for pupils to find information."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","find / look up information = tìm kiếm thông tin; fast → by far the fastest"]'::jsonb, 'C1', '10. Công nghệ'),
    (6, 81, 'Bảo vệ dữ liệu cá nhân cũng quan trọng ngang với phát triển công nghệ mới.', 'Protecting personal data is as important as developing new technology.', '["Protecting personal data is just as important as developing new technology.","Protecting people''s personal data is as important as developing new technology.","Protecting personal data is as important as developing new technologies."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","personal data = dữ liệu cá nhân; protect = bảo vệ; develop = phát triển"]'::jsonb, 'B1', '10. Công nghệ'),
    (6, 82, 'Tự động hóa lan rộng càng nhanh, người lao động càng cần được đào tạo lại sớm.', 'The faster automation spreads, the sooner workers need to be retrained.', '["The faster automation spreads, the sooner workers need retraining.","The faster automation spreads, the earlier workers need to be retrained.","The more quickly automation spreads, the sooner workers need to be retrained."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","automation = tự động hóa; spread = lan rộng; retrain = đào tạo lại; fast → the faster; soon → the sooner"]'::jsonb, 'C1', '10. Công nghệ'),
    (6, 83, 'Đối với phần lớn nhân viên văn phòng, lợi ích của việc dùng công cụ AI lớn hơn bất lợi.', 'For most office workers, the advantages of using AI tools outweigh the disadvantages.', '["For most office workers, the benefits of using AI tools outweigh the drawbacks.","For most office workers, the advantages of using artificial intelligence tools outweigh the disadvantages.","For most office staff, the advantages of using AI tools outweigh the disadvantages."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","office worker = nhân viên văn phòng; AI (artificial intelligence) = trí tuệ nhân tạo; tool = công cụ"]'::jsonb, 'B2', '10. Công nghệ'),
    (6, 84, 'Máy móc vẫn còn kém hơn con người về khả năng thấu hiểu cảm xúc.', 'Machines are still inferior to humans when it comes to understanding emotions.', '["Machines are still inferior to people when it comes to understanding emotions.","Machines remain inferior to humans when it comes to understanding emotions.","Machines are still inferior to humans in understanding emotions."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","machine = máy móc; understand emotions = thấu hiểu cảm xúc; be inferior to = kém hơn"]'::jsonb, 'C1', '10. Công nghệ'),
    (6, 85, 'Đối với người đi làm bận rộn, mua sắm trực tuyến tiện lợi hơn đi siêu thị.', 'For busy professionals, online shopping is more convenient than going to the supermarket.', '["For busy professionals, shopping online is more convenient than going to the supermarket.","For busy professionals, online shopping is more convenient than visiting the supermarket.","For busy people, online shopping is more convenient than going to the supermarket."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","busy professionals = người đi làm bận rộn; convenient = tiện lợi; convenient → more convenient than"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (6, 86, 'So với những người chưa có con, cha mẹ đi làm có ít thời gian rảnh cho bản thân hơn.', 'Compared with people without children, working parents have less free time for themselves.', '["In comparison with people without children, working parents have less free time for themselves.","Compared to people without children, working parents have less free time for themselves.","Compared with people who have no children, working parents have less free time for themselves."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","working parents = cha mẹ đi làm; free time = thời gian rảnh; less = ít hơn"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (6, 87, 'Vào giờ cao điểm, đi tàu điện ngầm nhanh hơn nhiều so với lái xe qua trung tâm thành phố.', 'During rush hour, taking the metro is much quicker than driving through the city centre.', '["During rush hour, taking the metro is much quicker than driving through the city center.","During rush hour, taking the metro is far quicker than driving through the city centre.","During rush hour, taking the metro is considerably quicker than driving through the city centre."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","rush hour = giờ cao điểm; metro = tàu điện ngầm; city centre (Mỹ: center) = trung tâm thành phố; quick → much quicker"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (6, 88, 'Quãng đường đi làm càng ngắn, người ta càng có nhiều thời gian cho gia đình.', 'The shorter people''s commute is, the more time they have for their families.', '["The shorter the commute, the more time people have for their families.","The shorter people''s commute is, the more time they can spend with their families.","The shorter their commute is, the more time people have for their families."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","commute = quãng đường đi làm; short → the shorter; much time → the more time"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (6, 89, 'Đối với nhiều nhân viên, làm việc tại nhà có thể đạt năng suất ngang với làm việc ở văn phòng.', 'For many employees, working from home can be as productive as working in the office.', '["For many employees, working from home can be just as productive as working in the office.","For many employees, working from home can be as productive as working in an office.","For many employees, working from home can be as productive as working at the office."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","work from home = làm việc tại nhà; productive = năng suất; productive → as productive as"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (6, 90, 'Đối với các gia đình đông người, máy rửa bát là thiết bị tiết kiệm thời gian hữu ích nhất, bỏ xa các thiết bị khác.', 'For large families, a dishwasher is by far the most useful time-saving appliance.', '["For big families, a dishwasher is by far the most useful time-saving appliance.","For large families, the dishwasher is by far the most useful time-saving appliance.","For large families, a dishwasher is by far the most useful time-saving device."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","dishwasher = máy rửa bát; time-saving = tiết kiệm thời gian; appliance = thiết bị gia dụng; useful → by far the most useful"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (6, 91, 'Đối với các gia đình bận rộn, lợi ích của ứng dụng giao đồ ăn lớn hơn bất lợi.', 'For busy families, the advantages of food delivery apps outweigh the disadvantages.', '["For busy families, the benefits of food delivery apps outweigh the drawbacks.","For busy families, the advantages of food delivery services outweigh the disadvantages.","For busy households, the advantages of food delivery apps outweigh the disadvantages."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","food delivery app = ứng dụng giao đồ ăn; advantage = lợi ích; disadvantage = bất lợi"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (6, 92, 'Xét về sự tiện lợi, chi nhánh ngân hàng truyền thống kém hơn ngân hàng trực tuyến.', 'In terms of convenience, traditional bank branches are inferior to online banking.', '["In terms of convenience, traditional bank branches are inferior to internet banking.","When it comes to convenience, traditional bank branches are inferior to online banking.","In terms of convenience, traditional banks are inferior to online banking."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","in terms of = xét về; bank branch = chi nhánh ngân hàng; online banking = ngân hàng trực tuyến; be inferior to = kém hơn"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (6, 93, 'Nhu cầu của các thế hệ tương lai cũng quan trọng ngang với nhu cầu của những người đang sống hôm nay.', 'The needs of future generations are as important as those of people living today.', '["The needs of future generations are just as important as those of people living today.","The needs of future generations are as important as the needs of people living today.","The interests of future generations are as important as those of people living today."]'::jsonb, '["as + adj + as = bằng, ngang với (mục 2.6)","future generations = thế hệ tương lai; needs = nhu cầu; those of = của (thay cho danh từ đã nói)"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (6, 94, 'Với nhiều chính trị gia, kết quả nhanh chóng hấp dẫn hơn lợi ích lâu dài.', 'For many politicians, quick results are more attractive than long-term benefits.', '["For many politicians, quick results are more appealing than long-term benefits.","For many politicians, quick wins are more attractive than long-term benefits.","For many politicians, fast results are more attractive than long-term benefits."]'::jsonb, '["more / less + adj + than = hơn / kém hơn (mục 2.6)","politician = chính trị gia; quick results = kết quả nhanh; attractive / appealing = hấp dẫn; long-term = lâu dài"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (6, 95, 'Đối với nhân viên, giai đoạn đào tạo là phần khó khăn nhất khi áp dụng một hệ thống mới, bỏ xa các phần khác.', 'For staff, the training period is by far the most difficult part of adopting a new system.', '["For employees, the training period is by far the most difficult part of adopting a new system.","For staff, the training period is by far the hardest part of adopting a new system.","For staff, the training period is by far the most difficult stage of adopting a new system."]'::jsonb, '["by far the most + adj = … nhất, bỏ xa (mục 2.6)","training period = giai đoạn đào tạo; adopt a new system = áp dụng hệ thống mới; difficult → by far the most difficult"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (6, 96, 'Về lâu dài, các tòa nhà tiết kiệm năng lượng có chi phí vận hành rẻ hơn nhiều so với tòa nhà truyền thống.', 'In the long term, energy-efficient buildings are far cheaper to run than traditional ones.', '["In the long term, energy-efficient buildings are much cheaper to run than traditional ones.","In the long term, energy-efficient buildings are considerably cheaper to run than conventional ones.","Over time, energy-efficient buildings are far cheaper to run than traditional ones."]'::jsonb, '["far / much / considerably + comparative = hơn nhiều (mục 2.6)","in the long term = về lâu dài; energy-efficient = tiết kiệm năng lượng; run = vận hành; cheap → far cheaper"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (6, 97, 'So với những cải cách đột ngột, thay đổi từng bước giúp người dân dễ thích nghi hơn.', 'Compared with sudden reforms, gradual changes are easier for people to adapt to.', '["In comparison with sudden reforms, gradual changes are easier for people to adapt to.","Compared to sudden reforms, gradual changes are easier for people to adapt to.","Compared with sudden changes, gradual reforms are easier for people to adapt to."]'::jsonb, '["compared with / in comparison with sth = so với (mục 2.6)","sudden reform = cải cách đột ngột; gradual = từng bước; adapt to sth = thích nghi với"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (6, 98, 'Chúng ta càng trì hoãn hành động lâu, cái giá mà thế hệ sau phải trả càng cao.', 'The longer we delay action, the higher the price the next generation will pay.', '["The longer we delay action, the higher the price that the next generation will pay.","The longer we delay taking action, the higher the price the next generation will pay.","The longer we put off action, the higher the price the next generation will pay."]'::jsonb, '["The + comparative …, the + comparative … = càng … càng … (mục 2.6)","delay / put off = trì hoãn; pay the price = trả giá; the next generation = thế hệ sau; high → the higher"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (6, 99, 'Với hầu hết hộ gia đình, lợi ích lâu dài của pin mặt trời lớn hơn bất lợi là chi phí lắp đặt cao.', 'For most households, the long-term advantages of solar panels outweigh the disadvantage of a high installation cost.', '["For most households, the long-term benefits of solar panels outweigh the drawback of a high installation cost.","For most families, the long-term advantages of solar panels outweigh the disadvantage of a high installation cost.","For most households, the long-term advantages of solar panels outweigh the disadvantage of high installation costs."]'::jsonb, '["the advantages outweigh the disadvantages = lợi nhiều hơn hại (mục 2.6)","household = hộ gia đình; solar panel = pin mặt trời; installation cost = chi phí lắp đặt; outweigh = lớn hơn"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (6, 100, 'Các giải pháp tạm thời kém hơn giải pháp bền vững vì vấn đề sẽ sớm quay lại.', 'Quick fixes are inferior to sustainable solutions because the problem soon returns.', '["Quick fixes are inferior to long-term solutions because the problem soon returns.","Temporary solutions are inferior to sustainable ones because the problem soon returns.","Quick fixes are inferior to sustainable solutions because the problem soon comes back."]'::jsonb, '["be superior / inferior to sth = vượt trội / kém hơn (mục 2.6)","quick fix = giải pháp tạm thời; sustainable = bền vững; return / come back = quay lại; be inferior to = kém hơn"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (7, 1, 'Chính phủ nên dùng tiền thuế thu từ thuốc lá để tài trợ cho các chương trình cai thuốc.', 'The government should use tax revenue from cigarettes to fund quit-smoking programmes.', '["The government ought to use tax revenue from cigarettes to fund quit-smoking programmes.","The government should use tax revenue from cigarettes to fund quit-smoking programs.","The government should use the tax revenue from cigarettes to fund quit-smoking programmes.","Governments should use tax revenue from cigarettes to fund quit-smoking programmes."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","tax revenue = tiền thuế thu được; fund = tài trợ, cấp vốn; quit-smoking programme = chương trình cai thuốc lá (Mỹ: program)"]'::jsonb, 'B1', '1. Chính phủ'),
    (7, 2, 'Chỉ chính phủ mới có đủ tiền bạc và quyền lực pháp lý để giải quyết nạn nghèo đói trên quy mô quốc gia.', 'Only the government has enough money and legal power to tackle poverty on a national scale.', '["Only the government has enough money and legal power to address poverty on a national scale.","Only the government has enough money and legal power to combat poverty on a national scale.","Only the government has sufficient money and legal power to tackle poverty on a national scale.","Only the government has enough funds and legal power to tackle poverty on a national scale."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","tackle poverty = giải quyết nạn nghèo đói; legal power = quyền lực pháp lý; on a national scale = trên quy mô quốc gia"]'::jsonb, 'B2', '1. Chính phủ'),
    (7, 3, 'Chính quyền địa phương cần áp dụng biện pháp để cải thiện đường sá và nguồn nước sạch ở nông thôn.', 'Local authorities need to take measures to improve roads and clean water supplies in rural areas.', '["Local authorities need to take steps to improve roads and clean water supplies in rural areas.","Local authorities must take measures to improve roads and clean water supplies in rural areas.","Local governments need to take measures to improve roads and clean water supplies in rural areas.","Local authorities need to take measures to improve roads and clean water supply in rural areas."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","local authorities = chính quyền địa phương; take measures = áp dụng biện pháp; clean water supplies = nguồn nước sạch; rural areas = vùng nông thôn"]'::jsonb, 'B2', '1. Chính phủ'),
    (7, 4, 'Một cách để thay đổi hành vi của người dân là triển khai các chiến dịch nâng cao nhận thức trên truyền hình và mạng xã hội.', 'One way to change people''s behaviour is to launch awareness campaigns on television and social media.', '["One way to change people''s behavior is to launch awareness campaigns on television and social media.","One way to change public behaviour is to launch awareness campaigns on television and social media.","One way to change people''s behaviour is to run awareness campaigns on television and social media.","One way to change people''s behaviour is to launch awareness campaigns on TV and social media."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","behaviour = hành vi (Mỹ: behavior); launch a campaign = phát động chiến dịch; awareness = nhận thức"]'::jsonb, 'B1', '1. Chính phủ'),
    (7, 5, 'Điều thiết yếu là các nhà hoạch định chính sách tham khảo ý kiến chuyên gia để tiền thuế của người dân không bị lãng phí.', 'It is essential that policymakers consult experts so that taxpayers'' money is not wasted.', '["It is essential that policymakers should consult experts so that taxpayers'' money is not wasted.","It is vital that policymakers consult experts so that taxpayers'' money is not wasted.","It''s essential that policymakers consult experts so that taxpayers'' money is not wasted.","It is essential that policy makers consult experts so that taxpayers'' money is not wasted."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","policymaker = nhà hoạch định chính sách; consult experts = tham khảo ý kiến chuyên gia; taxpayers'' money = tiền thuế của dân; sau that: S + (should) + V nguyên mẫu"]'::jsonb, 'B2', '1. Chính phủ'),
    (7, 6, 'Nhà nước phải áp dụng biện pháp để đảm bảo luật mới được thực thi nhất quán trên cả nước.', 'The state must take measures to ensure that new laws are enforced consistently across the country.', '["The state must take steps to ensure that new laws are enforced consistently across the country.","The state must take measures to ensure new laws are enforced consistently across the country.","The state has to take measures to ensure that new laws are enforced consistently across the country.","The state must take measures to make sure that new laws are enforced consistently across the country."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","ensure = đảm bảo; enforce = thực thi (luật); consistently = một cách nhất quán; across the country = trên cả nước"]'::jsonb, 'B2', '1. Chính phủ'),
    (7, 7, 'Đường bộ và đường sắt tốt hơn sẽ góp phần lớn vào việc thu hút đầu tư về các vùng nông thôn.', 'Better roads and railways would go a long way towards attracting investment to rural regions.', '["Better roads and railways would go a long way toward attracting investment to rural regions.","Better roads and railways will go a long way towards attracting investment to rural regions.","Better roads and railways would go a long way towards attracting investment to rural areas.","Better roads and railways would go a long way towards bringing investment to rural regions."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","go a long way towards + V-ing = góp phần lớn vào việc (Mỹ: toward); attract investment = thu hút đầu tư; rural regions = vùng nông thôn"]'::jsonb, 'C1', '1. Chính phủ'),
    (7, 8, 'Đã đến lúc chính phủ phải thay các khuyến nghị tự nguyện bằng những quy định có tính ràng buộc pháp lý.', 'It is high time the government replaced voluntary guidelines with legally binding rules.', '["It is high time that the government replaced voluntary guidelines with legally binding rules.","It''s high time the government replaced voluntary guidelines with legally binding rules.","It is high time the government replaced voluntary guidelines with legally binding regulations.","It is high time governments replaced voluntary guidelines with legally binding rules."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (replaced); voluntary guidelines = khuyến nghị tự nguyện; legally binding = có tính ràng buộc pháp lý"]'::jsonb, 'C1', '1. Chính phủ'),
    (7, 9, 'Một chính sách tốt cần cân bằng giữa vai trò dẫn dắt của chính phủ và sự tham gia của người dân.', 'A good policy needs to strike a balance between government leadership and public participation.', '["A good policy must strike a balance between government leadership and public participation.","A good policy needs to strike a balance between government leadership and citizen participation.","Good policies need to strike a balance between government leadership and public participation.","A good policy needs to strike a balance between the leadership of the government and public participation."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","strike a balance between A and B = cân bằng giữa A và B; leadership = vai trò dẫn dắt; public participation = sự tham gia của người dân"]'::jsonb, 'C1', '1. Chính phủ'),
    (7, 10, 'Người tiêu dùng nên chọn sản phẩm ít bao bì bất cứ khi nào có thể.', 'Consumers should choose products with less packaging whenever possible.', '["Consumers ought to choose products with less packaging whenever possible.","Consumers should choose products with less packaging whenever they can.","Consumers should pick products with less packaging whenever possible.","Consumers should choose products that have less packaging whenever possible."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","consumer = người tiêu dùng; packaging = bao bì; whenever possible = bất cứ khi nào có thể"]'::jsonb, 'B1', '2. Cá nhân'),
    (7, 11, 'Mỗi người có thể áp dụng biện pháp để tiết kiệm điện ở nhà bằng cách tắt các thiết bị không dùng đến.', 'Individuals can take measures to save electricity at home by switching off unused appliances.', '["Individuals can take steps to save electricity at home by switching off unused appliances.","Individuals can take measures to save electricity at home by turning off unused appliances.","People can take measures to save electricity at home by switching off unused appliances.","Individuals can take measures to save electricity at home by switching off appliances that are not in use."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","save electricity = tiết kiệm điện; switch off = tắt; unused appliances = thiết bị không dùng đến"]'::jsonb, 'B2', '2. Cá nhân'),
    (7, 12, 'Điều thiết yếu là mỗi người kiên trì với thói quen mới, ngay cả khi lúc đầu chúng có vẻ khó khăn.', 'It is vital that each person stick to new habits, even if they seem difficult at first.', '["It is vital that each person should stick to new habits, even if they seem difficult at first.","It is essential that each person stick to new habits, even if they seem difficult at first.","It is vital that everyone stick to new habits, even if they seem difficult at first.","It''s vital that each person stick to new habits, even if they seem difficult at first."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","stick to = kiên trì với; at first = lúc đầu; sau that: S + (should) + V nguyên mẫu (stick, không thêm s)"]'::jsonb, 'B2', '2. Cá nhân'),
    (7, 13, 'Mỗi người có thể giải quyết vấn đề lãng phí thực phẩm bằng cách chỉ mua những gì mình cần.', 'Each person can tackle the problem of food waste by buying only what they need.', '["Each person can address the problem of food waste by buying only what they need.","Each person can tackle the problem of food waste by only buying what they need.","Everyone can tackle the problem of food waste by buying only what they need.","Each person can tackle the issue of food waste by buying only what they need."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","tackle the problem of = giải quyết vấn đề; food waste = lãng phí thực phẩm"]'::jsonb, 'B2', '2. Cá nhân'),
    (7, 14, 'Một cách để truyền cảm hứng cho người khác là làm gương bằng những hành động nhỏ hằng ngày.', 'One way to inspire others is to set a good example through small daily actions.', '["One way to inspire other people is to set a good example through small daily actions.","One way to inspire others is to set a good example through small everyday actions.","One way to inspire others is to set an example through small daily actions.","One way to inspire others is to set a good example with small daily actions."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","inspire = truyền cảm hứng; set a good example = làm gương; daily actions = hành động hằng ngày"]'::jsonb, 'B1', '2. Cá nhân'),
    (7, 15, 'Mang theo bình nước cá nhân mỗi ngày có thể góp phần lớn vào việc giảm rác thải nhựa.', 'Carrying a reusable water bottle every day can go a long way towards reducing plastic waste.', '["Carrying a reusable water bottle every day can go a long way toward reducing plastic waste.","Carrying a reusable water bottle every day can go a long way towards cutting plastic waste.","Carrying your own water bottle every day can go a long way towards reducing plastic waste.","Carrying a reusable bottle every day can go a long way towards reducing plastic waste."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","reusable water bottle = bình nước dùng nhiều lần; plastic waste = rác thải nhựa; go a long way towards + V-ing = góp phần lớn vào việc"]'::jsonb, 'C1', '2. Cá nhân'),
    (7, 16, 'Mọi người nên đọc kỹ nhãn mác và đánh giá sản phẩm trước khi mua hàng.', 'People should read labels and product reviews carefully before making a purchase.', '["People ought to read labels and product reviews carefully before making a purchase.","People should carefully read labels and product reviews before making a purchase.","People should read labels and product reviews carefully before buying anything.","People should read product labels and reviews carefully before making a purchase."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","label = nhãn mác; product review = đánh giá sản phẩm; make a purchase = mua hàng"]'::jsonb, 'B1', '2. Cá nhân'),
    (7, 17, 'Đã đến lúc người dân bình thường phải lên tiếng và gây áp lực buộc chính quyền hành động.', 'It is high time ordinary citizens spoke up and put pressure on the authorities to act.', '["It is high time that ordinary citizens spoke up and put pressure on the authorities to act.","It''s high time ordinary citizens spoke up and put pressure on the authorities to act.","It is high time ordinary people spoke up and put pressure on the authorities to act.","It is high time ordinary citizens spoke out and put pressure on the authorities to act."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (spoke, put); speak up = lên tiếng; put pressure on = gây áp lực lên"]'::jsonb, 'C1', '2. Cá nhân'),
    (7, 18, 'Người tiêu dùng cần cân bằng giữa giá rẻ và việc mua sắm có trách nhiệm.', 'Consumers need to strike a balance between low prices and responsible shopping.', '["Consumers must strike a balance between low prices and responsible shopping.","Consumers have to strike a balance between low prices and responsible shopping.","Consumers need to strike a balance between low prices and ethical shopping.","Shoppers need to strike a balance between low prices and responsible shopping."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","strike a balance between A and B = cân bằng giữa A và B; low prices = giá rẻ; responsible shopping = mua sắm có trách nhiệm"]'::jsonb, 'C1', '2. Cá nhân'),
    (7, 19, 'Giáo viên nên được bồi dưỡng thường xuyên để theo kịp các phương pháp giảng dạy mới.', 'Teachers should receive regular training so that they can keep up with new teaching methods.', '["Teachers ought to receive regular training so that they can keep up with new teaching methods.","Teachers should receive regular training so they can keep up with new teaching methods.","Teachers should be given regular training so that they can keep up with new teaching methods.","Teachers should receive regular training so that they can keep up with modern teaching methods."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","receive training = được đào tạo, bồi dưỡng; keep up with = theo kịp; teaching methods = phương pháp giảng dạy"]'::jsonb, 'B1', '3. Trường học'),
    (7, 20, 'Các trường đại học phải áp dụng biện pháp để giáo dục đại học trở nên vừa túi tiền với sinh viên từ các gia đình nghèo.', 'Universities must take measures to make higher education affordable for students from poor families.', '["Universities must take steps to make higher education affordable for students from poor families.","Universities need to take measures to make higher education affordable for students from poor families.","Universities must take measures to make higher education affordable for students from low-income families.","Universities must take measures to make university education affordable for students from poor families."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","affordable = vừa túi tiền; higher education = giáo dục đại học; low-income = thu nhập thấp"]'::jsonb, 'B2', '3. Trường học'),
    (7, 21, 'Một cách để chuẩn bị cho sinh viên đi làm là cho họ đi thực tập vào năm cuối.', 'One way to prepare students for the workplace is to offer them internships in their final year.', '["One way to prepare students for the workplace is to offer them internships during their final year.","One way to prepare students for work is to offer them internships in their final year.","One way to prepare students for the workplace is to give them internships in their final year.","One way to prepare students for working life is to offer them internships in their final year."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","prepare sb for = chuẩn bị cho ai; workplace = môi trường làm việc; internship = kỳ thực tập; final year = năm cuối"]'::jsonb, 'B1', '3. Trường học'),
    (7, 22, 'Điều thiết yếu là nhà trường dạy trẻ biết tự đánh giá thông tin trên mạng.', 'It is vital that schools teach children to evaluate online information for themselves.', '["It is vital that schools should teach children to evaluate online information for themselves.","It is essential that schools teach children to evaluate online information for themselves.","It is vital that schools teach children to judge online information for themselves.","It''s vital that schools teach children to evaluate online information for themselves."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","evaluate = đánh giá; online information = thông tin trên mạng; for themselves = tự mình"]'::jsonb, 'B2', '3. Trường học'),
    (7, 23, 'Nhà trường có thể giải quyết vấn đề học sinh chọn sai ngành bằng cách hướng nghiệp từ sớm.', 'Schools can tackle the problem of students choosing the wrong major by offering early career guidance.', '["Schools can address the problem of students choosing the wrong major by offering early career guidance.","Schools can tackle the issue of students choosing the wrong major by offering early career guidance.","Schools can tackle the problem of students choosing the wrong major by providing early career guidance.","Schools can tackle the problem of students choosing the wrong major by offering career guidance early."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","choose the wrong major = chọn sai ngành; career guidance = hướng nghiệp; early = sớm"]'::jsonb, 'B2', '3. Trường học'),
    (7, 24, 'Một cách để giảm áp lực thi cử là đánh giá học sinh qua các dự án chứ không chỉ qua bài kiểm tra.', 'One way to reduce exam pressure is to assess students through projects, not just tests.', '["One way to reduce exam pressure is to assess students through projects as well as tests.","One way to ease exam pressure is to assess students through projects, not just tests.","One way to reduce exam stress is to assess students through projects, not just tests.","One way to reduce exam pressure is to assess students through projects, not only tests."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","exam pressure = áp lực thi cử; assess = đánh giá; project = dự án; not just = chứ không chỉ"]'::jsonb, 'B1', '3. Trường học'),
    (7, 25, 'Các tiết học về tài chính cá nhân sẽ góp phần lớn vào việc giúp người trẻ tránh rơi vào nợ nần.', 'Lessons in personal finance would go a long way towards keeping young adults out of debt.', '["Lessons in personal finance would go a long way toward keeping young adults out of debt.","Lessons on personal finance would go a long way towards keeping young adults out of debt.","Personal finance lessons would go a long way towards keeping young adults out of debt.","Lessons in personal finance would go a long way towards keeping young people out of debt."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","personal finance = tài chính cá nhân; keep sb out of debt = giúp ai tránh nợ nần; young adults = người trẻ"]'::jsonb, 'C1', '3. Trường học'),
    (7, 26, 'Đã đến lúc các trường đại học phải từ bỏ lối học thuộc lòng và tập trung vào kỹ năng thực hành.', 'It is high time universities moved away from rote learning and focused on practical skills.', '["It is high time that universities moved away from rote learning and focused on practical skills.","It''s high time universities moved away from rote learning and focused on practical skills.","It is high time universities abandoned rote learning and focused on practical skills.","It is high time universities moved away from rote learning and concentrated on practical skills."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (moved, focused); move away from = từ bỏ; rote learning = học thuộc lòng"]'::jsonb, 'C1', '3. Trường học'),
    (7, 27, 'Nhà trường phải cân bằng giữa kết quả thi cử trước mắt và sự phát triển lâu dài của học sinh.', 'Schools must strike a balance between short-term exam results and students'' long-term development.', '["Schools need to strike a balance between short-term exam results and students'' long-term development.","Schools must strike a balance between short-term exam results and the long-term development of students.","Schools have to strike a balance between short-term exam results and students'' long-term development.","Schools must strike a balance between short-term exam results and pupils'' long-term development."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","strike a balance between A and B = cân bằng giữa A và B; short-term = trước mắt; long-term development = sự phát triển lâu dài"]'::jsonb, 'C1', '3. Trường học'),
    (7, 28, 'Điều thiết yếu là cha mẹ kiềm chế cơn nóng giận của mình, vì trẻ học bằng cách quan sát người lớn xung quanh.', 'It is vital that parents control their own temper, as children learn by watching the adults around them.', '["It is vital that parents should control their own temper, as children learn by watching the adults around them.","It is essential that parents control their own temper, as children learn by watching the adults around them.","It is vital that parents control their temper, as children learn by watching the adults around them.","It is vital that parents control their own temper, since children learn by watching the adults around them."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","control your temper = kiềm chế nóng giận; learn by watching = học bằng cách quan sát; sau that: S + (should) + V nguyên mẫu"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (7, 29, 'Cha mẹ nên giao cho con những việc nhà đơn giản để dạy chúng tinh thần trách nhiệm.', 'Parents should give their children simple household chores to teach them responsibility.', '["Parents ought to give their children simple household chores to teach them responsibility.","Parents should give their children simple chores to teach them responsibility.","Parents should give children simple household chores to teach them responsibility.","Parents should give their children simple household chores to teach them a sense of responsibility."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","household chores = việc nhà; responsibility = tinh thần trách nhiệm"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (7, 30, 'Nhiều gia đình giải quyết vấn đề trông con bằng cách nhờ ông bà chăm sóc các cháu.', 'Many families address the problem of childcare by asking grandparents to look after the children.', '["Many families tackle the problem of childcare by asking grandparents to look after the children.","Many families address the issue of childcare by asking grandparents to look after the children.","Many families address the problem of childcare by asking the grandparents to look after the children.","Many families address the problem of childcare by asking grandparents to look after the kids."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","address the problem of = giải quyết vấn đề; childcare = việc trông trẻ; look after = chăm sóc"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (7, 31, 'Một cách để giảm thời gian dùng màn hình của trẻ là không để điện thoại trong phòng ngủ vào ban đêm.', 'One way to reduce children''s screen time is to keep phones out of their bedrooms at night.', '["One way to cut children''s screen time is to keep phones out of their bedrooms at night.","One way to reduce children''s screen time is to keep phones out of the bedroom at night.","One way to limit children''s screen time is to keep phones out of their bedrooms at night.","One way to reduce children''s screen time is to keep mobile phones out of their bedrooms at night."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","screen time = thời gian dùng màn hình; keep sth out of = không để cái gì ở (nơi nào)"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (7, 32, 'Cha mẹ có thể áp dụng biện pháp để bảo vệ con khỏi nội dung độc hại trên mạng bằng cách dùng tính năng kiểm soát của phụ huynh.', 'Parents can take measures to protect their children from harmful online content by using parental controls.', '["Parents can take steps to protect their children from harmful online content by using parental controls.","Parents can take measures to protect their children from harmful content online by using parental controls.","Parents can take measures to protect their kids from harmful online content by using parental controls.","Parents can take measures to protect children from harmful online content by using parental controls."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","protect sb from = bảo vệ ai khỏi; harmful content = nội dung độc hại; parental controls = tính năng kiểm soát của phụ huynh"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (7, 33, 'Cùng đọc truyện trước giờ ngủ có thể góp phần lớn vào việc xây dựng sự gắn kết gần gũi giữa cha mẹ và con cái.', 'Reading bedtime stories together can go a long way towards building a close bond between parents and children.', '["Reading bedtime stories together can go a long way toward building a close bond between parents and children.","Reading bedtime stories together can go a long way towards creating a close bond between parents and children.","Reading bedtime stories together can go a long way towards building a strong bond between parents and children.","Reading bedtime stories together can go a long way towards building a close bond between parents and their children."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","bedtime story = truyện kể trước giờ ngủ; build a close bond = xây dựng sự gắn kết gần gũi"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (7, 34, 'Các gia đình cần đối phó với chứng nghiện màn hình trước khi nó gây hại cho sức khỏe và việc học của con.', 'Families need to tackle screen addiction before it harms their children''s health and schoolwork.', '["Families need to address screen addiction before it harms their children''s health and schoolwork.","Families need to combat screen addiction before it harms their children''s health and schoolwork.","Families need to tackle screen addiction before it damages their children''s health and schoolwork.","Families need to tackle the problem of screen addiction before it harms their children''s health and schoolwork."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","tackle = đối phó, giải quyết; screen addiction = chứng nghiện màn hình; schoolwork = việc học"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (7, 35, 'Đã đến lúc các bậc cha mẹ đi làm phải cất điện thoại đi trong bữa ăn gia đình.', 'It is high time working parents put away their phones during family meals.', '["It is high time working parents put their phones away during family meals.","It is high time that working parents put away their phones during family meals.","It''s high time working parents put away their phones during family meals.","It is high time working parents put away their phones at family meals."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (put); put away = cất đi; family meals = bữa ăn gia đình"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (7, 36, 'Cha mẹ phải cân bằng giữa việc cho con tự do và đặt ra quy tắc rõ ràng.', 'Parents must strike a balance between giving children freedom and setting clear rules.', '["Parents need to strike a balance between giving children freedom and setting clear rules.","Parents must strike a balance between giving their children freedom and setting clear rules.","Parents have to strike a balance between giving children freedom and setting clear rules."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","strike a balance between A and B = cân bằng giữa A và B; freedom = sự tự do; set clear rules = đặt ra quy tắc rõ ràng"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (7, 37, 'Các công ty lớn nên dành một phần lợi nhuận cho những dự án mang lại lợi ích cho cộng đồng nghèo.', 'Large firms should spend part of their profits on projects that benefit poor communities.', '["Large firms ought to spend part of their profits on projects that benefit poor communities.","Large companies should spend part of their profits on projects that benefit poor communities.","Large firms should spend some of their profits on projects that benefit poor communities.","Large firms should spend part of their profits on projects which benefit poor communities."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","profits = lợi nhuận; benefit = mang lại lợi ích cho; poor communities = cộng đồng nghèo"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (7, 38, 'Các nhà sản xuất phải áp dụng biện pháp để xử lý nước thải trước khi nó chảy ra sông.', 'Manufacturers must take measures to treat waste water before it flows into rivers.', '["Manufacturers must take steps to treat waste water before it flows into rivers.","Manufacturers must take measures to treat wastewater before it flows into rivers.","Manufacturers have to take measures to treat waste water before it flows into rivers.","Manufacturers must take measures to treat waste water before it flows into the rivers."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","manufacturer = nhà sản xuất; treat waste water = xử lý nước thải; flow into = chảy vào"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (7, 39, 'Một cách để giữ chân nhân viên giỏi là mang đến cho họ cơ hội thăng tiến rõ ràng.', 'One way to retain talented staff is to offer them clear opportunities for promotion.', '["One way to keep talented staff is to offer them clear opportunities for promotion.","One way to retain talented employees is to offer them clear opportunities for promotion.","One way to retain talented staff is to give them clear opportunities for promotion.","One way to retain talented staff is to offer them clear promotion opportunities."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","retain = giữ chân; talented staff = nhân viên giỏi; opportunities for promotion = cơ hội thăng tiến"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (7, 40, 'Điều thiết yếu là các công ty cho nhân viên khám sức khỏe định kỳ, vì lợi nhuận phụ thuộc vào đội ngũ lao động khỏe mạnh.', 'It is essential that companies offer their staff regular health checks, as profits depend on a healthy workforce.', '["It is essential that companies should offer their staff regular health checks, as profits depend on a healthy workforce.","It is vital that companies offer their staff regular health checks, as profits depend on a healthy workforce.","It is essential that companies offer their employees regular health checks, as profits depend on a healthy workforce.","It''s essential that companies offer their staff regular health checks, as profits depend on a healthy workforce."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","health check = khám sức khỏe; depend on = phụ thuộc vào; workforce = đội ngũ lao động; sau that: S + (should) + V nguyên mẫu"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (7, 41, 'Các hãng thời trang phải giải quyết vấn đề điều kiện làm việc thiếu an toàn trong nhà máy của họ.', 'Clothing brands must address the problem of unsafe working conditions in their factories.', '["Clothing brands must tackle the problem of unsafe working conditions in their factories.","Clothing brands must address the issue of unsafe working conditions in their factories.","Fashion brands must address the problem of unsafe working conditions in their factories.","Clothing brands have to address the problem of unsafe working conditions in their factories."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","address the problem of = giải quyết vấn đề; unsafe working conditions = điều kiện làm việc thiếu an toàn; clothing brand = hãng thời trang"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (7, 42, 'Chuyển sang bao bì có thể tái chế sẽ góp phần lớn vào việc nâng cao uy tín của thương hiệu.', 'Switching to recyclable packaging would go a long way towards improving a brand''s reputation.', '["Switching to recyclable packaging would go a long way toward improving a brand''s reputation.","Switching to recyclable packaging would go a long way towards boosting a brand''s reputation.","Switching to recyclable packaging will go a long way towards improving a brand''s reputation.","Moving to recyclable packaging would go a long way towards improving a brand''s reputation."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","switch to = chuyển sang; recyclable packaging = bao bì có thể tái chế; reputation = uy tín"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (7, 43, 'Đã đến lúc các doanh nghiệp phải thôi đặt lợi nhuận trước mắt lên trên sức khỏe của người lao động.', 'It is high time businesses stopped putting short-term profit before their workers'' health.', '["It is high time that businesses stopped putting short-term profit before their workers'' health.","It''s high time businesses stopped putting short-term profit before their workers'' health.","It is high time businesses stopped putting short-term profit ahead of their workers'' health.","It is high time businesses stopped putting short-term profits before their workers'' health."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (stopped); put A before B = đặt A lên trên B; short-term profit = lợi nhuận trước mắt"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (7, 44, 'Doanh nghiệp phải cân bằng giữa việc theo đuổi lợi nhuận và thực hiện trách nhiệm xã hội.', 'Businesses must strike a balance between pursuing profit and meeting their social responsibilities.', '["Businesses need to strike a balance between pursuing profit and meeting their social responsibilities.","Companies must strike a balance between pursuing profit and meeting their social responsibilities.","Businesses must strike a balance between pursuing profits and meeting their social responsibilities.","Businesses have to strike a balance between pursuing profit and meeting their social responsibilities."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","pursue profit = theo đuổi lợi nhuận; meet responsibilities = thực hiện trách nhiệm; social responsibility = trách nhiệm xã hội"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (7, 45, 'Nơi làm việc nên cung cấp dịch vụ tư vấn tâm lý miễn phí cho những nhân viên bị căng thẳng.', 'Workplaces should offer free counselling to employees who suffer from stress.', '["Workplaces ought to offer free counselling to employees who suffer from stress.","Workplaces should offer free counseling to employees who suffer from stress.","Workplaces should provide free counselling to employees who suffer from stress.","Workplaces should offer free counselling to staff who suffer from stress."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","counselling = tư vấn tâm lý (Mỹ: counseling); suffer from stress = bị căng thẳng"]'::jsonb, 'B1', '6. Sức khỏe'),
    (7, 46, 'Một cách để giữ sức khỏe khi làm công việc văn phòng là đứng dậy đi lại mỗi giờ.', 'One way to stay healthy in an office job is to stand up and walk around every hour.', '["One way to stay healthy in an office job is to get up and walk around every hour.","One way to keep healthy in an office job is to stand up and walk around every hour.","One way to stay healthy in an office job is to stand up and move around every hour.","One way to keep fit in an office job is to stand up and walk around every hour."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","stay healthy = giữ sức khỏe; office job = công việc văn phòng; walk around = đi lại"]'::jsonb, 'B1', '6. Sức khỏe'),
    (7, 47, 'Các bệnh viện phải áp dụng biện pháp để rút ngắn thời gian chờ đợi cho bệnh nhân cao tuổi.', 'Hospitals must take measures to shorten waiting times for elderly patients.', '["Hospitals must take steps to shorten waiting times for elderly patients.","Hospitals must take measures to reduce waiting times for elderly patients.","Hospitals must take measures to shorten waiting times for older patients.","Hospitals need to take measures to shorten waiting times for elderly patients."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","shorten = rút ngắn; waiting times = thời gian chờ; elderly patients = bệnh nhân cao tuổi"]'::jsonb, 'B2', '6. Sức khỏe'),
    (7, 48, 'Chính phủ và nhà trường phải phối hợp để đối phó với tình trạng béo phì ở trẻ em.', 'Governments and schools must work together to combat childhood obesity.', '["Governments and schools must work together to tackle childhood obesity.","Governments and schools must work together to combat obesity in children.","Governments and schools must cooperate to combat childhood obesity.","The government and schools must work together to combat childhood obesity."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","combat = đối phó, chống lại; childhood obesity = béo phì ở trẻ em; work together = phối hợp"]'::jsonb, 'B2', '6. Sức khỏe'),
    (7, 49, 'Điều thiết yếu là bác sĩ coi sức khỏe tinh thần và sức khỏe thể chất quan trọng như nhau.', 'It is vital that doctors treat mental and physical health as equally important.', '["It is vital that doctors should treat mental and physical health as equally important.","It is essential that doctors treat mental and physical health as equally important.","It is vital that doctors treat physical and mental health as equally important.","It''s vital that doctors treat mental and physical health as equally important."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","mental health = sức khỏe tinh thần; physical health = sức khỏe thể chất; treat sth as = coi cái gì là; equally important = quan trọng như nhau"]'::jsonb, 'B2', '6. Sức khỏe'),
    (7, 50, 'Tầm soát tiểu đường sớm sẽ góp phần lớn vào việc giảm số ca nhập viện.', 'Early screening for diabetes would go a long way towards reducing hospital admissions.', '["Early screening for diabetes would go a long way toward reducing hospital admissions.","Early screening for diabetes would go a long way towards cutting hospital admissions.","Early diabetes screening would go a long way towards reducing hospital admissions.","Early screening for diabetes would go a long way towards reducing the number of hospital admissions."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","screening = tầm soát; diabetes = bệnh tiểu đường; hospital admissions = số ca nhập viện"]'::jsonb, 'C1', '6. Sức khỏe'),
    (7, 51, 'Đã đến lúc hệ thống y tế phải tập trung vào phòng bệnh thay vì chỉ chữa bệnh.', 'It is high time health systems focused on preventing disease rather than just treating it.', '["It is high time that health systems focused on preventing disease rather than just treating it.","It''s high time health systems focused on preventing disease rather than just treating it.","It is high time healthcare systems focused on preventing disease rather than just treating it.","It is high time health systems focused on preventing disease rather than just curing it."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (focused); prevent disease = phòng bệnh; rather than = thay vì"]'::jsonb, 'C1', '6. Sức khỏe'),
    (7, 52, 'Mọi người cần cân bằng giữa việc thưởng thức món ăn yêu thích và ăn uống lành mạnh.', 'People need to strike a balance between enjoying their favourite foods and eating healthily.', '["People need to strike a balance between enjoying their favorite foods and eating healthily.","People must strike a balance between enjoying their favourite foods and eating healthily.","People need to strike a balance between enjoying their favourite food and eating healthily.","People need to strike a balance between enjoying their favourite foods and eating a healthy diet."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","favourite = yêu thích (Mỹ: favorite); eat healthily = ăn uống lành mạnh"]'::jsonb, 'C1', '6. Sức khỏe'),
    (7, 53, 'Chính phủ nên dành ưu đãi thuế cho các công ty tạo việc làm ở những vùng nghèo hơn.', 'The government should offer tax incentives to companies that create jobs in poorer regions.', '["The government ought to offer tax incentives to companies that create jobs in poorer regions.","The government should give tax incentives to companies that create jobs in poorer regions.","The government should offer tax breaks to companies that create jobs in poorer regions.","Governments should offer tax incentives to companies that create jobs in poorer regions."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","tax incentives / tax breaks = ưu đãi thuế; create jobs = tạo việc làm; poorer regions = vùng nghèo hơn"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (7, 54, 'Một cách để xoay xở trước chi phí sinh hoạt tăng cao là lập kế hoạch chi tiêu hằng tháng cho gia đình.', 'One way to cope with the rising cost of living is to plan a monthly family budget.', '["One way to cope with the rising cost of living is to make a monthly family budget.","One way to deal with the rising cost of living is to plan a monthly family budget.","One way to cope with rising living costs is to plan a monthly family budget.","One way to cope with the rising cost of living is to plan a monthly household budget."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","cope with = xoay xở, đương đầu với; cost of living = chi phí sinh hoạt; budget = kế hoạch chi tiêu"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (7, 55, 'Các quốc gia phải áp dụng biện pháp để thu hẹp khoảng cách kỹ năng đang làm chậm tăng trưởng kinh tế.', 'Countries must take measures to close the skills gap that is slowing down economic growth.', '["Countries must take steps to close the skills gap that is slowing down economic growth.","Countries must take measures to close the skills gap that is slowing economic growth.","Countries need to take measures to close the skills gap that is slowing down economic growth.","Countries must take measures to narrow the skills gap that is slowing down economic growth."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","close / narrow the skills gap = thu hẹp khoảng cách kỹ năng; slow down = làm chậm lại; economic growth = tăng trưởng kinh tế"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (7, 56, 'Chính phủ có thể giải quyết khoảng cách giàu nghèo ngày càng lớn bằng một hệ thống thuế công bằng hơn.', 'Governments can address the widening gap between rich and poor through a fairer tax system.', '["Governments can tackle the widening gap between rich and poor through a fairer tax system.","Governments can address the widening gap between the rich and the poor through a fairer tax system.","Governments can address the growing gap between rich and poor through a fairer tax system.","The government can address the widening gap between rich and poor through a fairer tax system."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","address = giải quyết; widening gap between rich and poor = khoảng cách giàu nghèo ngày càng lớn; tax system = hệ thống thuế"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (7, 57, 'Điều thiết yếu là chính phủ kiểm soát được nợ công khi đầu tư vào các dự án lớn.', 'It is vital that the government keep public debt under control when investing in large projects.', '["It is vital that the government should keep public debt under control when investing in large projects.","It is essential that the government keep public debt under control when investing in large projects.","It is vital that governments keep public debt under control when investing in large projects.","It''s vital that the government keep public debt under control when investing in large projects."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","public debt = nợ công; keep sth under control = kiểm soát; sau that: S + (should) + V nguyên mẫu (keep, không thêm s)"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (7, 58, 'Phát triển du lịch địa phương sẽ góp phần lớn vào việc tạo việc làm cho người trẻ ở nông thôn.', 'Developing local tourism would go a long way towards creating jobs for young people in the countryside.', '["Developing local tourism would go a long way toward creating jobs for young people in the countryside.","Developing local tourism will go a long way towards creating jobs for young people in the countryside.","Developing local tourism would go a long way towards creating jobs for young people in rural areas.","Promoting local tourism would go a long way towards creating jobs for young people in the countryside."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","local tourism = du lịch địa phương; create jobs = tạo việc làm; countryside = vùng nông thôn"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (7, 59, 'Đã đến lúc các nhà hoạch định chính sách phải ưu tiên tăng trưởng bền vững hơn lợi nhuận trước mắt.', 'It is high time policymakers prioritised sustainable growth over short-term profits.', '["It is high time policymakers prioritized sustainable growth over short-term profits.","It is high time that policymakers prioritised sustainable growth over short-term profits.","It''s high time policymakers prioritised sustainable growth over short-term profits.","It is high time policymakers prioritised sustainable growth over quick profits."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (prioritised, Mỹ: prioritized); prioritise A over B = ưu tiên A hơn B; sustainable growth = tăng trưởng bền vững"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (7, 60, 'Các quốc gia phải cân bằng giữa việc thu hút đầu tư nước ngoài và bảo vệ doanh nghiệp trong nước.', 'Countries must strike a balance between attracting foreign investment and protecting domestic businesses.', '["Countries need to strike a balance between attracting foreign investment and protecting domestic businesses.","Countries must strike a balance between attracting foreign investment and protecting local businesses.","Countries must strike a balance between attracting foreign investment and protecting domestic firms.","Countries have to strike a balance between attracting foreign investment and protecting domestic businesses."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","attract foreign investment = thu hút đầu tư nước ngoài; domestic businesses = doanh nghiệp trong nước"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (7, 61, 'Chính quyền địa phương nên mở các lớp học ngôn ngữ miễn phí cho người nhập cư mới đến.', 'Local councils should run free language classes for newly arrived immigrants.', '["Local councils ought to run free language classes for newly arrived immigrants.","Local councils should offer free language classes for newly arrived immigrants.","Local authorities should run free language classes for newly arrived immigrants.","Local councils should run free language courses for newly arrived immigrants."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","local council = chính quyền địa phương; run classes = mở lớp; newly arrived immigrants = người nhập cư mới đến"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (7, 62, 'Một cách để gắn kết hàng xóm với nhau là tổ chức lễ hội đường phố thường xuyên.', 'One way to bring neighbours closer together is to organise regular street festivals.', '["One way to bring neighbors closer together is to organize regular street festivals.","One way to bring neighbours closer together is to organize regular street festivals.","One way to bring neighbours closer is to organise regular street festivals.","One way to bring neighbours closer together is to hold regular street festivals."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","bring sb closer together = gắn kết ai với nhau; neighbour = hàng xóm (Mỹ: neighbor); organise = tổ chức (Mỹ: organize)"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (7, 63, 'Cư dân có thể áp dụng biện pháp để khu vực mình sống an toàn hơn bằng cách lập nhóm tuần tra khu phố.', 'Residents can take steps to make their area safer by forming a neighbourhood watch group.', '["Residents can take measures to make their area safer by forming a neighbourhood watch group.","Residents can take steps to make their area safer by forming a neighborhood watch group.","Residents can take steps to make their area safer by setting up a neighbourhood watch group.","Local residents can take steps to make their area safer by forming a neighbourhood watch group."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","take steps = áp dụng biện pháp; neighbourhood watch group = nhóm tuần tra khu phố (Mỹ: neighborhood); form / set up = thành lập"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (7, 64, 'Cộng đồng có thể giải quyết tình trạng cô đơn ở người cao tuổi bằng cách tổ chức thăm hỏi tại nhà thường xuyên.', 'Communities can tackle loneliness among older people by organising regular home visits.', '["Communities can address loneliness among older people by organising regular home visits.","Communities can combat loneliness among older people by organising regular home visits.","Communities can tackle loneliness among older people by organizing regular home visits.","Communities can tackle loneliness among the elderly by organising regular home visits."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","tackle loneliness = giải quyết tình trạng cô đơn; older people / the elderly = người cao tuổi; home visit = thăm hỏi tại nhà"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (7, 65, 'Điều thiết yếu là các tòa nhà công cộng phải thuận tiện cho người đi xe lăn.', 'It is essential that public buildings be accessible to wheelchair users.', '["It is essential that public buildings should be accessible to wheelchair users.","It is vital that public buildings be accessible to wheelchair users.","It is essential that public buildings be accessible to people in wheelchairs.","It''s essential that public buildings be accessible to wheelchair users."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","accessible = dễ tiếp cận, thuận tiện; wheelchair user = người đi xe lăn; sau that: S + (should) + be"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (7, 66, 'Các chương trình nhà ở giá rẻ sẽ góp phần lớn vào việc giảm tình trạng vô gia cư ở các thành phố lớn.', 'Affordable housing schemes would go a long way towards reducing homelessness in big cities.', '["Affordable housing schemes would go a long way toward reducing homelessness in big cities.","Affordable housing programmes would go a long way towards reducing homelessness in big cities.","Affordable housing schemes would go a long way towards cutting homelessness in big cities.","Affordable housing schemes will go a long way towards reducing homelessness in big cities."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","affordable housing = nhà ở giá rẻ; scheme = chương trình; homelessness = tình trạng vô gia cư"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (7, 67, 'Đã đến lúc người trẻ phải tham gia tích cực hơn vào đời sống cộng đồng.', 'It is high time young people took a more active part in community life.', '["It is high time that young people took a more active part in community life.","It''s high time young people took a more active part in community life.","It is high time young people played a more active part in community life.","It is high time young people took a more active role in community life."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (took); take an active part in = tham gia tích cực vào; community life = đời sống cộng đồng"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (7, 68, 'Các nhà quy hoạch đô thị cần cân bằng giữa nhà ở tư nhân và không gian sinh hoạt chung của cộng đồng.', 'Urban planners need to strike a balance between private housing and shared community spaces.', '["Urban planners must strike a balance between private housing and shared community spaces.","City planners need to strike a balance between private housing and shared community spaces.","Urban planners need to strike a balance between private housing and shared public spaces.","Urban planners have to strike a balance between private housing and shared community spaces."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","urban planner = nhà quy hoạch đô thị; private housing = nhà ở tư nhân; shared community spaces = không gian sinh hoạt chung"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (7, 69, 'Các nhà máy gây ô nhiễm sông ngòi nên tự chi trả chi phí làm sạch.', 'Factories that pollute rivers should pay for the clean-up themselves.', '["Factories that pollute rivers ought to pay for the clean-up themselves.","Factories which pollute rivers should pay for the clean-up themselves.","Factories that pollute rivers should pay for the cleanup themselves.","Factories that pollute rivers should cover the cost of the clean-up themselves."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","pollute = gây ô nhiễm; pay for = chi trả cho; clean-up = việc làm sạch"]'::jsonb, 'B1', '9. Môi trường'),
    (7, 70, 'Một cách để bảo vệ môi trường sống của động vật hoang dã là trồng lại rừng trên những vùng đất đã bị khai phá.', 'One way to protect wildlife habitats is to replant forests on land that has been cleared.', '["One way to protect wildlife habitats is to replant forests on cleared land.","One way to protect the habitats of wild animals is to replant forests on land that has been cleared.","One way to protect wildlife habitats is to restore forests on land that has been cleared.","One way to protect wildlife habitats is to plant new forests on land that has been cleared."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","wildlife habitat = môi trường sống của động vật hoang dã; replant forests = trồng lại rừng; cleared land = đất đã bị khai phá"]'::jsonb, 'B1', '9. Môi trường'),
    (7, 71, 'Chính quyền thành phố phải áp dụng biện pháp để hạn chế số lượng xe cá nhân đi vào trung tâm thành phố.', 'City authorities must take measures to limit the number of private cars entering the city centre.', '["City authorities must take steps to limit the number of private cars entering the city centre.","City authorities must take measures to limit the number of private cars entering the city center.","City authorities must take measures to reduce the number of private cars entering the city centre.","City authorities need to take measures to limit the number of private cars entering the city centre."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","limit = hạn chế; private cars = xe cá nhân; city centre = trung tâm thành phố (Mỹ: center)"]'::jsonb, 'B2', '9. Môi trường'),
    (7, 72, 'Mọi quốc gia phải giải quyết vấn đề tiêu dùng quá mức trước khi tài nguyên thiên nhiên cạn kiệt.', 'Every nation must address the issue of overconsumption before natural resources run out.', '["Every nation must tackle the issue of overconsumption before natural resources run out.","Every nation must address the problem of overconsumption before natural resources run out.","Every country must address the issue of overconsumption before natural resources run out.","All nations must address the issue of overconsumption before natural resources run out."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","address the issue of = giải quyết vấn đề; overconsumption = tiêu dùng quá mức; run out = cạn kiệt"]'::jsonb, 'B2', '9. Môi trường'),
    (7, 73, 'Điều thiết yếu là chúng ta phải hành động ngay, trước khi tổn hại đối với môi trường trở nên không thể đảo ngược.', 'It is vital that we act now, before the damage to the environment becomes irreversible.', '["It is vital that we should act now, before the damage to the environment becomes irreversible.","It is essential that we act now, before the damage to the environment becomes irreversible.","It''s vital that we act now, before the damage to the environment becomes irreversible.","It is vital that we take action now, before the damage to the environment becomes irreversible."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","act now / take action now = hành động ngay; damage = tổn hại; irreversible = không thể đảo ngược"]'::jsonb, 'B2', '9. Môi trường'),
    (7, 74, 'Dịch vụ xe buýt giá rẻ và đáng tin cậy sẽ góp phần lớn vào việc cắt giảm khí thải từ giao thông.', 'Affordable and reliable bus services would go a long way towards cutting emissions from traffic.', '["Affordable and reliable bus services would go a long way toward cutting emissions from traffic.","Affordable and reliable bus services would go a long way towards reducing emissions from traffic.","Affordable and reliable bus services would go a long way towards cutting traffic emissions.","Cheap and reliable bus services would go a long way towards cutting emissions from traffic."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","affordable = giá rẻ, vừa túi tiền; reliable = đáng tin cậy; emissions = khí thải"]'::jsonb, 'C1', '9. Môi trường'),
    (7, 75, 'Đã đến lúc các công ty năng lượng phải ngừng xây nhà máy điện than mới.', 'It is high time energy companies stopped building new coal-fired power stations.', '["It is high time that energy companies stopped building new coal-fired power stations.","It''s high time energy companies stopped building new coal-fired power stations.","It is high time energy companies stopped building new coal-fired power plants.","It is high time energy companies stopped building new coal power stations."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (stopped); coal-fired power station = nhà máy nhiệt điện than"]'::jsonb, 'C1', '9. Môi trường'),
    (7, 76, 'Nông dân cần cân bằng giữa việc sản xuất đủ lương thực và bảo vệ đất đai cho các thế hệ sau.', 'Farmers need to strike a balance between growing enough food and protecting the soil for future generations.', '["Farmers must strike a balance between growing enough food and protecting the soil for future generations.","Farmers need to strike a balance between producing enough food and protecting the soil for future generations.","Farmers need to strike a balance between growing enough food and protecting the land for future generations.","Farmers need to strike a balance between growing enough food and protecting soil for future generations."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","grow / produce food = sản xuất lương thực; soil = đất đai; future generations = các thế hệ sau"]'::jsonb, 'C1', '9. Môi trường'),
    (7, 77, 'Người cao tuổi nên được tham gia miễn phí các lớp học kỹ năng máy tính cơ bản.', 'Older people should be offered free classes in basic computer skills.', '["Older people ought to be offered free classes in basic computer skills.","Elderly people should be offered free classes in basic computer skills.","Older people should be given free classes in basic computer skills.","Older people should be offered free lessons in basic computer skills."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","be offered = được cung cấp, được mời tham gia; basic computer skills = kỹ năng máy tính cơ bản"]'::jsonb, 'B1', '10. Công nghệ'),
    (7, 78, 'Một cách để tránh phụ thuộc quá mức vào công nghệ là dành ra vài giờ không dùng màn hình mỗi ngày.', 'One way to avoid overdependence on technology is to set aside screen-free hours each day.', '["One way to avoid overdependence on technology is to set aside screen-free hours every day.","One way to avoid overdependence on technology is to have screen-free hours each day.","One way to prevent overdependence on technology is to set aside screen-free hours each day.","One way to avoid becoming too dependent on technology is to set aside screen-free hours each day."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","overdependence on = sự phụ thuộc quá mức vào; set aside = dành ra; screen-free = không dùng màn hình"]'::jsonb, 'B1', '10. Công nghệ'),
    (7, 79, 'Các doanh nghiệp đưa tự động hóa vào sản xuất phải áp dụng biện pháp để đào tạo lại những người lao động bị mất việc.', 'Firms that introduce automation must take measures to retrain workers who lose their jobs.', '["Firms that introduce automation must take steps to retrain workers who lose their jobs.","Companies that introduce automation must take measures to retrain workers who lose their jobs.","Firms that introduce automation must take measures to retrain the workers who lose their jobs.","Firms that introduce automation need to take measures to retrain workers who lose their jobs."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","introduce automation = đưa tự động hóa vào; retrain = đào tạo lại; lose your job = mất việc"]'::jsonb, 'B2', '10. Công nghệ'),
    (7, 80, 'Các nhà làm luật phải đối phó với tình trạng ứng dụng và trang web lạm dụng dữ liệu cá nhân.', 'Lawmakers must tackle the misuse of personal data by apps and websites.', '["Lawmakers must address the misuse of personal data by apps and websites.","Lawmakers must combat the misuse of personal data by apps and websites.","Legislators must tackle the misuse of personal data by apps and websites.","Lawmakers must tackle the misuse of personal information by apps and websites."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","lawmaker = nhà làm luật; misuse = sự lạm dụng; personal data = dữ liệu cá nhân"]'::jsonb, 'B2', '10. Công nghệ'),
    (7, 81, 'Điều thiết yếu là trẻ em học cách sử dụng Internet an toàn ngay từ nhỏ.', 'It is vital that children learn to use the Internet safely from an early age.', '["It is vital that children should learn to use the Internet safely from an early age.","It is essential that children learn to use the Internet safely from an early age.","It is vital that children learn how to use the Internet safely from an early age.","It''s vital that children learn to use the Internet safely from an early age."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","use the Internet safely = sử dụng Internet an toàn; from an early age = ngay từ nhỏ"]'::jsonb, 'B2', '10. Công nghệ'),
    (7, 82, 'Các khóa học trực tuyến có thể góp phần lớn vào việc giúp học sinh vùng xa tiếp cận giáo viên giỏi.', 'Online courses could go a long way towards giving students in remote areas access to good teachers.', '["Online courses could go a long way toward giving students in remote areas access to good teachers.","Online courses can go a long way towards giving students in remote areas access to good teachers.","Online courses could go a long way towards giving students in remote areas access to excellent teachers.","Online courses could go a long way towards giving students in remote regions access to good teachers."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","remote areas = vùng xa; give sb access to = giúp ai tiếp cận"]'::jsonb, 'C1', '10. Công nghệ'),
    (7, 83, 'Đã đến lúc các chính phủ phải ban hành quy định rõ ràng về việc sử dụng trí tuệ nhân tạo.', 'It is high time governments introduced clear rules on the use of artificial intelligence.', '["It is high time that governments introduced clear rules on the use of artificial intelligence.","It''s high time governments introduced clear rules on the use of artificial intelligence.","It is high time governments introduced clear rules on the use of AI.","It is high time governments introduced clear regulations on the use of artificial intelligence."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (introduced); introduce rules = ban hành quy định; artificial intelligence (AI) = trí tuệ nhân tạo"]'::jsonb, 'C1', '10. Công nghệ'),
    (7, 84, 'Nhà trường cần cân bằng giữa học trực tuyến và dạy học trực tiếp trên lớp.', 'Schools need to strike a balance between online learning and face-to-face teaching.', '["Schools must strike a balance between online learning and face-to-face teaching.","Schools need to strike a balance between online learning and classroom teaching.","Schools need to strike a balance between online and face-to-face teaching.","Schools need to strike a balance between online learning and teaching in the classroom."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","online learning = học trực tuyến; face-to-face teaching = dạy học trực tiếp"]'::jsonb, 'C1', '10. Công nghệ'),
    (7, 85, 'Những người đặt đồ ăn qua ứng dụng mỗi ngày vẫn nên dành thời gian tự nấu ăn.', 'People who order food through apps every day should still find time to cook for themselves.', '["People who order food through apps every day should still make time to cook for themselves.","People who order food via apps every day should still find time to cook for themselves.","People who order food through apps every day ought to still find time to cook for themselves.","People who order food through apps every day should still find time to cook their own meals."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","order food through apps = đặt đồ ăn qua ứng dụng; find time to = dành thời gian để; cook for yourself = tự nấu ăn"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (7, 86, 'Một cách để tránh những chuyến đi làm dài là làm việc tại nhà hai hoặc ba ngày mỗi tuần.', 'One way to avoid long commutes is to work from home two or three days a week.', '["One way to avoid long commutes is to work from home two or three days per week.","One way to avoid long commutes is to work remotely two or three days a week.","One way to avoid long commutes is to work from home for two or three days a week.","One way to avoid a long commute is to work from home two or three days a week."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","commute = quãng đường đi làm hằng ngày; work from home = làm việc tại nhà; work remotely = làm việc từ xa"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (7, 87, 'Cơ quan giao thông phải áp dụng biện pháp để giảm thời gian người dân bị kẹt xe.', 'Transport authorities must take measures to reduce the time people spend stuck in traffic.', '["Transport authorities must take steps to reduce the time people spend stuck in traffic.","Transport authorities must take measures to cut the time people spend stuck in traffic.","Transport authorities must take measures to reduce the time that people spend stuck in traffic.","Transportation authorities must take measures to reduce the time people spend stuck in traffic."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","transport authorities = cơ quan giao thông; be stuck in traffic = bị kẹt xe"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (7, 88, 'Các bậc cha mẹ đi làm có thể giải quyết vấn đề áp lực thời gian bằng cách chia sẻ việc nhà một cách công bằng.', 'Working parents can tackle the problem of time pressure by sharing household chores fairly.', '["Working parents can address the problem of time pressure by sharing household chores fairly.","Working parents can tackle the problem of time pressure by sharing housework fairly.","Working parents can tackle the issue of time pressure by sharing household chores fairly.","Working parents can tackle the problem of time pressure by sharing the household chores fairly."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","time pressure = áp lực thời gian; share household chores = chia sẻ việc nhà; fairly = công bằng"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (7, 89, 'Điều thiết yếu là mọi người dùng thời gian tiết kiệm được từ việc nhà để tập thể dục hoặc ở bên gia đình.', 'It is essential that people use the time they save on housework to exercise or be with their families.', '["It is essential that people should use the time they save on housework to exercise or be with their families.","It is vital that people use the time they save on housework to exercise or be with their families.","It is essential that people use the time they save on housework to exercise or spend time with their families.","It''s essential that people use the time they save on housework to exercise or be with their families."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","save time on = tiết kiệm thời gian cho; housework = việc nhà; be with your family = ở bên gia đình"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (7, 90, 'Thiết bị gia dụng thông minh có thể góp phần lớn vào việc giải phóng thời gian cho những người đi làm bận rộn.', 'Smart home appliances can go a long way towards freeing up time for busy professionals.', '["Smart home appliances can go a long way toward freeing up time for busy professionals.","Smart appliances can go a long way towards freeing up time for busy professionals.","Smart home appliances could go a long way towards freeing up time for busy professionals.","Smart home appliances can go a long way towards freeing up time for busy workers."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","smart home appliances = thiết bị gia dụng thông minh; free up time = giải phóng thời gian; busy professionals = người đi làm bận rộn"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (7, 91, 'Đã đến lúc chúng ta phải thôi phụ thuộc vào ứng dụng cho mọi việc nhỏ nhặt trong cuộc sống.', 'It is high time we stopped relying on apps for every small task in our lives.', '["It is high time that we stopped relying on apps for every small task in our lives.","It''s high time we stopped relying on apps for every small task in our lives.","It is high time we stopped depending on apps for every small task in our lives.","It is high time we stopped relying on apps for every little task in our lives."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (stopped); rely on = phụ thuộc vào; small task = việc nhỏ"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (7, 92, 'Chúng ta cần cân bằng giữa sự tiện lợi và việc duy trì vận động thể chất.', 'We need to strike a balance between convenience and staying physically active.', '["We must strike a balance between convenience and staying physically active.","We need to strike a balance between convenience and keeping physically active.","People need to strike a balance between convenience and staying physically active.","We have to strike a balance between convenience and staying physically active."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","convenience = sự tiện lợi; stay physically active = duy trì vận động thể chất"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (7, 93, 'Chính phủ nên hỗ trợ tài chính tạm thời cho những người lao động bị ảnh hưởng bởi các cải cách lớn.', 'The government should give temporary financial support to workers affected by major reforms.', '["The government ought to give temporary financial support to workers affected by major reforms.","The government should offer temporary financial support to workers affected by major reforms.","The government should provide temporary financial support to workers affected by major reforms.","Governments should give temporary financial support to workers affected by major reforms."]'::jsonb, '["should / ought to + V = nên (mục 2.7)","temporary financial support = hỗ trợ tài chính tạm thời; be affected by = bị ảnh hưởng bởi; reform = cải cách"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (7, 94, 'Một cách để giảm hóa đơn tiền điện về lâu dài là lắp pin mặt trời trên mái nhà.', 'One way to cut electricity bills in the long run is to install solar panels on the roof.', '["One way to reduce electricity bills in the long run is to install solar panels on the roof.","One way to lower electricity bills in the long run is to install solar panels on the roof.","One way to cut electricity bills in the long term is to install solar panels on the roof.","One way to cut electricity bills in the long run is to put solar panels on the roof."]'::jsonb, '["One way to V is to V = một cách để … là … (mục 2.7)","electricity bill = hóa đơn tiền điện; in the long run = về lâu dài; install solar panels = lắp pin mặt trời"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (7, 95, 'Các công ty phải áp dụng biện pháp để rút ngắn giai đoạn thích nghi khi đưa vào sử dụng một hệ thống mới.', 'Companies must take measures to shorten the adjustment period when they introduce a new system.', '["Companies must take steps to shorten the adjustment period when they introduce a new system.","Companies must take measures to reduce the adjustment period when they introduce a new system.","Companies need to take measures to shorten the adjustment period when they introduce a new system.","Firms must take measures to shorten the adjustment period when they introduce a new system."]'::jsonb, '["take measures / steps to V = áp dụng biện pháp để (mục 2.7)","adjustment period = giai đoạn thích nghi; shorten = rút ngắn; introduce a new system = đưa vào sử dụng hệ thống mới"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (7, 96, 'Chính phủ không thể giải quyết vấn đề dân số già hóa chỉ bằng các chính sách ngắn hạn.', 'Governments cannot address the issue of an ageing population with short-term policies alone.', '["Governments cannot tackle the issue of an ageing population with short-term policies alone.","Governments cannot address the issue of an aging population with short-term policies alone.","Governments cannot address the problem of an ageing population with short-term policies alone.","Governments can''t address the issue of an ageing population with short-term policies alone."]'::jsonb, '["tackle / address / combat a problem = giải quyết, đối phó với vấn đề (mục 2.7)","ageing population = dân số già hóa (Mỹ: aging); short-term policies = chính sách ngắn hạn; alone = chỉ riêng"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (7, 97, 'Điều thiết yếu là các nhà lãnh đạo ngày nay cân nhắc xem quyết định của họ sẽ ảnh hưởng thế nào đến các thế hệ tương lai.', 'It is essential that today''s leaders consider how their decisions will affect future generations.', '["It is essential that today''s leaders should consider how their decisions will affect future generations.","It is vital that today''s leaders consider how their decisions will affect future generations.","It''s essential that today''s leaders consider how their decisions will affect future generations.","It is essential that leaders today consider how their decisions will affect future generations."]'::jsonb, '["It is essential / vital that sb (should) do sth = điều thiết yếu là ai đó làm gì (mục 2.7)","consider = cân nhắc; affect = ảnh hưởng đến; future generations = các thế hệ tương lai; sau that: S + (should) + V nguyên mẫu"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (7, 98, 'Thực hiện cải cách từng bước sẽ góp phần lớn vào việc giảm sự phản đối của người dân.', 'Introducing reforms step by step would go a long way towards reducing public opposition.', '["Introducing reforms step by step would go a long way toward reducing public opposition.","Introducing reforms gradually would go a long way towards reducing public opposition.","Introducing reforms step by step would go a long way towards reducing public resistance.","Introducing reforms step by step will go a long way towards reducing public opposition."]'::jsonb, '["go a long way towards V-ing = góp phần lớn vào việc (mục 2.7)","step by step / gradually = từng bước; public opposition = sự phản đối của người dân"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (7, 99, 'Đã đến lúc các chính trị gia phải nhìn xa hơn cuộc bầu cử kế tiếp khi hoạch định chính sách.', 'It is high time politicians looked beyond the next election when making policies.', '["It is high time that politicians looked beyond the next election when making policies.","It''s high time politicians looked beyond the next election when making policies.","It is high time politicians looked beyond the next election when making policy.","It is high time politicians thought beyond the next election when making policies."]'::jsonb, '["It is high time sb did sth = đã đến lúc ai đó phải làm gì (mục 2.7)","sau high time: S + V quá khứ (looked); look beyond = nhìn xa hơn; election = cuộc bầu cử"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (7, 100, 'Các gia đình phải cân bằng giữa chi tiêu hôm nay và tiết kiệm cho ngày mai.', 'Families must strike a balance between spending today and saving for tomorrow.', '["Families need to strike a balance between spending today and saving for tomorrow.","Families have to strike a balance between spending today and saving for tomorrow.","Families must strike a balance between spending today and saving for the future.","Households must strike a balance between spending today and saving for tomorrow."]'::jsonb, '["strike a balance between A and B = cân bằng giữa A và B (mục 2.7)","strike a balance between A and B = cân bằng giữa A và B; spend = chi tiêu; save for tomorrow = tiết kiệm cho ngày mai"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (8, 1, 'Nếu chính phủ đánh thuế đồ uống có đường, người dân sẽ mua chúng ít hơn và tỷ lệ béo phì sẽ giảm.', 'If the government imposes a tax on sugary drinks, people will buy fewer of them and obesity rates will fall.', '["If the government taxes sugary drinks, people will buy fewer of them and obesity rates will fall.","If the government imposes a tax on sugary drinks, people will buy fewer of them and obesity rates will drop.","People will buy fewer sugary drinks and obesity rates will fall if the government imposes a tax on them."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","If + hiện tại đơn, will + V; impose a tax on sth = đánh thuế lên; sugary drinks = đồ uống có đường; obesity rate = tỷ lệ béo phì"]'::jsonb, 'B1', '1. Chính phủ'),
    (8, 2, 'Nếu chính phủ ban hành luật mới quá đột ngột, chúng sẽ vấp phải sự phản đối mạnh mẽ của người dân.', 'If the government introduces new laws too suddenly, they will meet strong public opposition.', '["If the government introduces new laws too suddenly, they will face strong public opposition.","If the government introduces new legislation too suddenly, it will meet strong public opposition.","New laws will meet strong public opposition if the government introduces them too suddenly."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","introduce a law = ban hành luật; suddenly = đột ngột; public opposition = sự phản đối của người dân"]'::jsonb, 'B1', '1. Chính phủ'),
    (8, 3, 'Nếu chính quyền địa phương có nhiều quyền quyết định hơn, họ sẽ đáp ứng nhu cầu của từng khu vực hiệu quả hơn.', 'If local authorities had more decision-making power, they would meet the needs of each area more effectively.', '["If local authorities had more power to make decisions, they would meet the needs of each area more effectively.","If local authorities had more decision-making power, they would meet each area''s needs more effectively.","Local authorities would meet the needs of each area more effectively if they had more decision-making power."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + quá khứ đơn, would + V (giả định); local authorities = chính quyền địa phương; decision-making power = quyền quyết định; meet the needs of = đáp ứng nhu cầu của"]'::jsonb, 'B2', '1. Chính phủ'),
    (8, 4, 'Nếu chính phủ chi nhiều hơn cho trường học và bệnh viện công, chất lượng sống của người dân sẽ cải thiện rõ rệt.', 'If the government spent more on public schools and hospitals, people''s quality of life would improve noticeably.', '["If the government spent more money on public schools and hospitals, people''s quality of life would improve noticeably.","If the government spent more on public schools and hospitals, citizens'' quality of life would improve noticeably.","People''s quality of life would improve noticeably if the government spent more on public schools and hospitals."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","spend more on sth = chi nhiều hơn cho; quality of life = chất lượng sống; noticeably = rõ rệt"]'::jsonb, 'B2', '1. Chính phủ'),
    (8, 5, 'Trừ khi các quy định có tính ràng buộc pháp lý, nhiều doanh nghiệp sẽ tiếp tục phớt lờ các tiêu chuẩn an toàn.', 'Unless regulations are legally binding, many companies will continue to ignore safety standards.', '["Unless the regulations are legally binding, many companies will continue to ignore safety standards.","Unless regulations are legally binding, many companies will keep ignoring safety standards.","Unless regulations are legally binding, many firms will continue to ignore safety standards.","Many companies will continue to ignore safety standards unless regulations are legally binding."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","legally binding = có tính ràng buộc pháp lý; ignore = phớt lờ; safety standards = tiêu chuẩn an toàn; unless không đi với not"]'::jsonb, 'B2', '1. Chính phủ'),
    (8, 6, 'Chi tiêu công mang lại lợi ích thực sự cho người dân, miễn là tiền thuế được quản lý minh bạch.', 'Public spending brings real benefits to citizens as long as taxpayers'' money is managed transparently.', '["Public spending brings real benefits to citizens provided that taxpayers'' money is managed transparently.","Public spending brings real benefits to people as long as taxpayers'' money is managed transparently.","As long as taxpayers'' money is managed transparently, public spending brings real benefits to citizens."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","public spending = chi tiêu công; taxpayers'' money = tiền thuế của dân; transparently = minh bạch"]'::jsonb, 'B2', '1. Chính phủ'),
    (8, 7, 'Nếu chính phủ đầu tư vào đường bộ và đường sắt ở nông thôn, các vùng này sẽ thu hút nhiều doanh nghiệp hơn.', 'Were the government to invest in rural roads and railways, these regions would attract more businesses.', '["Were the government to invest in roads and railways in rural areas, these regions would attract more businesses.","Were the government to invest in rural roads and railways, these areas would attract more businesses.","Were the government to invest in rural roads and railways, these regions would attract more companies."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; rural = ở nông thôn; railway = đường sắt; attract = thu hút"]'::jsonb, 'C1', '1. Chính phủ'),
    (8, 8, 'Nếu chính phủ lơi lỏng việc giám sát, doanh nghiệp có thể lại bắt đầu vi phạm quy định.', 'Should the government relax its monitoring, businesses may start breaking the rules again.', '["Should the government relax its monitoring, companies may start breaking the rules again.","Should the government relax monitoring, businesses may start breaking the rules again.","Should the government relax its monitoring, businesses may begin breaking the rules again.","Should the government relax its monitoring, businesses could start breaking the rules again."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + may V; relax monitoring = lơi lỏng giám sát; break the rules = vi phạm quy định"]'::jsonb, 'C1', '1. Chính phủ'),
    (8, 9, 'Giá mà cơ quan quản lý kiểm tra nhà máy thường xuyên hơn thì vụ rò rỉ hóa chất đã được ngăn chặn.', 'Had regulators inspected the factory more often, the chemical leak would have been prevented.', '["Had regulators inspected the factory more frequently, the chemical leak would have been prevented.","Had the regulators inspected the factory more often, the chemical leak would have been prevented.","Had regulators inspected the plant more often, the chemical leak would have been prevented.","Had regulatory bodies inspected the factory more often, the chemical leak would have been prevented."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; regulator = cơ quan quản lý; inspect = kiểm tra; chemical leak = rò rỉ hóa chất"]'::jsonb, 'C1', '1. Chính phủ'),
    (8, 10, 'Nếu một người bắt đầu đạp xe đi làm, đồng nghiệp của họ sẽ dễ làm theo hơn.', 'If one person starts cycling to work, their colleagues will be more likely to follow suit.', '["If one person starts cycling to work, their colleagues will be more likely to follow their example.","If one person begins cycling to work, their colleagues will be more likely to follow suit.","If one person starts to cycle to work, their colleagues will be more likely to follow suit.","Their colleagues will be more likely to follow suit if one person starts cycling to work."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","cycle to work = đạp xe đi làm; follow suit = làm theo; be more likely to V = dễ … hơn"]'::jsonb, 'B1', '2. Cá nhân'),
    (8, 11, 'Nếu người tiêu dùng từ chối mua đồ nhựa dùng một lần, các nhà sản xuất sẽ buộc phải thay đổi bao bì.', 'If consumers refuse to buy single-use plastics, manufacturers will be forced to change their packaging.', '["If consumers refuse to buy single-use plastic, manufacturers will be forced to change their packaging.","If consumers refuse to buy single-use plastics, producers will be forced to change their packaging.","If shoppers refuse to buy single-use plastics, manufacturers will be forced to change their packaging.","Manufacturers will be forced to change their packaging if consumers refuse to buy single-use plastics."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","single-use plastics = đồ nhựa dùng một lần; be forced to V = buộc phải; packaging = bao bì"]'::jsonb, 'B1', '2. Cá nhân'),
    (8, 12, 'Nếu ai cũng tắm nhanh hơn, cả thành phố sẽ tiết kiệm được hàng triệu lít nước mỗi năm.', 'If everyone took shorter showers, the whole city would save millions of litres of water every year.', '["If everyone took shorter showers, the whole city would save millions of liters of water every year.","If everybody took shorter showers, the whole city would save millions of litres of water every year.","If everyone took shorter showers, the entire city would save millions of litres of water each year.","The whole city would save millions of litres of water every year if everyone took shorter showers."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + quá khứ đơn, would + V (giả định); take shorter showers = tắm nhanh hơn; litre (Anh-Mỹ: liter) = lít"]'::jsonb, 'B2', '2. Cá nhân'),
    (8, 13, 'Trừ khi mỗi người kiên trì vượt qua những tuần đầu khó khăn, thói quen mới sẽ khó duy trì.', 'Unless individuals persist through the difficult first weeks, new habits will be hard to maintain.', '["Unless people persist through the difficult first weeks, new habits will be hard to maintain.","Unless individuals persevere through the difficult first weeks, new habits will be hard to maintain.","Unless individuals persist through the difficult first weeks, new habits will be difficult to maintain.","New habits will be hard to maintain unless individuals persist through the difficult first weeks."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","persist / persevere through sth = kiên trì vượt qua; maintain = duy trì; habit = thói quen"]'::jsonb, 'B2', '2. Cá nhân'),
    (8, 14, 'Trừ khi người dân thay đổi thói quen hằng ngày, các vấn đề môi trường sẽ khó được giải quyết.', 'Unless people change their daily habits, environmental problems will be difficult to solve.', '["Unless people change their everyday habits, environmental problems will be difficult to solve.","Unless individuals change their daily habits, environmental problems will be difficult to solve.","Unless people change their daily habits, environmental problems will be hard to solve.","Environmental problems will be difficult to solve unless people change their daily habits."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","daily / everyday habits = thói quen hằng ngày; solve = giải quyết; unless không đi với not"]'::jsonb, 'B2', '2. Cá nhân'),
    (8, 15, 'Người tiêu dùng có thể lựa chọn sáng suốt, miễn là họ chịu dành thời gian tìm hiểu sản phẩm trước khi mua.', 'Consumers can make informed choices as long as they take the time to research products before buying.', '["Consumers can make informed choices provided that they take the time to research products before buying.","Consumers can make informed choices as long as they take time to research products before buying.","Consumers can make informed choices as long as they take the time to research products before buying them.","As long as they take the time to research products before buying, consumers can make informed choices."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","make informed choices = lựa chọn sáng suốt; take the time to V = chịu dành thời gian; research = tìm hiểu"]'::jsonb, 'B2', '2. Cá nhân'),
    (8, 16, 'Nếu người trẻ đi bầu cử đông hơn, chính quyền sẽ phải lắng nghe kỹ hơn những mối quan tâm của họ.', 'Were young people to vote in greater numbers, the authorities would have to listen more closely to their concerns.', '["Were young people to vote in larger numbers, the authorities would have to listen more closely to their concerns.","Were young citizens to vote in greater numbers, the authorities would have to listen more closely to their concerns.","Were young people to vote in greater numbers, the authorities would need to listen more closely to their concerns.","Were more young people to vote, the authorities would have to listen more closely to their concerns."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; vote in greater numbers = đi bầu đông hơn; concerns = mối quan tâm"]'::jsonb, 'C1', '2. Cá nhân'),
    (8, 17, 'Nếu người lớn chuyển sang thói quen xanh hơn, thế hệ sau nhiều khả năng sẽ noi theo tấm gương của họ.', 'Should adults adopt greener habits, the next generation will probably follow their example.', '["Should adults adopt greener habits, the next generation will probably follow their lead.","Should adults adopt greener habits, the next generation is likely to follow their example.","Should adults adopt more environmentally friendly habits, the next generation will probably follow their example.","Should adults adopt greener habits, the younger generation will probably follow their example."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + will V; adopt greener habits = chuyển sang thói quen xanh hơn; follow sb''s example = noi gương ai"]'::jsonb, 'C1', '2. Cá nhân'),
    (8, 18, 'Giá mà có nhiều cư dân tham gia buổi dọn rác hơn thì bãi biển đã sạch rác trước mùa du lịch.', 'Had more residents joined the clean-up, the beach would have been free of litter before the tourist season.', '["Had more residents taken part in the clean-up, the beach would have been free of litter before the tourist season.","Had more local residents joined the clean-up, the beach would have been free of litter before the tourist season.","Had more residents joined the cleanup, the beach would have been free of litter before the tourist season.","Had more residents joined the clean-up, the beach would have been free of rubbish before the tourist season."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; clean-up = buổi dọn dẹp; free of litter = sạch rác; tourist season = mùa du lịch"]'::jsonb, 'C1', '2. Cá nhân'),
    (8, 19, 'Nếu nhà trường tư vấn hướng nghiệp từ sớm, sẽ có ít học sinh chọn sai ngành ở đại học hơn.', 'If schools provide career guidance early, fewer students will choose the wrong major at university.', '["If schools offer career guidance early, fewer students will choose the wrong major at university.","If schools provide early career guidance, fewer students will choose the wrong major at university.","If schools provide career guidance early, fewer students will pick the wrong major at university.","Fewer students will choose the wrong major at university if schools provide career guidance early."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","career guidance = tư vấn hướng nghiệp; choose the wrong major = chọn sai ngành; fewer + danh từ số nhiều = ít … hơn"]'::jsonb, 'B1', '3. Trường học'),
    (8, 20, 'Nếu các kỳ thi bớt nặng nề hơn, học sinh sẽ đỡ căng thẳng và hứng thú với việc học hơn.', 'If exams were less demanding, students would feel less stressed and enjoy learning more.', '["If exams were less demanding, students would be less stressed and enjoy learning more.","If exams were less demanding, students would feel less stressed and would enjoy learning more.","If examinations were less demanding, students would feel less stressed and enjoy learning more.","Students would feel less stressed and enjoy learning more if exams were less demanding."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + quá khứ đơn (were), would + V; demanding = nặng nề, đòi hỏi cao; stressed = căng thẳng; enjoy learning = hứng thú với việc học"]'::jsonb, 'B2', '3. Trường học'),
    (8, 21, 'Nếu trường nào cũng có giáo viên giỏi, trẻ em nhà nghèo sẽ có cơ hội ngang với trẻ em khá giả.', 'If every school had well-qualified teachers, children from poor families would have the same opportunities as wealthier children.', '["If every school had highly qualified teachers, children from poor families would have the same opportunities as wealthier children.","If all schools had well-qualified teachers, children from poor families would have the same opportunities as wealthier children.","If every school had well-qualified teachers, children from poor families would have the same chances as wealthier children.","Children from poor families would have the same opportunities as wealthier children if every school had well-qualified teachers."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","well-qualified = có trình độ tốt; the same opportunities as = cơ hội ngang với; wealthier = khá giả hơn"]'::jsonb, 'B2', '3. Trường học'),
    (8, 22, 'Trừ khi giáo viên được đào tạo bài bản, chương trình học mới sẽ khó mang lại kết quả.', 'Unless teachers receive proper training, the new curriculum will struggle to deliver results.', '["Unless teachers receive adequate training, the new curriculum will struggle to deliver results.","Unless teachers are properly trained, the new curriculum will struggle to deliver results.","Unless teachers receive proper training, the new curriculum will find it hard to deliver results.","The new curriculum will struggle to deliver results unless teachers receive proper training."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","receive proper training = được đào tạo bài bản; curriculum = chương trình học; deliver results = mang lại kết quả"]'::jsonb, 'B2', '3. Trường học'),
    (8, 23, 'Hoạt động ngoại khóa giúp học sinh rèn kỹ năng làm việc nhóm, miễn là chúng không chiếm quá nhiều thời gian học.', 'Extracurricular activities help students build teamwork skills, provided that they do not take up too much study time.', '["Extracurricular activities help students build teamwork skills, as long as they do not take up too much study time.","Extracurricular activities help students build teamwork skills, provided that they don''t take up too much study time.","Extracurricular activities help students develop teamwork skills, provided that they do not take up too much study time.","Provided that they do not take up too much study time, extracurricular activities help students build teamwork skills."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","extracurricular activities = hoạt động ngoại khóa; teamwork skills = kỹ năng làm việc nhóm; take up time = chiếm thời gian"]'::jsonb, 'B2', '3. Trường học'),
    (8, 24, 'Người trẻ sẽ ít có nguy cơ mắc nợ khi trưởng thành, miễn là các em được học cách lập ngân sách ở trường.', 'Young people are less likely to get into debt as adults as long as they learn how to budget at school.', '["Young people are less likely to get into debt as adults provided that they learn how to budget at school.","Young people are less likely to fall into debt as adults as long as they learn how to budget at school.","Young people are less likely to get into debt as adults as long as they learn to budget at school.","As long as they learn how to budget at school, young people are less likely to get into debt as adults."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","get into debt = mắc nợ; budget (động từ) = lập ngân sách, chi tiêu có kế hoạch; be less likely to V = ít có nguy cơ"]'::jsonb, 'B2', '3. Trường học'),
    (8, 25, 'Nếu nhà trường chú trọng dạy giá trị sống thay vì trừng phạt, nạn bắt nạt sẽ được giải quyết hiệu quả hơn nhiều.', 'Were schools to focus on teaching values rather than punishment, bullying would be tackled far more effectively.', '["Were schools to focus on teaching values rather than punishment, bullying would be tackled much more effectively.","Were schools to focus on teaching values instead of punishment, bullying would be tackled far more effectively.","Were schools to concentrate on teaching values rather than punishment, bullying would be tackled far more effectively.","Were schools to focus on teaching values rather than punishment, bullying would be addressed far more effectively."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; focus on V-ing = chú trọng; bullying = nạn bắt nạt; tackle = giải quyết"]'::jsonb, 'C1', '3. Trường học'),
    (8, 26, 'Nếu lợi ích của cải cách giáo dục phải nhiều năm mới thấy rõ, các nhà hoạch định chính sách cũng không được vội từ bỏ nó.', 'Should the benefits of education reform take years to appear, policymakers must not abandon it too early.', '["Should the benefits of education reform take years to appear, policymakers must not abandon it too soon.","Should the benefits of educational reform take years to appear, policymakers must not abandon it too early.","Should the benefits of education reform take years to become visible, policymakers must not abandon it too early.","Should the benefits of education reform take years to appear, policy makers must not abandon it too early."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + must not V; education reform = cải cách giáo dục; abandon = từ bỏ; policymaker = nhà hoạch định chính sách"]'::jsonb, 'C1', '3. Trường học'),
    (8, 27, 'Giá mà các trường đại học dạy nhiều kỹ năng thực tế hơn thì nhiều sinh viên mới tốt nghiệp đã tìm được việc dễ dàng hơn.', 'Had universities taught more practical skills, many recent graduates would have found jobs more easily.', '["Had universities taught more practical skills, many new graduates would have found jobs more easily.","Had universities taught more practical skills, many recent graduates would have found work more easily.","Had universities taught more hands-on skills, many recent graduates would have found jobs more easily.","Had the universities taught more practical skills, many recent graduates would have found jobs more easily."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; practical skills = kỹ năng thực tế; recent graduates = sinh viên mới tốt nghiệp"]'::jsonb, 'C1', '3. Trường học'),
    (8, 28, 'Nếu các gia đình cùng ăn tối mỗi ngày, các thành viên sẽ hiểu nhau hơn.', 'If families eat dinner together every day, their members will understand each other better.', '["If families have dinner together every day, their members will understand each other better.","If families eat dinner together every day, their members will understand one another better.","If families eat together every day, their members will understand each other better.","Family members will understand each other better if they eat dinner together every day."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","eat / have dinner together = cùng ăn tối; understand each other = hiểu nhau"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (8, 29, 'Nếu cha mẹ quá bận để trò chuyện với con, trẻ sẽ dễ tìm đến màn hình điện tử hơn.', 'If parents are too busy to talk to their children, the children will be more likely to turn to screens.', '["If parents are too busy to talk with their children, the children will be more likely to turn to screens.","If parents are too busy to talk to their children, the kids will be more likely to turn to screens.","If parents are too busy to talk to their kids, the children will be more likely to turn to screens.","Children will be more likely to turn to screens if their parents are too busy to talk to them."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","be too busy to V = quá bận để; turn to sth = tìm đến; screen = màn hình điện tử"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (8, 30, 'Nếu ông bà sống gần hơn, thêm nhiều cha mẹ trẻ sẽ có thể đi làm toàn thời gian mà không phải lo chuyện trông con.', 'If grandparents lived closer, more young parents would be able to work full-time without worrying about childcare.', '["If grandparents lived nearer, more young parents would be able to work full-time without worrying about childcare.","If grandparents lived closer, more young parents would be able to work full-time without worrying about child care.","If grandparents lived closer, more young parents would be able to work full-time without having to worry about childcare.","More young parents would be able to work full-time without worrying about childcare if grandparents lived closer."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + quá khứ đơn, would + V (giả định); live closer = sống gần hơn; work full-time = làm toàn thời gian; childcare = việc trông con"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (8, 31, 'Trừ khi cha mẹ tự mình làm gương, lời khuyên của họ sẽ ít có tác dụng với con cái.', 'Unless parents set a good example themselves, their advice will have little effect on their children.', '["Unless parents set a good example themselves, their advice will have little impact on their children.","Unless parents themselves set a good example, their advice will have little effect on their children.","Unless parents set a good example themselves, their advice will have little effect on their kids.","Their advice will have little effect on their children unless parents set a good example themselves."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","set a good example = làm gương; have little effect on = ít có tác dụng với; advice = lời khuyên"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (8, 32, 'Để trẻ tự đưa ra những quyết định nhỏ sẽ rèn tính tự lập cho trẻ, miễn là cha mẹ vẫn đặt ra giới hạn rõ ràng.', 'Letting children make small decisions builds their independence, as long as parents still set clear boundaries.', '["Letting children make small decisions builds their independence, provided that parents still set clear boundaries.","Letting children make small decisions builds their independence, as long as parents still set clear limits.","Allowing children to make small decisions builds their independence, as long as parents still set clear boundaries.","As long as parents still set clear boundaries, letting children make small decisions builds their independence."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","let sb do sth = để ai làm gì; independence = tính tự lập; set clear boundaries = đặt giới hạn rõ ràng"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (8, 33, 'Nếu cha mẹ dành nhiều thời gian chất lượng hơn cho con, sự gắn kết gia đình sẽ bền chặt hơn nhiều.', 'Were parents to spend more quality time with their children, family bonds would become much stronger.', '["Were parents to spend more quality time with their children, family ties would become much stronger.","Were parents to spend more quality time with their kids, family bonds would become much stronger.","Were parents to spend more quality time with their children, family bonds would grow much stronger.","Were parents to spend more quality time with children, family bonds would become much stronger."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; quality time = thời gian chất lượng bên nhau; family bonds = sự gắn kết gia đình"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (8, 34, 'Nếu gia đình và nhà trường thôi đổ lỗi cho nhau, trẻ sẽ nhận được sự hỗ trợ nhất quán hơn.', 'Were families and schools to stop blaming each other, children would receive more consistent support.', '["Were families and schools to stop blaming one another, children would receive more consistent support.","Were families and schools to stop blaming each other, children would get more consistent support.","Were parents and schools to stop blaming each other, children would receive more consistent support."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; blame each other = đổ lỗi cho nhau; consistent support = sự hỗ trợ nhất quán"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (8, 35, 'Nếu trẻ có dấu hiệu nghiện điện thoại, cha mẹ sẽ cần đặt ra quy tắc chặt chẽ về thời gian dùng thiết bị.', 'Should children show signs of phone addiction, parents will need to set firm rules on screen time.', '["Should children show signs of phone addiction, parents will need to set strict rules on screen time.","Should children show signs of smartphone addiction, parents will need to set firm rules on screen time.","Should children show any signs of phone addiction, parents will need to set firm rules on screen time.","Should children show signs of phone addiction, parents will have to set firm rules on screen time."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + will V; show signs of = có dấu hiệu; phone addiction = nghiện điện thoại; screen time = thời gian dùng thiết bị"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (8, 36, 'Giá mà cha mẹ động viên tinh thần con nhiều hơn trong mùa thi thì nhiều học sinh đã tự tin hơn hẳn.', 'Had their parents offered more emotional support during the exam season, many students would have felt far more confident.', '["Had their parents given more emotional support during the exam season, many students would have felt far more confident.","Had their parents provided more emotional support during the exam season, many students would have felt far more confident.","Had their parents offered more emotional support during the exam period, many students would have felt far more confident.","Had their parents offered more emotional support during the exam season, many students would have felt much more confident."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; emotional support = động viên tinh thần; exam season = mùa thi; confident = tự tin"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (8, 37, 'Nếu một công ty áp dụng giờ làm linh hoạt, nhân viên sẽ bớt căng thẳng và làm việc năng suất hơn.', 'If a company offers flexible working hours, its staff will feel less stressed and work more productively.', '["If a company offers flexible hours, its staff will feel less stressed and work more productively.","If a company offers flexible working hours, its employees will feel less stressed and work more productively.","If companies offer flexible working hours, their staff will feel less stressed and work more productively.","A company''s staff will feel less stressed and work more productively if it offers flexible working hours."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","flexible working hours = giờ làm linh hoạt; stressed = căng thẳng; productively = năng suất"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (8, 38, 'Nếu doanh nghiệp nhỏ được tiếp cận vốn vay dễ dàng hơn, họ sẽ tạo thêm nhiều việc làm cho người dân địa phương.', 'If small businesses had easier access to loans, they would create more jobs for local people.', '["If small firms had easier access to loans, they would create more jobs for local people.","If small businesses had easier access to credit, they would create more jobs for local people.","If small businesses had easier access to loans, they would create more jobs for local residents.","Small businesses would create more jobs for local people if they had easier access to loans."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + quá khứ đơn, would + V (giả định); have access to loans = được tiếp cận vốn vay; create jobs = tạo việc làm"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (8, 39, 'Nếu các doanh nghiệp xanh được đóng thuế thấp hơn, sẽ có thêm nhiều công ty chuyển sang công nghệ sạch.', 'If green businesses paid lower taxes, many more companies would switch to clean technology.', '["If green businesses paid less tax, many more companies would switch to clean technology.","If green companies paid lower taxes, many more firms would switch to clean technology.","If green businesses paid lower taxes, many more companies would move to clean technology.","Many more companies would switch to clean technology if green businesses paid lower taxes."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","pay lower taxes = đóng thuế thấp hơn; switch to sth = chuyển sang; clean technology = công nghệ sạch"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (8, 40, 'Trừ khi quyền lợi người lao động được bảo vệ đúng mức, một số công ty sẽ chạy theo lợi nhuận bằng cách đánh đổi sức khỏe của nhân viên.', 'Unless workers'' rights are properly protected, some firms will pursue profit at the expense of their staff''s health.', '["Unless workers'' rights are fully protected, some firms will pursue profit at the expense of their staff''s health.","Unless workers'' rights are properly protected, some companies will pursue profit at the expense of their staff''s health.","Unless workers'' rights are properly protected, some firms will chase profit at the expense of their staff''s health.","Some firms will pursue profit at the expense of their staff''s health unless workers'' rights are properly protected."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","workers'' rights = quyền lợi người lao động; pursue profit = chạy theo lợi nhuận; at the expense of = đánh đổi bằng"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (8, 41, 'Đầu tư cải thiện điều kiện làm việc sẽ tự hoàn vốn, miễn là công ty đủ kiên nhẫn chờ kết quả lâu dài.', 'Investing in better working conditions pays for itself, as long as the company is patient enough to wait for long-term results.', '["Investing in better working conditions pays for itself, provided that the company is patient enough to wait for long-term results.","Investing in better working conditions pays for itself, as long as the firm is patient enough to wait for long-term results.","Investment in better working conditions pays for itself, as long as the company is patient enough to wait for long-term results.","As long as the company is patient enough to wait for long-term results, investing in better working conditions pays for itself."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","working conditions = điều kiện làm việc; pay for itself = tự hoàn vốn; patient enough to V = đủ kiên nhẫn để"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (8, 42, 'Nếu các công ty đào tạo nhân viên về công nghệ mới, họ sẽ không bị đối thủ bỏ lại phía sau.', 'Were companies to train their staff in new technology, they would not fall behind their rivals.', '["Were companies to train their employees in new technology, they would not fall behind their rivals.","Were firms to train their staff in new technology, they would not fall behind their rivals.","Were companies to train their staff in new technology, they would not fall behind their competitors.","Were companies to train their staff to use new technology, they would not fall behind their rivals."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; train sb in sth = đào tạo ai về; fall behind = bị bỏ lại phía sau; rival = đối thủ"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (8, 43, 'Nếu các tập đoàn đa quốc gia mở nhà máy ở những vùng nghèo hơn, họ có thể giúp thu hẹp khoảng cách giàu nghèo.', 'Should multinational corporations open factories in poorer regions, they could help narrow the gap between rich and poor.', '["Should multinational corporations open factories in poorer regions, they could help bridge the gap between rich and poor.","Should multinational companies open factories in poorer regions, they could help narrow the gap between rich and poor.","Should multinational corporations open factories in poorer areas, they could help narrow the gap between rich and poor.","Should multinationals open factories in poorer regions, they could help narrow the gap between rich and poor."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + could V; multinational corporation = tập đoàn đa quốc gia; narrow / bridge the gap = thu hẹp khoảng cách"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (8, 44, 'Giá mà nhà máy đó lắp hệ thống xử lý nước thải thì con sông đã vẫn còn trong sạch.', 'Had the factory installed a wastewater treatment system, the river would have remained clean.', '["Had the factory installed a waste water treatment system, the river would have remained clean.","Had the factory installed a wastewater treatment system, the river would have stayed clean.","Had the plant installed a wastewater treatment system, the river would have remained clean.","Had the factory fitted a wastewater treatment system, the river would have remained clean."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; wastewater treatment system = hệ thống xử lý nước thải; remain clean = vẫn trong sạch"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (8, 45, 'Nếu bệnh được phát hiện sớm qua khám sức khỏe định kỳ, chi phí điều trị sẽ thấp hơn nhiều.', 'If diseases are detected early through regular check-ups, treatment will cost far less.', '["If illnesses are detected early through regular check-ups, treatment will cost far less.","If diseases are detected early through regular checkups, treatment will cost far less.","If diseases are detected early through regular check-ups, treatment will cost much less.","Treatment will cost far less if diseases are detected early through regular check-ups."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","detect = phát hiện; regular check-ups = khám sức khỏe định kỳ; cost far less = tốn ít hơn nhiều"]'::jsonb, 'B1', '6. Sức khỏe'),
    (8, 46, 'Nếu thực phẩm tươi rẻ ngang đồ ăn nhanh, sẽ có thêm nhiều gia đình ăn uống lành mạnh.', 'If fresh food were as cheap as fast food, many more families would eat healthily.', '["If fresh food was as cheap as fast food, many more families would eat healthily.","If fresh food were as cheap as fast food, many more families would eat healthy meals.","If fresh produce were as cheap as fast food, many more families would eat healthily.","Many more families would eat healthily if fresh food were as cheap as fast food."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + were (giả định, dùng cho mọi ngôi), would + V; as cheap as = rẻ ngang; eat healthily = ăn uống lành mạnh"]'::jsonb, 'B2', '6. Sức khỏe'),
    (8, 47, 'Trừ khi nhân viên văn phòng vận động nhiều hơn, họ sẽ có nguy cơ cao hơn mắc bệnh tim và tiểu đường.', 'Unless office workers become more active, they will face a higher risk of heart disease and diabetes.', '["Unless office workers become more physically active, they will face a higher risk of heart disease and diabetes.","Unless office workers exercise more, they will face a higher risk of heart disease and diabetes.","Unless office workers become more active, they will run a higher risk of heart disease and diabetes.","Office workers will face a higher risk of heart disease and diabetes unless they become more active."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","office workers = nhân viên văn phòng; become more active = vận động nhiều hơn; risk of sth = nguy cơ mắc; diabetes = tiểu đường"]'::jsonb, 'B2', '6. Sức khỏe'),
    (8, 48, 'Tập thể dục giúp giảm căng thẳng nhanh chóng, miễn là mọi người tập đều đặn chứ không phải thỉnh thoảng mới tập.', 'Exercise quickly reduces stress, provided that people do it regularly rather than occasionally.', '["Exercise quickly reduces stress, as long as people do it regularly rather than occasionally.","Exercise reduces stress quickly, provided that people do it regularly rather than occasionally.","Exercise quickly relieves stress, provided that people do it regularly rather than occasionally.","Provided that people do it regularly rather than occasionally, exercise quickly reduces stress."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","reduce / relieve stress = giảm căng thẳng; regularly = đều đặn; occasionally = thỉnh thoảng; rather than = chứ không phải"]'::jsonb, 'B2', '6. Sức khỏe'),
    (8, 49, 'Nếu nơi làm việc hỗ trợ sức khỏe tinh thần, nhân viên sẽ ít phải nghỉ ốm hơn.', 'Were workplaces to provide mental health support, employees would take fewer sick days.', '["Were workplaces to offer mental health support, employees would take fewer sick days.","Were workplaces to provide mental health support, staff would take fewer sick days.","Were workplaces to provide mental health support, employees would take less sick leave."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; mental health support = hỗ trợ sức khỏe tinh thần; sick days / sick leave = ngày nghỉ ốm"]'::jsonb, 'C1', '6. Sức khỏe'),
    (8, 50, 'Nếu số người cao tuổi tiếp tục tăng, bệnh viện sẽ cần thêm rất nhiều bác sĩ và y tá.', 'Should the number of elderly people keep rising, hospitals will need many more doctors and nurses.', '["Should the number of elderly people continue to rise, hospitals will need many more doctors and nurses.","Should the number of older people keep rising, hospitals will need many more doctors and nurses.","Should the number of elderly people keep increasing, hospitals will need many more doctors and nurses.","Should the elderly population keep growing, hospitals will need many more doctors and nurses."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + will V; elderly people = người cao tuổi; keep rising = tiếp tục tăng"]'::jsonb, 'C1', '6. Sức khỏe'),
    (8, 51, 'Nếu tình trạng làm việc nhiều giờ kéo dài, nhân viên có thể mắc các vấn đề sức khỏe tinh thần nghiêm trọng.', 'Should long working hours continue, employees may develop serious mental health problems.', '["Should long working hours persist, employees may develop serious mental health problems.","Should long working hours continue, staff may develop serious mental health problems.","Should long working hours continue, employees could develop serious mental health problems.","Should long working hours continue, employees may develop serious mental health issues."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + may V; long working hours = làm việc nhiều giờ; develop problems = mắc các vấn đề"]'::jsonb, 'C1', '6. Sức khỏe'),
    (8, 52, 'Giá mà chính phủ đầu tư vào phòng bệnh sớm hơn thì đã tiết kiệm được rất nhiều tiền chữa bệnh.', 'Had the government invested in disease prevention earlier, it would have saved a great deal of money on treatment.', '["Had the government invested in disease prevention sooner, it would have saved a great deal of money on treatment.","Had the government invested in preventing disease earlier, it would have saved a great deal of money on treatment.","Had the government invested in disease prevention earlier, it would have saved a lot of money on treatment.","Had the government invested in disease prevention earlier, it would have saved a great deal of money on medical treatment."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; disease prevention = phòng bệnh; a great deal of money = rất nhiều tiền"]'::jsonb, 'C1', '6. Sức khỏe'),
    (8, 53, 'Nếu du lịch phát triển, các khách sạn và nhà hàng mới sẽ tạo việc làm cho người dân địa phương.', 'If tourism grows, new hotels and restaurants will create jobs for local residents.', '["If tourism expands, new hotels and restaurants will create jobs for local residents.","If tourism develops, new hotels and restaurants will create jobs for local residents.","If tourism grows, new hotels and restaurants will create jobs for local people.","New hotels and restaurants will create jobs for local residents if tourism grows."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","tourism = du lịch; create jobs = tạo việc làm; local residents = người dân địa phương"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (8, 54, 'Nếu lương tăng kịp chi phí sinh hoạt, sẽ có ít gia đình phải chật vật mỗi cuối tháng hơn.', 'If wages kept pace with living costs, fewer families would struggle at the end of each month.', '["If wages kept pace with the cost of living, fewer families would struggle at the end of each month.","If wages kept up with living costs, fewer families would struggle at the end of each month.","If salaries kept pace with living costs, fewer families would struggle at the end of each month.","Fewer families would struggle at the end of each month if wages kept pace with living costs."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + quá khứ đơn, would + V (giả định); keep pace with = theo kịp; living costs = chi phí sinh hoạt; struggle = chật vật"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (8, 55, 'Trừ khi đất nước đào tạo thêm lao động có tay nghề, tăng trưởng kinh tế sẽ chậm lại.', 'Unless the country trains more skilled workers, its economic growth will slow down.', '["Unless the country trains more skilled workers, economic growth will slow down.","Unless the nation trains more skilled workers, its economic growth will slow down.","Unless the country trains more skilled workers, its economic growth will slow.","The country''s economic growth will slow down unless it trains more skilled workers."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","skilled workers = lao động có tay nghề; economic growth = tăng trưởng kinh tế; slow down = chậm lại"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (8, 56, 'Vay nợ để xây hạ tầng là hợp lý, miễn là các dự án mang lại lợi ích kinh tế lâu dài.', 'Borrowing to build infrastructure is justified as long as the projects bring long-term economic benefits.', '["Borrowing to build infrastructure is justified provided that the projects bring long-term economic benefits.","Borrowing to build infrastructure is justified as long as the projects deliver long-term economic benefits.","Borrowing money to build infrastructure is justified as long as the projects bring long-term economic benefits.","As long as the projects bring long-term economic benefits, borrowing to build infrastructure is justified."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","borrow = vay nợ; infrastructure = hạ tầng; be justified = hợp lý, xứng đáng; long-term economic benefits = lợi ích kinh tế lâu dài"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (8, 57, 'Nếu nhà nước tài trợ các khóa đào tạo lại, người lao động thất nghiệp sẽ tìm được việc mới nhanh hơn.', 'Were the state to fund retraining courses, unemployed workers would find new jobs more quickly.', '["Were the government to fund retraining courses, unemployed workers would find new jobs more quickly.","Were the state to pay for retraining courses, unemployed workers would find new jobs more quickly.","Were the state to fund retraining courses, jobless workers would find new jobs more quickly.","Were the state to fund retraining courses, unemployed workers would find new jobs faster."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; fund = tài trợ; retraining course = khóa đào tạo lại; unemployed = thất nghiệp"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (8, 58, 'Nếu tự động hóa làm giảm chi phí sản xuất, người tiêu dùng sẽ trả ít tiền hơn cho hàng hóa dùng hằng ngày.', 'Should automation lower production costs, consumers will pay less for everyday goods.', '["Should automation reduce production costs, consumers will pay less for everyday goods.","Should automation cut production costs, consumers will pay less for everyday goods.","Should automation lower production costs, consumers will pay less for everyday products.","Should automation lower the cost of production, consumers will pay less for everyday goods."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + will V; automation = tự động hóa; production costs = chi phí sản xuất; everyday goods = hàng hóa dùng hằng ngày"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (8, 59, 'Giá mà thành phố không chạy theo lợi nhuận ngắn hạn thì kinh tế địa phương đã phát triển bền vững hơn.', 'Had the city not chased short-term profits, its local economy would have grown more sustainably.', '["Had the city not pursued short-term profits, its local economy would have grown more sustainably.","Had the city not chased short-term profit, its local economy would have grown more sustainably.","Had the city not chased short-term profits, the local economy would have grown more sustainably.","Had the city not chased quick profits, its local economy would have grown more sustainably."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + not + V3, S + would have V3; chase short-term profits = chạy theo lợi nhuận ngắn hạn; sustainably = bền vững"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (8, 60, 'Giá mà chính sách thuế ổn định hơn thì các nhà đầu tư nước ngoài đã giữ vốn ở lại trong nước.', 'Had tax policies been more stable, foreign investors would have kept their money in the country.', '["Had tax policy been more stable, foreign investors would have kept their money in the country.","Had tax policies been more stable, foreign investors would have kept their capital in the country.","Had tax policies been more stable, overseas investors would have kept their money in the country.","Had tax policies been more stable, foreign investors would have kept their investments in the country."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + been + adj, S + would have V3; stable = ổn định; foreign investors = nhà đầu tư nước ngoài; capital = vốn"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (8, 61, 'Nếu chính quyền địa phương xây thêm công viên và thư viện, người dân sẽ có thêm nhiều nơi để gặp gỡ nhau.', 'If local authorities build more parks and libraries, residents will have more places to meet each other.', '["If local authorities build more parks and libraries, residents will have more places to meet one another.","If local authorities build more parks and libraries, local people will have more places to meet each other.","If the local authorities build more parks and libraries, residents will have more places to meet each other.","Residents will have more places to meet each other if local authorities build more parks and libraries."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","local authorities = chính quyền địa phương; residents = người dân, cư dân; meet each other = gặp gỡ nhau"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (8, 62, 'Nếu người cao tuổi có nhiều cơ hội giao lưu hơn, họ sẽ bớt cô đơn đi nhiều.', 'If elderly people had more chances to socialise, they would feel much less lonely.', '["If elderly people had more chances to socialize, they would feel much less lonely.","If older people had more chances to socialise, they would feel much less lonely.","If elderly people had more opportunities to socialise, they would feel much less lonely.","Elderly people would feel much less lonely if they had more chances to socialise."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + quá khứ đơn, would + V (giả định); socialise (Anh-Mỹ: socialize) = giao lưu; lonely = cô đơn"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (8, 63, 'Trừ khi người nhập cư được đối xử công bằng, họ sẽ vẫn bị đẩy ra bên lề xã hội.', 'Unless immigrants are treated fairly, they will remain on the margins of society.', '["Unless immigrants are treated fairly, they will stay on the margins of society.","Unless immigrants are treated equally, they will remain on the margins of society.","Unless migrants are treated fairly, they will remain on the margins of society.","Immigrants will remain on the margins of society unless they are treated fairly."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","immigrant = người nhập cư; treat sb fairly = đối xử công bằng; on the margins of society = bên lề xã hội"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (8, 64, 'Trừ khi người dân thực sự tham gia, các dự án cộng đồng sẽ khó tạo ra thay đổi lâu dài.', 'Unless residents genuinely take part, community projects will struggle to create lasting change.', '["Unless residents genuinely get involved, community projects will struggle to create lasting change.","Unless local people genuinely take part, community projects will struggle to create lasting change.","Unless residents really take part, community projects will struggle to create lasting change.","Community projects will struggle to create lasting change unless residents genuinely take part."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","take part / get involved = tham gia; genuinely = thực sự; lasting change = thay đổi lâu dài"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (8, 65, 'Trợ cấp tiền mặt có thể giúp các gia đình nghèo trước mắt, miễn là đi kèm với cơ hội việc làm thực sự.', 'Cash handouts can help poor families in the short term, provided that they come with real job opportunities.', '["Cash handouts can help poor families in the short term, as long as they come with real job opportunities.","Cash payments can help poor families in the short term, provided that they come with real job opportunities.","Cash handouts can help poor families in the short term, provided that they are combined with real job opportunities.","Provided that they come with real job opportunities, cash handouts can help poor families in the short term."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","cash handouts = trợ cấp tiền mặt; in the short term = trước mắt; come with = đi kèm với; job opportunities = cơ hội việc làm"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (8, 66, 'Nếu thành phố lắp thêm đèn đường và tăng cường tuần tra, các khu dân cư sẽ an toàn hơn vào ban đêm.', 'Were the city to install more street lights and increase patrols, residential areas would be safer at night.', '["Were the city to install more streetlights and increase patrols, residential areas would be safer at night.","Were the city to install more street lights and increase police patrols, residential areas would be safer at night.","Were the city to put up more street lights and increase patrols, residential areas would be safer at night."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; street lights = đèn đường; patrol = tuần tra; residential area = khu dân cư"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (8, 67, 'Nếu khoảng cách giàu nghèo tiếp tục nới rộng, căng thẳng xã hội có thể trở nên nghiêm trọng hơn.', 'Should the gap between rich and poor continue to widen, social tension could become more serious.', '["Should the gap between rich and poor keep widening, social tension could become more serious.","Should the gap between the rich and the poor continue to widen, social tension could become more serious.","Should the gap between rich and poor continue to widen, social tensions could become more serious.","Should the gap between rich and poor continue to widen, social tension may become more serious."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + could V; the gap between rich and poor = khoảng cách giàu nghèo; widen = nới rộng; social tension = căng thẳng xã hội"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (8, 68, 'Giá mà thị trấn mở một câu lạc bộ cho thanh thiếu niên thì đã có ít em sa vào tội phạm hơn.', 'Had the town opened a youth club, fewer teenagers would have become involved in crime.', '["Had the town set up a youth club, fewer teenagers would have become involved in crime.","Had the town opened a youth club, fewer teenagers would have got involved in crime.","Had the town opened a youth club, fewer teenagers would have become involved in criminal activity.","Had the town opened a youth club, fewer young people would have become involved in crime."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; youth club = câu lạc bộ thanh thiếu niên; become involved in crime = sa vào tội phạm"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (8, 69, 'Nếu giá vé tàu điện được giảm một nửa, số xe máy trên đường sẽ giảm đáng kể.', 'If metro fares are cut by half, the number of motorbikes on the roads will fall considerably.', '["If metro fares are halved, the number of motorbikes on the roads will fall considerably.","If metro fares are cut in half, the number of motorbikes on the roads will fall considerably.","If metro fares are cut by half, the number of motorbikes on the road will fall considerably.","The number of motorbikes on the roads will fall considerably if metro fares are cut by half."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","metro fare = giá vé tàu điện; cut by half / halve = giảm một nửa; considerably = đáng kể"]'::jsonb, 'B1', '9. Môi trường'),
    (8, 70, 'Nếu không khí ở các thành phố sạch hơn, số ca bệnh hô hấp ở trẻ em sẽ ít đi rất nhiều.', 'If the air in cities were cleaner, there would be far fewer cases of respiratory disease among children.', '["If the air in cities was cleaner, there would be far fewer cases of respiratory disease among children.","If the air in cities were cleaner, there would be far fewer cases of respiratory illness among children.","If city air were cleaner, there would be far fewer cases of respiratory disease among children.","There would be far fewer cases of respiratory disease among children if the air in cities were cleaner."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + were (giả định), would + V; respiratory disease = bệnh hô hấp; case = ca bệnh; far fewer = ít hơn rất nhiều"]'::jsonb, 'B2', '9. Môi trường'),
    (8, 71, 'Trừ khi các nhà máy phải trả tiền cho lượng khí thải mình tạo ra, họ sẽ có rất ít lý do để cắt giảm nó.', 'Unless factories have to pay for the emissions they produce, they will have little reason to cut them.', '["Unless factories pay for the emissions they produce, they will have little reason to cut them.","Unless factories have to pay for the emissions they produce, they will have little incentive to cut them.","Unless factories have to pay for the emissions they produce, they will have little reason to reduce them."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","emissions = khí thải; produce = tạo ra; have little reason / incentive to V = có ít lý do để"]'::jsonb, 'B2', '9. Môi trường'),
    (8, 72, 'Tăng trưởng kinh tế không nhất thiết phải hủy hoại thiên nhiên, miễn là các dự án mới tuân thủ quy định về môi trường.', 'Economic growth need not damage nature, as long as new projects follow environmental regulations.', '["Economic growth need not damage nature, provided that new projects follow environmental regulations.","Economic growth does not have to damage nature, as long as new projects follow environmental regulations.","Economic growth need not harm nature, as long as new projects follow environmental regulations.","Economic growth need not damage nature, as long as new projects comply with environmental regulations."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","need not + V = không nhất thiết; damage / harm nature = hủy hoại thiên nhiên; follow / comply with regulations = tuân thủ quy định"]'::jsonb, 'B2', '9. Môi trường'),
    (8, 73, 'Về lâu dài, năng lượng mặt trời sẽ rẻ hơn nhiên liệu hóa thạch, miễn là chi phí lắp đặt tiếp tục giảm.', 'Solar power will become cheaper than fossil fuels in the long run, provided that installation costs keep falling.', '["Solar power will become cheaper than fossil fuels in the long run, as long as installation costs keep falling.","Solar energy will become cheaper than fossil fuels in the long run, provided that installation costs keep falling.","Solar power will become cheaper than fossil fuels in the long run, provided that installation costs continue to fall.","Provided that installation costs keep falling, solar power will become cheaper than fossil fuels in the long run."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","solar power = năng lượng mặt trời; fossil fuels = nhiên liệu hóa thạch; installation costs = chi phí lắp đặt; in the long run = về lâu dài"]'::jsonb, 'B2', '9. Môi trường'),
    (8, 74, 'Nếu mọi siêu thị ngừng phát túi nilon miễn phí, lượng rác thải nhựa sẽ giảm đáng kể.', 'Were all supermarkets to stop giving out free plastic bags, plastic waste would fall significantly.', '["Were all supermarkets to stop handing out free plastic bags, plastic waste would fall significantly.","Were every supermarket to stop giving out free plastic bags, plastic waste would fall significantly.","Were all supermarkets to stop giving out free plastic bags, plastic waste would drop significantly.","Were all supermarkets to stop giving away free plastic bags, plastic waste would fall significantly."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; give out = phát; plastic bags = túi nilon; plastic waste = rác thải nhựa"]'::jsonb, 'C1', '9. Môi trường'),
    (8, 75, 'Nếu nạn phá rừng tiếp diễn với tốc độ hiện nay, nhiều loài động vật sẽ mất môi trường sống.', 'Should deforestation continue at its current rate, many animal species will lose their habitats.', '["Should deforestation continue at the current rate, many animal species will lose their habitats.","Should deforestation carry on at its current rate, many animal species will lose their habitats.","Should deforestation continue at its current pace, many animal species will lose their habitats.","Should deforestation continue at its current rate, many species will lose their natural habitats."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + will V; deforestation = nạn phá rừng; current rate = tốc độ hiện nay; habitat = môi trường sống"]'::jsonb, 'C1', '9. Môi trường'),
    (8, 76, 'Giá mà nhà chức trách ngăn ô nhiễm ngay từ đầu thì việc làm sạch hồ đã tốn ít tiền hơn nhiều.', 'Had the authorities prevented the pollution in the first place, cleaning up the lake would have cost far less.', '["Had the authorities prevented the pollution in the first place, cleaning up the lake would have cost much less.","Had the authorities stopped the pollution in the first place, cleaning up the lake would have cost far less.","Had the authorities prevented the pollution in the first place, cleaning the lake would have cost far less.","Had the authorities prevented pollution in the first place, cleaning up the lake would have cost far less."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; in the first place = ngay từ đầu; clean up = làm sạch; cost far less = tốn ít hơn nhiều"]'::jsonb, 'C1', '9. Môi trường'),
    (8, 77, 'Nếu robot đảm nhận các công việc lặp đi lặp lại, nhiều công nhân nhà máy sẽ mất việc trong ngắn hạn.', 'If robots take over repetitive tasks, many factory workers will lose their jobs in the short term.', '["If robots take over routine tasks, many factory workers will lose their jobs in the short term.","If robots take over repetitive tasks, many factory workers will be out of work in the short term.","If robots take over repetitive tasks, many factory workers will lose their jobs in the short run.","Many factory workers will lose their jobs in the short term if robots take over repetitive tasks."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","take over = đảm nhận, thay thế; repetitive tasks = công việc lặp đi lặp lại; in the short term = trong ngắn hạn"]'::jsonb, 'B1', '10. Công nghệ'),
    (8, 78, 'Nếu mọi người lao động đều được học kỹ năng số, họ sẽ thích nghi với thị trường việc làm mới dễ dàng hơn nhiều.', 'If every worker learned digital skills, they would adapt to the new job market far more easily.', '["If every worker learnt digital skills, they would adapt to the new job market far more easily.","If all workers learned digital skills, they would adapt to the new job market far more easily.","If every worker learned digital skills, they would adapt to the new job market much more easily.","Workers would adapt to the new job market far more easily if they all learned digital skills."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + quá khứ đơn, would + V (giả định); digital skills = kỹ năng số; adapt to = thích nghi với; job market = thị trường việc làm"]'::jsonb, 'B2', '10. Công nghệ'),
    (8, 79, 'Trừ khi các công ty công nghệ bị quản lý chặt chẽ, dữ liệu cá nhân của người dùng sẽ tiếp tục bị khai thác.', 'Unless tech companies are strictly regulated, users'' personal data will continue to be exploited.', '["Unless technology companies are strictly regulated, users'' personal data will continue to be exploited.","Unless tech companies are tightly regulated, users'' personal data will continue to be exploited.","Unless tech firms are strictly regulated, users'' personal data will continue to be exploited.","Users'' personal data will continue to be exploited unless tech companies are strictly regulated."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","tech companies = công ty công nghệ; regulate = quản lý bằng luật; personal data = dữ liệu cá nhân; exploit = khai thác"]'::jsonb, 'B2', '10. Công nghệ'),
    (8, 80, 'Trí tuệ nhân tạo mang lại lợi ích lớn, miễn là nó được dùng để hỗ trợ chứ không phải thay thế con người.', 'Artificial intelligence brings great benefits as long as it is used to support people rather than replace them.', '["Artificial intelligence brings great benefits provided that it is used to support people rather than replace them.","AI brings great benefits as long as it is used to support people rather than replace them.","Artificial intelligence brings huge benefits as long as it is used to support people rather than replace them.","Artificial intelligence brings great benefits as long as it is used to assist people rather than replace them."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","artificial intelligence = trí tuệ nhân tạo; support / assist = hỗ trợ; rather than = chứ không phải; replace = thay thế"]'::jsonb, 'B2', '10. Công nghệ'),
    (8, 81, 'Nếu nhà trường dạy trẻ cách dùng mạng xã hội có trách nhiệm, các em sẽ gặp ít rủi ro trên mạng hơn.', 'Were schools to teach children how to use social media responsibly, young people would face fewer risks online.', '["Were schools to teach children to use social media responsibly, young people would face fewer risks online.","Were schools to teach pupils how to use social media responsibly, young people would face fewer risks online.","Were schools to teach children how to use social media responsibly, they would face fewer risks online.","Were schools to teach children how to use social media responsibly, young people would face fewer online risks."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; use sth responsibly = dùng có trách nhiệm; risks online = rủi ro trên mạng"]'::jsonb, 'C1', '10. Công nghệ'),
    (8, 82, 'Nếu giá điện thoại thông minh giảm hơn nữa, gần như mọi học sinh ở vùng xa đều có thể học trực tuyến.', 'Were smartphone prices to fall further, almost every student in remote areas would be able to study online.', '["Were smartphone prices to drop further, almost every student in remote areas would be able to study online.","Were the price of smartphones to fall further, almost every student in remote areas would be able to study online.","Were smartphone prices to fall further, nearly every student in remote areas would be able to study online.","Were smartphone prices to fall further, almost every student in remote areas would be able to learn online."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; fall further = giảm hơn nữa; remote areas = vùng xa; study online = học trực tuyến"]'::jsonb, 'C1', '10. Công nghệ'),
    (8, 83, 'Nếu trẻ dành phần lớn thời gian rảnh trước màn hình, kỹ năng giao tiếp trực tiếp của các em có thể bị ảnh hưởng.', 'Should children spend most of their free time in front of screens, their face-to-face communication skills may suffer.', '["Should children spend most of their free time in front of screens, their face-to-face communication skills could suffer.","Should children spend most of their spare time in front of screens, their face-to-face communication skills may suffer.","Should children spend most of their free time in front of a screen, their face-to-face communication skills may suffer.","Should children spend most of their free time on screens, their face-to-face communication skills may suffer."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + may V; free / spare time = thời gian rảnh; face-to-face communication = giao tiếp trực tiếp; suffer = bị ảnh hưởng xấu"]'::jsonb, 'C1', '10. Công nghệ'),
    (8, 84, 'Giá mà công ty đó mã hóa dữ liệu khách hàng thì đã tránh được vụ rò rỉ dữ liệu.', 'Had the company encrypted its customers'' data, it would have avoided the data leak.', '["Had the company encrypted its customers'' data, it would have prevented the data leak.","Had the company encrypted customer data, it would have avoided the data leak.","Had the firm encrypted its customers'' data, it would have avoided the data leak.","Had the company encrypted its customers'' data, it would have avoided the leak."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; encrypt = mã hóa; data leak = rò rỉ dữ liệu; avoid = tránh được"]'::jsonb, 'C1', '10. Công nghệ'),
    (8, 85, 'Nếu nhân viên làm việc tại nhà hai ngày mỗi tuần, họ sẽ tiết kiệm được vài giờ đi lại.', 'If employees work from home two days a week, they will save several hours of commuting.', '["If employees work from home two days a week, they will save several hours on commuting.","If staff work from home two days a week, they will save several hours of commuting.","If employees work remotely two days a week, they will save several hours of commuting.","Employees will save several hours of commuting if they work from home two days a week."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","work from home / work remotely = làm việc tại nhà; commuting = việc đi lại đi làm; save time = tiết kiệm thời gian"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (8, 86, 'Nếu các thành phố có hệ thống tàu điện hiện đại, người đi làm sẽ không phải phí hàng giờ kẹt xe mỗi ngày.', 'If cities had modern metro systems, commuters would not waste hours in traffic jams every day.', '["If cities had modern metro systems, commuters would not spend hours in traffic jams every day.","If cities had modern subway systems, commuters would not waste hours in traffic jams every day.","If cities had modern metro systems, commuters would not waste hours stuck in traffic every day.","Commuters would not waste hours in traffic jams every day if cities had modern metro systems."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + quá khứ đơn, would + V (giả định); metro system = hệ thống tàu điện; commuter = người đi làm; traffic jam = kẹt xe"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (8, 87, 'Trừ khi mọi người chủ động giữ thói quen vận động, sự tiện lợi của dịch vụ giao hàng sẽ khiến họ ngày càng lười đi lại.', 'Unless people make an effort to stay active, the convenience of delivery services will make them increasingly sedentary.', '["Unless people make an effort to keep active, the convenience of delivery services will make them increasingly sedentary.","Unless people make an effort to stay active, the convenience of delivery services will make them increasingly inactive.","Unless people make an effort to stay active, convenient delivery services will make them increasingly sedentary.","The convenience of delivery services will make people increasingly sedentary unless they make an effort to stay active."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","make an effort to V = chủ động, cố gắng; stay active = giữ thói quen vận động; sedentary = ít vận động, lười đi lại"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (8, 88, 'Mua sắm trực tuyến là cách tiết kiệm thời gian tuyệt vời, miễn là số giờ tiết kiệm được dành cho việc có ích.', 'Online shopping is a great way to save time, as long as the hours saved are spent on something worthwhile.', '["Online shopping is a great way to save time, provided that the hours saved are spent on something worthwhile.","Online shopping is a great way to save time, as long as the time saved is spent on something worthwhile.","Shopping online is a great way to save time, as long as the hours saved are spent on something worthwhile.","As long as the hours saved are spent on something worthwhile, online shopping is a great way to save time."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","save time = tiết kiệm thời gian; the hours saved = số giờ tiết kiệm được; worthwhile = có ích, đáng làm"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (8, 89, 'Nếu nhà nào cũng có máy rửa bát, cha mẹ sẽ có thêm thời gian buổi tối để ở bên con cái.', 'Were every household to own a dishwasher, parents would have more time in the evening to spend with their children.', '["Were every household to have a dishwasher, parents would have more time in the evening to spend with their children.","Were every family to own a dishwasher, parents would have more time in the evening to spend with their children.","Were every household to own a dishwasher, parents would have more time in the evenings to spend with their children.","Were every household to own a dishwasher, parents would have more evening time to spend with their children."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; household = hộ gia đình; dishwasher = máy rửa bát; spend time with sb = ở bên ai"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (8, 90, 'Nếu giờ làm việc tiếp tục kéo dài thêm, nhân viên sẽ càng có ít thời gian nấu những bữa ăn tử tế.', 'Should working hours keep getting longer, employees will have even less time to cook proper meals.', '["Should working hours continue to get longer, employees will have even less time to cook proper meals.","Should working hours keep getting longer, workers will have even less time to cook proper meals.","Should working hours keep getting longer, employees will have even less time to cook a proper meal.","Should working hours keep growing longer, employees will have even less time to cook proper meals."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + will V; working hours = giờ làm việc; proper meal = bữa ăn tử tế; even less = càng ít hơn"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (8, 91, 'Nếu bạn thấy mình phụ thuộc vào ứng dụng giao đồ ăn, hãy thử tự nấu ăn ở nhà vài lần mỗi tuần.', 'Should you find yourself relying on food delivery apps, try cooking at home a few times a week.', '["Should you find yourself depending on food delivery apps, try cooking at home a few times a week.","Should you find yourself relying on food delivery apps, try to cook at home a few times a week.","Should you find yourself relying on food delivery apps, try cooking at home several times a week.","Should you find yourself relying on food delivery apps, try cooking for yourself a few times a week."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, + câu mệnh lệnh; rely on / depend on = phụ thuộc vào; food delivery app = ứng dụng giao đồ ăn"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (8, 92, 'Giá mà ngân hàng ra mắt dịch vụ trực tuyến sớm hơn thì khách hàng đã tiết kiệm được vô số giờ xếp hàng ở chi nhánh.', 'Had banks launched online services earlier, customers would have saved countless hours of queuing at branches.', '["Had banks introduced online services earlier, customers would have saved countless hours of queuing at branches.","Had banks launched online services sooner, customers would have saved countless hours of queuing at branches.","Had banks launched online services earlier, customers would have saved countless hours queuing at branches.","Had banks launched online services earlier, customers would have saved countless hours of waiting in line at branches."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; launch = ra mắt; queue (Anh-Mỹ: wait in line) = xếp hàng; branch = chi nhánh"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (8, 93, 'Nếu một hộ gia đình lắp pin mặt trời ngay bây giờ, họ sẽ trả tiền điện thấp hơn nhiều trong hàng chục năm.', 'If a household installs solar panels now, it will pay much lower electricity bills for decades.', '["If a household installs solar panels now, it will pay far lower electricity bills for decades.","If a family installs solar panels now, it will pay much lower electricity bills for decades.","If a household installs solar panels now, it will have much lower electricity bills for decades.","A household will pay much lower electricity bills for decades if it installs solar panels now."]'::jsonb, '["If + present, will + V = nếu … thì sẽ (có thể xảy ra) (mục 2.8)","household = hộ gia đình; install solar panels = lắp pin mặt trời; electricity bills = tiền điện; for decades = trong hàng chục năm"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (8, 94, 'Nếu các chính trị gia không phải lo chuyện tái đắc cử, họ sẽ sẵn sàng theo đuổi các kế hoạch dài hạn hơn.', 'If politicians did not have to worry about re-election, they would be more willing to pursue long-term plans.', '["If politicians didn''t have to worry about re-election, they would be more willing to pursue long-term plans.","If politicians did not need to worry about re-election, they would be more willing to pursue long-term plans.","If politicians did not have to worry about being re-elected, they would be more willing to pursue long-term plans.","Politicians would be more willing to pursue long-term plans if they did not have to worry about re-election."]'::jsonb, '["If + past, would + V = nếu … thì sẽ (giả định) (mục 2.8)","If + quá khứ đơn, would + V (giả định); re-election = tái đắc cử; be willing to V = sẵn sàng; pursue long-term plans = theo đuổi kế hoạch dài hạn"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (8, 95, 'Trừ khi những người lao động bị ảnh hưởng được hỗ trợ tài chính trong giai đoạn chuyển đổi, cuộc cải cách sẽ vấp phải sự phản đối gay gắt.', 'Unless affected workers receive financial support during the transition, the reform will meet fierce resistance.', '["Unless affected workers receive financial support during the transition, the reform will face fierce resistance.","Unless affected workers receive financial help during the transition, the reform will meet fierce resistance.","Unless affected workers are given financial support during the transition, the reform will meet fierce resistance.","The reform will meet fierce resistance unless affected workers receive financial support during the transition."]'::jsonb, '["unless + clause = trừ khi (mục 2.8)","affected workers = người lao động bị ảnh hưởng; transition = giai đoạn chuyển đổi; fierce resistance = sự phản đối gay gắt"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (8, 96, 'Một giải pháp tạm thời vẫn có thể chấp nhận được, miễn là nó không che giấu gốc rễ của vấn đề.', 'A quick fix is acceptable as long as it does not hide the root cause of the problem.', '["A quick fix is acceptable provided that it does not hide the root cause of the problem.","A quick fix is acceptable as long as it doesn''t hide the root cause of the problem.","A temporary solution is acceptable as long as it does not hide the root cause of the problem.","As long as it does not hide the root cause of the problem, a quick fix is acceptable."]'::jsonb, '["provided that / as long as + clause = miễn là (mục 2.8)","quick fix / temporary solution = giải pháp tạm thời; root cause = gốc rễ; hide = che giấu"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (8, 97, 'Nếu thế hệ hiện tại khai thác cạn kiệt tài nguyên thiên nhiên, con cháu chúng ta sẽ phải gánh chịu hậu quả.', 'Were the current generation to use up natural resources, our grandchildren would bear the consequences.', '["Were the present generation to use up natural resources, our grandchildren would bear the consequences.","Were the current generation to exhaust natural resources, our grandchildren would bear the consequences.","Were the current generation to use up natural resources, our grandchildren would suffer the consequences.","Were the current generation to use up the planet''s natural resources, our grandchildren would bear the consequences."]'::jsonb, '["Were sb to V, … = nếu ai đó … (đảo ngữ) (mục 2.8)","đảo ngữ, không dùng If: Were + S + to V, S + would V; use up / exhaust = khai thác cạn kiệt; bear the consequences = gánh chịu hậu quả"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (8, 98, 'Nếu giai đoạn thích nghi kéo dài hơn dự kiến, nhân viên có thể cần thêm thời gian đào tạo.', 'Should the adjustment period last longer than expected, staff may need extra training time.', '["Should the adjustment period last longer than expected, employees may need extra training time.","Should the adjustment period last longer than expected, staff may need additional training time.","Should the adjustment period take longer than expected, staff may need extra training time.","Should the adjustment period last longer than expected, staff might need extra training time."]'::jsonb, '["Should + S + V, … = nếu … (đảo ngữ, ít khả năng) (mục 2.8)","đảo ngữ, không dùng If: Should + S + V, S + may V; adjustment period = giai đoạn thích nghi; longer than expected = lâu hơn dự kiến"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (8, 99, 'Giá mà các nhà hoạch định chính sách tính đến lợi ích lâu dài thì thành phố đã bảo vệ được rừng ngập mặn ven biển.', 'Had policymakers considered long-term interests, the city would have protected its coastal mangrove forests.', '["Had policymakers considered long-term interests, the city would have preserved its coastal mangrove forests.","Had policymakers thought about long-term interests, the city would have protected its coastal mangrove forests.","Had policy makers considered long-term interests, the city would have protected its coastal mangrove forests.","Had policymakers considered long-term interests, the city would have protected its coastal mangroves."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; policymaker = nhà hoạch định chính sách; long-term interests = lợi ích lâu dài; mangrove forest = rừng ngập mặn"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (8, 100, 'Giá mà công ty nâng cấp máy móc từ năm năm trước thì đã tiết kiệm được một khoản tiền lớn cho việc sửa chữa.', 'Had the company upgraded its machinery five years ago, it would have saved a fortune on repairs.', '["Had the company upgraded its machinery five years ago, it would have saved a lot of money on repairs.","Had the firm upgraded its machinery five years ago, it would have saved a fortune on repairs.","Had the company upgraded its machines five years ago, it would have saved a fortune on repairs.","Had the company upgraded its equipment five years ago, it would have saved a fortune on repairs."]'::jsonb, '["Had sb done sth, … would have … = giá mà … thì đã … (quá khứ) (mục 2.8)","đảo ngữ, không dùng If: Had + S + V3, S + would have V3; upgrade machinery = nâng cấp máy móc; save a fortune = tiết kiệm được khoản tiền lớn; repairs = việc sửa chữa"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (9, 1, 'Chính các cấp chính quyền địa phương, chứ không phải các bộ ở trung ương, mới hiểu rõ nhất từng khu vực cần gì.', 'It is local authorities, not central ministries, that know best what each area needs.', '["It is local authorities, not central ministries, who know best what each area needs.","It is local authorities rather than central ministries that know best what each area needs.","It is local authorities, not central ministries, that best know what each area needs."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","local authorities = chính quyền địa phương; central ministries = các bộ ở trung ương; know best = hiểu rõ nhất; It is + X + that/who + V = chính X mới …"]'::jsonb, 'B2', '1. Chính phủ'),
    (9, 2, 'Từng cá nhân hiếm khi đủ nguồn lực để tự mình giải quyết những vấn đề của cả quốc gia.', 'Rarely do individuals have enough resources to solve national problems on their own.', '["Seldom do individuals have enough resources to solve national problems on their own.","Rarely do individuals have sufficient resources to solve national problems on their own.","Rarely do individuals have enough resources to solve national problems by themselves."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","resources = nguồn lực; on their own = tự mình; đảo ngữ: Rarely + do + S + V"]'::jsonb, 'C1', '1. Chính phủ'),
    (9, 3, 'Lý do thị trường tự do cần được quản lý là vì nếu không, người yếu thế sẽ không được bảo vệ.', 'The reason why the free market needs regulation is that vulnerable people would otherwise be left unprotected.', '["The reason why the free market needs to be regulated is that vulnerable people would otherwise be left unprotected.","The reason why the free market needs regulation is that vulnerable people would otherwise go unprotected.","The reason why the free market needs regulating is that vulnerable people would otherwise be left unprotected."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","free market = thị trường tự do; regulation = sự quản lý, điều tiết; vulnerable people = người yếu thế; otherwise = nếu không thì"]'::jsonb, 'C1', '1. Chính phủ'),
    (9, 4, 'Không còn nghi ngờ gì rằng một đạo luật mới có thể thay đổi hành vi của cả xã hội trong thời gian ngắn.', 'There is no doubt that a new law can change the behaviour of a whole society in a short time.', '["There''s no doubt that a new law can change the behaviour of a whole society in a short time.","There is no doubt that a new law can change the behavior of a whole society in a short time.","There is no doubt that a new law can change the behaviour of an entire society in a short time."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","behaviour (Anh-Mỹ: behavior) = hành vi; a whole society = cả xã hội; in a short time = trong thời gian ngắn"]'::jsonb, 'B2', '1. Chính phủ'),
    (9, 5, 'Điều mà chính phủ nên làm trước tiên là tăng ngân sách cho trường học và bệnh viện công.', 'What the government should do first is increase funding for public schools and hospitals.', '["What the government should do first is to increase funding for public schools and hospitals.","What the government should do first is raise funding for public schools and hospitals.","What the government ought to do first is increase funding for public schools and hospitals."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","increase funding for = tăng ngân sách cho; public schools and hospitals = trường học và bệnh viện công; What + S + should do + is (to) V = điều mà … nên làm là …"]'::jsonb, 'C1', '1. Chính phủ'),
    (9, 6, 'Chỉ bằng cách phát động các chiến dịch quốc gia thì chính phủ mới nâng cao được nhận thức của người dân về vấn đề này.', 'Only by launching national campaigns can the government raise public awareness of this issue.', '["Only by running national campaigns can the government raise public awareness of this issue.","Only by launching nationwide campaigns can the government raise public awareness of this issue.","Only by launching national campaigns can the government raise public awareness of the issue."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","launch a campaign = phát động chiến dịch; raise public awareness of = nâng cao nhận thức của người dân về; đảo ngữ: can + S + V"]'::jsonb, 'C1', '1. Chính phủ'),
    (9, 7, 'Mãi đến khi giá thuốc lá tăng mạnh thì nhiều người hút thuốc mới quyết định bỏ thuốc.', 'Not until cigarette prices rise sharply do many smokers decide to quit.', '["Not until cigarette prices rise sharply do many smokers decide to give up.","Not until the price of cigarettes rises sharply do many smokers decide to quit.","Not until cigarette prices rise steeply do many smokers decide to quit."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","cigarette prices = giá thuốc lá; rise sharply = tăng mạnh; quit / give up = bỏ (thuốc); đảo ngữ: do + S + V"]'::jsonb, 'C1', '1. Chính phủ'),
    (9, 8, 'Chỉ bằng cách áp dụng luật một cách nhất quán thì chính phủ mới tạo ra được thay đổi lâu dài.', 'Only by applying the law consistently can the government bring about lasting change.', '["Only by enforcing the law consistently can the government bring about lasting change.","Only by applying laws consistently can the government bring about lasting change.","Only by applying the law consistently can the government create lasting change."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","apply / enforce the law = áp dụng / thực thi luật; consistently = một cách nhất quán; bring about lasting change = tạo ra thay đổi lâu dài"]'::jsonb, 'C1', '1. Chính phủ'),
    (9, 9, 'Không còn nghi ngờ gì rằng luật có chế tài mang lại kết quả nhanh hơn các chiến dịch tự nguyện.', 'There is no doubt that laws backed by penalties bring faster results than voluntary campaigns.', '["There''s no doubt that laws backed by penalties bring faster results than voluntary campaigns.","There is no doubt that laws backed by penalties produce faster results than voluntary campaigns.","There is no doubt that laws backed by sanctions bring faster results than voluntary campaigns."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","backed by penalties = có chế tài đi kèm; voluntary campaigns = chiến dịch tự nguyện; bring results = mang lại kết quả"]'::jsonb, 'B2', '1. Chính phủ'),
    (9, 10, 'Chính người tiêu dùng mới quyết định doanh nghiệp sản xuất gì và sản xuất bao nhiêu.', 'It is consumers who decide what businesses produce and how much they produce.', '["It is consumers that decide what businesses produce and how much they produce.","It is consumers who decide what companies produce and how much they produce.","It is consumers who decide what businesses make and how much they make."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","consumers = người tiêu dùng; produce = sản xuất; It is + người + who + V = chính … mới …"]'::jsonb, 'B2', '2. Cá nhân'),
    (9, 11, 'Điều mà luật pháp không thể kiểm soát là cách mỗi người cư xử trong đời sống riêng.', 'What the law cannot control is how people behave in their private lives.', '["What laws cannot control is how people behave in their private lives.","What the law cannot control is how people act in their private lives.","What the law cannot control is the way people behave in their private lives."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","control = kiểm soát; behave = cư xử; private lives = đời sống riêng; What + S + V + is … = điều mà … là …"]'::jsonb, 'C1', '2. Cá nhân'),
    (9, 12, 'Những người hay đổ lỗi cho người khác hiếm khi tự giải quyết được vấn đề của mình.', 'Rarely do people who blame others solve their own problems.', '["Seldom do people who blame others solve their own problems.","Rarely do those who blame others solve their own problems.","Rarely do people who blame others manage to solve their own problems."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","blame others = đổ lỗi cho người khác; solve problems = giải quyết vấn đề; đảo ngữ: Rarely + do + S + V"]'::jsonb, 'C1', '2. Cá nhân'),
    (9, 13, 'Không còn nghi ngờ gì rằng những thay đổi nhỏ của hàng triệu người có thể tạo ra tác động rất lớn.', 'There is no doubt that small changes made by millions of people can have a huge impact.', '["There''s no doubt that small changes made by millions of people can have a huge impact.","There is no doubt that small changes by millions of people can have a huge impact.","There is no doubt that small changes made by millions of people can have an enormous impact."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","small changes = những thay đổi nhỏ; have a huge impact = tạo ra tác động rất lớn"]'::jsonb, 'B2', '2. Cá nhân'),
    (9, 14, 'Chính những thói quen nhỏ hằng ngày mới quyết định sức khỏe và tài chính của mỗi người về lâu dài.', 'It is small daily habits that determine each person''s health and finances in the long run.', '["It is small everyday habits that determine each person''s health and finances in the long run.","It is small daily habits that shape each person''s health and finances in the long run.","It is small daily habits that determine a person''s health and finances in the long run."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","daily habits = thói quen hằng ngày; determine = quyết định; finances = tình hình tài chính; in the long run = về lâu dài"]'::jsonb, 'B2', '2. Cá nhân'),
    (9, 15, 'Điều mà người tiêu dùng nên làm trước khi mua hàng là tìm hiểu kỹ về sản phẩm.', 'What consumers should do before making a purchase is research products carefully.', '["What consumers should do before making a purchase is to research products carefully.","What consumers should do before buying anything is research products carefully.","What consumers should do before making a purchase is research the products carefully."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","make a purchase = mua hàng; research = tìm hiểu kỹ; What + S + should do + is (to) V = điều mà … nên làm là …"]'::jsonb, 'C1', '2. Cá nhân'),
    (9, 16, 'Chỉ bằng cách thay đổi thói quen hằng ngày thì mỗi người mới giảm được lượng rác thải mình tạo ra.', 'Only by changing their daily habits can individuals reduce the amount of waste they produce.', '["Only by changing their everyday habits can individuals reduce the amount of waste they produce.","Only by changing their daily habits can people reduce the amount of waste they produce.","Only by changing their daily habits can individuals cut the amount of waste they produce."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","individuals = mỗi người, cá nhân; reduce the amount of waste = giảm lượng rác thải; đảo ngữ: can + S + V"]'::jsonb, 'C1', '2. Cá nhân'),
    (9, 17, 'Mãi đến khi người ta kiên trì với một thói quen mới trong vài tháng thì nó mới trở nên tự nhiên.', 'Not until people stick with a new habit for several months does it become second nature.', '["Not until people stick to a new habit for several months does it become second nature.","Not until people stick with a new habit for a few months does it become second nature.","Not until people keep up a new habit for several months does it become second nature."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","stick with / stick to = kiên trì với; second nature = điều tự nhiên như bản năng; đảo ngữ: does + S + V"]'::jsonb, 'C1', '2. Cá nhân'),
    (9, 18, 'Lý do hành động cá nhân thường bị xem nhẹ là vì tác động của một người có vẻ quá nhỏ.', 'The reason why individual action is often underestimated is that one person''s impact seems too small.', '["The reason why individual action is often underrated is that one person''s impact seems too small.","The reason why individual action is often underestimated is that the impact of one person seems too small.","The reason why individual efforts are often underestimated is that one person''s impact seems too small."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","individual action = hành động cá nhân; underestimate = xem nhẹ, đánh giá thấp; impact = tác động"]'::jsonb, 'C1', '2. Cá nhân'),
    (9, 19, 'Không còn nghi ngờ gì rằng một giáo viên giỏi có thể thay đổi thái độ học tập của cả lớp.', 'There is no doubt that a good teacher can change the attitude of a whole class towards learning.', '["There''s no doubt that a good teacher can change the attitude of a whole class towards learning.","There is no doubt that a good teacher can change the attitude of a whole class toward learning.","There is no doubt that a good teacher can change the attitude of an entire class towards learning."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","attitude towards learning (Anh-Mỹ: toward) = thái độ học tập; a whole class = cả lớp"]'::jsonb, 'B2', '3. Trường học'),
    (9, 20, 'Chính ở trường mà trẻ em nhà nghèo được tiếp cận kiến thức ngang với các bạn cùng trang lứa.', 'It is at school that children from poor families gain the same access to knowledge as their peers.', '["It is at school that children from poor families get the same access to knowledge as their peers.","It is at school that children from low-income families gain the same access to knowledge as their peers.","It is in school that children from poor families gain the same access to knowledge as their peers."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","children from poor families = trẻ em nhà nghèo; access to knowledge = sự tiếp cận kiến thức; peers = bạn cùng trang lứa; It is + nơi chốn + that …"]'::jsonb, 'B2', '3. Trường học'),
    (9, 21, 'Không còn nghi ngờ gì rằng áp lực thi cử đang gây căng thẳng nghiêm trọng cho nhiều học sinh.', 'There is no doubt that exam pressure is causing serious stress for many students.', '["There''s no doubt that exam pressure is causing serious stress for many students.","There is no doubt that exam pressure is causing serious stress among many students.","There is no doubt that exam pressure causes serious stress for many students."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","exam pressure = áp lực thi cử; cause serious stress = gây căng thẳng nghiêm trọng"]'::jsonb, 'B2', '3. Trường học'),
    (9, 22, 'Điều mà nhiều học sinh còn thiếu là khả năng quản lý tiền bạc trước khi bắt đầu đi làm.', 'What many students lack is the ability to manage money before they start work.', '["What many students lack is the ability to manage their money before they start work.","What many pupils lack is the ability to manage money before they start work.","What many students lack is the ability to manage money before they start working."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","lack = thiếu; the ability to manage money = khả năng quản lý tiền bạc; start work = bắt đầu đi làm"]'::jsonb, 'C1', '3. Trường học'),
    (9, 23, 'Chỉ bằng cách hướng nghiệp từ sớm thì nhà trường mới giúp học sinh tránh chọn sai ngành.', 'Only by offering career guidance early can schools help students avoid choosing the wrong major.', '["Only by providing career guidance early can schools help students avoid choosing the wrong major.","Only by offering early career guidance can schools help students avoid choosing the wrong major.","Only by offering career guidance early can schools help students avoid choosing the wrong course."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","career guidance = hướng nghiệp; avoid V-ing = tránh làm gì; the wrong major = sai ngành; đảo ngữ: can + S + V"]'::jsonb, 'C1', '3. Trường học'),
    (9, 24, 'Mãi đến khi bắt đầu đi làm thì nhiều sinh viên tốt nghiệp mới nhận ra rằng chỉ có lý thuyết thôi là chưa đủ.', 'Not until they start work do many graduates realise that theory alone is not enough.', '["Not until they start working do many graduates realise that theory alone is not enough.","Not until they start work do many graduates realize that theory alone is not enough.","Not until they start work do many graduates realise that theoretical knowledge alone is not enough."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","graduates = sinh viên tốt nghiệp; realise (Anh-Mỹ: realize) = nhận ra; theory alone = chỉ riêng lý thuyết; đảo ngữ: do + S + V"]'::jsonb, 'C1', '3. Trường học'),
    (9, 25, 'Lý do cải cách giáo dục tốn kém trước mắt là vì giáo viên cần được đào tạo lại.', 'The reason why education reform is costly at first is that teachers need to be retrained.', '["The reason why education reform is expensive at first is that teachers need to be retrained.","The reason why educational reform is costly at first is that teachers need to be retrained.","The reason why education reform is costly at first is that teachers need retraining."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","education reform = cải cách giáo dục; costly = tốn kém; at first = trước mắt, lúc đầu; retrain = đào tạo lại"]'::jsonb, 'C1', '3. Trường học'),
    (9, 26, 'Học sinh chỉ dựa vào học thuộc lòng hiếm khi áp dụng được kiến thức vào đời sống thực.', 'Rarely can students who rely only on rote learning apply their knowledge in real life.', '["Seldom can students who rely only on rote learning apply their knowledge in real life.","Rarely can students who rely only on rote learning apply their knowledge to real life.","Rarely are students who rely only on rote learning able to apply their knowledge in real life."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","rote learning = học thuộc lòng; apply knowledge = áp dụng kiến thức; đảo ngữ: Rarely + can + S + V"]'::jsonb, 'C1', '3. Trường học'),
    (9, 27, 'Lý do giáo dục hiệu quả hơn trừng phạt là vì nó giải quyết tận gốc vấn đề.', 'The reason why education works better than punishment is that it tackles the root cause of the problem.', '["The reason why education is more effective than punishment is that it tackles the root cause of the problem.","The reason why education works better than punishment is that it addresses the root cause of the problem.","The reason why education works better than punishment is that it deals with the root cause of the problem."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","punishment = sự trừng phạt; work better than = hiệu quả hơn; tackle the root cause = giải quyết tận gốc"]'::jsonb, 'C1', '3. Trường học'),
    (9, 28, 'Chính ông bà mới là người giúp nhiều cha mẹ trẻ có thể yên tâm đi làm.', 'It is grandparents who allow many young parents to go to work without worrying.', '["It is grandparents that allow many young parents to go to work without worrying.","It is grandparents who allow many young parents to go to work without worry.","It is grandparents who enable many young parents to go to work without worrying."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","grandparents = ông bà; young parents = cha mẹ trẻ; without worrying = yên tâm, không phải lo lắng"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (9, 29, 'Chính nhờ quan sát cha mẹ mà trẻ học được cách đối xử với người khác.', 'It is by watching their parents that children learn how to treat other people.', '["It is by observing their parents that children learn how to treat other people.","It is by watching their parents that children learn how to treat others.","It is by watching their parents that children learn how to behave towards other people."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","watch / observe = quan sát; treat other people = đối xử với người khác; It is + by V-ing + that … = chính nhờ … mà …"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (9, 30, 'Lý do cha mẹ phải cẩn trọng trong lời nói là vì con cái bắt chước mọi điều chúng nghe thấy.', 'The reason why parents must be careful about what they say is that children copy everything they hear.', '["The reason why parents must be careful with their words is that children copy everything they hear.","The reason why parents must watch what they say is that children copy everything they hear.","The reason why parents must be careful about what they say is that children imitate everything they hear."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","be careful about what you say = cẩn trọng trong lời nói; copy / imitate = bắt chước"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (9, 31, 'Không còn nghi ngờ gì rằng trẻ lớn lên trong gia đình yêu thương tự tin hơn khi gặp khó khăn.', 'There is no doubt that children who grow up in loving homes are more confident when facing difficulties.', '["There''s no doubt that children who grow up in loving homes are more confident when facing difficulties.","There is no doubt that children raised in loving homes are more confident when facing difficulties.","There is no doubt that children who grow up in loving families are more confident when facing difficulties."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","grow up = lớn lên; loving home = gia đình yêu thương; face difficulties = gặp khó khăn"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (9, 32, 'Mãi đến khi con nghiện điện thoại thì nhiều cha mẹ mới bắt đầu giới hạn thời gian dùng màn hình.', 'Not until their children become addicted to phones do many parents start to set limits on screen time.', '["Not until their children become addicted to their phones do many parents start to set limits on screen time.","Not until their children become addicted to phones do many parents start setting limits on screen time.","Not until their children are addicted to phones do many parents start to set limits on screen time."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","become addicted to = nghiện; set limits on screen time = giới hạn thời gian dùng màn hình; đảo ngữ: do + S + V"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (9, 33, 'Chỉ bằng cách tự mình hạn chế dùng điện thoại thì cha mẹ mới có thể yêu cầu con làm điều tương tự.', 'Only by limiting their own phone use can parents ask their children to do the same.', '["Only by limiting their own phone use can parents expect their children to do the same.","Only by reducing their own phone use can parents ask their children to do the same.","Only by cutting down on their own phone use can parents ask their children to do the same."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","limit phone use = hạn chế dùng điện thoại; their own = của chính mình; do the same = làm điều tương tự; đảo ngữ: can + S + V"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (9, 34, 'Những đứa trẻ thường xuyên ăn tối cùng gia đình hiếm khi cảm thấy cô đơn.', 'Rarely do children who regularly have dinner with their families feel lonely.', '["Seldom do children who regularly have dinner with their families feel lonely.","Rarely do children who regularly eat dinner with their families feel lonely.","Rarely do children who often have dinner with their families feel lonely."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","have dinner = ăn tối; regularly = thường xuyên; feel lonely = cảm thấy cô đơn; đảo ngữ: Rarely + do + S + V"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (9, 35, 'Mãi đến khi tự mình làm cha mẹ thì nhiều người mới hiểu được những hy sinh của cha mẹ mình.', 'Not until they become parents themselves do many people understand the sacrifices their own parents made.', '["Not until they have children of their own do many people understand the sacrifices their parents made.","Not until they become parents themselves do many people appreciate the sacrifices their own parents made.","Not until they become parents themselves do many people understand their own parents'' sacrifices."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","become parents themselves = tự mình làm cha mẹ; sacrifices = những hy sinh; đảo ngữ: do + S + V"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (9, 36, 'Điều mà trẻ học được ở nhà thường quan trọng hơn những gì chúng học ở trường.', 'What children learn at home is often more important than what they learn at school.', '["What children learn at home is often more important than what they are taught at school.","What children learn at home is often more important than what they learn in school.","What children learn at home is frequently more important than what they learn at school."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","learn at home = học ở nhà; more important than = quan trọng hơn; What + S + V + is … = điều mà … là …"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (9, 37, 'Chính các doanh nghiệp vừa và nhỏ mới tạo ra phần lớn việc làm ở nhiều quốc gia.', 'It is small and medium-sized enterprises that create most jobs in many countries.', '["It is small and medium-sized businesses that create most jobs in many countries.","It is small and medium-sized enterprises that create most of the jobs in many countries.","It is small and medium enterprises that create most jobs in many countries."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","small and medium-sized enterprises (SMEs) = doanh nghiệp vừa và nhỏ; create jobs = tạo việc làm"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (9, 38, 'Lý do doanh nghiệp nên chăm lo cho nhân viên là vì lợi nhuận phụ thuộc vào một đội ngũ khỏe mạnh.', 'The reason why businesses should look after their staff is that profits depend on a healthy workforce.', '["The reason why businesses should take care of their staff is that profits depend on a healthy workforce.","The reason why companies should look after their staff is that profits depend on a healthy workforce.","The reason why businesses should look after their employees is that profits depend on a healthy workforce."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","look after = chăm lo; profits = lợi nhuận; depend on = phụ thuộc vào; workforce = đội ngũ lao động"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (9, 39, 'Những công ty chỉ chạy theo lợi nhuận hiếm khi quan tâm đến sức khỏe của người lao động.', 'Rarely do companies that only chase profit care about their workers'' health.', '["Seldom do companies that only chase profit care about their workers'' health.","Rarely do firms that only chase profit care about their workers'' health.","Rarely do companies that only chase profit care about their workers'' wellbeing."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","chase profit = chạy theo lợi nhuận; care about = quan tâm đến; đảo ngữ: Rarely + do + S + V"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (9, 40, 'Không còn nghi ngờ gì rằng đào tạo nhân viên thường xuyên giúp doanh nghiệp theo kịp công nghệ mới.', 'There is no doubt that regular staff training helps companies keep up with new technology.', '["There''s no doubt that regular staff training helps companies keep up with new technology.","There is no doubt that regular staff training helps firms keep up with new technology.","There is no doubt that regular training for employees helps companies keep up with new technology."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","staff training = đào tạo nhân viên; keep up with = theo kịp"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (9, 41, 'Điều mà nhiều công ty nhận thấy sau khi áp dụng giờ làm linh hoạt là nhân viên ít căng thẳng hơn.', 'What many companies notice after introducing flexible hours is that staff feel less stressed.', '["What many companies notice after introducing flexible hours is that employees feel less stressed.","What many firms notice after introducing flexible hours is that staff feel less stressed.","What many companies find after introducing flexible hours is that staff feel less stressed."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","introduce flexible hours = áp dụng giờ làm linh hoạt; notice = nhận thấy; feel less stressed = bớt căng thẳng"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (9, 42, 'Chỉ bằng cách đối xử tốt với nhân viên thì công ty mới giữ chân được người giỏi.', 'Only by treating staff well can a company keep its best employees.', '["Only by treating employees well can a company keep its best staff.","Only by treating staff well can a company retain its best employees.","Only by treating staff well can companies keep their best employees."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","treat sb well = đối xử tốt với ai; keep / retain = giữ chân; đảo ngữ: can + S + V"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (9, 43, 'Người tiêu dùng hiếm khi trung thành với những thương hiệu gây ô nhiễm môi trường.', 'Rarely do consumers stay loyal to brands that pollute the environment.', '["Seldom do consumers stay loyal to brands that pollute the environment.","Rarely do customers stay loyal to brands that pollute the environment.","Rarely do consumers remain loyal to brands that pollute the environment."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","stay loyal to = trung thành với; brands = thương hiệu; pollute the environment = gây ô nhiễm môi trường"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (9, 44, 'Mãi đến khi bị phạt nặng thì nhiều nhà máy mới chịu xử lý chất thải đúng cách.', 'Not until they face heavy fines do many factories start treating their waste properly.', '["Not until they face heavy fines do many factories begin treating their waste properly.","Not until they face heavy fines do many factories start to treat their waste properly.","Not until they receive heavy fines do many factories start treating their waste properly."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","face heavy fines = bị phạt nặng; treat waste = xử lý chất thải; properly = đúng cách; đảo ngữ: do + S + V"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (9, 45, 'Chính bác sĩ gia đình mới là người phát hiện sớm nhiều bệnh nguy hiểm.', 'It is family doctors who detect many serious diseases at an early stage.', '["It is family doctors that detect many serious diseases at an early stage.","It is family doctors who detect many serious illnesses at an early stage.","It is family doctors who detect many serious diseases early."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","family doctor = bác sĩ gia đình; detect = phát hiện; at an early stage = ở giai đoạn sớm"]'::jsonb, 'B2', '6. Sức khỏe'),
    (9, 46, 'Điều mà hệ thống y tế đang phải đối mặt là nhu cầu chăm sóc ngày càng tăng của người cao tuổi.', 'What the healthcare system is facing is the growing demand for care from elderly people.', '["What the healthcare system is facing is the rising demand for care from elderly people.","What the health system is facing is the growing demand for care from elderly people.","What the healthcare system is facing is the growing demand for care from the elderly."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","healthcare system = hệ thống y tế; face = đối mặt; growing demand for = nhu cầu ngày càng tăng về"]'::jsonb, 'C1', '6. Sức khỏe'),
    (9, 47, 'Không còn nghi ngờ gì rằng lối sống ít vận động là nguyên nhân chính của nhiều bệnh thời hiện đại.', 'There is no doubt that a sedentary lifestyle is a major cause of many modern diseases.', '["There''s no doubt that a sedentary lifestyle is a major cause of many modern diseases.","There is no doubt that a sedentary lifestyle is a major cause of many modern illnesses.","There is no doubt that an inactive lifestyle is a major cause of many modern diseases."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","sedentary lifestyle = lối sống ít vận động; a major cause of = nguyên nhân chính của"]'::jsonb, 'B2', '6. Sức khỏe'),
    (9, 48, 'Các gia đình thu nhập thấp hiếm khi đủ khả năng mua thực phẩm tươi thay cho đồ ăn nhanh giá rẻ.', 'Rarely can low-income families afford fresh food instead of cheap fast food.', '["Seldom can low-income families afford fresh food instead of cheap fast food.","Rarely can low-income families afford fresh produce instead of cheap fast food.","Rarely are low-income families able to afford fresh food instead of cheap fast food."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","low-income families = gia đình thu nhập thấp; afford = đủ khả năng chi trả; đảo ngữ: Rarely + can + S + V"]'::jsonb, 'C1', '6. Sức khỏe'),
    (9, 49, 'Mãi đến khi kiệt sức thì nhiều nhân viên văn phòng mới tìm đến sự hỗ trợ về sức khỏe tinh thần.', 'Not until they suffer burnout do many office workers seek mental health support.', '["Not until they burn out do many office workers seek mental health support.","Not until they suffer burnout do many office workers look for mental health support.","Not until they suffer from burnout do many office workers seek mental health support."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","burnout = tình trạng kiệt sức; seek support = tìm kiếm sự hỗ trợ; mental health = sức khỏe tinh thần; đảo ngữ: do + S + V"]'::jsonb, 'C1', '6. Sức khỏe'),
    (9, 50, 'Chỉ bằng cách kết hợp ăn uống cân bằng với tập luyện đều đặn thì mọi người mới kiểm soát được cân nặng lâu dài.', 'Only by combining a balanced diet with regular exercise can people control their weight in the long term.', '["Only by combining a balanced diet with regular exercise can people control their weight in the long run.","Only by combining a balanced diet with regular exercise can people manage their weight in the long term.","Only by combining a balanced diet and regular exercise can people control their weight in the long term."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","combine A with B = kết hợp A với B; balanced diet = chế độ ăn cân bằng; control weight = kiểm soát cân nặng; đảo ngữ: can + S + V"]'::jsonb, 'C1', '6. Sức khỏe'),
    (9, 51, 'Không còn nghi ngờ gì rằng chỉ vài tuần tập thể dục cũng có thể giúp người ta ngủ ngon hơn và bớt căng thẳng.', 'There is no doubt that just a few weeks of exercise can help people sleep better and feel less stressed.', '["There''s no doubt that just a few weeks of exercise can help people sleep better and feel less stressed.","There is no doubt that only a few weeks of exercise can help people sleep better and feel less stressed.","There is no doubt that just a few weeks of exercise can help people sleep better and be less stressed."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","a few weeks of exercise = vài tuần tập thể dục; sleep better = ngủ ngon hơn; feel less stressed = bớt căng thẳng"]'::jsonb, 'B2', '6. Sức khỏe'),
    (9, 52, 'Lý do phòng bệnh được ưu tiên hơn chữa bệnh là vì nó vừa tiết kiệm tiền vừa cứu được nhiều sinh mạng.', 'The reason why prevention is preferred to cure is that it saves both money and lives.', '["The reason why prevention is preferable to cure is that it saves both money and lives.","The reason why prevention is preferred over cure is that it saves both money and lives.","The reason why prevention is preferred to cure is that it saves money as well as lives."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","prevention = phòng bệnh; cure = chữa bệnh; be preferred to = được ưu tiên hơn; save lives = cứu sinh mạng"]'::jsonb, 'C1', '6. Sức khỏe'),
    (9, 53, 'Lý do nhà đầu tư nước ngoài rót vốn vào một quốc gia là vì chính sách ở đó ổn định và minh bạch.', 'The reason why foreign investors put money into a country is that its policies are stable and transparent.', '["The reason why foreign investors invest in a country is that its policies are stable and transparent.","The reason why overseas investors put money into a country is that its policies are stable and transparent.","The reason why foreign investors put money into a country is that its policies are stable and clear."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","foreign investors = nhà đầu tư nước ngoài; put money into = rót vốn vào; stable = ổn định; transparent = minh bạch"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (9, 54, 'Điều khiến nhiều gia đình lo lắng nhất là tiền lương không theo kịp đà tăng giá.', 'What worries many families most is that their wages are not keeping up with rising prices.', '["What worries many families most is that their wages are not keeping pace with rising prices.","What worries many families most is that wages are not keeping up with rising prices.","What concerns many families most is that their wages are not keeping up with rising prices."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","wages = tiền lương; keep up with / keep pace with = theo kịp; rising prices = giá cả tăng; What + V + O + is … = điều khiến … là …"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (9, 55, 'Lý do nhiều việc làm trong nhà máy đang biến mất là vì robot rẻ hơn và nhanh hơn con người.', 'The reason why many factory jobs are disappearing is that robots are cheaper and faster than humans.', '["The reason why many factory jobs are disappearing is that robots are cheaper and faster than people.","The reason why many factory jobs are vanishing is that robots are cheaper and faster than humans.","The reason why many jobs in factories are disappearing is that robots are cheaper and faster than humans."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","factory jobs = việc làm trong nhà máy; disappear / vanish = biến mất; cheaper and faster = rẻ hơn và nhanh hơn"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (9, 56, 'Không còn nghi ngờ gì rằng tăng trưởng không đồng đều đang nới rộng khoảng cách giàu nghèo.', 'There is no doubt that uneven growth is widening the gap between rich and poor.', '["There''s no doubt that uneven growth is widening the gap between rich and poor.","There is no doubt that uneven growth is widening the gap between the rich and the poor.","There is no doubt that unequal growth is widening the gap between rich and poor."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","uneven growth = tăng trưởng không đồng đều; widen the gap between rich and poor = nới rộng khoảng cách giàu nghèo"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (9, 57, 'Chính du lịch mới là thứ đã tạo ra hàng nghìn việc làm cho người trẻ ở các thị trấn ven biển.', 'It is tourism that has created thousands of jobs for young people in coastal towns.', '["It is the tourism industry that has created thousands of jobs for young people in coastal towns.","It is tourism that has created thousands of jobs for young people in seaside towns.","It was tourism that created thousands of jobs for young people in coastal towns."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","tourism (industry) = (ngành) du lịch; create jobs = tạo việc làm; coastal towns = thị trấn ven biển"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (9, 58, 'Chỉ bằng cách đào tạo lại người lao động thì nền kinh tế mới thích nghi được với tự động hóa.', 'Only by retraining workers can the economy adapt to automation.', '["Only by retraining its workers can the economy adapt to automation.","Only by retraining workers can an economy adapt to automation.","Only by retraining the workforce can the economy adapt to automation."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","retrain = đào tạo lại; adapt to = thích nghi với; automation = tự động hóa; đảo ngữ: can + S + V"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (9, 59, 'Mãi đến khi một tuyến tàu điện ngầm mới đi vào hoạt động thì người dân mới thấy rõ lợi ích kinh tế của nó.', 'Not until a new metro line opens do residents clearly see its economic benefits.', '["Not until a new metro line opens do residents see its economic benefits clearly.","Not until a new metro line opens do people clearly see its economic benefits.","Not until a new underground line opens do residents clearly see its economic benefits."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","metro line = tuyến tàu điện ngầm; open = đi vào hoạt động; economic benefits = lợi ích kinh tế; đảo ngữ: do + S + V"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (9, 60, 'Trợ cấp kéo dài hiếm khi giúp người dân thoát nghèo hiệu quả bằng việc làm ổn định.', 'Rarely do long-term handouts lift people out of poverty as effectively as stable jobs do.', '["Seldom do long-term handouts lift people out of poverty as effectively as stable jobs do.","Rarely do long-term handouts lift people out of poverty as effectively as stable jobs.","Rarely do long-term welfare payments lift people out of poverty as effectively as stable jobs do."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","handouts = tiền trợ cấp; lift sb out of poverty = giúp ai thoát nghèo; as effectively as = hiệu quả bằng; đảo ngữ: Rarely + do + S + V"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (9, 61, 'Không còn nghi ngờ gì rằng người nhập cư đóng góp đáng kể cho nền kinh tế và văn hóa địa phương.', 'There is no doubt that immigrants make a significant contribution to the local economy and culture.', '["There''s no doubt that immigrants make a significant contribution to the local economy and culture.","There is no doubt that immigrants make a considerable contribution to the local economy and culture.","There is no doubt that immigrants contribute significantly to the local economy and culture."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","immigrants = người nhập cư; make a significant contribution to = đóng góp đáng kể cho"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (9, 62, 'Chính cư dân trong khu phố, chứ không chỉ cảnh sát, mới là người giữ cho đường phố an toàn.', 'It is local residents, not just the police, who keep the streets safe.', '["It is local residents, not only the police, who keep the streets safe.","It is local residents, not just the police, that keep the streets safe.","It is local residents, not just the police, who keep streets safe."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","local residents = cư dân trong khu phố; not just = chứ không chỉ; keep sth safe = giữ cho cái gì an toàn"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (9, 63, 'Điều mà nhiều người dân thành phố đã đánh mất là mối quan hệ thân thiết với hàng xóm.', 'What many city dwellers have lost is a close relationship with their neighbours.', '["What many city residents have lost is a close relationship with their neighbours.","What many city dwellers have lost is a close relationship with their neighbors.","What many city dwellers have lost is close relationships with their neighbours."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","city dwellers = người dân thành phố; close relationship = mối quan hệ thân thiết; neighbours (Anh-Mỹ: neighbors) = hàng xóm"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (9, 64, 'Lý do nhiều người già cảm thấy cô đơn là vì khu dân cư thiếu không gian công cộng để họ gặp gỡ.', 'The reason why many elderly people feel lonely is that their neighbourhoods lack public spaces where they can meet.', '["The reason why many older people feel lonely is that their neighbourhoods lack public spaces where they can meet.","The reason why many elderly people feel lonely is that their neighborhoods lack public spaces where they can meet.","The reason why many elderly people feel lonely is that their neighbourhoods lack public places where they can meet."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","feel lonely = cảm thấy cô đơn; neighbourhood (Anh-Mỹ: neighborhood) = khu dân cư; lack = thiếu; public spaces = không gian công cộng"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (9, 65, 'Những khu phố gắn kết hiếm khi có tỷ lệ tội phạm cao.', 'Rarely do close-knit neighbourhoods experience high rates of crime.', '["Seldom do close-knit neighbourhoods experience high rates of crime.","Rarely do close-knit neighborhoods experience high rates of crime.","Rarely do close-knit neighbourhoods experience high crime rates."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","close-knit = gắn kết; experience = gặp phải; high rates of crime = tỷ lệ tội phạm cao; đảo ngữ: Rarely + do + S + V"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (9, 66, 'Chính ở các trung tâm cộng đồng mà người già và người trẻ có dịp gặp gỡ, trò chuyện với nhau.', 'It is in community centres that older and younger people get the chance to meet and talk.', '["It is in community centres that old and young people get the chance to meet and talk.","It is in community centers that older and younger people get the chance to meet and talk.","It is at community centres that older and younger people get the chance to meet and talk."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","community centre (Anh-Mỹ: center) = trung tâm cộng đồng; get the chance to = có dịp; It is + in + nơi chốn + that …"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (9, 67, 'Mãi đến khi tự mình đi làm tình nguyện thì nhiều bạn trẻ mới hiểu hết những khó khăn của người nghèo.', 'Not until they volunteer themselves do many young people fully understand the hardships of the poor.', '["Not until they volunteer themselves do many young people fully understand the difficulties of the poor.","Not until they do voluntary work themselves do many young people fully understand the hardships of the poor.","Not until they volunteer do many young people fully understand the hardships of poor people."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","volunteer = làm tình nguyện; fully understand = hiểu hết; hardships = những khó khăn, gian khổ; đảo ngữ: do + S + V"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (9, 68, 'Chỉ bằng cách tạo ra cơ hội học tập và việc làm thì xã hội mới giúp được nhóm yếu thế thoát nghèo.', 'Only by creating education and job opportunities can society help vulnerable groups escape poverty.', '["Only by creating educational and job opportunities can society help vulnerable groups escape poverty.","Only by creating opportunities for education and work can society help vulnerable groups escape poverty.","Only by creating education and job opportunities can society help vulnerable groups get out of poverty."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","create opportunities = tạo cơ hội; vulnerable groups = nhóm yếu thế; escape poverty = thoát nghèo; đảo ngữ: can + S + V"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (9, 69, 'Chính xe cá nhân, chứ không phải nhà máy, mới gây ra phần lớn ô nhiễm không khí ở nhiều thành phố.', 'It is private cars, not factories, that cause most of the air pollution in many cities.', '["It is private cars, not factories, that cause most air pollution in many cities.","It is private vehicles, not factories, that cause most of the air pollution in many cities.","It is private cars rather than factories that cause most of the air pollution in many cities."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","private cars / vehicles = xe cá nhân; air pollution = ô nhiễm không khí; It is X, not Y, that … = chính X chứ không phải Y mới …"]'::jsonb, 'B2', '9. Môi trường'),
    (9, 70, 'Không còn nghi ngờ gì rằng việc đốt than và dầu là thủ phạm chính gây ra biến đổi khí hậu.', 'There is no doubt that burning coal and oil is the main cause of climate change.', '["There''s no doubt that burning coal and oil is the main cause of climate change.","There is no doubt that the burning of coal and oil is the main cause of climate change.","There is no doubt that burning coal and oil is the main culprit behind climate change."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","burn coal and oil = đốt than và dầu; the main cause / culprit = thủ phạm chính; climate change = biến đổi khí hậu"]'::jsonb, 'B2', '9. Môi trường'),
    (9, 71, 'Điều mà các nhà khoa học lo sợ nhất là rác thải nhựa đang tràn vào đại dương.', 'What scientists fear most is that plastic waste is flooding into the oceans.', '["What scientists fear most is that plastic waste is pouring into the oceans.","What scientists are most afraid of is that plastic waste is flooding into the oceans.","What scientists fear most is that plastic waste is flooding into the sea."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","fear = lo sợ; plastic waste = rác thải nhựa; flood / pour into = tràn vào"]'::jsonb, 'C1', '9. Môi trường'),
    (9, 72, 'Lý do nhiều loài động vật đang bị đe dọa là vì những khu rừng nơi chúng sinh sống đang bị chặt phá.', 'The reason why many animal species are under threat is that the forests they live in are being cut down.', '["The reason why many animal species are endangered is that the forests they live in are being cut down.","The reason why many species are under threat is that the forests they live in are being cut down.","The reason why many animal species are under threat is that their forest habitats are being cut down."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","species = loài; under threat = bị đe dọa; cut down = chặt phá; habitat = môi trường sống"]'::jsonb, 'C1', '9. Môi trường'),
    (9, 73, 'Chỉ bằng cách chuyển sang năng lượng tái tạo thì các quốc gia mới cắt giảm được khí thải carbon trên quy mô lớn.', 'Only by switching to renewable energy can countries cut carbon emissions on a large scale.', '["Only by switching to renewable energy can countries reduce carbon emissions on a large scale.","Only by moving to renewable energy can countries cut carbon emissions on a large scale.","Only by switching to renewable energy sources can countries cut carbon emissions on a large scale."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","switch to = chuyển sang; renewable energy = năng lượng tái tạo; cut carbon emissions = cắt giảm khí thải carbon; on a large scale = trên quy mô lớn"]'::jsonb, 'C1', '9. Môi trường'),
    (9, 74, 'Chỉ bằng cách cải thiện giao thông công cộng thì các thành phố mới thuyết phục được người lái xe bớt dùng ô tô.', 'Only by improving public transport can cities persuade drivers to use their cars less.', '["Only by improving public transport can cities convince drivers to use their cars less.","Only by improving public transport can cities persuade drivers to drive less.","Only by improving public transportation can cities persuade drivers to use their cars less."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","public transport (Anh-Mỹ: public transportation) = giao thông công cộng; persuade sb to V = thuyết phục ai làm gì; đảo ngữ: can + S + V"]'::jsonb, 'C1', '9. Môi trường'),
    (9, 75, 'Mãi đến khi lũ lụt và hạn hán xảy ra thường xuyên thì nhiều chính phủ mới coi trọng biến đổi khí hậu.', 'Not until floods and droughts became frequent did many governments take climate change seriously.', '["Not until floods and droughts became common did many governments take climate change seriously.","Not until floods and droughts became more frequent did many governments take climate change seriously.","Not until floods and droughts started to occur frequently did many governments take climate change seriously."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","floods and droughts = lũ lụt và hạn hán; take sth seriously = coi trọng; đảo ngữ quá khứ: did + S + V"]'::jsonb, 'C1', '9. Môi trường'),
    (9, 76, 'Nếu tính cả chi phí ô nhiễm, nhiên liệu hóa thạch hiếm khi rẻ hơn năng lượng sạch.', 'Rarely are fossil fuels cheaper than clean energy once the cost of pollution is included.', '["Seldom are fossil fuels cheaper than clean energy once the cost of pollution is included.","Rarely are fossil fuels cheaper than clean energy once pollution costs are included.","Rarely are fossil fuels cheaper than clean energy when the cost of pollution is included."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","fossil fuels = nhiên liệu hóa thạch; clean energy = năng lượng sạch; once … is included = khi tính cả …; đảo ngữ: Rarely + are + S + adj"]'::jsonb, 'C1', '9. Môi trường'),
    (9, 77, 'Chính các tập đoàn công nghệ lớn, chứ không phải người dùng bình thường, mới phải chịu trách nhiệm giữ an toàn cho dữ liệu cá nhân.', 'It is tech giants, not ordinary users, that should be responsible for keeping personal data safe.', '["It is tech giants, not ordinary users, who should be responsible for keeping personal data safe.","It is big tech companies, not ordinary users, that should be responsible for keeping personal data safe.","It is tech giants rather than ordinary users that should be responsible for keeping personal data safe."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","tech giants = các tập đoàn công nghệ lớn; be responsible for = chịu trách nhiệm; keep personal data safe = giữ an toàn cho dữ liệu cá nhân"]'::jsonb, 'B2', '10. Công nghệ'),
    (9, 78, 'Lý do gần như ai cũng có điện thoại thông minh là vì thiết bị ngày càng rẻ.', 'The reason why almost everyone owns a smartphone is that devices are becoming cheaper.', '["The reason why nearly everyone owns a smartphone is that devices are becoming cheaper.","The reason why almost everyone has a smartphone is that devices are becoming cheaper.","The reason why almost everyone owns a smartphone is that devices are getting cheaper."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","own = sở hữu, có; devices = thiết bị; become cheaper = ngày càng rẻ"]'::jsonb, 'C1', '10. Công nghệ'),
    (9, 79, 'Điều mà trẻ em đang đánh mất vì màn hình là thời gian trò chuyện trực tiếp với người khác.', 'What children are losing because of screens is time spent talking face to face with others.', '["What children are losing to screens is time spent talking face to face with others.","What children are losing because of screens is face-to-face time with other people.","What children are losing because of screens is time for face-to-face conversation with others."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","screens = màn hình; face to face = trực tiếp; What + S + V + is … = điều mà … là …"]'::jsonb, 'C1', '10. Công nghệ'),
    (9, 80, 'Ngày nay học sinh hiếm khi cần đến thư viện để tìm thông tin.', 'Rarely do students need to visit a library to find information these days.', '["Seldom do students need to visit a library to find information these days.","Rarely do students have to go to a library to find information these days.","Rarely do students need to visit a library to find information nowadays."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","visit a library = đến thư viện; find information = tìm thông tin; these days / nowadays = ngày nay; đảo ngữ: Rarely + do + S + V"]'::jsonb, 'C1', '10. Công nghệ'),
    (9, 81, 'Mãi đến khi dữ liệu cá nhân bị rò rỉ thì nhiều người dùng mới bắt đầu quan tâm đến quyền riêng tư.', 'Not until their personal data is leaked do many users start to care about privacy.', '["Not until their personal data is leaked do many users begin to care about privacy.","Not until their personal data has been leaked do many users start to care about privacy.","Not until their personal data is leaked do many users start caring about privacy."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","personal data = dữ liệu cá nhân; be leaked = bị rò rỉ; care about privacy = quan tâm đến quyền riêng tư; đảo ngữ: do + S + V"]'::jsonb, 'C1', '10. Công nghệ'),
    (9, 82, 'Chỉ bằng cách ban hành luật bảo vệ dữ liệu nghiêm ngặt thì chính phủ mới bảo vệ được quyền riêng tư của người dùng.', 'Only by passing strict data protection laws can governments protect users'' privacy.', '["Only by introducing strict data protection laws can governments protect users'' privacy.","Only by passing tough data protection laws can governments protect users'' privacy.","Only by passing strict data protection laws can governments safeguard users'' privacy."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","pass a law = ban hành luật; data protection = bảo vệ dữ liệu; privacy = quyền riêng tư; đảo ngữ: can + S + V"]'::jsonb, 'C1', '10. Công nghệ'),
    (9, 83, 'Không còn nghi ngờ gì rằng trí tuệ nhân tạo sẽ tạo ra những nghề mà ngày nay chưa hề tồn tại.', 'There is no doubt that artificial intelligence will create jobs that do not exist today.', '["There''s no doubt that artificial intelligence will create jobs that don''t exist today.","There is no doubt that AI will create jobs that do not exist today.","There is no doubt that artificial intelligence will create jobs which do not exist today."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","artificial intelligence (AI) = trí tuệ nhân tạo; create jobs = tạo ra nghề, việc làm; exist = tồn tại"]'::jsonb, 'B2', '10. Công nghệ'),
    (9, 84, 'Điều mà công nghệ nên làm là hỗ trợ con người chứ không phải thay thế họ.', 'What technology should do is support people, not replace them.', '["What technology should do is assist people, not replace them.","What technology should do is support people rather than replace them.","What technology should do is to support people, not replace them."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","support / assist = hỗ trợ; replace = thay thế; What + S + should do + is (to) V = điều mà … nên làm là …"]'::jsonb, 'C1', '10. Công nghệ'),
    (9, 85, 'Những người phải đi làm xa hiếm khi về nhà kịp bữa tối cùng gia đình.', 'Rarely do long-distance commuters get home in time for dinner with their families.', '["Seldom do long-distance commuters get home in time for dinner with their families.","Rarely do long-distance commuters get home in time to have dinner with their families.","Rarely do people with long commutes get home in time for dinner with their families."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","long-distance commuters = người đi làm xa; get home in time for = về nhà kịp; đảo ngữ: Rarely + do + S + V"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (9, 86, 'Chính nạn kẹt xe mới khiến thời gian đi làm của người dân thành phố ngày càng kéo dài.', 'It is traffic congestion that makes city dwellers'' commutes longer and longer.', '["It is traffic congestion that is making city dwellers'' commutes longer and longer.","It is traffic jams that make city dwellers'' commutes longer and longer.","It is traffic congestion that makes commutes in cities longer and longer."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","traffic congestion / traffic jams = nạn kẹt xe; commute = chuyến đi làm hằng ngày; longer and longer = ngày càng dài"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (9, 87, 'Không còn nghi ngờ gì rằng các thiết bị gia dụng như máy rửa bát đã giảm thời gian mọi người dành cho việc nhà.', 'There is no doubt that household appliances such as dishwashers have cut the time people spend on chores.', '["There''s no doubt that household appliances such as dishwashers have cut the time people spend on chores.","There is no doubt that household appliances such as dishwashers have reduced the time people spend on chores.","There is no doubt that household appliances such as dishwashers have cut the time people spend on housework."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","household appliances = thiết bị gia dụng; dishwasher = máy rửa bát; chores / housework = việc nhà"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (9, 88, 'Điều mà nhiều người không nhận ra là việc phụ thuộc vào ứng dụng giao hàng làm họ ít tiếp xúc với người khác hơn.', 'What many people fail to realise is that relying on delivery apps reduces their contact with other people.', '["What many people fail to realize is that relying on delivery apps reduces their contact with other people.","What many people do not realise is that relying on delivery apps reduces their contact with other people.","What many people fail to realise is that depending on delivery apps reduces their contact with other people."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","fail to realise (Anh-Mỹ: realize) = không nhận ra; rely on / depend on = phụ thuộc vào; delivery apps = ứng dụng giao hàng; contact with = sự tiếp xúc với"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (9, 89, 'Chỉ bằng cách làm việc tại nhà thì nhiều nhân viên mới tránh được một đến hai tiếng đi lại mỗi ngày.', 'Only by working from home can many employees avoid spending one to two hours commuting every day.', '["Only by working from home can many employees avoid one to two hours of commuting every day.","Only by working remotely can many employees avoid spending one to two hours commuting every day.","Only by working from home can many employees avoid spending one or two hours commuting each day."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","work from home / work remotely = làm việc tại nhà; avoid V-ing = tránh làm gì; commute = đi lại (đi làm); đảo ngữ: can + S + V"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (9, 90, 'Những người mua sắm trực tuyến hiếm khi phải xếp hàng ở siêu thị.', 'Rarely do people who shop online have to queue at the supermarket.', '["Seldom do people who shop online have to queue at the supermarket.","Rarely do people who shop online need to queue at the supermarket.","Rarely do online shoppers have to queue at the supermarket."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","shop online = mua sắm trực tuyến; queue = xếp hàng; đảo ngữ: Rarely + do + S + V"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (9, 91, 'Mãi đến khi được làm việc theo giờ linh hoạt thì nhiều cha mẹ mới có thời gian đưa đón con đi học.', 'Not until they are given flexible hours do many parents find time to take their children to and from school.', '["Not until they get flexible hours do many parents find time to take their children to and from school.","Not until they are given flexible working hours do many parents find time to take their children to and from school.","Not until they are given flexible hours do many parents have time to take their children to and from school."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","flexible hours = giờ làm linh hoạt; find time to V = có thời gian để; take children to and from school = đưa đón con đi học; đảo ngữ: do + S + V"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (9, 92, 'Lý do nhiều công ty chọn mô hình làm việc kết hợp là vì nó cân bằng giữa sự linh hoạt và tinh thần đồng đội.', 'The reason why many companies choose hybrid working is that it balances flexibility with teamwork.', '["The reason why many companies choose hybrid working is that it balances flexibility and teamwork.","The reason why many firms choose hybrid working is that it balances flexibility with teamwork.","The reason why many companies opt for hybrid working is that it balances flexibility with teamwork."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","hybrid working = làm việc kết hợp; balance A with B = cân bằng giữa A và B; teamwork = tinh thần đồng đội"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (9, 93, 'Chính các thế hệ tương lai mới phải trả giá cho những quyết định thiếu cân nhắc hôm nay.', 'It is future generations who will pay the price for today''s careless decisions.', '["It is future generations that will pay the price for today''s careless decisions.","It is future generations who will pay for today''s careless decisions.","It is future generations who will pay the price for today''s thoughtless decisions."]'::jsonb, '["It is … that … (câu chẻ) = chính … mà … (mục 2.9)","future generations = thế hệ tương lai; pay the price for = trả giá cho; careless / thoughtless decisions = quyết định thiếu cân nhắc"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (9, 94, 'Lý do người lao động cần được hỗ trợ tài chính là vì họ có thể mất thu nhập trong giai đoạn chuyển đổi.', 'The reason why workers need financial support is that they may lose their income during the transition period.', '["The reason why workers need financial help is that they may lose their income during the transition period.","The reason why workers need financial support is that they might lose their income during the transition period.","The reason why workers need financial support is that they may lose their income during the transition."]'::jsonb, '["The reason why … is that … = lý do … là vì … (mục 2.9)","financial support = hỗ trợ tài chính; lose income = mất thu nhập; transition period = giai đoạn chuyển đổi"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (9, 95, 'Mãi đến khi các dòng sông bị ô nhiễm nặng thì người ta mới nhận ra cái giá thật sự của tăng trưởng nóng.', 'Not until rivers become badly polluted do people realise the true cost of rapid growth.', '["Not until rivers become badly polluted do people realize the true cost of rapid growth.","Not until rivers become seriously polluted do people realise the true cost of rapid growth.","Not until rivers become badly polluted do people realise the real cost of rapid growth."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","badly polluted = bị ô nhiễm nặng; the true cost = cái giá thật sự; rapid growth = tăng trưởng nóng; đảo ngữ: do + S + V"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (9, 96, 'Không còn nghi ngờ gì rằng mọi hệ thống mới đều cần một giai đoạn thích nghi trước khi mọi người quen với nó.', 'There is no doubt that every new system needs an adjustment period before people get used to it.', '["There''s no doubt that every new system needs an adjustment period before people get used to it.","There is no doubt that every new system requires an adjustment period before people get used to it.","There is no doubt that any new system needs an adjustment period before people get used to it."]'::jsonb, '["There is no doubt that … = không còn nghi ngờ gì rằng (mục 2.9)","adjustment period = giai đoạn thích nghi; get used to = quen với"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (9, 97, 'Điều mà các nhà hoạch định chính sách nên làm là thực hiện thay đổi từng bước một.', 'What policymakers should do is introduce changes one step at a time.', '["What policymakers should do is introduce changes step by step.","What policymakers should do is to introduce changes one step at a time.","What policy makers should do is introduce changes one step at a time."]'::jsonb, '["What + clause + is … = điều mà … là … (mục 2.9)","policymakers = nhà hoạch định chính sách; introduce changes = thực hiện thay đổi; one step at a time / step by step = từng bước một"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (9, 98, 'Chỉ bằng cách đặt ra mục tiêu dài hạn rõ ràng thì chính phủ mới theo dõi được tiến độ một cách chính xác.', 'Only by setting clear long-term targets can governments monitor progress accurately.', '["Only by setting clear long-term goals can governments monitor progress accurately.","Only by setting clear long-term targets can governments track progress accurately.","Only by setting clear long-term targets can a government monitor progress accurately."]'::jsonb, '["Only by V-ing can S + V = chỉ bằng cách … thì mới … (mục 2.9)","set targets / goals = đặt mục tiêu; long-term = dài hạn; monitor / track progress = theo dõi tiến độ; đảo ngữ: can + S + V"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (9, 99, 'Mãi đến khi vài năm trôi qua thì các hộ gia đình lắp pin mặt trời mới thu hồi được vốn ban đầu.', 'Not until several years have passed do households with solar panels recover their initial investment.', '["Not until a few years have passed do households with solar panels recover their initial investment.","Not until several years have passed do households with solar panels get back their initial investment.","Not until several years have passed do families with solar panels recover their initial investment."]'::jsonb, '["Not until … do / does S + V = mãi đến khi … mới … (mục 2.9)","solar panels = pin mặt trời; recover the initial investment = thu hồi vốn ban đầu; đảo ngữ: do + S + V"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (9, 100, 'Các giải pháp tạm thời hiếm khi giải quyết vấn đề một cách triệt để.', 'Rarely do quick fixes solve a problem for good.', '["Seldom do quick fixes solve a problem for good.","Rarely do quick fixes solve a problem permanently.","Rarely do temporary solutions solve a problem for good."]'::jsonb, '["Rarely / Seldom + trợ động từ + S + V = hiếm khi (mục 2.9)","quick fixes / temporary solutions = giải pháp tạm thời; for good = triệt để, vĩnh viễn; đảo ngữ: Rarely + do + S + V"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (10, 1, 'Trước mắt, thuế mới đánh vào đồ uống có đường được dự đoán sẽ vấp phải sự phản đối từ các nhà sản xuất.', 'In the short term, the new tax on sugary drinks is expected to face opposition from manufacturers.', '["In the short term, the new tax on sugary drinks is expected to meet opposition from manufacturers.","In the short term, the new tax on sugary drinks is expected to face resistance from manufacturers.","In the short run, the new tax on sugary drinks is expected to face opposition from producers."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","sugary drinks = đồ uống có đường; face / meet opposition = vấp phải sự phản đối; manufacturers = nhà sản xuất; in the short term = trước mắt"]'::jsonb, 'B2', '1. Chính phủ'),
    (10, 2, 'Ngày càng nhiều vấn đề, như ô nhiễm và thất nghiệp, quá lớn để từng cá nhân tự giải quyết.', 'More and more problems, such as pollution and unemployment, are too large for individuals to solve alone.', '["More and more problems, such as pollution and unemployment, are too big for individuals to solve alone.","More and more problems, like pollution and unemployment, are too large for individuals to solve alone.","More and more problems, such as pollution and unemployment, are too large for individuals to solve on their own."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","pollution = ô nhiễm; unemployment = thất nghiệp; too large for sb to V = quá lớn để ai làm gì; alone / on their own = tự mình"]'::jsonb, 'B1', '1. Chính phủ'),
    (10, 3, 'Ngày càng có nhiều chính quyền địa phương tự xây dựng chính sách riêng để giải quyết vấn đề của địa phương mình.', 'A growing number of local authorities are designing their own policies to solve local problems.', '["An increasing number of local authorities are designing their own policies to solve local problems.","A growing number of local authorities are developing their own policies to solve local problems.","A growing number of local authorities are designing their own policies to address local problems."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","local authorities = chính quyền địa phương; design / develop policies = xây dựng chính sách; a growing number of + N số nhiều + V số nhiều"]'::jsonb, 'B2', '1. Chính phủ'),
    (10, 4, 'Mức phạt nặng và sự giám sát chặt chẽ có khả năng khiến doanh nghiệp tuân thủ các quy định an toàn.', 'Heavy fines and strict monitoring are likely to make businesses comply with safety regulations.', '["Heavy fines and strict monitoring are likely to make companies comply with safety regulations.","Heavy fines and close monitoring are likely to make businesses comply with safety regulations.","Heavy fines and strict monitoring are likely to make firms obey safety regulations."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","heavy fines = mức phạt nặng; strict monitoring = sự giám sát chặt chẽ; comply with = tuân thủ; safety regulations = quy định an toàn"]'::jsonb, 'B2', '1. Chính phủ'),
    (10, 5, 'Ngày càng có xu hướng các chính phủ dùng mạng xã hội để nâng cao nhận thức của cộng đồng về các vấn đề sức khỏe.', 'There is a growing tendency for governments to use social media to raise public awareness of health issues.', '["There is a growing tendency for governments to use social media to raise public awareness about health issues.","There is a growing tendency for governments to use social networks to raise public awareness of health issues.","There is a growing tendency for governments to use social media to raise public awareness of health problems."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","social media = mạng xã hội; raise public awareness of = nâng cao nhận thức cộng đồng về; There is a growing tendency for + sb + to V"]'::jsonb, 'C1', '1. Chính phủ'),
    (10, 6, 'Các tuyến đường sắt mới ở nông thôn được dự đoán sẽ thu hút đầu tư và tạo thêm việc làm cho người dân địa phương.', 'New railway lines in rural areas are expected to attract investment and create more jobs for local people.', '["New rail lines in rural areas are expected to attract investment and create more jobs for local people.","New railway lines in the countryside are expected to attract investment and create more jobs for local people.","New railway lines in rural areas are expected to attract investment and create more jobs for local residents."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","railway lines = tuyến đường sắt; rural areas = nông thôn; attract investment = thu hút đầu tư; create jobs = tạo việc làm"]'::jsonb, 'B2', '1. Chính phủ'),
    (10, 7, 'Các lời kêu gọi tự nguyện khó có khả năng mang lại hiệu quả như các biện pháp có tính ràng buộc pháp lý.', 'Voluntary appeals are unlikely to be as effective as legally binding measures.', '["Voluntary appeals are unlikely to be as effective as legally binding rules.","Voluntary calls for action are unlikely to be as effective as legally binding measures.","Voluntary appeals are unlikely to work as well as legally binding measures."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","voluntary appeals = lời kêu gọi tự nguyện; legally binding measures = biện pháp có tính ràng buộc pháp lý; be unlikely to V = khó có khả năng"]'::jsonb, 'B2', '1. Chính phủ'),
    (10, 8, 'Ngày càng có nhiều chính phủ dùng tiền thuế thuốc lá để tài trợ cho các chương trình cai thuốc.', 'An increasing number of governments are using tobacco taxes to fund quit-smoking programmes.', '["A growing number of governments are using tobacco taxes to fund quit-smoking programmes.","An increasing number of governments are using tobacco taxes to fund quit-smoking programs.","An increasing number of governments use tobacco taxes to fund quit-smoking programmes.","An increasing number of governments are using cigarette taxes to fund quit-smoking programmes."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","tobacco taxes = thuế thuốc lá; fund = tài trợ; quit-smoking programmes (Anh-Mỹ: programs) = chương trình cai thuốc"]'::jsonb, 'B2', '1. Chính phủ'),
    (10, 9, 'Lệnh cấm túi nilon trên toàn quốc chắc chắn sẽ thay đổi thói quen mua sắm của hàng triệu người.', 'The nationwide ban on plastic bags is set to change the shopping habits of millions of people.', '["The national ban on plastic bags is set to change the shopping habits of millions of people.","The nationwide ban on plastic bags is set to change millions of people''s shopping habits.","The nationwide plastic bag ban is set to change the shopping habits of millions of people.","The nationwide ban on plastic bags is set to transform the shopping habits of millions of people."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","nationwide ban = lệnh cấm toàn quốc; plastic bags = túi nilon; shopping habits = thói quen mua sắm; be set to V = chắc chắn sẽ"]'::jsonb, 'C1', '1. Chính phủ'),
    (10, 10, 'Ngày càng nhiều người mang theo bình nước riêng thay vì mua nước đóng chai.', 'More and more people are carrying their own water bottles instead of buying bottled water.', '["More and more people carry their own water bottles instead of buying bottled water.","More and more people are carrying their own water bottles rather than buying bottled water.","More and more people are bringing their own water bottles instead of buying bottled water."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","carry / bring = mang theo; water bottle = bình nước; bottled water = nước đóng chai; instead of / rather than V-ing = thay vì"]'::jsonb, 'B1', '2. Cá nhân'),
    (10, 11, 'Người trẻ có khả năng tiếp nhận thói quen mới nhanh hơn người lớn tuổi.', 'Young people are likely to adopt new habits more quickly than older people.', '["Young people are likely to adopt new habits faster than older people.","Young people are likely to pick up new habits more quickly than older people.","Young people are likely to adopt new habits more quickly than the elderly."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","adopt / pick up new habits = tiếp nhận thói quen mới; more quickly / faster = nhanh hơn; older people = người lớn tuổi"]'::jsonb, 'B2', '2. Cá nhân'),
    (10, 12, 'Ngày càng có nhiều người dân lên tiếng trên mạng để gây áp lực lên chính quyền.', 'A growing number of citizens are speaking up online to put pressure on the authorities.', '["An increasing number of citizens are speaking up online to put pressure on the authorities.","A growing number of citizens are speaking out online to put pressure on the authorities.","A growing number of citizens are speaking up online to pressure the authorities."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","citizens = người dân, công dân; speak up / speak out = lên tiếng; put pressure on = gây áp lực lên; the authorities = chính quyền"]'::jsonb, 'B2', '2. Cá nhân'),
    (10, 13, 'Ngày càng có xu hướng người tiêu dùng đọc đánh giá trên mạng trước khi mua hàng.', 'There is a growing tendency for consumers to read online reviews before making a purchase.', '["There is a growing tendency for consumers to read online reviews before buying products.","There is a growing tendency for consumers to read reviews online before making a purchase.","There is a growing tendency for shoppers to read online reviews before making a purchase."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","online reviews = đánh giá trên mạng; make a purchase = mua hàng; There is a growing tendency for + sb + to V"]'::jsonb, 'C1', '2. Cá nhân'),
    (10, 14, 'Ngày càng nhiều người đi làm học thêm kỹ năng mới qua các khóa học trực tuyến vào buổi tối.', 'More and more working adults are learning new skills through online courses in the evening.', '["More and more working adults learn new skills through online courses in the evening.","More and more working adults are learning new skills through online courses in the evenings.","More and more working adults are picking up new skills through online courses in the evening."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","working adults = người đi làm; online courses = khóa học trực tuyến; pick up skills = học được kỹ năng; in the evening = vào buổi tối"]'::jsonb, 'B1', '2. Cá nhân'),
    (10, 15, 'Những thói quen tiết kiệm năng lượng được dự đoán sẽ trở thành điều tự nhiên sau vài tháng.', 'Energy-saving habits are expected to become second nature after a few months.', '["Energy-saving habits are expected to become second nature within a few months.","Habits of saving energy are expected to become second nature after a few months.","Energy-saving habits are expected to become automatic after a few months."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","energy-saving habits = thói quen tiết kiệm năng lượng; become second nature = trở thành điều tự nhiên; within a few months = trong vòng vài tháng"]'::jsonb, 'B2', '2. Cá nhân'),
    (10, 16, 'Một người hành động đơn lẻ khó có khả năng tạo ra khác biệt lớn cho môi trường.', 'One person acting alone is unlikely to make a big difference to the environment.', '["A single person acting alone is unlikely to make a big difference to the environment.","One person acting alone is unlikely to make a major difference to the environment.","One person acting on their own is unlikely to make a big difference to the environment."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","acting alone = hành động đơn lẻ; make a difference to = tạo khác biệt cho; be unlikely to V = khó có khả năng"]'::jsonb, 'B2', '2. Cá nhân'),
    (10, 17, 'Ngày càng có xu hướng người dân lái xe ngay cả cho những quãng đường rất ngắn.', 'There is a growing tendency for people to drive even for very short journeys.', '["There is a growing tendency for people to drive even for very short trips.","There is a growing tendency for people to drive even very short distances.","There is a growing tendency for people to use their cars even for very short journeys."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","drive = lái xe; short journeys / trips = quãng đường ngắn; even = ngay cả; There is a growing tendency for + sb + to V"]'::jsonb, 'C1', '2. Cá nhân'),
    (10, 18, 'Sự thay đổi trong thói quen mua sắm của người tiêu dùng chắc chắn sẽ buộc các thương hiệu lớn thay đổi sản phẩm.', 'Changes in consumers'' shopping habits are set to force major brands to change their products.', '["Changes in consumer shopping habits are set to force major brands to change their products.","Changes in consumers'' shopping habits are set to force big brands to change their products.","Changes in consumers'' shopping habits are set to force major brands to alter their products."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","shopping habits = thói quen mua sắm; force sb to V = buộc ai làm gì; major brands = thương hiệu lớn; be set to V = chắc chắn sẽ"]'::jsonb, 'C1', '2. Cá nhân'),
    (10, 19, 'Ngày càng nhiều trường học đưa môn tài chính cá nhân vào chương trình giảng dạy.', 'More and more schools are including personal finance in their curriculum.', '["More and more schools include personal finance in their curriculum.","More and more schools are adding personal finance to their curriculum.","More and more schools are introducing personal finance into their curriculum."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","personal finance = tài chính cá nhân; curriculum = chương trình giảng dạy; include sth in = đưa vào"]'::jsonb, 'B1', '3. Trường học'),
    (10, 20, 'Ngày càng có nhiều trường đại học hợp tác với doanh nghiệp để trang bị kỹ năng thực tế cho sinh viên.', 'A growing number of universities are working with companies to equip students with practical skills.', '["An increasing number of universities are working with companies to equip students with practical skills.","A growing number of universities are partnering with companies to equip students with practical skills.","A growing number of universities are working with businesses to equip students with practical skills."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","work / partner with = hợp tác với; equip sb with sth = trang bị cho ai cái gì; practical skills = kỹ năng thực tế"]'::jsonb, 'B2', '3. Trường học'),
    (10, 21, 'Chương trình học mới được dự đoán sẽ mất vài năm mới mang lại kết quả rõ rệt.', 'The new curriculum is expected to take several years to produce clear results.', '["The new curriculum is expected to take several years to deliver clear results.","The new curriculum is expected to take a few years to produce clear results.","The new syllabus is expected to take several years to produce clear results."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","curriculum / syllabus = chương trình học; take several years to V = mất vài năm để; produce / deliver results = mang lại kết quả"]'::jsonb, 'B2', '3. Trường học'),
    (10, 22, 'Ngày càng có xu hướng học sinh tin vào mọi thông tin chúng đọc được trên mạng.', 'There is a growing tendency for students to believe everything they read online.', '["There is a growing tendency for students to trust everything they read online.","There is a growing tendency for pupils to believe everything they read online.","There is a growing tendency for students to believe everything they read on the Internet."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","believe / trust = tin; read online = đọc trên mạng; There is a growing tendency for + sb + to V"]'::jsonb, 'C1', '3. Trường học'),
    (10, 23, 'Chỉ trừng phạt học sinh thì khó có khả năng giải quyết được gốc rễ của hành vi xấu.', 'Punishing students alone is unlikely to tackle the root cause of bad behaviour.', '["Punishing students alone is unlikely to tackle the root cause of bad behavior.","Punishing students alone is unlikely to address the root cause of bad behaviour.","Punishment alone is unlikely to tackle the root cause of bad behaviour."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","punish = trừng phạt; tackle / address the root cause = giải quyết gốc rễ; behaviour (Anh-Mỹ: behavior) = hành vi"]'::jsonb, 'B2', '3. Trường học'),
    (10, 24, 'Ngày càng nhiều học sinh bị căng thẳng vì áp lực thi cử.', 'More and more students are suffering from stress because of exam pressure.', '["More and more students suffer from stress because of exam pressure.","More and more pupils are suffering from stress because of exam pressure.","More and more students are suffering from stress due to exam pressure."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","suffer from stress = bị căng thẳng; exam pressure = áp lực thi cử; because of / due to = vì"]'::jsonb, 'B1', '3. Trường học'),
    (10, 25, 'Số trường tổ chức câu lạc bộ thể thao và dự án tình nguyện sau giờ học ngày càng tăng.', 'An increasing number of schools are organising sports clubs and volunteer projects after class.', '["A growing number of schools are organising sports clubs and volunteer projects after class.","An increasing number of schools are organizing sports clubs and volunteer projects after class.","An increasing number of schools are running sports clubs and volunteer projects after class."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","organise (Anh-Mỹ: organize) / run = tổ chức; sports clubs = câu lạc bộ thể thao; volunteer projects = dự án tình nguyện; after class = sau giờ học"]'::jsonb, 'B2', '3. Trường học'),
    (10, 26, 'Các buổi hướng nghiệp sớm được dự đoán sẽ giúp học sinh chọn ngành học phù hợp hơn.', 'Early career guidance sessions are expected to help students choose more suitable majors.', '["Early career guidance sessions are expected to help students choose more appropriate majors.","Early career guidance sessions are expected to help students pick more suitable majors.","Early career guidance is expected to help students choose more suitable majors."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","career guidance = hướng nghiệp; session = buổi; major = ngành học; suitable / appropriate = phù hợp"]'::jsonb, 'B2', '3. Trường học'),
    (10, 27, 'Các bài học kỹ năng số sắp sửa trở thành một phần bắt buộc trong chương trình phổ thông.', 'Digital literacy lessons are set to become a compulsory part of the school curriculum.', '["Digital literacy lessons are set to become a mandatory part of the school curriculum.","Digital literacy classes are set to become a compulsory part of the school curriculum.","Lessons in digital literacy are set to become a compulsory part of the school curriculum."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","digital literacy = kỹ năng số; compulsory / mandatory = bắt buộc; school curriculum = chương trình phổ thông; be set to V = sắp sửa"]'::jsonb, 'C1', '3. Trường học'),
    (10, 28, 'Ngày càng nhiều ông bà trông cháu để cha mẹ có thể đi làm toàn thời gian.', 'More and more grandparents are looking after their grandchildren so that parents can work full-time.', '["More and more grandparents look after their grandchildren so that parents can work full-time.","More and more grandparents are taking care of their grandchildren so that parents can work full-time.","More and more grandparents are looking after their grandchildren so parents can work full-time."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","look after / take care of = trông, chăm sóc; grandchildren = cháu; work full-time = làm việc toàn thời gian; so that = để"]'::jsonb, 'B1', '4. Cha mẹ và gia đình'),
    (10, 29, 'Ngày càng có nhiều trẻ nhỏ nghiện điện thoại vì cha mẹ quá bận rộn.', 'A growing number of young children are addicted to phones because their parents are too busy.', '["An increasing number of young children are addicted to phones because their parents are too busy.","A growing number of young children are addicted to smartphones because their parents are too busy.","A growing number of small children are addicted to phones because their parents are too busy."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","be addicted to = nghiện; too busy = quá bận rộn; a growing number of + N số nhiều + are"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (10, 30, 'Những đứa trẻ được tự đưa ra các quyết định nhỏ từ sớm có khả năng trở nên tự tin hơn khi lớn lên.', 'Children who are allowed to make small decisions from an early age are likely to become more confident as they grow up.', '["Children who are allowed to make small decisions from a young age are likely to become more confident as they grow up.","Children who are allowed to make small decisions early on are likely to become more confident as they grow up.","Children who are allowed to make minor decisions from an early age are likely to become more confident as they grow up."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","be allowed to V = được phép; from an early age = từ sớm, từ nhỏ; confident = tự tin; grow up = lớn lên"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (10, 31, 'Ngày càng có xu hướng các ông bố đảm nhận nhiều việc nhà và việc chăm con hơn.', 'There is a growing tendency for fathers to take on more housework and childcare.', '["There is a growing tendency for fathers to take on more of the housework and childcare.","There is a growing tendency for fathers to do more housework and childcare.","There is a growing tendency for fathers to take on more household chores and childcare."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","take on = đảm nhận; housework / household chores = việc nhà; childcare = việc chăm con; There is a growing tendency for + sb + to V"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (10, 32, 'Trước mắt, việc giảm giờ làm để dành thời gian cho con được dự đoán sẽ làm giảm thu nhập của nhiều gia đình.', 'In the short term, cutting working hours to spend time with children is expected to reduce the income of many families.', '["In the short term, reducing working hours to spend time with children is expected to lower the income of many families.","In the short term, cutting working hours to spend time with children is expected to reduce many families'' income.","In the short term, cutting working hours to spend time with their children is expected to reduce the income of many families."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","cut / reduce working hours = giảm giờ làm; spend time with = dành thời gian cho; income = thu nhập; in the short term = trước mắt"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (10, 33, 'Số gia đình đặt ra quy tắc không dùng điện thoại trong bữa tối ngày càng tăng.', 'An increasing number of families are setting rules against using phones at dinner.', '["A growing number of families are setting rules against using phones at dinner.","An increasing number of families are making rules against using phones at dinner.","An increasing number of families are setting rules against using phones during dinner."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","set / make rules = đặt ra quy tắc; against using = không được dùng; at / during dinner = trong bữa tối"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (10, 34, 'La mắng khó có khả năng dạy dỗ trẻ hiệu quả bằng việc cha mẹ làm gương.', 'Scolding is unlikely to teach children as effectively as setting a good example.', '["Scolding is unlikely to teach children as effectively as leading by example.","Scolding is unlikely to teach children as well as setting a good example.","Scolding children is unlikely to be as effective as setting a good example."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","scold = la mắng; set a good example / lead by example = làm gương; as effectively as = hiệu quả bằng"]'::jsonb, 'B2', '4. Cha mẹ và gia đình'),
    (10, 35, 'Ngày càng có xu hướng cha mẹ dùng ứng dụng để theo dõi việc con dùng Internet.', 'There is a growing tendency for parents to use apps to monitor their children''s Internet use.', '["There is a growing tendency for parents to use apps to track their children''s Internet use.","There is a growing tendency for parents to use apps to monitor how their children use the Internet.","There is a growing tendency for parents to use applications to monitor their children''s Internet use."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","apps / applications = ứng dụng; monitor / track = theo dõi; Internet use = việc dùng Internet"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (10, 36, 'Khi cả cha lẫn mẹ đều đi làm, nhu cầu về dịch vụ trông trẻ chắc chắn sẽ tăng mạnh.', 'With both parents working, the demand for childcare services is set to rise sharply.', '["With both parents working, demand for childcare services is set to rise sharply.","As both parents work, the demand for childcare services is set to rise sharply.","With both parents working, the demand for childcare services is set to increase sharply."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","both parents = cả cha lẫn mẹ; demand for = nhu cầu về; childcare services = dịch vụ trông trẻ; rise sharply = tăng mạnh"]'::jsonb, 'C1', '4. Cha mẹ và gia đình'),
    (10, 37, 'Ngày càng nhiều công ty tự đào tạo nhân viên để họ theo kịp công nghệ mới.', 'More and more companies are training their own staff to keep up with new technology.', '["More and more companies train their own staff to keep up with new technology.","More and more firms are training their own staff to keep up with new technology.","More and more companies are training their own employees to keep up with new technology."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","train staff = đào tạo nhân viên; keep up with = theo kịp; new technology = công nghệ mới"]'::jsonb, 'B1', '5. Doanh nghiệp'),
    (10, 38, 'Ngày càng có nhiều doanh nghiệp nhỏ chuyển sang dùng năng lượng mặt trời cho nhà xưởng.', 'A growing number of small businesses are switching to solar power for their factories.', '["An increasing number of small businesses are switching to solar power for their factories.","A growing number of small firms are switching to solar power for their factories.","A growing number of small businesses are switching to solar energy for their factories."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","small businesses = doanh nghiệp nhỏ; switch to = chuyển sang; solar power / energy = năng lượng mặt trời; factory = nhà xưởng"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (10, 39, 'Những công ty bắt nhân viên làm thêm giờ không lương có khả năng sẽ khó tuyển người mới.', 'Companies that force staff to work unpaid overtime are likely to struggle to recruit new workers.', '["Companies that force staff to work unpaid overtime are likely to have difficulty recruiting new workers.","Firms that force staff to work unpaid overtime are likely to struggle to recruit new workers.","Companies that force employees to work unpaid overtime are likely to struggle to recruit new workers."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","force sb to V = bắt ai làm gì; unpaid overtime = làm thêm giờ không lương; struggle to V / have difficulty V-ing = gặp khó khăn khi; recruit = tuyển"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (10, 40, 'Tự động hóa trong nhà máy chắc chắn sẽ thay đổi loại kỹ năng mà doanh nghiệp cần ở nhân viên.', 'Factory automation is set to change the kinds of skills that businesses need from their staff.', '["Factory automation is set to change the types of skills that businesses need from their staff.","Factory automation is set to change the kinds of skills businesses need from their staff.","Automation in factories is set to change the kinds of skills that businesses need from their staff."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","factory automation = tự động hóa nhà máy; kinds / types of skills = loại kỹ năng; need from = cần ở; be set to V = chắc chắn sẽ"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (10, 41, 'Số tập đoàn lớn tài trợ cho trường học ở các vùng nghèo ngày càng tăng.', 'An increasing number of large corporations are funding schools in poor areas.', '["A growing number of large corporations are funding schools in poor areas.","An increasing number of big corporations are funding schools in poor areas.","An increasing number of large corporations are sponsoring schools in poor areas."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","corporations = tập đoàn; fund / sponsor = tài trợ; poor areas = vùng nghèo; an increasing number of + N số nhiều + V số nhiều"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (10, 42, 'Trước mắt, việc chuyển sang công nghệ sản xuất sạch được dự đoán sẽ làm giảm lợi nhuận của nhiều nhà máy.', 'In the short term, switching to clean production technology is expected to reduce profits at many factories.', '["In the short term, switching to clean production technology is expected to cut profits at many factories.","In the short term, moving to clean production technology is expected to reduce profits at many factories.","In the short term, switching to clean production technology is expected to reduce many factories'' profits."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","clean production technology = công nghệ sản xuất sạch; reduce / cut profits = làm giảm lợi nhuận; in the short term = trước mắt"]'::jsonb, 'B2', '5. Doanh nghiệp'),
    (10, 43, 'Ngày càng có xu hướng nhà tuyển dụng đánh giá ứng viên dựa trên kỹ năng thay vì bằng cấp.', 'There is a growing tendency for employers to judge candidates on their skills rather than their degrees.', '["There is a growing tendency for employers to assess candidates on their skills rather than their degrees.","There is a growing tendency for employers to judge applicants on their skills rather than their degrees.","There is a growing tendency for employers to judge candidates on their skills rather than their qualifications."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","employers = nhà tuyển dụng; judge / assess = đánh giá; candidates / applicants = ứng viên; degrees / qualifications = bằng cấp; rather than = thay vì"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (10, 44, 'Các quy định mới về rác thải công nghiệp sắp sửa buộc nhà sản xuất chịu trách nhiệm về ô nhiễm mà họ gây ra.', 'New rules on industrial waste are set to hold manufacturers accountable for the pollution they cause.', '["New regulations on industrial waste are set to hold manufacturers accountable for the pollution they cause.","New rules on industrial waste are set to hold manufacturers responsible for the pollution they cause.","New rules on industrial waste are set to hold producers accountable for the pollution they cause."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","industrial waste = rác thải công nghiệp; hold sb accountable / responsible for = buộc ai chịu trách nhiệm về; manufacturers = nhà sản xuất"]'::jsonb, 'C1', '5. Doanh nghiệp'),
    (10, 45, 'Ngày càng nhiều gia đình ăn đồ ăn nhanh thay vì tự nấu ở nhà.', 'More and more families are eating fast food instead of cooking at home.', '["More and more families eat fast food instead of cooking at home.","More and more families are eating fast food rather than cooking at home.","More and more families are eating fast food instead of cooking meals at home."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","fast food = đồ ăn nhanh; instead of / rather than V-ing = thay vì; cook at home = nấu ở nhà"]'::jsonb, 'B1', '6. Sức khỏe'),
    (10, 46, 'Chỉ sau vài tuần tập thể dục, mọi người có khả năng ngủ ngon hơn và bớt căng thẳng.', 'After just a few weeks of exercise, people are likely to sleep better and feel less stressed.', '["After only a few weeks of exercise, people are likely to sleep better and feel less stressed.","After just a few weeks of exercising, people are likely to sleep better and feel less stressed.","After just a few weeks of physical activity, people are likely to sleep better and feel less stressed."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","a few weeks of exercise = vài tuần tập thể dục; sleep better = ngủ ngon hơn; feel less stressed = bớt căng thẳng"]'::jsonb, 'B2', '6. Sức khỏe'),
    (10, 47, 'Số người cao tuổi cần được chăm sóc y tế lâu dài ngày càng tăng.', 'A growing number of elderly people need long-term medical care.', '["An increasing number of elderly people need long-term medical care.","A growing number of older people need long-term medical care.","A growing number of elderly people require long-term medical care."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","elderly people = người cao tuổi; long-term medical care = chăm sóc y tế lâu dài; need / require = cần; a growing number of + N số nhiều + V số nhiều"]'::jsonb, 'B2', '6. Sức khỏe'),
    (10, 48, 'Ô nhiễm không khí ở các thành phố lớn được dự đoán sẽ gây ra thêm nhiều ca bệnh hô hấp.', 'Air pollution in big cities is expected to cause more cases of respiratory disease.', '["Air pollution in large cities is expected to cause more cases of respiratory disease.","Air pollution in big cities is expected to lead to more cases of respiratory disease.","Air pollution in big cities is expected to cause more cases of respiratory illness."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","air pollution = ô nhiễm không khí; cause / lead to = gây ra; cases = ca bệnh; respiratory disease = bệnh hô hấp"]'::jsonb, 'B2', '6. Sức khỏe'),
    (10, 49, 'Ngày càng nhiều người trẻ tìm đến chuyên gia tư vấn tâm lý khi cảm thấy căng thẳng.', 'More and more young people are seeking help from counsellors when they feel stressed.', '["More and more young people are seeking help from counselors when they feel stressed.","More and more young people seek help from counsellors when they feel stressed.","More and more young people are turning to counsellors when they feel stressed."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","seek help from / turn to = tìm đến; counsellor (Anh-Mỹ: counselor) = chuyên gia tư vấn tâm lý; feel stressed = cảm thấy căng thẳng"]'::jsonb, 'B1', '6. Sức khỏe'),
    (10, 50, 'Ngày càng có xu hướng mọi người dùng đồng hồ thông minh để theo dõi sức khỏe của mình.', 'There is a growing tendency for people to use smartwatches to monitor their health.', '["There is a growing tendency for people to use smart watches to monitor their health.","There is a growing tendency for people to use smartwatches to track their health.","There is a growing tendency for people to use smartwatches to keep track of their health."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","smartwatch = đồng hồ thông minh; monitor / track / keep track of = theo dõi; There is a growing tendency for + sb + to V"]'::jsonb, 'C1', '6. Sức khỏe'),
    (10, 51, 'Chỉ dùng thuốc thì khó có khả năng chữa khỏi các bệnh do lối sống như béo phì và tiểu đường.', 'Medicine alone is unlikely to cure lifestyle diseases such as obesity and diabetes.', '["Medication alone is unlikely to cure lifestyle diseases such as obesity and diabetes.","Medicine alone is unlikely to cure lifestyle diseases like obesity and diabetes.","Medicine on its own is unlikely to cure lifestyle diseases such as obesity and diabetes."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","medicine / medication = thuốc; alone / on its own = chỉ riêng; lifestyle diseases = bệnh do lối sống; obesity = béo phì; diabetes = tiểu đường"]'::jsonb, 'B2', '6. Sức khỏe'),
    (10, 52, 'Chương trình khám sức khỏe miễn phí chắc chắn sẽ giúp bác sĩ phát hiện bệnh ở giai đoạn sớm hơn.', 'The free check-up programme is set to help doctors detect illnesses at an earlier stage.', '["The free check-up program is set to help doctors detect illnesses at an earlier stage.","The free check-up programme is set to help doctors detect diseases at an earlier stage.","The free check-up programme is set to help doctors spot illnesses at an earlier stage."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","check-up programme (Anh-Mỹ: program) = chương trình khám sức khỏe; detect / spot = phát hiện; at an earlier stage = ở giai đoạn sớm hơn"]'::jsonb, 'C1', '6. Sức khỏe'),
    (10, 53, 'Ngày càng nhiều gia đình trẻ gặp khó khăn vì chi phí nhà ở tăng nhanh hơn thu nhập.', 'More and more young families are struggling because housing costs are rising faster than incomes.', '["More and more young families struggle because housing costs are rising faster than incomes.","More and more young families are struggling as housing costs are rising faster than incomes.","More and more young families are struggling because housing costs are rising faster than their incomes."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","struggle = gặp khó khăn; housing costs = chi phí nhà ở; rise faster than = tăng nhanh hơn; incomes = thu nhập"]'::jsonb, 'B1', '7. Kinh tế và tài chính'),
    (10, 54, 'Ngành du lịch được dự đoán sẽ mang lại thêm nguồn thu thuế cho chính quyền địa phương.', 'The tourism industry is expected to generate more tax revenue for local governments.', '["The tourism industry is expected to bring in more tax revenue for local governments.","The tourist industry is expected to generate more tax revenue for local governments.","The tourism industry is expected to generate extra tax revenue for local governments."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","tourism industry = ngành du lịch; generate / bring in = mang lại, tạo ra; tax revenue = nguồn thu thuế; local governments = chính quyền địa phương"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (10, 55, 'Ngày càng có nhiều nhà đầu tư nước ngoài mở nhà máy ở các nước đang phát triển.', 'A growing number of foreign investors are opening factories in developing countries.', '["An increasing number of foreign investors are opening factories in developing countries.","A growing number of foreign investors are setting up factories in developing countries.","A growing number of overseas investors are opening factories in developing countries."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","foreign / overseas investors = nhà đầu tư nước ngoài; open / set up factories = mở nhà máy; developing countries = nước đang phát triển"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (10, 56, 'Chi phí sinh hoạt ở các thành phố lớn chắc chắn sẽ tiếp tục tăng trong những năm tới.', 'The cost of living in big cities is set to keep rising in the coming years.', '["The cost of living in big cities is set to continue rising in the coming years.","The cost of living in major cities is set to keep rising in the coming years.","The cost of living in big cities is set to keep rising over the coming years."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","cost of living = chi phí sinh hoạt; keep / continue rising = tiếp tục tăng; in the coming years = trong những năm tới"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (10, 57, 'Tăng trưởng không đồng đều khó có khả năng mang lại lợi ích cho những người nghèo nhất trong xã hội.', 'Uneven growth is unlikely to benefit the poorest members of society.', '["Unequal growth is unlikely to benefit the poorest members of society.","Uneven growth is unlikely to benefit the poorest people in society.","Uneven economic growth is unlikely to benefit the poorest members of society."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","uneven / unequal growth = tăng trưởng không đồng đều; benefit = mang lại lợi ích cho; the poorest members of society = những người nghèo nhất trong xã hội"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (10, 58, 'Ngày càng có xu hướng người trẻ rời quê lên thành phố lớn để tìm việc làm lương cao hơn.', 'There is a growing tendency for young people to leave their hometowns for big cities in search of better-paid jobs.', '["There is a growing tendency for young people to leave their home towns for big cities in search of better-paid jobs.","There is a growing tendency for young people to leave their hometowns for big cities to look for better-paid jobs.","There is a growing tendency for young people to leave their hometowns for large cities in search of higher-paid jobs."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","hometown = quê; leave A for B = rời A để đến B; in search of / to look for = để tìm; better-paid jobs = việc làm lương cao hơn"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (10, 59, 'Các chương trình đào tạo lại được dự đoán sẽ giúp những người mất việc vì tự động hóa chuyển sang ngành nghề mới.', 'Retraining programmes are expected to help workers who lose their jobs to automation move into new industries.', '["Retraining programs are expected to help workers who lose their jobs to automation move into new industries.","Retraining programmes are expected to help workers who lose their jobs to automation move into new sectors.","Retraining programmes are expected to help people who lose their jobs to automation move into new industries."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","retraining programmes (Anh-Mỹ: programs) = chương trình đào tạo lại; lose one''s job to automation = mất việc vì tự động hóa; move into = chuyển sang"]'::jsonb, 'B2', '7. Kinh tế và tài chính'),
    (10, 60, 'Khu công nghệ cao mới chắc chắn sẽ thúc đẩy kinh tế của cả vùng.', 'The new high-tech park is set to boost the economy of the whole region.', '["The new high-tech park is set to boost the economy of the entire region.","The new high-tech zone is set to boost the economy of the whole region.","The new high-tech park is set to boost the whole region''s economy."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","high-tech park = khu công nghệ cao; boost the economy = thúc đẩy kinh tế; the whole / entire region = cả vùng"]'::jsonb, 'C1', '7. Kinh tế và tài chính'),
    (10, 61, 'Ngày càng nhiều người ở thành phố sống một mình và hầu như không quen biết hàng xóm.', 'More and more city dwellers live alone and barely know their neighbours.', '["More and more city dwellers live alone and barely know their neighbors.","More and more city dwellers live alone and hardly know their neighbours.","More and more city dwellers are living alone and barely know their neighbours."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","city dwellers = người ở thành phố; live alone = sống một mình; barely / hardly = hầu như không; neighbour (Anh-Mỹ: neighbor) = hàng xóm"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (10, 62, 'Ngày càng có xu hướng mọi người giao tiếp với nhau qua mạng thay vì gặp mặt trực tiếp.', 'There is a growing tendency for people to communicate online rather than meet face to face.', '["There is a growing tendency for people to communicate online instead of meeting face to face.","There is a growing tendency for people to interact online rather than meet face to face.","There is a growing tendency for people to communicate online rather than meet in person."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","communicate / interact online = giao tiếp qua mạng; face to face / in person = gặp mặt trực tiếp; rather than / instead of = thay vì"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (10, 63, 'Ngày càng có nhiều cộng đồng địa phương tổ chức lễ hội để tăng cường sự gắn kết giữa các cư dân.', 'A growing number of local communities are holding festivals to strengthen ties among residents.', '["An increasing number of local communities are holding festivals to strengthen ties among residents.","A growing number of local communities are holding festivals to strengthen bonds among residents.","A growing number of local communities are organising festivals to strengthen ties among residents."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","local communities = cộng đồng địa phương; hold / organise festivals = tổ chức lễ hội; strengthen ties / bonds = tăng cường gắn kết; residents = cư dân"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (10, 64, 'Những khu dân cư có nhiều không gian công cộng có khả năng có tỷ lệ tội phạm thấp hơn.', 'Neighbourhoods with plenty of public spaces are likely to have lower crime rates.', '["Neighborhoods with plenty of public spaces are likely to have lower crime rates.","Neighbourhoods with plenty of public spaces are likely to have less crime.","Residential areas with plenty of public spaces are likely to have lower crime rates."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","neighbourhood (Anh-Mỹ: neighborhood) / residential area = khu dân cư; public spaces = không gian công cộng; crime rates = tỷ lệ tội phạm"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (10, 65, 'Ngày càng nhiều người cao tuổi cảm thấy cô đơn khi con cháu chuyển đi nơi khác.', 'More and more elderly people feel lonely when their children and grandchildren move away.', '["More and more elderly people feel lonely when their children and grandchildren move elsewhere.","More and more older people feel lonely when their children and grandchildren move away.","More and more elderly people feel lonely after their children and grandchildren move away."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","elderly / older people = người cao tuổi; feel lonely = cảm thấy cô đơn; move away = chuyển đi nơi khác; grandchildren = cháu"]'::jsonb, 'B1', '8. Xã hội và cộng đồng'),
    (10, 66, 'Luật chống phân biệt đối xử mới được dự đoán sẽ giúp người khuyết tật dễ tìm việc làm hơn.', 'The new anti-discrimination law is expected to make it easier for disabled people to find work.', '["The new anti-discrimination law is expected to make it easier for people with disabilities to find work.","The new anti-discrimination law is expected to make it easier for disabled people to find jobs.","The new anti-discrimination law is expected to help disabled people find work more easily."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","anti-discrimination law = luật chống phân biệt đối xử; disabled people / people with disabilities = người khuyết tật; make it easier for sb to V = giúp ai dễ làm gì hơn"]'::jsonb, 'B2', '8. Xã hội và cộng đồng'),
    (10, 67, 'Ngày càng có xu hướng các bạn trẻ tình nguyện giúp đỡ người vô gia cư trong thành phố của mình.', 'There is a growing tendency for young people to volunteer to help homeless people in their city.', '["There is a growing tendency for young people to volunteer to help the homeless in their city.","There is a growing tendency for young people to volunteer to support homeless people in their city.","There is a growing tendency for young people to volunteer to help homeless people in their own city."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","volunteer to V = tình nguyện làm gì; homeless people / the homeless = người vô gia cư; support = hỗ trợ"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (10, 68, 'Thành phố sắp sửa mở thêm nhiều thư viện và trung tâm cộng đồng ở các khu dân cư nghèo.', 'The city is set to open more libraries and community centres in poor neighbourhoods.', '["The city is set to open more libraries and community centers in poor neighborhoods.","The city is set to open more libraries and community centres in poor areas.","The city is set to build more libraries and community centres in poor neighbourhoods."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","community centre (Anh-Mỹ: center) = trung tâm cộng đồng; poor neighbourhoods (Anh-Mỹ: neighborhoods) = khu dân cư nghèo; be set to V = sắp sửa"]'::jsonb, 'C1', '8. Xã hội và cộng đồng'),
    (10, 69, 'Ngày càng có nhiều quốc gia chuyển từ than đá sang năng lượng gió và mặt trời.', 'A growing number of countries are switching from coal to wind and solar power.', '["An increasing number of countries are switching from coal to wind and solar power.","A growing number of countries are moving from coal to wind and solar power.","A growing number of countries are switching from coal to wind and solar energy.","A growing number of nations are switching from coal to wind and solar power."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","switch from A to B = chuyển từ A sang B; coal = than đá; wind and solar power = năng lượng gió và mặt trời"]'::jsonb, 'B2', '9. Môi trường'),
    (10, 70, 'Biến đổi khí hậu được dự đoán sẽ khiến hạn hán và lũ lụt xảy ra thường xuyên hơn.', 'Climate change is expected to make droughts and floods more frequent.', '["Climate change is expected to make floods and droughts more frequent.","Climate change is expected to make droughts and floods more common.","Climate change is expected to cause more frequent droughts and floods."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","climate change = biến đổi khí hậu; drought = hạn hán; flood = lũ lụt; frequent = thường xuyên"]'::jsonb, 'B2', '9. Môi trường'),
    (10, 71, 'Ngày càng nhiều người dân đi làm bằng tàu điện ngầm thay vì lái xe.', 'More and more residents are taking the metro to work instead of driving.', '["More and more residents take the metro to work instead of driving.","More and more residents are taking the metro to work rather than driving.","More and more residents are using the metro to get to work instead of driving."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","take the metro = đi tàu điện ngầm; residents = người dân; instead of / rather than V-ing = thay vì"]'::jsonb, 'B1', '9. Môi trường'),
    (10, 72, 'Nếu không hành động ngay, các rạn san hô bị tổn hại khó có khả năng phục hồi.', 'Without immediate action, damaged coral reefs are unlikely to recover.', '["Without urgent action, damaged coral reefs are unlikely to recover.","Unless action is taken now, damaged coral reefs are unlikely to recover.","Without immediate action, damaged coral reefs are unlikely to be able to recover."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","immediate / urgent action = hành động ngay; coral reefs = rạn san hô; damaged = bị tổn hại; recover = phục hồi"]'::jsonb, 'B2', '9. Môi trường'),
    (10, 73, 'Số loài động vật mất môi trường sống do nạn phá rừng ngày càng tăng.', 'An increasing number of animal species are losing their habitats because of deforestation.', '["A growing number of animal species are losing their habitats because of deforestation.","An increasing number of animal species are losing their habitats due to deforestation.","An increasing number of species are losing their natural habitats because of deforestation."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","species = loài (số ít và số nhiều giống nhau); habitat = môi trường sống; deforestation = nạn phá rừng; because of / due to = do"]'::jsonb, 'B2', '9. Môi trường'),
    (10, 74, 'Ngày càng có xu hướng người tiêu dùng thay điện thoại mới dù máy cũ vẫn dùng tốt.', 'There is a growing tendency for consumers to replace their phones even when the old ones still work well.', '["There is a growing tendency for consumers to replace their phones even though the old ones still work well.","There is a growing tendency for consumers to replace their phones even when their old ones still work well.","There is a growing tendency for consumers to buy new phones even when the old ones still work well."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","replace = thay mới; even when / even though = dù; still work well = vẫn dùng tốt; There is a growing tendency for + sb + to V"]'::jsonb, 'C1', '9. Môi trường'),
    (10, 75, 'Chương trình hoàn tiền khi trả lại vỏ chai được dự đoán sẽ làm tăng đáng kể tỷ lệ tái chế.', 'The bottle deposit scheme is expected to increase recycling rates significantly.', '["The bottle deposit scheme is expected to raise recycling rates significantly.","The bottle deposit scheme is expected to boost recycling rates significantly.","The bottle deposit scheme is expected to increase recycling rates considerably."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","deposit scheme = chương trình hoàn tiền vỏ chai; recycling rates = tỷ lệ tái chế; significantly / considerably = đáng kể"]'::jsonb, 'B2', '9. Môi trường'),
    (10, 76, 'Mực nước biển dâng chắc chắn sẽ đe dọa nhiều thành phố ven biển trong những thập kỷ tới.', 'Rising sea levels are set to threaten many coastal cities in the coming decades.', '["Rising sea levels are set to threaten many coastal cities over the coming decades.","Rising sea levels are set to endanger many coastal cities in the coming decades.","Rising sea levels are set to threaten many coastal cities in the decades ahead."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","rising sea levels = mực nước biển dâng; threaten / endanger = đe dọa; coastal cities = thành phố ven biển; in the coming decades = trong những thập kỷ tới"]'::jsonb, 'C1', '9. Môi trường'),
    (10, 77, 'Ngày càng nhiều người cao tuổi dùng điện thoại thông minh để gọi video cho con cháu.', 'More and more older people are using smartphones to video call their children and grandchildren.', '["More and more older people use smartphones to video call their children and grandchildren.","More and more elderly people are using smartphones to video call their children and grandchildren.","More and more older people are using smartphones to make video calls to their children and grandchildren."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","older / elderly people = người cao tuổi; video call sb = gọi video cho ai; smartphones = điện thoại thông minh"]'::jsonb, 'B1', '10. Công nghệ'),
    (10, 78, 'Trước mắt, những người làm công việc lặp lại có khả năng bị robot thay thế.', 'In the short term, workers who do repetitive tasks are likely to be replaced by robots.', '["In the short term, workers who perform repetitive tasks are likely to be replaced by robots.","In the short term, workers doing repetitive tasks are likely to be replaced by robots.","In the short run, workers who do repetitive tasks are likely to be replaced by robots."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","repetitive tasks = công việc lặp lại; be replaced by = bị thay thế bởi; in the short term = trước mắt"]'::jsonb, 'B2', '10. Công nghệ'),
    (10, 79, 'Ngày càng có nhiều ứng dụng thu thập dữ liệu cá nhân mà người dùng không hề hay biết.', 'A growing number of apps are collecting personal data without users'' knowledge.', '["An increasing number of apps are collecting personal data without users'' knowledge.","A growing number of apps collect personal data without users'' knowledge.","A growing number of apps are collecting personal data without users knowing."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","collect personal data = thu thập dữ liệu cá nhân; without sb''s knowledge = mà ai không hay biết; apps = ứng dụng"]'::jsonb, 'B2', '10. Công nghệ'),
    (10, 80, 'Các ứng dụng dịch tức thời chắc chắn sẽ giúp việc giao tiếp giữa các nền văn hóa dễ dàng hơn nhiều.', 'Instant translation apps are set to make communication between cultures much easier.', '["Instant translation apps are set to make communication across cultures much easier.","Instant translation apps are set to make cross-cultural communication much easier.","Real-time translation apps are set to make communication between cultures much easier."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","instant / real-time translation = dịch tức thời; communication between cultures = giao tiếp giữa các nền văn hóa; much easier = dễ dàng hơn nhiều"]'::jsonb, 'C1', '10. Công nghệ'),
    (10, 81, 'Trí tuệ nhân tạo khó có khả năng thay thế hoàn toàn giáo viên trong lớp học.', 'Artificial intelligence is unlikely to replace teachers in the classroom completely.', '["Artificial intelligence is unlikely to completely replace teachers in the classroom.","AI is unlikely to replace teachers in the classroom completely.","Artificial intelligence is unlikely to fully replace teachers in the classroom."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","artificial intelligence (AI) = trí tuệ nhân tạo; replace = thay thế; completely / fully = hoàn toàn"]'::jsonb, 'B2', '10. Công nghệ'),
    (10, 82, 'Ngày càng có xu hướng trẻ em dành hàng giờ với máy tính bảng thay vì chơi ngoài trời.', 'There is a growing tendency for children to spend hours on tablets instead of playing outdoors.', '["There is a growing tendency for children to spend hours on tablets rather than playing outdoors.","There is a growing tendency for children to spend hours on tablets instead of playing outside.","There is a growing tendency for kids to spend hours on tablets instead of playing outdoors."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","spend hours on = dành hàng giờ với; tablets = máy tính bảng; play outdoors / outside = chơi ngoài trời"]'::jsonb, 'C1', '10. Công nghệ'),
    (10, 83, 'Luật bảo vệ dữ liệu mới được dự đoán sẽ buộc các công ty công nghệ minh bạch hơn với người dùng.', 'The new data protection law is expected to force tech companies to be more transparent with users.', '["The new data protection law is expected to force technology companies to be more transparent with users.","The new data protection law is expected to make tech companies more transparent with users.","The new data protection law is expected to force tech firms to be more transparent with users."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","data protection law = luật bảo vệ dữ liệu; tech companies = công ty công nghệ; transparent = minh bạch"]'::jsonb, 'B2', '10. Công nghệ'),
    (10, 84, 'Học trực tuyến chắc chắn sẽ giúp học sinh ở vùng xa được tiếp cận với giáo viên giỏi.', 'Online learning is set to give students in remote areas access to good teachers.', '["Online learning is set to give students in remote areas access to excellent teachers.","Online education is set to give students in remote areas access to good teachers.","Online learning is set to give pupils in remote areas access to good teachers."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","online learning = học trực tuyến; remote areas = vùng xa; give sb access to = giúp ai tiếp cận"]'::jsonb, 'C1', '10. Công nghệ'),
    (10, 85, 'Ngày càng nhiều người mua hàng tạp hóa trên mạng để khỏi phải xếp hàng ở siêu thị.', 'More and more people are buying groceries online to avoid queuing at the supermarket.', '["More and more people buy groceries online to avoid queuing at the supermarket.","More and more people are buying groceries online to avoid queueing at the supermarket.","More and more people are buying groceries online to avoid waiting in line at the supermarket."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","groceries = hàng tạp hóa; queue (Anh-Mỹ: wait in line) = xếp hàng; avoid V-ing = tránh"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (10, 86, 'Ngày càng có xu hướng các công ty cho nhân viên làm việc tại nhà vài ngày mỗi tuần.', 'There is a growing tendency for companies to let staff work from home a few days a week.', '["There is a growing tendency for companies to let employees work from home a few days a week.","There is a growing tendency for companies to allow staff to work from home a few days a week.","There is a growing tendency for firms to let staff work from home a few days a week."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","let sb V / allow sb to V = cho ai làm gì; work from home = làm việc tại nhà; a few days a week = vài ngày mỗi tuần"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (10, 87, 'Ngày càng có nhiều ngân hàng chuyển phần lớn dịch vụ sang ứng dụng di động.', 'A growing number of banks are moving most of their services to mobile apps.', '["An increasing number of banks are moving most of their services to mobile apps.","A growing number of banks are shifting most of their services to mobile apps.","A growing number of banks are moving most of their services onto mobile apps."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","move / shift sth to = chuyển cái gì sang; services = dịch vụ; mobile apps = ứng dụng di động"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (10, 88, 'Những người quá phụ thuộc vào dịch vụ giao hàng có khả năng trở nên lười vận động hơn.', 'People who rely too much on delivery services are likely to become less active.', '["People who depend too much on delivery services are likely to become less active.","People who rely too heavily on delivery services are likely to become less active.","People who rely too much on delivery services are likely to become less physically active."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","rely / depend on = phụ thuộc vào; delivery services = dịch vụ giao hàng; less active = ít vận động hơn"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (10, 89, 'Ngày càng nhiều nhân viên văn phòng ăn trưa ngay tại bàn làm việc vì thiếu thời gian.', 'More and more office workers are eating lunch at their desks because they are short of time.', '["More and more office workers eat lunch at their desks because they are short of time.","More and more office workers are having lunch at their desks because they are short of time.","More and more office workers are eating lunch at their desks because they lack time."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","eat / have lunch = ăn trưa; at their desks = tại bàn làm việc; be short of time / lack time = thiếu thời gian"]'::jsonb, 'B1', '11. Thời gian và sự tiện lợi'),
    (10, 90, 'Tuyến tàu điện mới được dự đoán sẽ rút ngắn đáng kể thời gian đi làm của người dân ngoại ô.', 'The new metro line is expected to cut commuting times for suburban residents considerably.', '["The new metro line is expected to reduce commuting times for suburban residents considerably.","The new metro line is expected to cut commuting time for suburban residents considerably.","The new metro line is expected to considerably cut commuting times for suburban residents."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","metro line = tuyến tàu điện; commuting times = thời gian đi làm; suburban residents = người dân ngoại ô; considerably = đáng kể"]'::jsonb, 'B2', '11. Thời gian và sự tiện lợi'),
    (10, 91, 'Ngày càng có xu hướng mọi người dùng thời gian tiết kiệm được để lướt mạng xã hội thay vì tập thể dục.', 'There is a growing tendency for people to spend the time they save scrolling through social media instead of exercising.', '["There is a growing tendency for people to spend the time they save on social media instead of exercising.","There is a growing tendency for people to spend the time they save scrolling through social media rather than exercising.","There is a growing tendency for people to spend their saved time scrolling through social media instead of exercising."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","the time they save = thời gian tiết kiệm được; scroll through social media = lướt mạng xã hội; instead of / rather than V-ing = thay vì"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (10, 92, 'Thiết bị gia dụng thông minh sắp sửa trở nên phổ biến trong hầu hết các gia đình ở thành phố.', 'Smart home appliances are set to become common in most urban households.', '["Smart home appliances are set to become commonplace in most urban households.","Smart household appliances are set to become common in most urban households.","Smart home appliances are set to become common in most city households."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","smart home appliances = thiết bị gia dụng thông minh; become common / commonplace = trở nên phổ biến; urban households = gia đình ở thành phố"]'::jsonb, 'C1', '11. Thời gian và sự tiện lợi'),
    (10, 93, 'Ngày càng nhiều người trẻ lo rằng họ sẽ phải trả giá cho các quyết định của những thế hệ trước.', 'More and more young people worry that they will have to pay the price for the decisions of earlier generations.', '["More and more young people are worried that they will have to pay the price for the decisions of earlier generations.","More and more young people worry that they will have to pay the price for earlier generations'' decisions.","More and more young people worry that they will have to pay the price for the decisions of previous generations."]'::jsonb, '["more and more + noun = ngày càng nhiều (mục 2.10)","worry that / be worried that = lo rằng; pay the price for = trả giá cho; earlier / previous generations = những thế hệ trước"]'::jsonb, 'B1', '12. Ngắn hạn và dài hạn'),
    (10, 94, 'Lúc đầu, hệ thống mới được dự đoán sẽ làm chậm công việc vì nhân viên cần thời gian làm quen.', 'At first, the new system is expected to slow down work because staff need time to adjust.', '["At first, the new system is expected to slow work down because staff need time to adjust.","Initially, the new system is expected to slow down work because staff need time to adjust.","At first, the new system is expected to slow down work because employees need time to adapt."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","at first / initially = lúc đầu; slow down = làm chậm; adjust / adapt = làm quen, thích nghi"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (10, 95, 'Chính phủ sắp sửa áp dụng thuế carbon theo từng giai đoạn để doanh nghiệp có thời gian thích nghi.', 'The government is set to introduce a carbon tax in stages so that businesses have time to adapt.', '["The government is set to introduce a carbon tax gradually so that businesses have time to adapt.","The government is set to phase in a carbon tax so that businesses have time to adapt.","The government is set to introduce a carbon tax in stages so businesses have time to adapt."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","introduce sth in stages / phase in = áp dụng theo từng giai đoạn; carbon tax = thuế carbon; adapt = thích nghi"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (10, 96, 'Ngày càng có nhiều hộ gia đình chấp nhận trả chi phí ban đầu cao để lắp pin mặt trời nhằm tiết kiệm tiền về lâu dài.', 'A growing number of households are paying high upfront costs for solar panels to save money in the long run.', '["An increasing number of households are paying high upfront costs for solar panels to save money in the long run.","A growing number of households are paying high upfront costs for solar panels to save money in the long term.","A growing number of households are paying high initial costs for solar panels to save money in the long run."]'::jsonb, '["an increasing / a growing number of + noun = số lượng ngày càng tăng (mục 2.10)","upfront / initial costs = chi phí ban đầu; solar panels = pin mặt trời; in the long run / term = về lâu dài"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (10, 97, 'Các giải pháp tạm thời khó có khả năng giải quyết vấn đề một cách bền vững.', 'Quick fixes are unlikely to solve the problem in a sustainable way.', '["Quick fixes are unlikely to solve the problem sustainably.","Temporary solutions are unlikely to solve the problem in a sustainable way.","Quick fixes are unlikely to resolve the problem in a sustainable way."]'::jsonb, '["be likely / unlikely to V = có khả năng / không có khả năng (mục 2.10)","quick fixes / temporary solutions = giải pháp tạm thời; solve / resolve = giải quyết; sustainable = bền vững"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (10, 98, 'Ngày càng có xu hướng các công ty cắt giảm đầu tư dài hạn để thu lợi nhuận nhanh.', 'There is a growing tendency for companies to cut long-term investment in order to make quick profits.', '["There is a growing tendency for companies to cut long-term investment to make quick profits.","There is a growing tendency for firms to cut long-term investment in order to make quick profits.","There is a growing tendency for companies to reduce long-term investment in order to make quick profits."]'::jsonb, '["There is a growing tendency for sb to V = ngày càng có xu hướng ai đó làm gì (mục 2.10)","cut / reduce investment = cắt giảm đầu tư; long-term = dài hạn; make quick profits = thu lợi nhuận nhanh"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn'),
    (10, 99, 'Việc khai thác nước ngầm quá mức hôm nay được dự đoán sẽ gây thiếu nước cho các thế hệ sau.', 'Today''s overuse of groundwater is expected to cause water shortages for future generations.', '["The overuse of groundwater today is expected to cause water shortages for future generations.","Today''s overuse of groundwater is expected to lead to water shortages for future generations.","Today''s overuse of groundwater is expected to cause water shortages for the next generation."]'::jsonb, '["be expected to V = được dự đoán sẽ (mục 2.10)","overuse = khai thác quá mức; groundwater = nước ngầm; water shortages = tình trạng thiếu nước; future generations = các thế hệ sau"]'::jsonb, 'B2', '12. Ngắn hạn và dài hạn'),
    (10, 100, 'Những khoản đầu tư vào giáo dục hôm nay chắc chắn sẽ mang lại kết quả trong nhiều thập kỷ tới.', 'Today''s investment in education is set to pay off for decades to come.', '["Today''s investments in education are set to pay off for decades to come.","Investment in education today is set to pay off for decades to come.","Today''s investment in education is set to pay off for many decades to come."]'::jsonb, '["be set to V = chắc chắn sẽ, sắp sửa (mục 2.10)","investment in = đầu tư vào; pay off = mang lại kết quả, đáng công; for decades to come = trong nhiều thập kỷ tới"]'::jsonb, 'C1', '12. Ngắn hạn và dài hạn')
  ) as s (k, n, vi, en, alt, hints, level, topic)
  where v_folder[s.k] is not null;
end $$;

-- Kiểm tra: phải thấy 10 dòng, mỗi dòng so_cau = 100
select f.name, count(s.id) as so_cau
from public.sentence_folders f
left join public.sentences s on s.folder_id = f.id and s.deleted_at is null
where f.name like 'Pattern 2.% · %' and f.deleted_at is null
group by f.id, f.name, f.created_at
order by f.created_at;
